window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["PRO"]={"book":"PRO","editions":{"hbo-source":[[1,1,"מִ֭שְׁלֵי שְׁלֹמֹ֣ה בֶן־דָּוִ֑ד מֶ֝֗לֶךְ יִשְׂרָאֵֽל׃","mi֭şĕ̌léy şĕ̌lòmò֣h ben-dá̇wi֑d me֝֗lekĕ yişĕ̂ráʼéֽl׃"],[1,2,"לָ⁠דַ֣עַת חָכְמָ֣ה וּ⁠מוּסָ֑ר לְ֝⁠הָבִ֗ין אִמְרֵ֥י בִינָֽה׃","lá⁠da֣ʻaţ ẖákĕmá֣h ẇ⁠mẇsá֑r lĕ֝⁠hábi֗yn ʼimĕré֥y biynáֽh׃"],[1,3,"לָ֭⁠קַחַת מוּסַ֣ר הַשְׂכֵּ֑ל צֶ֥דֶק וּ֝⁠מִשְׁפָּ֗ט וּ⁠מֵישָׁרִֽים׃","lá֭⁠qaẖaţ mẇsa֣r haşĕ̂ké֑̇l ẕe֥deq ẇ֝⁠mişĕ̌pá̇֗t ẇ⁠méyşá̌riֽym׃"],[1,4,"לָ⁠תֵ֣ת לִ⁠פְתָאיִ֣ם עָרְמָ֑ה לְ֝⁠נַ֗עַר דַּ֣עַת וּ⁠מְזִמָּֽה׃","lá⁠ţé֣ţ li⁠pĕţáʼyi֣m ʻárĕmá֑h lĕ֝⁠na֗ʻar dȧ֣ʻaţ ẇ⁠mĕzimáֽ̇h׃"],[1,5,"יִשְׁמַ֣ע חָ֭כָם וְ⁠י֣וֹסֶף לֶ֑קַח וְ֝⁠נָב֗וֹן תַּחְבֻּל֥וֹת יִקְנֶֽה׃","yişĕ̌ma֣ʻ ẖá֭kám wĕ⁠y֣wòsep le֑qaẖ wĕ֝⁠náb֗wòn ţȧẖĕbu̇l֥wòţ yiqĕneֽh׃"],[1,6,"לְ⁠הָבִ֣ין מָ֭שָׁל וּ⁠מְלִיצָ֑ה דִּבְרֵ֥י חֲ֝כָמִ֗ים וְ⁠חִידֹתָֽ⁠ם׃","lĕ⁠hábi֣yn má֭şá̌l ẇ⁠mĕliyẕá֑h di̇bĕré֥y ẖà֝kámi֗ym wĕ⁠ẖiydòţáֽ⁠m׃"],[1,7,"יִרְאַ֣ת יְ֭הוָה רֵאשִׁ֣ית דָּ֑עַת חָכְמָ֥ה וּ֝⁠מוּסָ֗ר אֱוִילִ֥ים בָּֽזוּ׃פ","yirĕʼa֣ţ yĕ֭hwáh réʼşǐ֣yţ dá֑̇ʻaţ ẖákĕmá֥h ẇ֝⁠mẇsá֗r ʼèwiyli֥ym báֽ̇zẇ׃p"],[1,8,"שְׁמַ֣ע בְּ֭נִ⁠י מוּסַ֣ר אָבִ֑י⁠ךָ וְ⁠אַל־תִּ֝טֹּ֗שׁ תּוֹרַ֥ת אִמֶּֽ⁠ךָ׃","şĕ̌ma֣ʻ bĕ֭̇ni⁠y mẇsa֣r ʼábi֑y⁠ká wĕ⁠ʼal-ţi̇֝tò̇֗ş̌ ţ̇wòra֥ţ ʼimėֽ⁠ká׃"],[1,9,"כִּ֤י ׀ לִוְיַ֤ת חֵ֓ן הֵ֬ם לְ⁠רֹאשֶׁ֑⁠ךָ וַ֝⁠עֲנָקִ֗ים לְ⁠גַרְגְּרֹתֶֽי⁠ךָ׃","ki֤̇y ׀ liwĕya֤ţ ẖé֓n hé֬m lĕ⁠ròʼşě֑⁠ká wa֝⁠ʻànáqi֗ym lĕ⁠garĕgĕ̇ròţeֽy⁠ká׃"],[1,10,"בְּנִ֡⁠י אִם־יְפַתּ֥וּ⁠ךָ חַ֝טָּאִ֗ים אַל־תֹּבֵֽא׃","bĕ̇ni֡⁠y ʼim-yĕpaţ֥̇ẇ⁠ká ẖa֝tá̇ʼi֗ym ʼal-ţò̇béֽʼ׃"],[1,11,"אִם־יֹאמְרוּ֮ לְכָ֪⁠ה אִ֫תָּ֥⁠נוּ נֶאֶרְבָ֥ה לְ⁠דָ֑ם נִצְפְּנָ֖ה לְ⁠נָקִ֣י חִנָּֽם׃","ʼim-yòʼmĕrẇ֮ lĕká֪⁠h ʼi֫ţá֥̇⁠nẇ neʼerĕbá֥h lĕ⁠dá֑m niẕĕpĕ̇ná֖h lĕ⁠náqi֣y ẖináֽ̇m׃"],[1,12,"נִ֭בְלָעֵ⁠ם כִּ⁠שְׁא֣וֹל חַיִּ֑ים וּ֝⁠תְמִימִ֗ים כְּ⁠י֣וֹרְדֵי בֽוֹר׃","ni֭bĕláʻé⁠m ki̇⁠şĕ̌ʼ֣wòl ẖayi֑̇ym ẇ֝⁠ţĕmiymi֗ym kĕ̇⁠y֣wòrĕdéy bֽwòr׃"],[1,13,"כָּל־ה֣וֹן יָקָ֣ר נִמְצָ֑א נְמַלֵּ֖א בָתֵּ֣י⁠נוּ שָׁלָֽל׃","ká̇l-h֣wòn yáqá֣r nimĕẕá֑ʼ nĕmalé֖̇ʼ báţé֣̇y⁠nẇ şá̌láֽl׃"],[1,14,"גּ֭וֹרָ֣לְ⁠ךָ תַּפִּ֣יל בְּ⁠תוֹכֵ֑⁠נוּ כִּ֥יס אֶ֝חָ֗ד יִהְיֶ֥ה לְ⁠כֻלָּֽ⁠נוּ׃","ġ֭wòrá֣lĕ⁠ká ţȧpi֣̇yl bĕ̇⁠ţwòké֑⁠nẇ ki֥̇ys ʼe֝ẖá֗d yihĕye֥h lĕ⁠kuláֽ̇⁠nẇ׃"],[1,15,"בְּנִ֗⁠י אַל־תֵּלֵ֣ךְ בְּ⁠דֶ֣רֶךְ אִתָּ֑⁠ם מְנַ֥ע רַ֝גְלְ⁠ךָ֗ מִ⁠נְּתִיבָתָֽ⁠ם׃","bĕ̇ni֗⁠y ʼal-ţé̇lé֣kĕ bĕ̇⁠de֣rekĕ ʼiţá֑̇⁠m mĕna֥ʻ ra֝gĕlĕ⁠ká֗ mi⁠nĕ̇ţiybáţáֽ⁠m׃"],[1,16,"כִּ֣י רַ֭גְלֵי⁠הֶם לָ⁠רַ֣ע יָר֑וּצוּ וִֽ֝⁠ימַהֲר֗וּ לִ⁠שְׁפָּךְ־דָּֽם׃","ki֣̇y ra֭gĕléy⁠hem lá⁠ra֣ʻ yár֑ẇẕẇ wiֽ֝⁠ymahàr֗ẇ li⁠şĕ̌pá̇kĕ-dáֽ̇m׃"],[1,17,"כִּֽי־חִ֭נָּם מְזֹרָ֣ה הָ⁠רָ֑שֶׁת בְּ֝⁠עֵינֵ֗י כָל־בַּ֥עַל כָּנָֽף׃","kiֽ̇y-ẖi֭ná̇m mĕzòrá֣h há⁠rá֑şěţ bĕ̇֝⁠ʻéyné֗y kál-bȧ֥ʻal ká̇náֽp׃"],[1,18,"וְ֭⁠הֵם לְ⁠דָמָ֣⁠ם יֶאֱרֹ֑בוּ יִ֝צְפְּנ֗וּ לְ⁠נַפְשֹׁתָֽ⁠ם׃","wĕ֭⁠hém lĕ⁠dámá֣⁠m yeʼèrò֑bẇ yi֝ẕĕpĕ̇n֗ẇ lĕ⁠napĕşò̌ţáֽ⁠m׃"],[1,19,"כֵּ֗ן אָ֭רְחוֹת כָּל־בֹּ֣צֵֽעַ בָּ֑צַע אֶת־נֶ֖פֶשׁ בְּעָלָ֣י⁠ו יִקָּֽח׃פ","ké̇֗n ʼá֭rĕẖwòţ ká̇l-bò֣̇ẕéֽʻa bá֑̇ẕaʻ ʼeţ-ne֖peş̌ bĕ̇ʻálá֣y⁠w yiqáֽ̇ẖ׃p"],[1,20,"חָ֭כְמוֹת בַּ⁠ח֣וּץ תָּרֹ֑נָּה בָּ֝⁠רְחֹב֗וֹת תִּתֵּ֥ן קוֹלָֽ⁠הּ׃","ẖá֭kĕmwòţ bȧ⁠ẖ֣ẇẕ ţá̇rò֑ná̇h bá̇֝⁠rĕẖòb֗wòţ ţi̇ţé֥̇n qwòláֽ⁠ḣ׃"],[1,21,"בְּ⁠רֹ֥אשׁ הֹמִיּ֗וֹת תִּ֫קְרָ֥א בְּ⁠פִתְחֵ֖י שְׁעָרִ֥ים בָּ⁠עִ֗יר אֲמָרֶ֥י⁠הָ תֹאמֵֽר׃","bĕ̇⁠rò֥ʼş̌ hòmiẏ֗wòţ ţi̇֫qĕrá֥ʼ bĕ̇⁠piţĕẖé֖y şĕ̌ʻári֥ym bá̇⁠ʻi֗yr ʼàmáre֥y⁠há ţòʼméֽr׃"],[1,22,"עַד־מָתַ֣י ׀ פְּתָיִם֮ תְּֽאֵהֲב֫וּ פֶ֥תִי וְ⁠לֵצִ֗ים לָ֭צוֹן חָמְד֣וּ לָ⁠הֶ֑ם וּ֝⁠כְסִילִ֗ים יִשְׂנְאוּ־דָֽעַת׃","ʻad-máţa֣y ׀ pĕ̇ţáyim֮ ţĕֽ̇ʼéhàb֫ẇ pe֥ţiy wĕ⁠léẕi֗ym lá֭ẕwòn ẖámĕd֣ẇ lá⁠he֑m ẇ֝⁠kĕsiyli֗ym yişĕ̂nĕʼẇ-dáֽʻaţ׃"],[1,23,"תָּשׁ֗וּבוּ לְֽ⁠ת֫וֹכַחְתִּ֥⁠י הִנֵּ֤ה אַבִּ֣יעָה לָ⁠כֶ֣ם רוּחִ֑⁠י אוֹדִ֖יעָה דְבָרַ֣⁠י אֶתְ⁠כֶֽם׃","ţá̇ş̌֗ẇbẇ lĕֽ⁠ţ֫wòkaẖĕţi֥̇⁠y hiné֤̇h ʼabi֣̇yʻáh lá⁠ke֣m rẇẖi֑⁠y ʼwòdi֖yʻáh dĕbára֣⁠y ʼeţĕ⁠keֽm׃"],[1,24,"יַ֣עַן קָ֭רָאתִי וַ⁠תְּמָאֵ֑נוּ נָטִ֥יתִי יָ֝דִ֗⁠י וְ⁠אֵ֣ין מַקְשִֽׁיב׃","ya֣ʻan qá֭ráʼţiy wa⁠ţĕ̇máʼé֑nẇ náti֥yţiy yá֝di֗⁠y wĕ⁠ʼé֣yn maqĕşǐֽyb׃"],[1,25,"וַ⁠תִּפְרְע֥וּ כָל־עֲצָתִ֑⁠י וְ֝⁠תוֹכַחְתִּ֗⁠י לֹ֣א אֲבִיתֶֽם׃","wa⁠ţi̇pĕrĕʻ֥ẇ kál-ʻàẕáţi֑⁠y wĕ֝⁠ţwòkaẖĕţi̇֗⁠y lò֣ʼ ʼàbiyţeֽm׃"],[1,26,"גַּם־אֲ֭נִי בְּ⁠אֵידְ⁠כֶ֣ם אֶשְׂחָ֑ק אֶ֝לְעַ֗ג בְּ⁠בֹ֣א פַחְדְּ⁠כֶֽם׃","gȧm-ʼà֭niy bĕ̇⁠ʼéydĕ⁠ke֣m ʼeşĕ̂ẖá֑q ʼe֝lĕʻa֗g bĕ̇⁠bò֣ʼ paẖĕdĕ̇⁠keֽm׃"],[1,27,"בְּ⁠בֹ֤א כ⁠שאוה ׀ פַּחְדְּ⁠כֶ֗ם וְֽ֭⁠אֵידְ⁠כֶם כְּ⁠סוּפָ֣ה יֶאֱתֶ֑ה בְּ⁠בֹ֥א עֲ֝לֵי⁠כֶ֗ם צָרָ֥ה וְ⁠צוּקָֽה׃","bĕ̇⁠bò֤ʼ k⁠şʼwh ׀ pȧẖĕdĕ̇⁠ke֗m wĕֽ֭⁠ʼéydĕ⁠kem kĕ̇⁠sẇpá֣h yeʼèţe֑h bĕ̇⁠bò֥ʼ ʻà֝léy⁠ke֗m ẕárá֥h wĕ⁠ẕẇqáֽh׃"],[1,28,"אָ֣ז יִ֭קְרָאֻ⁠נְנִי וְ⁠לֹ֣א אֶֽעֱנֶ֑ה יְ֝שַׁחֲרֻ֗⁠נְנִי וְ⁠לֹ֣א יִמְצָאֻֽ⁠נְנִי׃","ʼá֣z yi֭qĕráʼu⁠nĕniy wĕ⁠lò֣ʼ ʼeֽʻène֑h yĕ֝şǎẖàru֗⁠nĕniy wĕ⁠lò֣ʼ yimĕẕáʼuֽ⁠nĕniy׃"],[1,29,"תַּ֭חַת כִּי־שָׂ֣נְאוּ דָ֑עַת וְ⁠יִרְאַ֥ת יְ֝הֹוָ֗ה לֹ֣א בָחָֽרוּ׃","ţȧ֭ẖaţ ki̇y-şá֣̂nĕʼẇ dá֑ʻaţ wĕ⁠yirĕʼa֥ţ yĕ֝hòwá֗h lò֣ʼ báẖáֽrẇ׃"],[1,30,"לֹא־אָב֥וּ לַ⁠עֲצָתִ֑⁠י נָ֝אֲצ֗וּ כָּל־תּוֹכַחְתִּֽ⁠י׃","lòʼ-ʼáb֥ẇ la⁠ʻàẕáţi֑⁠y ná֝ʼàẕ֗ẇ ká̇l-ţ̇wòkaẖĕţiֽ̇⁠y׃"],[1,31,"וְֽ֭⁠יֹאכְלוּ מִ⁠פְּרִ֣י דַרְכָּ֑⁠ם וּֽ⁠מִ⁠מֹּעֲצֹ֖תֵי⁠הֶ֣ם יִשְׂבָּֽעוּ׃","wĕֽ֭⁠yòʼkĕlẇ mi⁠pĕ̇ri֣y darĕká֑̇⁠m ẇֽ⁠mi⁠mò̇ʻàẕò֖ţéy⁠he֣m yişĕ̂báֽ̇ʻẇ׃"],[1,32,"כִּ֤י מְשׁוּבַ֣ת פְּתָיִ֣ם תַּֽהַרְגֵ֑⁠ם וְ⁠שַׁלְוַ֖ת כְּסִילִ֣ים תְּאַבְּדֵֽ⁠ם׃","ki֤̇y mĕş̌ẇba֣ţ pĕ̇ţáyi֣m ţȧֽharĕgé֑⁠m wĕ⁠şǎlĕwa֖ţ kĕ̇siyli֣ym ţĕ̇ʼabĕ̇déֽ⁠m׃"],[1,33,"וְ⁠שֹׁמֵ֣עַֽ לִ֭⁠י יִשְׁכָּן־בֶּ֑טַח וְ֝⁠שַׁאֲנַ֗ן מִ⁠פַּ֥חַד רָעָֽה׃פ","wĕ⁠şò̌mé֣ʻaֽ li֭⁠y yişĕ̌ká̇n-bė֑taẖ wĕ֝⁠şǎʼàna֗n mi⁠pȧ֥ẖad ráʻáֽh׃p"],[2,1,"בְּ֭נִ⁠י אִם־תִּקַּ֣ח אֲמָרָ֑⁠י וּ֝⁠מִצְוֺתַ֗⁠י תִּצְפֹּ֥ן אִתָּֽ⁠ךְ׃","bĕ֭̇ni⁠y ʼim-ţi̇qȧ֣ẖ ʼàmárá֑⁠y ẇ֝⁠miẕĕwֺţa֗⁠y ţi̇ẕĕpò֥̇n ʼiţáֽ̇⁠kĕ׃"],[2,2,"לְ⁠הַקְשִׁ֣יב לַֽ⁠חָכְמָ֣ה אָזְנֶ֑⁠ךָ תַּטֶּ֥ה לִ֝בְּ⁠ךָ֗ לַ⁠תְּבוּנָֽה׃","lĕ⁠haqĕşǐ֣yb laֽ⁠ẖákĕmá֣h ʼázĕne֑⁠ká ţȧtė֥h li֝bĕ̇⁠ká֗ la⁠ţĕ̇bẇnáֽh׃"],[2,3,"כִּ֤י אִ֣ם לַ⁠בִּינָ֣ה תִקְרָ֑א לַ֝⁠תְּבוּנָ֗ה תִּתֵּ֥ן קוֹלֶֽ⁠ךָ׃","ki֤̇y ʼi֣m la⁠bi̇yná֣h ţiqĕrá֑ʼ la֝⁠ţĕ̇bẇná֗h ţi̇ţé֥̇n qwòleֽ⁠ká׃"],[2,4,"אִם־תְּבַקְשֶׁ֥⁠נָּה כַ⁠כָּ֑סֶף וְֽ⁠כַ⁠מַּטְמוֹנִ֥ים תַּחְפְּשֶֽׂ⁠נָּה׃","ʼim-ţĕ̇baqĕşě֥⁠ná̇h ka⁠ká֑̇sep wĕֽ⁠ka⁠mȧtĕmwòni֥ym ţȧẖĕpĕ̇şêֽ⁠ná̇h׃"],[2,5,"אָ֗ז תָּ֭בִין יִרְאַ֣ת יְהוָ֑ה וְ⁠דַ֖עַת אֱלֹהִ֣ים תִּמְצָֽא׃","ʼá֗z ţá֭̇biyn yirĕʼa֣ţ yĕhwá֑h wĕ⁠da֖ʻaţ ʼèlòhi֣ym ţi̇mĕẕáֽʼ׃"],[2,6,"כִּֽי־יְ֭הוָה יִתֵּ֣ן חָכְמָ֑ה מִ֝⁠פִּ֗י⁠ו דַּ֣עַת וּ⁠תְבוּנָֽה׃","kiֽ̇y-yĕ֭hwáh yiţé֣̇n ẖákĕmá֑h mi֝⁠pi̇֗y⁠w dȧ֣ʻaţ ẇ⁠ţĕbẇnáֽh׃"],[2,7,"ו⁠צפן לַ֭⁠יְשָׁרִים תּוּשִׁיָּ֑ה מָ֝גֵ֗ן לְ⁠הֹ֣לְכֵי תֹֽם׃","w⁠ẕpn la֭⁠yĕşá̌riym ţ̇ẇşǐyá֑̇h má֝gé֗n lĕ⁠hò֣lĕkéy ţòֽm׃"],[2,8,"לִ֭⁠נְצֹר אָרְח֣וֹת מִשְׁפָּ֑ט וְ⁠דֶ֖רֶךְ חסיד⁠ו יִשְׁמֹֽר׃","li֭⁠nĕẕòr ʼárĕẖ֣wòţ mişĕ̌pá֑̇t wĕ⁠de֖rekĕ ẖsyd⁠w yişĕ̌mòֽr׃"],[2,9,"אָ֗ז תָּ֭בִין צֶ֣דֶק וּ⁠מִשְׁפָּ֑ט וּ֝⁠מֵישָׁרִ֗ים כָּל־מַעְגַּל־טֽוֹב׃","ʼá֗z ţá֭̇biyn ẕe֣deq ẇ⁠mişĕ̌pá֑̇t ẇ֝⁠méyşá̌ri֗ym ká̇l-maʻĕgȧl-tֽwòb׃"],[2,10,"כִּֽי־תָב֣וֹא חָכְמָ֣ה בְ⁠לִבֶּ֑⁠ךָ וְ֝⁠דַ֗עַת לְֽ⁠נַפְשְׁ⁠ךָ֥ יִנְעָֽם׃","kiֽ̇y-ţáb֣wòʼ ẖákĕmá֣h bĕ⁠libė֑⁠ká wĕ֝⁠da֗ʻaţ lĕֽ⁠napĕşĕ̌⁠ká֥ yinĕʻáֽm׃"],[2,11,"מְ֭זִמָּה תִּשְׁמֹ֥ר עָלֶ֗י⁠ךָ תְּבוּנָ֥ה תִנְצְרֶֽ⁠כָּה׃","mĕ֭zimá̇h ţi̇şĕ̌mò֥r ʻále֗y⁠ká ţĕ̇bẇná֥h ţinĕẕĕreֽ⁠ká̇h׃"],[2,12,"לְ֭⁠הַצִּ֣ילְ⁠ךָ מִ⁠דֶּ֣רֶךְ רָ֑ע מֵ֝⁠אִ֗ישׁ מְדַבֵּ֥ר תַּהְפֻּכֽוֹת׃","lĕ֭⁠haẕi֣̇ylĕ⁠ká mi⁠dė֣rekĕ rá֑ʻ mé֝⁠ʼi֗yş̌ mĕdabé֥̇r ţȧhĕpu̇kֽwòţ׃"],[2,13,"הַ֭⁠עֹ֣זְבִים אָרְח֣וֹת יֹ֑שֶׁר לָ֝⁠לֶ֗כֶת בְּ⁠דַרְכֵי־חֹֽשֶׁךְ׃","ha֭⁠ʻò֣zĕbiym ʼárĕẖ֣wòţ yò֑şěr lá֝⁠le֗keţ bĕ̇⁠darĕkéy-ẖòֽşěkĕ׃"],[2,14,"הַ֭⁠שְּׂמֵחִים לַ⁠עֲשׂ֥וֹת רָ֑ע יָ֝גִ֗ילוּ בְּֽ⁠תַהְפֻּכ֥וֹת רָֽע׃","ha֭⁠şĕ̇̂méẖiym la⁠ʻàş֥̂wòţ rá֑ʻ yá֝gi֗ylẇ bĕֽ̇⁠ţahĕpu̇k֥wòţ ráֽʻ׃"],[2,15,"אֲשֶׁ֣ר אָרְחֹתֵי⁠הֶ֣ם עִקְּשִׁ֑ים וּ֝⁠נְלוֹזִ֗ים בְּ⁠מַעְגְּלוֹתָֽ⁠ם׃","ʼàşě֣r ʼárĕẖòţéy⁠he֣m ʻiqĕ̇şǐ֑ym ẇ֝⁠nĕlwòzi֗ym bĕ̇⁠maʻĕgĕ̇lwòţáֽ⁠m׃"],[2,16,"לְ֭⁠הַצִּ֣ילְ⁠ךָ מֵ⁠אִשָּׁ֣ה זָרָ֑ה מִ֝⁠נָּכְרִיָּ֗ה אֲמָרֶ֥י⁠הָ הֶחֱלִֽיקָה׃","lĕ֭⁠haẕi֣̇ylĕ⁠ká mé⁠ʼişá֣̇̌h zárá֑h mi֝⁠ná̇kĕriyá̇֗h ʼàmáre֥y⁠há heẖèliֽyqáh׃"],[2,17,"הַ֭⁠עֹזֶבֶת אַלּ֣וּף נְעוּרֶ֑י⁠הָ וְ⁠אֶת־בְּרִ֖ית אֱלֹהֶ֣י⁠הָ שָׁכֵֽחָה׃","ha֭⁠ʻòzebeţ ʼal֣̇ẇp nĕʻẇre֑y⁠há wĕ⁠ʼeţ-bĕ̇ri֖yţ ʼèlòhe֣y⁠há şá̌kéֽẖáh׃"],[2,18,"כִּ֤י שָׁ֣חָה אֶל־מָ֣וֶת בֵּיתָ֑⁠הּ וְ⁠אֶל־רְ֝פָאִ֗ים מַעְגְּלֹתֶֽי⁠הָ׃","ki֤̇y şá֣̌ẖáh ʼel-má֣weţ bé̇yţá֑⁠ḣ wĕ⁠ʼel-rĕ֝páʼi֗ym maʻĕgĕ̇lòţeֽy⁠há׃"],[2,19,"כָּל־בָּ֭אֶי⁠הָ לֹ֣א יְשׁוּב֑וּ⁠ן וְ⁠לֹֽא־יַ֝שִּׂ֗יגוּ אָרְח֥וֹת חַיִּֽים׃","ká̇l-bá֭̇ʼey⁠há lò֣ʼ yĕş̌ẇb֑ẇ⁠n wĕ⁠lòֽʼ-ya֝şi̇̂֗ygẇ ʼárĕẖ֥wòţ ẖayiֽ̇ym׃"],[2,20,"לְמַ֗עַן תֵּ֭לֵךְ בְּ⁠דֶ֣רֶךְ טוֹבִ֑ים וְ⁠אָרְח֖וֹת צַדִּיקִ֣ים תִּשְׁמֹֽר׃","lĕma֗ʻan ţé֭̇lékĕ bĕ̇⁠de֣rekĕ twòbi֑ym wĕ⁠ʼárĕẖ֖wòţ ẕadi̇yqi֣ym ţi̇şĕ̌mòֽr׃"],[2,21,"כִּֽי־יְשָׁרִ֥ים יִשְׁכְּנוּ אָ֑רֶץ וּ֝⁠תְמִימִ֗ים יִוָּ֥תְרוּ בָֽ⁠הּ׃","kiֽ̇y-yĕşá̌ri֥ym yişĕ̌kĕ̇nẇ ʼá֑reẕ ẇ֝⁠ţĕmiymi֗ym yiwá֥̇ţĕrẇ báֽ⁠ḣ׃"],[2,22,"וּ֭⁠רְשָׁעִים מֵ⁠אֶ֣רֶץ יִכָּרֵ֑תוּ וּ֝⁠בוֹגְדִ֗ים יִסְּח֥וּ מִמֶּֽ⁠נָּה׃פ","ẇ֭⁠rĕşá̌ʻiym mé⁠ʼe֣reẕ yiká̇ré֑ţẇ ẇ֝⁠bwògĕdi֗ym yisĕ̇ẖ֥ẇ mimėֽ⁠ná̇h׃p"],[3,1,"בְּ֭נִ⁠י תּוֹרָתִ֣⁠י אַל־תִּשְׁכָּ֑ח וּ֝⁠מִצְוֺתַ֗⁠י יִצֹּ֥ר לִבֶּֽ⁠ךָ׃","bĕ֭̇ni⁠y ţ̇wòráţi֣⁠y ʼal-ţi̇şĕ̌ká֑̇ẖ ẇ֝⁠miẕĕwֺţa֗⁠y yiẕò֥̇r libėֽ⁠ká׃"],[3,2,"כִּ֤י אֹ֣רֶךְ יָ֭מִים וּ⁠שְׁנ֣וֹת חַיִּ֑ים וְ֝⁠שָׁל֗וֹם יוֹסִ֥יפוּ לָֽ⁠ךְ׃","ki֤̇y ʼò֣rekĕ yá֭miym ẇ⁠şĕ̌n֣wòţ ẖayi֑̇ym wĕ֝⁠şá̌l֗wòm ywòsi֥ypẇ láֽ⁠kĕ׃"],[3,3,"חֶ֥סֶד וֶ⁠אֱמֶ֗ת אַֽל־יַעַ֫זְבֻ֥⁠ךָ קָשְׁרֵ֥⁠ם עַל־גַּרְגְּרוֹתֶ֑י⁠ךָ כָּ֝תְבֵ֗⁠ם עַל־ל֥וּחַ לִבֶּֽ⁠ךָ׃","ẖe֥sed we⁠ʼème֗ţ ʼaֽl-yaʻa֫zĕbu֥⁠ká qáşĕ̌ré֥⁠m ʻal-gȧrĕgĕ̇rwòţe֑y⁠ká ká̇֝ţĕbé֗⁠m ʻal-l֥ẇẖa libėֽ⁠ká׃"],[3,4,"וּ⁠מְצָא־חֵ֖ן וְ⁠שֵֽׂכֶל־ט֑וֹב בְּ⁠עֵינֵ֖י אֱלֹהִ֣ים וְ⁠אָדָֽם׃פ","ẇ⁠mĕẕáʼ-ẖé֖n wĕ⁠şéֽ̂kel-t֑wòb bĕ̇⁠ʻéyné֖y ʼèlòhi֣ym wĕ⁠ʼádáֽm׃p"],[3,5,"בְּטַ֣ח אֶל־יְ֭הוָה בְּ⁠כָל־לִבֶּ֑⁠ךָ וְ⁠אֶל־בִּֽ֝ינָתְ⁠ךָ֗ אַל־תִּשָּׁעֵֽן׃","bĕ̇ta֣ẖ ʼel-yĕ֭hwáh bĕ̇⁠kál-libė֑⁠ká wĕ⁠ʼel-biֽ̇֝ynáţĕ⁠ká֗ ʼal-ţi̇şá̇̌ʻéֽn׃"],[3,6,"בְּ⁠כָל־דְּרָכֶ֥י⁠ךָ דָעֵ֑⁠הוּ וְ֝⁠ה֗וּא יְיַשֵּׁ֥ר אֹֽרְחֹתֶֽי⁠ךָ׃","bĕ̇⁠kál-dĕ̇ráke֥y⁠ká dáʻé֑⁠hẇ wĕ֝⁠h֗ẇʼ yĕyaşé֥̇̌r ʼòֽrĕẖòţeֽy⁠ká׃"],[3,7,"אַל־תְּהִ֣י חָכָ֣ם בְּ⁠עֵינֶ֑י⁠ךָ יְרָ֥א אֶת־יְ֝הוָ֗ה וְ⁠ס֣וּר מֵ⁠רָֽע׃","ʼal-ţĕ̇hi֣y ẖáká֣m bĕ̇⁠ʻéyne֑y⁠ká yĕrá֥ʼ ʼeţ-yĕ֝hwá֗h wĕ⁠s֣ẇr mé⁠ráֽʻ׃"],[3,8,"רִ֭פְאוּת תְּהִ֣י לְ⁠שָׁרֶּ֑⁠ךָ וְ֝⁠שִׁקּ֗וּי לְ⁠עַצְמוֹתֶֽי⁠ךָ׃","ri֭pĕʼẇţ ţĕ̇hi֣y lĕ⁠şá̌rė֑⁠ká wĕ֝⁠şǐq̇֗ẇy lĕ⁠ʻaẕĕmwòţeֽy⁠ká׃"],[3,9,"כַּבֵּ֣ד אֶת־יְ֭הוָה מֵ⁠הוֹנֶ֑⁠ךָ וּ֝⁠מֵ⁠רֵאשִׁ֗ית כָּל־תְּבוּאָתֶֽ⁠ךָ׃","kȧbé֣̇d ʼeţ-yĕ֭hwáh mé⁠hwòne֑⁠ká ẇ֝⁠mé⁠réʼşǐ֗yţ ká̇l-ţĕ̇bẇʼáţeֽ⁠ká׃"],[3,10,"וְ⁠יִמָּלְא֣וּ אֲסָמֶ֣י⁠ךָ שָׂבָ֑ע וְ֝⁠תִיר֗וֹשׁ יְקָבֶ֥י⁠ךָ יִפְרֹֽצוּ׃פ","wĕ⁠yimá̇lĕʼ֣ẇ ʼàsáme֣y⁠ká şá̂bá֑ʻ wĕ֝⁠ţiyr֗wòş̌ yĕqábe֥y⁠ká yipĕròֽẕẇ׃p"],[3,11,"מוּסַ֣ר יְ֭הוָה בְּנִ֣⁠י אַל־תִּמְאָ֑ס וְ⁠אַל־תָּ֝קֹ֗ץ בְּ⁠תוֹכַחְתּֽ⁠וֹ׃","mẇsa֣r yĕ֭hwáh bĕ̇ni֣⁠y ʼal-ţi̇mĕʼá֑s wĕ⁠ʼal-ţá̇֝qò֗ẕ bĕ̇⁠ţwòkaẖĕţֽ̇⁠wò׃"],[3,12,"כִּ֤י אֶ֥ת אֲשֶׁ֣ר יֶאֱהַ֣ב יְהוָ֣ה יוֹכִ֑יחַ וּ֝⁠כְ⁠אָ֗ב אֶת־בֵּ֥ן יִרְצֶֽה׃","ki֤̇y ʼe֥ţ ʼàşě֣r yeʼèha֣b yĕhwá֣h ywòki֑yẖa ẇ֝⁠kĕ⁠ʼá֗b ʼeţ-bé֥̇n yirĕẕeֽh׃"],[3,13,"אַשְׁרֵ֣י אָ֭דָם מָצָ֣א חָכְמָ֑ה וְ֝⁠אָדָ֗ם יָפִ֥יק תְּבוּנָֽה׃","ʼaşĕ̌ré֣y ʼá֭dám máẕá֣ʼ ẖákĕmá֑h wĕ֝⁠ʼádá֗m yápi֥yq ţĕ̇bẇnáֽh׃"],[3,14,"כִּ֤י ט֣וֹב סַ֭חְרָ⁠הּ מִ⁠סְּחַר־כָּ֑סֶף וּ֝⁠מֵ⁠חָר֗וּץ תְּבוּאָתָֽ⁠הּ׃","ki֤̇y t֣wòb sa֭ẖĕrá⁠ḣ mi⁠sĕ̇ẖar-ká֑̇sep ẇ֝⁠mé⁠ẖár֗ẇẕ ţĕ̇bẇʼáţáֽ⁠ḣ׃"],[3,15,"יְקָ֣רָה הִ֭יא מ⁠פניים וְ⁠כָל־חֲ֝פָצֶ֗י⁠ךָ לֹ֣א יִֽשְׁווּ־בָֽ⁠הּ׃","yĕqá֣ráh hi֭yʼ m⁠pnyym wĕ⁠kál-ẖà֝páẕe֗y⁠ká lò֣ʼ yiֽşĕ̌wẇ-báֽ⁠ḣ׃"],[3,16,"אֹ֣רֶךְ יָ֭מִים בִּֽ⁠ימִינָ֑⁠הּ בִּ֝⁠שְׂמֹאולָ֗⁠הּ עֹ֣שֶׁר וְ⁠כָבֽוֹד׃","ʼò֣rekĕ yá֭miym biֽ̇⁠ymiyná֑⁠ḣ bi̇֝⁠şĕ̂mòʼwlá֗⁠ḣ ʻò֣şěr wĕ⁠kábֽwòd׃"],[3,17,"דְּרָכֶ֥י⁠הָ דַרְכֵי־נֹ֑עַם וְֽ⁠כָל־נְתִ֖יבוֹתֶ֣י⁠הָ שָׁלֽוֹם׃","dĕ̇ráke֥y⁠há darĕkéy-nò֑ʻam wĕֽ⁠kál-nĕţi֖ybwòţe֣y⁠há şá̌lֽwòm׃"],[3,18,"עֵץ־חַיִּ֣ים הִ֭יא לַ⁠מַּחֲזִיקִ֣ים בָּ֑⁠הּ וְֽ⁠תֹמְכֶ֥י⁠הָ מְאֻשָּֽׁר׃פ","ʻéẕ-ẖayi֣̇ym hi֭yʼ la⁠mȧẖàziyqi֣ym bá֑̇⁠ḣ wĕֽ⁠ţòmĕke֥y⁠há mĕʼuşáֽ̇̌r׃p"],[3,19,"יְֽהוָ֗ה בְּ⁠חָכְמָ֥ה יָֽסַד־אָ֑רֶץ כּוֹנֵ֥ן שָׁ֝מַ֗יִם בִּ⁠תְבוּנָֽה׃","yĕֽhwá֗h bĕ̇⁠ẖákĕmá֥h yáֽsad-ʼá֑reẕ k̇wòné֥n şá̌֝ma֗yim bi̇⁠ţĕbẇnáֽh׃"],[3,20,"בְּ֭⁠דַעְתּ⁠וֹ תְּהוֹמ֣וֹת נִבְקָ֑עוּ וּ֝⁠שְׁחָקִ֗ים יִרְעֲפוּ־טָֽל׃","bĕ֭̇⁠daʻĕţ̇⁠wò ţĕ̇hwòm֣wòţ nibĕqá֑ʻẇ ẇ֝⁠şĕ̌ẖáqi֗ym yirĕʻàpẇ-táֽl׃"],[3,21,"בְּ֭נִ⁠י אַל־יָלֻ֣זוּ מֵ⁠עֵינֶ֑י⁠ךָ נְצֹ֥ר תֻּ֝שִׁיָּ֗ה וּ⁠מְזִמָּֽה׃","bĕ֭̇ni⁠y ʼal-yálu֣zẇ mé⁠ʻéyne֑y⁠ká nĕẕò֥r ţu̇֝şǐyá̇֗h ẇ⁠mĕzimáֽ̇h׃"],[3,22,"וְ⁠יִֽהְי֣וּ חַיִּ֣ים לְ⁠נַפְשֶׁ֑⁠ךָ וְ֝⁠חֵ֗ן לְ⁠גַרְגְּרֹתֶֽי⁠ךָ׃","wĕ⁠yiֽhĕy֣ẇ ẖayi֣̇ym lĕ⁠napĕşě֑⁠ká wĕ֝⁠ẖé֗n lĕ⁠garĕgĕ̇ròţeֽy⁠ká׃"],[3,23,"אָ֤ז תֵּלֵ֣ךְ לָ⁠בֶ֣טַח דַּרְכֶּ֑⁠ךָ וְ֝⁠רַגְלְ⁠ךָ֗ לֹ֣א תִגּֽוֹף׃","ʼá֤z ţé̇lé֣kĕ lá⁠be֣taẖ dȧrĕkė֑⁠ká wĕ֝⁠ragĕlĕ⁠ká֗ lò֣ʼ ţiġֽwòp׃"],[3,24,"אִם־תִּשְׁכַּ֥ב לֹֽא־תִפְחָ֑ד וְ֝⁠שָׁכַבְתָּ֗ וְֽ⁠עָרְבָ֥ה שְׁנָתֶֽ⁠ךָ׃","ʼim-ţi̇şĕ̌kȧ֥b lòֽʼ-ţipĕẖá֑d wĕ֝⁠şá̌kabĕţá̇֗ wĕֽ⁠ʻárĕbá֥h şĕ̌náţeֽ⁠ká׃"],[3,25,"אַל־תִּ֭ירָא מִ⁠פַּ֣חַד פִּתְאֹ֑ם וּ⁠מִ⁠שֹּׁאַ֥ת רְ֝שָׁעִ֗ים כִּ֣י תָבֹֽא׃","ʼal-ţi֭̇yráʼ mi⁠pȧ֣ẖad pi̇ţĕʼò֑m ẇ⁠mi⁠şò̇̌ʼa֥ţ rĕ֝şá̌ʻi֗ym ki֣̇y ţábòֽʼ׃"],[3,26,"כִּֽי־יְ֭הוָה יִהְיֶ֣ה בְ⁠כִסְלֶ֑⁠ךָ וְ⁠שָׁמַ֖ר רַגְלְ⁠ךָ֣ מִ⁠לָּֽכֶד׃","kiֽ̇y-yĕ֭hwáh yihĕye֣h bĕ⁠kisĕle֑⁠ká wĕ⁠şá̌ma֖r ragĕlĕ⁠ká֣ mi⁠láֽ̇ked׃"],[3,27,"אַל־תִּמְנַע־ט֥וֹב מִ⁠בְּעָלָ֑י⁠ו בִּ⁠הְי֨וֹת לְ⁠אֵ֖ל ידי⁠ך לַ⁠עֲשֽׂוֹת׃","ʼal-ţi̇mĕnaʻ-t֥wòb mi⁠bĕ̇ʻálá֑y⁠w bi̇⁠hĕy֨wòţ lĕ⁠ʼé֖l ydy⁠k la⁠ʻàşֽ̂wòţ׃"],[3,28,"אַל־תֹּ֘אמַ֤ר ל⁠רעי⁠ך ׀ לֵ֣ךְ וָ֭⁠שׁוּב וּ⁠מָחָ֥ר אֶתֵּ֗ן וְ⁠יֵ֣שׁ אִתָּֽ⁠ךְ׃","ʼal-ţò̇֘ʼma֤r l⁠rʻy⁠k ׀ lé֣kĕ wá֭⁠ş̌ẇb ẇ⁠máẖá֥r ʼeţé̇֗n wĕ⁠yé֣ş̌ ʼiţáֽ̇⁠kĕ׃"],[3,29,"אַל־תַּחֲרֹ֣שׁ עַל־רֵעֲ⁠ךָ֣ רָעָ֑ה וְ⁠הֽוּא־יוֹשֵׁ֖ב לָ⁠בֶ֣טַח אִתָּֽ⁠ךְ׃","ʼal-ţȧẖàrò֣ş̌ ʻal-réʻà⁠ká֣ ráʻá֑h wĕ⁠hֽẇʼ-ywòşé֖̌b lá⁠be֣taẖ ʼiţáֽ̇⁠kĕ׃"],[3,30,"אַל־תרוב עִם־אָדָ֣ם חִנָּ֑ם אִם־לֹ֖א גְמָלְ⁠ךָ֣ רָעָֽה׃","ʼal-ţrwb ʻim-ʼádá֣m ẖiná֑̇m ʼim-lò֖ʼ gĕmálĕ⁠ká֣ ráʻáֽh׃"],[3,31,"אַל־תְּ֭קַנֵּא בְּ⁠אִ֣ישׁ חָמָ֑ס וְ⁠אַל־תִּ֝בְחַ֗ר בְּ⁠כָל־דְּרָכָֽי⁠ו׃","ʼal-ţĕ֭̇qané̇ʼ bĕ̇⁠ʼi֣yş̌ ẖámá֑s wĕ⁠ʼal-ţi̇֝bĕẖa֗r bĕ̇⁠kál-dĕ̇rákáֽy⁠w׃"],[3,32,"כִּ֤י תוֹעֲבַ֣ת יְהוָ֣ה נָל֑וֹז וְֽ⁠אֶת־יְשָׁרִ֥ים סוֹדֽ⁠וֹ׃","ki֤̇y ţwòʻàba֣ţ yĕhwá֣h nál֑wòz wĕֽ⁠ʼeţ-yĕşá̌ri֥ym swòdֽ⁠wò׃"],[3,33,"מְאֵרַ֣ת יְ֭הוָה בְּ⁠בֵ֣ית רָשָׁ֑ע וּ⁠נְוֵ֖ה צַדִּיקִ֣ים יְבָרֵֽךְ׃","mĕʼéra֣ţ yĕ֭hwáh bĕ̇⁠bé֣yţ ráşá֑̌ʻ ẇ⁠nĕwé֖h ẕadi̇yqi֣ym yĕbáréֽkĕ׃"],[3,34,"אִם־לַ⁠לֵּצִ֥ים הֽוּא־יָלִ֑יץ ו⁠ל⁠עניים יִתֶּן־חֵֽן׃","ʼim-la⁠lé̇ẕi֥ym hֽẇʼ-yáli֑yẕ w⁠l⁠ʻnyym yiţėn-ẖéֽn׃"],[3,35,"כָּ֭בוֹד חֲכָמִ֣ים יִנְחָ֑לוּ וּ֝⁠כְסִילִ֗ים מֵרִ֥ים קָלֽוֹן׃פ","ká֭̇bwòd ẖàkámi֣ym yinĕẖá֑lẇ ẇ֝⁠kĕsiyli֗ym méri֥ym qálֽwòn׃p"],[4,1,"שִׁמְע֣וּ בָ֭נִים מ֣וּסַר אָ֑ב וְ֝⁠הַקְשִׁ֗יבוּ לָ⁠דַ֥עַת בִּינָֽה׃","şǐmĕʻ֣ẇ bá֭niym m֣ẇsar ʼá֑b wĕ֝⁠haqĕşǐ֗ybẇ lá⁠da֥ʻaţ bi̇ynáֽh׃"],[4,2,"כִּ֤י לֶ֣קַח ט֭וֹב נָתַ֣תִּי לָ⁠כֶ֑ם תּֽ֝וֹרָתִ֗⁠י אַֽל־תַּעֲזֹֽבוּ׃","ki֤̇y le֣qaẖ t֭wòb náţa֣ţi̇y lá⁠ke֑m ţֽ̇֝wòráţi֗⁠y ʼaֽl-ţȧʻàzòֽbẇ׃"],[4,3,"כִּי־בֵ֭ן הָיִ֣יתִי לְ⁠אָבִ֑⁠י רַ֥ךְ וְ֝⁠יָחִ֗יד לִ⁠פְנֵ֥י אִמִּֽ⁠י׃","ki̇y-bé֭n háyi֣yţiy lĕ⁠ʼábi֑⁠y ra֥kĕ wĕ֝⁠yáẖi֗yd li⁠pĕné֥y ʼimiֽ̇⁠y׃"],[4,4,"וַ⁠יֹּרֵ֗⁠נִי וַ⁠יֹּ֥אמֶר לִ֗⁠י יִֽתְמָךְ־דְּבָרַ֥⁠י לִבֶּ֑⁠ךָ שְׁמֹ֖ר מִצְוֺתַ֣⁠י וֶֽ⁠חְיֵֽה׃","wa⁠yò̇ré֗⁠niy wa⁠yò֥̇ʼmer li֗⁠y yiֽţĕmákĕ-dĕ̇bára֥⁠y libė֑⁠ká şĕ̌mò֖r miẕĕwֺţa֣⁠y weֽ⁠ẖĕyéֽh׃"],[4,5,"קְנֵ֣ה חָ֭כְמָה קְנֵ֣ה בִינָ֑ה אַל־תִּשְׁכַּ֥ח וְ⁠אַל־תֵּ֝֗ט מֵֽ⁠אִמְרֵי־פִֽ⁠י׃","qĕné֣h ẖá֭kĕmáh qĕné֣h biyná֑h ʼal-ţi̇şĕ̌kȧ֥ẖ wĕ⁠ʼal-ţé̇֝֗t méֽ⁠ʼimĕréy-piֽ⁠y׃"],[4,6,"אַל־תַּעַזְבֶ֥⁠הָ וְ⁠תִשְׁמְרֶ֑⁠ךָּ אֱהָבֶ֥⁠הָ וְ⁠תִצְּרֶֽ⁠ךָּ׃","ʼal-ţȧʻazĕbe֥⁠há wĕ⁠ţişĕ̌mĕre֑⁠ká̇ ʼèhábe֥⁠há wĕ⁠ţiẕĕ̇reֽ⁠ká̇׃"],[4,7,"רֵאשִׁ֣ית חָ֭כְמָה קְנֵ֣ה חָכְמָ֑ה וּ⁠בְ⁠כָל־קִ֝נְיָנְ⁠ךָ֗ קְנֵ֣ה בִינָֽה׃","réʼşǐ֣yţ ẖá֭kĕmáh qĕné֣h ẖákĕmá֑h ẇ⁠bĕ⁠kál-qi֝nĕyánĕ⁠ká֗ qĕné֣h biynáֽh׃"],[4,8,"סַלְסְלֶ֥⁠הָ וּֽ⁠תְרוֹמְמֶ֑⁠ךָּ תְּ֝כַבֵּ֗דְ⁠ךָ כִּ֣י תְחַבְּקֶֽ⁠נָּה׃","salĕsĕle֥⁠há ẇֽ⁠ţĕrwòmĕme֑⁠ká̇ ţĕ̇֝kabé̇֗dĕ⁠ká ki֣̇y ţĕẖabĕ̇qeֽ⁠ná̇h׃"],[4,9,"תִּתֵּ֣ן לְ֭⁠רֹאשְׁ⁠ךָ לִוְיַת־חֵ֑ן עֲטֶ֖רֶת תִּפְאֶ֣רֶת תְּמַגְּנֶֽ⁠ךָּ׃","ţi̇ţé֣̇n lĕ֭⁠ròʼşĕ̌⁠ká liwĕyaţ-ẖé֑n ʻàte֖reţ ţi̇pĕʼe֣reţ ţĕ̇magĕ̇neֽ⁠ká̇׃"],[4,10,"שְׁמַ֣ע בְּ֭נִ⁠י וְ⁠קַ֣ח אֲמָרָ֑⁠י וְ⁠יִרְבּ֥וּ לְ֝⁠ךָ֗ שְׁנ֣וֹת חַיִּֽים׃","şĕ̌ma֣ʻ bĕ֭̇ni⁠y wĕ⁠qa֣ẖ ʼàmárá֑⁠y wĕ⁠yirĕḃ֥ẇ lĕ֝⁠ká֗ şĕ̌n֣wòţ ẖayiֽ̇ym׃"],[4,11,"בְּ⁠דֶ֣רֶךְ חָ֭כְמָה הֹרֵתִ֑י⁠ךָ הִ֝דְרַכְתִּ֗י⁠ךָ בְּ⁠מַעְגְּלֵי־יֹֽשֶׁר׃","bĕ̇⁠de֣rekĕ ẖá֭kĕmáh hòréţi֑y⁠ká hi֝dĕrakĕţi̇֗y⁠ká bĕ̇⁠maʻĕgĕ̇léy-yòֽşěr׃"],[4,12,"בְּֽ֭⁠לֶכְתְּ⁠ךָ לֹא־יֵצַ֣ר צַעֲדֶ֑⁠ךָ וְ⁠אִם־תָּ֝ר֗וּץ לֹ֣א תִכָּשֵֽׁל׃","bĕֽ֭̇⁠lekĕţĕ̇⁠ká lòʼ-yéẕa֣r ẕaʻàde֑⁠ká wĕ⁠ʼim-ţá̇֝r֗ẇẕ lò֣ʼ ţiká̇şéֽ̌l׃"],[4,13,"הַחֲזֵ֣ק בַּ⁠מּוּסָ֣ר אַל־תֶּ֑רֶף נִ֝צְּרֶ֗⁠הָ כִּי־הִ֥יא חַיֶּֽי⁠ךָ׃","haẖàzé֣q bȧ⁠ṁẇsá֣r ʼal-ţė֑rep ni֝ẕĕ̇re֗⁠há ki̇y-hi֥yʼ ẖayėֽy⁠ká׃"],[4,14,"בְּ⁠אֹ֣רַח רְ֭שָׁעִים אַל־תָּבֹ֑א וְ⁠אַל־תְּ֝אַשֵּׁ֗ר בְּ⁠דֶ֣רֶךְ רָעִֽים׃","bĕ̇⁠ʼò֣raẖ rĕ֭şá̌ʻiym ʼal-ţá̇bò֑ʼ wĕ⁠ʼal-ţĕ̇֝ʼaşé̇̌֗r bĕ̇⁠de֣rekĕ ráʻiֽym׃"],[4,15,"פְּרָעֵ֥⁠הוּ אַל־תַּעֲבָר־בּ֑⁠וֹ שְׂטֵ֖ה מֵ⁠עָלָ֣י⁠ו וַ⁠עֲבֽוֹר׃","pĕ̇ráʻé֥⁠hẇ ʼal-ţȧʻàbár-ḃ֑⁠wò şĕ̂té֖h mé⁠ʻálá֣y⁠w wa⁠ʻàbֽwòr׃"],[4,16,"כִּ֤י לֹ֣א יִֽ֭שְׁנוּ אִם־לֹ֣א יָרֵ֑עוּ וְֽ⁠נִגְזְלָ֥ה שְׁ֝נָתָ֗⁠ם אִם־לֹ֥א יכשולו׃","ki֤̇y lò֣ʼ yiֽ֭şĕ̌nẇ ʼim-lò֣ʼ yáré֑ʻẇ wĕֽ⁠nigĕzĕlá֥h şĕ̌֝náţá֗⁠m ʼim-lò֥ʼ ykşwlw׃"],[4,17,"כִּ֣י לָ֭חֲמוּ לֶ֣חֶם רֶ֑שַׁע וְ⁠יֵ֖ין חֲמָסִ֣ים יִשְׁתּֽוּ׃","ki֣̇y lá֭ẖàmẇ le֣ẖem re֑şǎʻ wĕ⁠yé֖yn ẖàmási֣ym yişĕ̌ţֽ̇ẇ׃"],[4,18,"וְ⁠אֹ֣רַח צַ֭דִּיקִים כְּ⁠א֣וֹר נֹ֑גַהּ הוֹלֵ֥ךְ וָ֝⁠א֗וֹר עַד־נְכ֥וֹן הַ⁠יּֽוֹם׃","wĕ⁠ʼò֣raẖ ẕa֭di̇yqiym kĕ̇⁠ʼ֣wòr nò֑gaḣ hwòlé֥kĕ wá֝⁠ʼ֗wòr ʻad-nĕk֥wòn ha⁠ẏֽwòm׃"],[4,19,"דֶּ֣רֶךְ רְ֭שָׁעִים כָּֽ⁠אֲפֵלָ֑ה לֹ֥א יָ֝דְע֗וּ בַּ⁠מֶּ֥ה יִכָּשֵֽׁלוּ׃פ","dė֣rekĕ rĕ֭şá̌ʻiym káֽ̇⁠ʼàpélá֑h lò֥ʼ yá֝dĕʻ֗ẇ bȧ⁠mė֥h yiká̇şéֽ̌lẇ׃p"],[4,20,"בְּ֭נִ⁠י לִ⁠דְבָרַ֣⁠י הַקְשִׁ֑יבָ⁠ה לַ֝⁠אֲמָרַ֗⁠י הַט־אָזְנֶֽ⁠ךָ׃","bĕ֭̇ni⁠y li⁠dĕbára֣⁠y haqĕşǐ֑ybá⁠h la֝⁠ʼàmára֗⁠y hat-ʼázĕneֽ⁠ká׃"],[4,21,"אַל־יַלִּ֥יזוּ מֵ⁠עֵינֶ֑י⁠ךָ שָׁ֝מְרֵ֗⁠ם בְּ⁠ת֣וֹךְ לְבָבֶֽ⁠ךָ׃","ʼal-yali֥̇yzẇ mé⁠ʻéyne֑y⁠ká şá̌֝mĕré֗⁠m bĕ̇⁠ţ֣wòkĕ lĕbábeֽ⁠ká׃"],[4,22,"כִּֽי־חַיִּ֣ים הֵ֭ם לְ⁠מֹצְאֵי⁠הֶ֑ם וּֽ⁠לְ⁠כָל־בְּשָׂר֥⁠וֹ מַרְפֵּֽא׃","kiֽ̇y-ẖayi֣̇ym hé֭m lĕ⁠mòẕĕʼéy⁠he֑m ẇֽ⁠lĕ⁠kál-bĕ̇şá̂r֥⁠wò marĕpéֽ̇ʼ׃"],[4,23,"מִֽ⁠כָּל־מִ֭שְׁמָר נְצֹ֣ר לִבֶּ֑⁠ךָ כִּֽי־מִ֝מֶּ֗⁠נּוּ תּוֹצְא֥וֹת חַיִּֽים׃","miֽ⁠ká̇l-mi֭şĕ̌már nĕẕò֣r libė֑⁠ká kiֽ̇y-mi֝mė֗⁠ṅẇ ţ̇wòẕĕʼ֥wòţ ẖayiֽ̇ym׃"],[4,24,"הָסֵ֣ר מִ֭מְּ⁠ךָ עִקְּשׁ֣וּת פֶּ֑ה וּ⁠לְז֥וּת שְׂ֝פָתַ֗יִם הַרְחֵ֥ק מִמֶּֽ⁠ךָּ׃","hásé֣r mi֭mĕ̇⁠ká ʻiqĕ̇ş֣̌ẇţ pė֑h ẇ⁠lĕz֥ẇţ şĕ̂֝páţa֗yim harĕẖé֥q mimėֽ⁠ká̇׃"],[4,25,"עֵ֭ינֶי⁠ךָ לְ⁠נֹ֣כַח יַבִּ֑יטוּ וְ֝⁠עַפְעַפֶּ֗י⁠ךָ יַיְשִׁ֥רוּ נֶגְדֶּֽ⁠ךָ׃","ʻé֭yney⁠ká lĕ⁠nò֣kaẖ yabi֑̇ytẇ wĕ֝⁠ʻapĕʻapė֗y⁠ká yayĕşǐ֥rẇ negĕdėֽ⁠ká׃"],[4,26,"פַּ֭לֵּס מַעְגַּ֣ל רַגְלֶ֑⁠ךָ וְֽ⁠כָל־דְּרָכֶ֥י⁠ךָ יִכֹּֽנוּ׃","pȧ֭lé̇s maʻĕgȧ֣l ragĕle֑⁠ká wĕֽ⁠kál-dĕ̇ráke֥y⁠ká yikòֽ̇nẇ׃"],[4,27,"אַֽל־תֵּט־יָמִ֥ין וּ⁠שְׂמֹ֑אול הָסֵ֖ר רַגְלְ⁠ךָ֣ מֵ⁠רָֽע׃","ʼaֽl-ţé̇t-yámi֥yn ẇ⁠şĕ̂mò֑ʼwl hásé֖r ragĕlĕ⁠ká֣ mé⁠ráֽʻ׃"],[5,1,"בְּ֭נִ⁠י לְ⁠חָכְמָתִ֣⁠י הַקְשִׁ֑יבָ⁠ה לִ֝⁠תְבוּנָתִ֗⁠י הַט־אָזְנֶֽ⁠ךָ׃","bĕ֭̇ni⁠y lĕ⁠ẖákĕmáţi֣⁠y haqĕşǐ֑ybá⁠h li֝⁠ţĕbẇnáţi֗⁠y hat-ʼázĕneֽ⁠ká׃"],[5,2,"לִ⁠שְׁמֹ֥ר מְזִמּ֑וֹת וְ֝⁠דַ֗עַת שְׂפָתֶ֥י⁠ךָ יִנְצֹֽרוּ׃","li⁠şĕ̌mò֥r mĕziṁ֑wòţ wĕ֝⁠da֗ʻaţ şĕ̂páţe֥y⁠ká yinĕẕòֽrẇ׃"],[5,3,"כִּ֤י נֹ֣פֶת תִּ֭טֹּפְנָה שִׂפְתֵ֣י זָרָ֑ה וְ⁠חָלָ֖ק מִ⁠שֶּׁ֣מֶן חִכָּֽ⁠הּ׃","ki֤̇y nò֣peţ ţi֭̇tò̇pĕnáh şîpĕţé֣y zárá֑h wĕ⁠ẖálá֖q mi⁠şė֣̌men ẖikáֽ̇⁠ḣ׃"],[5,4,"וְֽ֭⁠אַחֲרִיתָ⁠הּ מָרָ֣ה כַֽ⁠לַּעֲנָ֑ה חַ֝דָּ֗ה כְּ⁠חֶ֣רֶב פִּיּֽוֹת׃","wĕֽ֭⁠ʼaẖàriyţá⁠ḣ márá֣h kaֽ⁠lȧʻàná֑h ẖa֝dá̇֗h kĕ̇⁠ẖe֣reb pi̇ẏֽwòţ׃"],[5,5,"רַ֭גְלֶי⁠הָ יֹרְד֣וֹת מָ֑וֶת שְׁ֝א֗וֹל צְעָדֶ֥י⁠הָ יִתְמֹֽכוּ׃","ra֭gĕley⁠há yòrĕd֣wòţ má֑weţ şĕ̌֝ʼ֗wòl ẕĕʻáde֥y⁠há yiţĕmòֽkẇ׃"],[5,6,"אֹ֣רַח חַ֭יִּים פֶּן־תְּפַלֵּ֑ס נָע֥וּ מַ֝עְגְּלֹתֶ֗י⁠הָ לֹ֣א תֵדָֽע׃פ","ʼò֣raẖ ẖa֭yi̇ym pėn-ţĕ̇palé֑̇s náʻ֥ẇ ma֝ʻĕgĕ̇lòţe֗y⁠há lò֣ʼ ţédáֽʻ׃p"],[5,7,"וְ⁠עַתָּ֣ה בָ֭נִים שִׁמְעוּ־לִ֑⁠י וְ⁠אַל־תָּ֝ס֗וּרוּ מֵ⁠אִמְרֵי־פִֽ⁠י׃","wĕ⁠ʻaţá֣̇h bá֭niym şǐmĕʻẇ-li֑⁠y wĕ⁠ʼal-ţá̇֝s֗ẇrẇ mé⁠ʼimĕréy-piֽ⁠y׃"],[5,8,"הַרְחֵ֣ק מֵ⁠עָלֶ֣י⁠הָ דַרְכֶּ֑⁠ךָ וְ⁠אַל־תִּ֝קְרַ֗ב אֶל־פֶּ֥תַח בֵּיתָֽ⁠הּ׃","harĕẖé֣q mé⁠ʻále֣y⁠há darĕkė֑⁠ká wĕ⁠ʼal-ţi̇֝qĕra֗b ʼel-pė֥ţaẖ bé̇yţáֽ⁠ḣ׃"],[5,9,"פֶּן־תִּתֵּ֣ן לַ⁠אֲחֵרִ֣ים הוֹדֶ֑⁠ךָ וּ֝⁠שְׁנֹתֶ֗י⁠ךָ לְ⁠אַכְזָרִֽי׃","pėn-ţi̇ţé֣̇n la⁠ʼàẖéri֣ym hwòde֑⁠ká ẇ֝⁠şĕ̌nòţe֗y⁠ká lĕ⁠ʼakĕzáriֽy׃"],[5,10,"פֶּֽן־יִשְׂבְּע֣וּ זָרִ֣ים כֹּחֶ֑⁠ךָ וַ֝⁠עֲצָבֶ֗י⁠ךָ בְּ⁠בֵ֣ית נָכְרִֽי׃","pėֽn-yişĕ̂bĕ̇ʻ֣ẇ zári֣ym kò̇ẖe֑⁠ká wa֝⁠ʻàẕábe֗y⁠ká bĕ̇⁠bé֣yţ nákĕriֽy׃"],[5,11,"וְ⁠נָהַמְתָּ֥ בְ⁠אַחֲרִיתֶ֑⁠ךָ בִּ⁠כְל֥וֹת בְּ֝שָׂרְ⁠ךָ֗ וּ⁠שְׁאֵרֶֽ⁠ךָ׃","wĕ⁠náhamĕţá֥̇ bĕ⁠ʼaẖàriyţe֑⁠ká bi̇⁠kĕl֥wòţ bĕ̇֝şá̂rĕ⁠ká֗ ẇ⁠şĕ̌ʼéreֽ⁠ká׃"],[5,12,"וְֽ⁠אָמַרְתָּ֗ אֵ֭יךְ שָׂנֵ֣אתִי מוּסָ֑ר וְ֝⁠תוֹכַ֗חַת נָאַ֥ץ לִבִּֽ⁠י׃","wĕֽ⁠ʼámarĕţá̇֗ ʼé֭ykĕ şá̂né֣ʼţiy mẇsá֑r wĕ֝⁠ţwòka֗ẖaţ náʼa֥ẕ libiֽ̇⁠y׃"],[5,13,"וְֽ⁠לֹא־שָׁ֭מַעְתִּי בְּ⁠ק֣וֹל מוֹרָ֑⁠י וְ֝⁠לִֽ⁠מְלַמְּדַ֗⁠י לֹא־הִטִּ֥יתִי אָזְנִֽ⁠י׃","wĕֽ⁠lòʼ-şá֭̌maʻĕţi̇y bĕ̇⁠q֣wòl mwòrá֑⁠y wĕ֝⁠liֽ⁠mĕlamĕ̇da֗⁠y lòʼ-hiti֥̇yţiy ʼázĕniֽ⁠y׃"],[5,14,"כִּ֭⁠מְעַט הָיִ֣יתִי בְ⁠כָל־רָ֑ע בְּ⁠ת֖וֹךְ קָהָ֣ל וְ⁠עֵדָֽה׃","ki֭̇⁠mĕʻat háyi֣yţiy bĕ⁠kál-rá֑ʻ bĕ̇⁠ţ֖wòkĕ qáhá֣l wĕ⁠ʻédáֽh׃"],[5,15,"שְׁתֵה־מַ֥יִם מִ⁠בּוֹרֶ֑⁠ךָ וְ֝⁠נֹזְלִ֗ים מִ⁠תּ֥וֹךְ בְּאֵרֶֽ⁠ךָ׃","şĕ̌ţéh-ma֥yim mi⁠ḃwòre֑⁠ká wĕ֝⁠nòzĕli֗ym mi⁠ţ֥̇wòkĕ bĕ̇ʼéreֽ⁠ká׃"],[5,16,"יָפ֣וּצוּ מַעְיְנֹתֶ֣י⁠ךָ ח֑וּצָ⁠ה בָּ֝⁠רְחֹב֗וֹת פַּלְגֵי־מָֽיִם׃","yáp֣ẇẕẇ maʻĕyĕnòţe֣y⁠ká ẖ֑ẇẕá⁠h bá̇֝⁠rĕẖòb֗wòţ pȧlĕgéy-máֽyim׃"],[5,17,"יִֽהְיוּ־לְ⁠ךָ֥ לְ⁠בַדֶּ֑⁠ךָ וְ⁠אֵ֖ין לְ⁠זָרִ֣ים אִתָּֽ⁠ךְ׃","yiֽhĕyẇ-lĕ⁠ká֥ lĕ⁠badė֑⁠ká wĕ⁠ʼé֖yn lĕ⁠zári֣ym ʼiţáֽ̇⁠kĕ׃"],[5,18,"יְהִֽי־מְקוֹרְ⁠ךָ֥ בָר֑וּךְ וּ֝⁠שְׂמַ֗ח מֵ⁠אֵ֥שֶׁת נְעוּרֶֽ⁠ךָ׃","yĕhiֽy-mĕqwòrĕ⁠ká֥ bár֑ẇkĕ ẇ֝⁠şĕ̂ma֗ẖ mé⁠ʼé֥şěţ nĕʻẇreֽ⁠ká׃"],[5,19,"אַיֶּ֥לֶת אֲהָבִ֗ים וְֽ⁠יַעֲלַ֫ת־חֵ֥ן דַּ֭דֶּי⁠הָ יְרַוֻּ֣⁠ךָ בְ⁠כָל־עֵ֑ת בְּ֝⁠אַהֲבָתָ֗⁠הּ תִּשְׁגֶּ֥ה תָמִֽיד׃","ʼayė֥leţ ʼàhábi֗ym wĕֽ⁠yaʻàla֫ţ-ẖé֥n dȧ֭dėy⁠há yĕrawu֣̇⁠ká bĕ⁠kál-ʻé֑ţ bĕ̇֝⁠ʼahàbáţá֗⁠ḣ ţi̇şĕ̌gė֥h ţámiֽyd׃"],[5,20,"וְ⁠לָ֤⁠מָּה תִשְׁגֶּ֣ה בְנִ֣⁠י בְ⁠זָרָ֑ה וּ֝⁠תְחַבֵּ֗ק חֵ֣ק נָכְרִיָּֽה׃","wĕ⁠lá֤⁠má̇h ţişĕ̌gė֣h bĕni֣⁠y bĕ⁠zárá֑h ẇ֝⁠ţĕẖabé̇֗q ẖé֣q nákĕriyáֽ̇h׃"],[5,21,"כִּ֤י נֹ֨כַח ׀ עֵינֵ֣י יְ֭הוָה דַּרְכֵי־אִ֑ישׁ וְֽ⁠כָל־מַעְגְּלֹתָ֥י⁠ו מְפַלֵּֽס׃","ki֤̇y nò֨kaẖ ׀ ʻéyné֣y yĕ֭hwáh dȧrĕkéy-ʼi֑yş̌ wĕֽ⁠kál-maʻĕgĕ̇lòţá֥y⁠w mĕpaléֽ̇s׃"],[5,22,"עַֽווֹנוֹתָ֗י⁠ו יִלְכְּדֻ⁠נ֥וֹ אֶת־הָ⁠רָשָׁ֑ע וּ⁠בְ⁠חַבְלֵ֥י חַ֝טָּאת֗⁠וֹ יִתָּמֵֽךְ׃","ʻaֽwwònwòţá֗y⁠w yilĕkĕ̇du⁠n֥wò ʼeţ-há⁠ráşá֑̌ʻ ẇ⁠bĕ⁠ẖabĕlé֥y ẖa֝tá̇ʼţ֗⁠wò yiţá̇méֽkĕ׃"],[5,23,"ה֗וּא יָ֭מוּת בְּ⁠אֵ֣ין מוּסָ֑ר וּ⁠בְ⁠רֹ֖ב אִוַּלְתּ֣⁠וֹ יִשְׁגֶּֽה׃פ","h֗ẇʼ yá֭mẇţ bĕ̇⁠ʼé֣yn mẇsá֑r ẇ⁠bĕ⁠rò֖b ʼiwȧlĕţ֣̇⁠wò yişĕ̌gėֽh׃p"],[6,1,"בְּ֭נִ⁠י אִם־עָרַ֣בְתָּ לְ⁠רֵעֶ֑⁠ךָ תָּקַ֖עְתָּ לַ⁠זָּ֣ר כַּפֶּֽי⁠ךָ׃","bĕ֭̇ni⁠y ʼim-ʻára֣bĕţá̇ lĕ⁠réʻe֑⁠ká ţá̇qa֖ʻĕţá̇ la⁠zá֣̇r kȧpėֽy⁠ká׃"],[6,2,"נוֹקַ֥שְׁתָּ בְ⁠אִמְרֵי־פִ֑י⁠ךָ נִ֝לְכַּ֗דְתָּ בְּ⁠אִמְרֵי־פִֽי⁠ךָ׃","nwòqa֥şĕ̌ţá̇ bĕ⁠ʼimĕréy-pi֑y⁠ká ni֝lĕkȧ֗dĕţá̇ bĕ̇⁠ʼimĕréy-piֽy⁠ká׃"],[6,3,"עֲשֵׂ֨ה זֹ֥את אֵפ֪וֹא ׀ בְּנִ֡⁠י וְֽ⁠הִנָּצֵ֗ל כִּ֘י בָ֤אתָ בְ⁠כַף־רֵעֶ֑⁠ךָ לֵ֥ךְ הִ֝תְרַפֵּ֗ס וּ⁠רְהַ֥ב רֵעֶֽי⁠ךָ׃","ʻàşé̂֨h zò֥ʼţ ʼép֪wòʼ ׀ bĕ̇ni֡⁠y wĕֽ⁠hiná̇ẕé֗l ki̇֘y bá֤ʼţá bĕ⁠kap-réʻe֑⁠ká lé֥kĕ hi֝ţĕrapé̇֗s ẇ⁠rĕha֥b réʻeֽy⁠ká׃"],[6,4,"אַל־תִּתֵּ֣ן שֵׁנָ֣ה לְ⁠עֵינֶ֑י⁠ךָ וּ֝⁠תְנוּמָ֗ה לְ⁠עַפְעַפֶּֽי⁠ךָ׃","ʼal-ţi̇ţé֣̇n şé̌ná֣h lĕ⁠ʻéyne֑y⁠ká ẇ֝⁠ţĕnẇmá֗h lĕ⁠ʻapĕʻapėֽy⁠ká׃"],[6,5,"הִ֭נָּצֵל כִּ⁠צְבִ֣י מִ⁠יָּ֑ד וּ֝⁠כְ⁠צִפּ֗וֹר מִ⁠יַּ֥ד יָקֽוּשׁ׃פ","hi֭ná̇ẕél ki̇⁠ẕĕbi֣y mi⁠yá֑̇d ẇ֝⁠kĕ⁠ẕiṗ֗wòr mi⁠yȧ֥d yáqֽẇş̌׃p"],[6,6,"לֵֽךְ־אֶל־נְמָלָ֥ה עָצֵ֑ל רְאֵ֖ה דְרָכֶ֣י⁠הָ וַ⁠חֲכָֽם׃","léֽkĕ-ʼel-nĕmálá֥h ʻáẕé֑l rĕʼé֖h dĕráke֣y⁠há wa⁠ẖàkáֽm׃"],[6,7,"אֲשֶׁ֖ר אֵֽין־לָ֥⁠הּ קָצִ֗ין שֹׁטֵ֥ר וּ⁠מֹשֵֽׁל׃","ʼàşě֖r ʼéֽyn-lá֥⁠ḣ qáẕi֗yn şò̌té֥r ẇ⁠mòşéֽ̌l׃"],[6,8,"תָּכִ֣ין בַּ⁠קַּ֣יִץ לַחְמָ֑⁠הּ אָגְרָ֥ה בַ֝⁠קָּצִ֗יר מַאֲכָלָֽ⁠הּ׃","ţá̇ki֣yn bȧ⁠qȧ֣yiẕ laẖĕmá֑⁠ḣ ʼágĕrá֥h ba֝⁠qá̇ẕi֗yr maʼàkáláֽ⁠ḣ׃"],[6,9,"עַד־מָתַ֖י עָצֵ֥ל ׀ תִּשְׁכָּ֑ב מָ֝תַ֗י תָּק֥וּם מִ⁠שְּׁנָתֶֽ⁠ךָ׃","ʻad-máţa֖y ʻáẕé֥l ׀ ţi̇şĕ̌ká֑̇b má֝ţa֗y ţá̇q֥ẇm mi⁠şĕ̇̌náţeֽ⁠ká׃"],[6,10,"מְעַ֣ט שֵׁ֭נוֹת מְעַ֣ט תְּנוּמ֑וֹת מְעַ֓ט ׀ חִבֻּ֖ק יָדַ֣יִם לִ⁠שְׁכָּֽב׃","mĕʻa֣t şé֭̌nwòţ mĕʻa֣t ţĕ̇nẇm֑wòţ mĕʻa֓t ׀ ẖibu֖̇q yáda֣yim li⁠şĕ̌káֽ̇b׃"],[6,11,"וּ⁠בָֽא־כִ⁠מְהַלֵּ֥ךְ רֵאשֶׁ֑⁠ךָ וּ֝⁠מַחְסֹֽרְ⁠ךָ֗ כְּ⁠אִ֣ישׁ מָגֵֽן׃פ","ẇ⁠báֽʼ-ki⁠mĕhalé֥̇kĕ réʼşě֑⁠ká ẇ֝⁠maẖĕsòֽrĕ⁠ká֗ kĕ̇⁠ʼi֣yş̌ mágéֽn׃p"],[6,12,"אָדָ֣ם בְּ֭לִיַּעַל אִ֣ישׁ אָ֑וֶן ה֝וֹלֵ֗ךְ עִקְּשׁ֥וּת פֶּֽה׃","ʼádá֣m bĕ֭̇liyȧʻal ʼi֣yş̌ ʼá֑wen h֝wòlé֗kĕ ʻiqĕ̇ş֥̌ẇţ pėֽh׃"],[6,13,"קֹרֵ֣ץ בְּ֭⁠עֵינָ⁠ו מֹלֵ֣ל בְּ⁠רַגְלָ֑⁠ו מֹ֝רֶ֗ה בְּ⁠אֶצְבְּעֹתָֽי⁠ו׃","qòré֣ẕ bĕ֭̇⁠ʻéyná⁠w mòlé֣l bĕ̇⁠ragĕlá֑⁠w mò֝re֗h bĕ̇⁠ʼeẕĕbĕ̇ʻòţáֽy⁠w׃"],[6,14,"תַּֽהְפֻּכ֨וֹת ׀ בְּ⁠לִבּ֗⁠וֹ חֹרֵ֣שׁ רָ֣ע בְּ⁠כָל־עֵ֑ת מדנים יְשַׁלֵּֽחַ׃","ţȧֽhĕpu̇k֨wòţ ׀ bĕ̇⁠liḃ֗⁠wò ẖòré֣ş̌ rá֣ʻ bĕ̇⁠kál-ʻé֑ţ mdnym yĕşǎléֽ̇ẖa׃"],[6,15,"עַל־כֵּ֗ן פִּ֭תְאֹם יָב֣וֹא אֵיד֑⁠וֹ פֶּ֥תַע יִ֝שָּׁבֵ֗ר וְ⁠אֵ֣ין מַרְפֵּֽא׃פ","ʻal-ké̇֗n pi֭̇ţĕʼòm yáb֣wòʼ ʼéyd֑⁠wò pė֥ţaʻ yi֝şá̇̌bé֗r wĕ⁠ʼé֣yn marĕpéֽ̇ʼ׃p"],[6,16,"שֶׁשׁ־הֵ֭נָּה שָׂנֵ֣א יְהוָ֑ה וְ֝⁠שֶׁ֗בַע תועבות נַפְשֽׁ⁠וֹ׃","şěş̌-hé֭ná̇h şá̂né֣ʼ yĕhwá֑h wĕ֝⁠şě֗baʻ ţwʻbwţ napĕşֽ̌⁠wò׃"],[6,17,"עֵינַ֣יִם רָ֭מוֹת לְשׁ֣וֹן שָׁ֑קֶר וְ֝⁠יָדַ֗יִם שֹׁפְכ֥וֹת דָּם־נָקִֽי׃","ʻéyna֣yim rá֭mwòţ lĕş֣̌wòn şá֑̌qer wĕ֝⁠yáda֗yim şò̌pĕk֥wòţ dá̇m-náqiֽy׃"],[6,18,"לֵ֗ב חֹ֭רֵשׁ מַחְשְׁב֣וֹת אָ֑וֶן רַגְלַ֥יִם מְ֝מַהֲר֗וֹת לָ⁠ר֥וּץ לָֽ⁠רָעָה׃","lé֗b ẖò֭réş̌ maẖĕşĕ̌b֣wòţ ʼá֑wen ragĕla֥yim mĕ֝mahàr֗wòţ lá⁠r֥ẇẕ láֽ⁠ráʻáh׃"],[6,19,"יָפִ֣יחַ כְּ֭זָבִים עֵ֣ד שָׁ֑קֶר וּ⁠מְשַׁלֵּ֥חַ מְ֝דָנִ֗ים בֵּ֣ין אַחִֽים׃פ","yápi֣yẖa kĕ֭̇zábiym ʻé֣d şá֑̌qer ẇ⁠mĕşǎlé֥̇ẖa mĕ֝dáni֗ym bé֣̇yn ʼaẖiֽym׃p"],[6,20,"נְצֹ֣ר בְּ֭נִ⁠י מִצְוַ֣ת אָבִ֑י⁠ךָ וְ⁠אַל־תִּ֝טֹּ֗שׁ תּוֹרַ֥ת אִמֶּֽ⁠ךָ׃","nĕẕò֣r bĕ֭̇ni⁠y miẕĕwa֣ţ ʼábi֑y⁠ká wĕ⁠ʼal-ţi̇֝tò̇֗ş̌ ţ̇wòra֥ţ ʼimėֽ⁠ká׃"],[6,21,"קָשְׁרֵ֣⁠ם עַל־לִבְּ⁠ךָ֣ תָמִ֑יד עָ֝נְדֵ֗⁠ם עַל־גַּרְגְּרֹתֶֽ⁠ךָ׃","qáşĕ̌ré֣⁠m ʻal-libĕ̇⁠ká֣ ţámi֑yd ʻá֝nĕdé֗⁠m ʻal-gȧrĕgĕ̇ròţeֽ⁠ká׃"],[6,22,"בְּ⁠הִתְהַלֶּכְ⁠ךָ֨ ׀ תַּנְחֶ֬ה אֹתָ֗⁠ךְ בְּֽ֭⁠שָׁכְבְּ⁠ךָ תִּשְׁמֹ֣ר עָלֶ֑י⁠ךָ וַ֝⁠הֲקִיצ֗וֹתָ הִ֣יא תְשִׂיחֶֽ⁠ךָ׃","bĕ̇⁠hiţĕhalėkĕ⁠ká֨ ׀ ţȧnĕẖe֬h ʼòţá֗⁠kĕ bĕֽ֭̇⁠şá̌kĕbĕ̇⁠ká ţi̇şĕ̌mò֣r ʻále֑y⁠ká wa֝⁠hàqiyẕ֗wòţá hi֣yʼ ţĕşîyẖeֽ⁠ká׃"],[6,23,"כִּ֤י נֵ֣ר מִ֭צְוָה וְ⁠ת֣וֹרָה א֑וֹר וְ⁠דֶ֥רֶךְ חַ֝יִּ֗ים תּוֹכְח֥וֹת מוּסָֽר׃","ki֤̇y né֣r mi֭ẕĕwáh wĕ⁠ţ֣wòráh ʼ֑wòr wĕ⁠de֥rekĕ ẖa֝yi̇֗ym ţ̇wòkĕẖ֥wòţ mẇsáֽr׃"],[6,24,"לִ֭⁠שְׁמָרְ⁠ךָ מֵ⁠אֵ֣שֶׁת רָ֑ע מֵֽ֝⁠חֶלְקַ֗ת לָשׁ֥וֹן נָכְרִיָּֽה׃","li֭⁠şĕ̌márĕ⁠ká mé⁠ʼé֣şěţ rá֑ʻ méֽ֝⁠ẖelĕqa֗ţ láş֥̌wòn nákĕriyáֽ̇h׃"],[6,25,"אַל־תַּחְמֹ֣ד יָ֭פְיָ⁠הּ בִּ⁠לְבָבֶ֑⁠ךָ וְ⁠אַל־תִּ֝קָּֽחֲ⁠ךָ֗ בְּ⁠עַפְעַפֶּֽי⁠הָ׃","ʼal-ţȧẖĕmò֣d yá֭pĕyá⁠ḣ bi̇⁠lĕbábe֑⁠ká wĕ⁠ʼal-ţi̇֝qáֽ̇ẖà⁠ká֗ bĕ̇⁠ʻapĕʻapėֽy⁠há׃"],[6,26,"כִּ֤י בְעַד־אִשָּׁ֥ה זוֹנָ֗ה עַֽד־כִּכַּ֫ר לָ֥חֶם וְ⁠אֵ֥שֶׁת אִ֑ישׁ נֶ֖פֶשׁ יְקָרָ֣ה תָצֽוּד׃פ","ki֤̇y bĕʻad-ʼişá֥̇̌h zwòná֗h ʻaֽd-ki̇kȧ֫r lá֥ẖem wĕ⁠ʼé֥şěţ ʼi֑yş̌ ne֖peş̌ yĕqárá֣h ţáẕֽẇd׃p"],[6,27,"הֲ⁠יַחְתֶּ֤ה אִ֓ישׁ אֵ֬שׁ בְּ⁠חֵיק֑⁠וֹ וּ֝⁠בְגָדָ֗י⁠ו לֹ֣א תִשָּׂרַֽפְנָה׃","hà⁠yaẖĕţė֤h ʼi֓yş̌ ʼé֬ş̌ bĕ̇⁠ẖéyq֑⁠wò ẇ֝⁠bĕgádá֗y⁠w lò֣ʼ ţişá̇̂raֽpĕnáh׃"],[6,28,"אִם־יְהַלֵּ֣ךְ אִ֭ישׁ עַל־הַ⁠גֶּחָלִ֑ים וְ֝⁠רַגְלָ֗י⁠ו לֹ֣א תִכָּוֶֽינָה׃","ʼim-yĕhalé֣̇kĕ ʼi֭yş̌ ʻal-ha⁠gėẖáli֑ym wĕ֝⁠ragĕlá֗y⁠w lò֣ʼ ţiká̇weֽynáh׃"],[6,29,"כֵּ֗ן הַ֭⁠בָּא אֶל־אֵ֣שֶׁת רֵעֵ֑⁠הוּ לֹ֥א יִ֝נָּקֶ֗ה כָּֽל־הַ⁠נֹּגֵ֥עַ בָּֽ⁠הּ׃","ké̇֗n ha֭⁠bá̇ʼ ʼel-ʼé֣şěţ réʻé֑⁠hẇ lò֥ʼ yi֝ná̇qe֗h káֽ̇l-ha⁠nò̇gé֥ʻa báֽ̇⁠ḣ׃"],[6,30,"לֹא־יָב֣וּזוּ לַ֭⁠גַּנָּב כִּ֣י יִגְנ֑וֹב לְ⁠מַלֵּ֥א נַ֝פְשׁ֗⁠וֹ כִּ֣י יִרְעָֽב׃","lòʼ-yáb֣ẇzẇ la֭⁠gȧná̇b ki֣̇y yigĕn֑wòb lĕ⁠malé֥̇ʼ na֝pĕş̌֗⁠wò ki֣̇y yirĕʻáֽb׃"],[6,31,"וְ֭⁠נִמְצָא יְשַׁלֵּ֣ם שִׁבְעָתָ֑יִם אֶת־כָּל־ה֖וֹן בֵּית֣⁠וֹ יִתֵּֽן׃","wĕ֭⁠nimĕẕáʼ yĕşǎlé֣̇m şǐbĕʻáţá֑yim ʼeţ-ká̇l-h֖wòn bé̇yţ֣⁠wò yiţéֽ̇n׃"],[6,32,"נֹאֵ֣ף אִשָּׁ֣ה חֲסַר־לֵ֑ב מַֽשְׁחִ֥ית נַ֝פְשׁ֗⁠וֹ ה֣וּא יַעֲשֶֽׂ⁠נָּה׃","nòʼé֣p ʼişá֣̇̌h ẖàsar-lé֑b maֽşĕ̌ẖi֥yţ na֝pĕş̌֗⁠wò h֣ẇʼ yaʻàşêֽ⁠ná̇h׃"],[6,33,"נֶֽגַע־וְ⁠קָל֥וֹן יִמְצָ֑א וְ֝⁠חֶרְפָּת֗⁠וֹ לֹ֣א תִמָּחֶֽה׃","neֽgaʻ-wĕ⁠qál֥wòn yimĕẕá֑ʼ wĕ֝⁠ẖerĕpá̇ţ֗⁠wò lò֣ʼ ţimá̇ẖeֽh׃"],[6,34,"כִּֽי־קִנְאָ֥ה חֲמַת־גָּ֑בֶר וְ⁠לֹֽא־יַ֝חְמ֗וֹל בְּ⁠י֣וֹם נָקָֽם׃","kiֽ̇y-qinĕʼá֥h ẖàmaţ-gá֑̇ber wĕ⁠lòֽʼ-ya֝ẖĕm֗wòl bĕ̇⁠y֣wòm náqáֽm׃"],[6,35,"לֹא־יִ֭שָּׂא פְּנֵ֣י כָל־כֹּ֑פֶר וְ⁠לֹֽא־יֹ֝אבֶ֗ה כִּ֣י תַרְבֶּה־שֹֽׁחַד׃פ","lòʼ-yi֭şá̇̂ʼ pĕ̇né֣y kál-kò֑̇per wĕ⁠lòֽʼ-yò֝ʼbe֗h ki֣̇y ţarĕbėh-şòֽ̌ẖad׃p"],[7,1,"בְּ֭נִ⁠י שְׁמֹ֣ר אֲמָרָ֑⁠י וּ֝⁠מִצְוֺתַ֗⁠י תִּצְפֹּ֥ן אִתָּֽ⁠ךְ׃","bĕ֭̇ni⁠y şĕ̌mò֣r ʼàmárá֑⁠y ẇ֝⁠miẕĕwֺţa֗⁠y ţi̇ẕĕpò֥̇n ʼiţáֽ̇⁠kĕ׃"],[7,2,"שְׁמֹ֣ר מִצְוֺתַ֣⁠י וֶ⁠חְיֵ֑ה וְ֝⁠תוֹרָתִ֗⁠י כְּ⁠אִישׁ֥וֹן עֵינֶֽי⁠ךָ׃","şĕ̌mò֣r miẕĕwֺţa֣⁠y we⁠ẖĕyé֑h wĕ֝⁠ţwòráţi֗⁠y kĕ̇⁠ʼiyş֥̌wòn ʻéyneֽy⁠ká׃"],[7,3,"קָשְׁרֵ֥⁠ם עַל־אֶצְבְּעֹתֶ֑י⁠ךָ כָּ֝תְבֵ֗⁠ם עַל־ל֥וּחַ לִבֶּֽ⁠ךָ׃","qáşĕ̌ré֥⁠m ʻal-ʼeẕĕbĕ̇ʻòţe֑y⁠ká ká̇֝ţĕbé֗⁠m ʻal-l֥ẇẖa libėֽ⁠ká׃"],[7,4,"אֱמֹ֣ר לַֽ֭⁠חָכְמָה אֲחֹ֣תִ⁠י אָ֑תְּ וּ֝⁠מֹדָ֗ע לַ⁠בִּינָ֥ה תִקְרָֽא׃","ʼèmò֣r laֽ֭⁠ẖákĕmáh ʼàẖò֣ţi⁠y ʼá֑ţĕ̇ ẇ֝⁠mòdá֗ʻ la⁠bi̇yná֥h ţiqĕráֽʼ׃"],[7,5,"לִ֭⁠שְׁמָרְ⁠ךָ מֵ⁠אִשָּׁ֣ה זָרָ֑ה מִ֝⁠נָּכְרִיָּ֗ה אֲמָרֶ֥י⁠הָ הֶחֱלִֽיקָה׃","li֭⁠şĕ̌márĕ⁠ká mé⁠ʼişá֣̇̌h zárá֑h mi֝⁠ná̇kĕriyá̇֗h ʼàmáre֥y⁠há heẖèliֽyqáh׃"],[7,6,"כִּ֭י בְּ⁠חַלּ֣וֹן בֵּיתִ֑⁠י בְּעַ֖ד אֶשְׁנַבִּ֣⁠י נִשְׁקָֽפְתִּי׃","ki֭̇y bĕ̇⁠ẖal֣̇wòn bé̇yţi֑⁠y bĕ̇ʻa֖d ʼeşĕ̌nabi֣̇⁠y nişĕ̌qáֽpĕţi̇y׃"],[7,7,"וָ⁠אֵ֤רֶא בַ⁠פְּתָאיִ֗ם אָ֘בִ֤ינָה בַ⁠בָּנִ֗ים נַ֣עַר חֲסַר־לֵֽב׃","wá⁠ʼé֤reʼ ba⁠pĕ̇ţáʼyi֗m ʼá֘bi֤ynáh ba⁠bá̇ni֗ym na֣ʻar ẖàsar-léֽb׃"],[7,8,"עֹבֵ֣ר בַּ֭⁠שּׁוּק אֵ֣צֶל פִּנָּ֑⁠הּ וְ⁠דֶ֖רֶךְ בֵּיתָ֣⁠הּ יִצְעָֽד׃","ʻòbé֣r bȧ֭⁠ş̇̌ẇq ʼé֣ẕel pi̇ná֑̇⁠ḣ wĕ⁠de֖rekĕ bé̇yţá֣⁠ḣ yiẕĕʻáֽd׃"],[7,9,"בְּ⁠נֶֽשֶׁף־בְּ⁠עֶ֥רֶב י֑וֹם בְּ⁠אִישׁ֥וֹן לַ֝֗יְלָה וַ⁠אֲפֵלָֽה׃","bĕ̇⁠neֽşěp-bĕ̇⁠ʻe֥reb y֑wòm bĕ̇⁠ʼiyş֥̌wòn la֝֗yĕláh wa⁠ʼàpéláֽh׃"],[7,10,"וְ⁠הִנֵּ֣ה אִ֭שָּׁה לִ⁠קְרָאת֑⁠וֹ שִׁ֥ית ז֝וֹנָ֗ה וּ⁠נְצֻ֥רַת לֵֽב׃","wĕ⁠hiné֣̇h ʼi֭şá̇̌h li⁠qĕráʼţ֑⁠wò şǐ֥yţ z֝wòná֗h ẇ⁠nĕẕu֥raţ léֽb׃"],[7,11,"הֹמִיָּ֣ה הִ֣יא וְ⁠סֹרָ֑רֶת בְּ֝⁠בֵיתָ֗⁠הּ לֹא־יִשְׁכְּנ֥וּ רַגְלֶֽי⁠הָ׃","hòmiyá֣̇h hi֣yʼ wĕ⁠sòrá֑reţ bĕ̇֝⁠béyţá֗⁠ḣ lòʼ-yişĕ̌kĕ̇n֥ẇ ragĕleֽy⁠há׃"],[7,12,"פַּ֤עַם ׀ בַּ⁠ח֗וּץ פַּ֥עַם בָּ⁠רְחֹב֑וֹת וְ⁠אֵ֖צֶל כָּל־פִּנָּ֣ה תֶאֱרֹֽב׃","pȧ֤ʻam ׀ bȧ⁠ẖ֗ẇẕ pȧ֥ʻam bá̇⁠rĕẖòb֑wòţ wĕ⁠ʼé֖ẕel ká̇l-pi̇ná֣̇h ţeʼèròֽb׃"],[7,13,"וְ⁠הֶחֱזִ֣יקָה בּ֭⁠וֹ וְ⁠נָ֣שְׁקָה־לּ֑⁠וֹ הֵעֵ֥זָה פָ֝נֶ֗י⁠הָ וַ⁠תֹּ֣אמַר לֽ⁠וֹ׃","wĕ⁠heẖèzi֣yqáh ḃ֭⁠wò wĕ⁠ná֣şĕ̌qáh-l֑̇⁠wò héʻé֥záh pá֝ne֗y⁠há wa⁠ţò֣̇ʼmar lֽ⁠wò׃"],[7,14,"זִבְחֵ֣י שְׁלָמִ֣ים עָלָ֑⁠י הַ֝⁠יּ֗וֹם שִׁלַּ֥מְתִּי נְדָרָֽ⁠י׃","zibĕẖé֣y şĕ̌lámi֣ym ʻálá֑⁠y ha֝⁠ẏ֗wòm şǐlȧ֥mĕţi̇y nĕdáráֽ⁠y׃"],[7,15,"עַל־כֵּ֭ן יָצָ֣אתִי לִ⁠קְרָאתֶ֑⁠ךָ לְ⁠שַׁחֵ֥ר פָּ֝נֶ֗י⁠ךָ וָ⁠אֶמְצָאֶֽ⁠ךָּ׃","ʻal-ké֭̇n yáẕá֣ʼţiy li⁠qĕráʼţe֑⁠ká lĕ⁠şǎẖé֥r pá̇֝ne֗y⁠ká wá⁠ʼemĕẕáʼeֽ⁠ká̇׃"],[7,16,"מַ֭רְבַדִּים רָבַ֣דְתִּי עַרְשִׂ֑⁠י חֲ֝טֻב֗וֹת אֵט֥וּן מִצְרָֽיִם׃","ma֭rĕbadi̇ym rába֣dĕţi̇y ʻarĕşî֑⁠y ẖà֝tub֗wòţ ʼét֥ẇn miẕĕráֽyim׃"],[7,17,"נַ֥פְתִּי מִשְׁכָּבִ֑⁠י מֹ֥ר אֲ֝הָלִ֗ים וְ⁠קִנָּמֽוֹן׃","na֥pĕţi̇y mişĕ̌ká̇bi֑⁠y mò֥r ʼà֝háli֗ym wĕ⁠qiná̇mֽwòn׃"],[7,18,"לְכָ֤⁠ה נִרְוֶ֣ה דֹ֭דִים עַד־הַ⁠בֹּ֑קֶר נִ֝תְעַלְּסָ֗ה בָּ⁠אֳהָבִֽים׃","lĕká֤⁠h nirĕwe֣h dò֭diym ʻad-ha⁠bò֑̇qer ni֝ţĕʻalĕ̇sá֗h bá̇⁠ʼohábiֽym׃"],[7,19,"כִּ֤י אֵ֣ין הָ⁠אִ֣ישׁ בְּ⁠בֵית֑⁠וֹ הָ֝לַ֗ךְ בְּ⁠דֶ֣רֶךְ מֵ⁠רָחֽוֹק׃","ki֤̇y ʼé֣yn há⁠ʼi֣yş̌ bĕ̇⁠béyţ֑⁠wò há֝la֗kĕ bĕ̇⁠de֣rekĕ mé⁠ráẖֽwòq׃"],[7,20,"צְֽרוֹר־הַ֭⁠כֶּסֶף לָקַ֣ח בְּ⁠יָד֑⁠וֹ לְ⁠י֥וֹם הַ֝⁠כֵּ֗סֶא יָבֹ֥א בֵיתֽ⁠וֹ׃","ẕĕֽrwòr-ha֭⁠kėsep láqa֣ẖ bĕ̇⁠yád֑⁠wò lĕ⁠y֥wòm ha֝⁠ké̇֗seʼ yábò֥ʼ béyţֽ⁠wò׃"],[7,21,"הִ֭טַּתּ⁠וּ בְּ⁠רֹ֣ב לִקְחָ֑⁠הּ בְּ⁠חֵ֥לֶק שְׂ֝פָתֶ֗י⁠הָ תַּדִּיחֶֽ⁠נּוּ׃","hi֭tȧţ̇⁠ẇ bĕ̇⁠rò֣b liqĕẖá֑⁠ḣ bĕ̇⁠ẖé֥leq şĕ̂֝páţe֗y⁠há ţȧdi̇yẖeֽ⁠ṅẇ׃"],[7,22,"ה֤וֹלֵ֥ךְ אַחֲרֶ֗י⁠הָ פִּ֫תְאֹ֥ם כְּ֭⁠שׁוֹר אֶל־טָ֣בַח יָב֑וֹא וּ֝⁠כְ⁠עֶ֗כֶס אֶל־מוּסַ֥ר אֱוִֽיל׃","h֤wòlé֥kĕ ʼaẖàre֗y⁠há pi̇֫ţĕʼò֥m kĕ֭̇⁠ş̌wòr ʼel-tá֣baẖ yáb֑wòʼ ẇ֝⁠kĕ⁠ʻe֗kes ʼel-mẇsa֥r ʼèwiֽyl׃"],[7,23,"עַ֤ד יְפַלַּ֪ח חֵ֡ץ כְּֽבֵד֗⁠וֹ כְּ⁠מַהֵ֣ר צִפּ֣וֹר אֶל־פָּ֑ח וְ⁠לֹֽא־יָ֝דַ֗ע כִּֽי־בְ⁠נַפְשׁ֥⁠וֹ הֽוּא׃פ","ʻa֤d yĕpalȧ֪ẖ ẖé֡ẕ kĕֽ̇béd֗⁠wò kĕ̇⁠mahé֣r ẕiṗ֣wòr ʼel-pá֑̇ẖ wĕ⁠lòֽʼ-yá֝da֗ʻ kiֽ̇y-bĕ⁠napĕş֥̌⁠wò hֽẇʼ׃p"],[7,24,"וְ⁠עַתָּ֣ה בָ֭נִים שִׁמְעוּ־לִ֑⁠י וְ֝⁠הַקְשִׁ֗יבוּ לְ⁠אִמְרֵי־פִֽ⁠י׃","wĕ⁠ʻaţá֣̇h bá֭niym şǐmĕʻẇ-li֑⁠y wĕ֝⁠haqĕşǐ֗ybẇ lĕ⁠ʼimĕréy-piֽ⁠y׃"],[7,25,"אַל־יֵ֣שְׂטְ אֶל־דְּרָכֶ֣י⁠הָ לִבֶּ֑⁠ךָ אַל־תֵּ֝תַע בִּ⁠נְתִיבוֹתֶֽי⁠הָ׃","ʼal-yé֣şĕ̂tĕ ʼel-dĕ̇ráke֣y⁠há libė֑⁠ká ʼal-ţé̇֝ţaʻ bi̇⁠nĕţiybwòţeֽy⁠há׃"],[7,26,"כִּֽי־רַבִּ֣ים חֲלָלִ֣ים הִפִּ֑ילָה וַ֝⁠עֲצֻמִ֗ים כָּל־הֲרֻגֶֽי⁠הָ׃","kiֽ̇y-rabi֣̇ym ẖàláli֣ym hipi֑̇yláh wa֝⁠ʻàẕumi֗ym ká̇l-hàrugeֽy⁠há׃"],[7,27,"דַּרְכֵ֣י שְׁא֣וֹל בֵּיתָ֑⁠הּ יֹ֝רְד֗וֹת אֶל־חַדְרֵי־מָֽוֶת׃פ","dȧrĕké֣y şĕ̌ʼ֣wòl bé̇yţá֑⁠ḣ yò֝rĕd֗wòţ ʼel-ẖadĕréy-máֽweţ׃p"],[8,1,"הֲ⁠לֹֽא־חָכְמָ֥ה תִקְרָ֑א וּ֝⁠תְבוּנָ֗ה תִּתֵּ֥ן קוֹלָֽ⁠הּ׃","hà⁠lòֽʼ-ẖákĕmá֥h ţiqĕrá֑ʼ ẇ֝⁠ţĕbẇná֗h ţi̇ţé֥̇n qwòláֽ⁠ḣ׃"],[8,2,"בְּ⁠רֹאשׁ־מְרוֹמִ֥ים עֲלֵי־דָ֑רֶךְ בֵּ֖ית נְתִיב֣וֹת נִצָּֽבָה׃","bĕ̇⁠ròʼş̌-mĕrwòmi֥ym ʻàléy-dá֑rekĕ bé֖̇yţ nĕţiyb֣wòţ niẕáֽ̇báh׃"],[8,3,"לְ⁠יַד־שְׁעָרִ֥ים לְ⁠פִי־קָ֑רֶת מְב֖וֹא פְתָחִ֣ים תָּרֹֽנָּה׃","lĕ⁠yad-şĕ̌ʻári֥ym lĕ⁠piy-qá֑reţ mĕb֖wòʼ pĕţáẖi֣ym ţá̇ròֽná̇h׃"],[8,4,"אֲלֵי⁠כֶ֣ם אִישִׁ֣ים אֶקְרָ֑א וְ֝⁠קוֹלִ֗⁠י אֶל־בְּנֵ֥י אָדָֽם׃","ʼàléy⁠ke֣m ʼiyşǐ֣ym ʼeqĕrá֑ʼ wĕ֝⁠qwòli֗⁠y ʼel-bĕ̇né֥y ʼádáֽm׃"],[8,5,"הָבִ֣ינוּ פְתָאיִ֣ם עָרְמָ֑ה וּ֝⁠כְסִילִ֗ים הָבִ֥ינוּ לֵֽב׃","hábi֣ynẇ pĕţáʼyi֣m ʻárĕmá֑h ẇ֝⁠kĕsiyli֗ym hábi֥ynẇ léֽb׃"],[8,6,"שִׁ֭מְעוּ כִּֽי־נְגִידִ֣ים אֲדַבֵּ֑ר וּ⁠מִפְתַּ֥ח שְׂ֝פָתַ֗⁠י מֵישָׁרִֽים׃","şǐ֭mĕʻẇ kiֽ̇y-nĕgiydi֣ym ʼàdabé֑̇r ẇ⁠mipĕţȧ֥ẖ şĕ̂֝páţa֗⁠y méyşá̌riֽym׃"],[8,7,"כִּֽי־אֱ֭מֶת יֶהְגֶּ֣ה חִכִּ֑⁠י וְ⁠תוֹעֲבַ֖ת שְׂפָתַ֣⁠י רֶֽשַׁע׃","kiֽ̇y-ʼè֭meţ yehĕgė֣h ẖiki֑̇⁠y wĕ⁠ţwòʻàba֖ţ şĕ̂páţa֣⁠y reֽşǎʻ׃"],[8,8,"בְּ⁠צֶ֥דֶק כָּל־אִמְרֵי־פִ֑⁠י אֵ֥ין בָּ֝⁠הֶ֗ם נִפְתָּ֥ל וְ⁠עִקֵּֽשׁ׃","bĕ̇⁠ẕe֥deq ká̇l-ʼimĕréy-pi֑⁠y ʼé֥yn bá̇֝⁠he֗m nipĕţá֥̇l wĕ⁠ʻiqéֽ̇ş̌׃"],[8,9,"כֻּלָּ֣⁠ם נְ֭כֹחִים לַ⁠מֵּבִ֑ין וִֽ֝⁠ישָׁרִ֗ים לְ⁠מֹ֣צְאֵי דָֽעַת׃","ku̇lá֣̇⁠m nĕ֭kòẖiym la⁠mé̇bi֑yn wiֽ֝⁠yşá̌ri֗ym lĕ⁠mò֣ẕĕʼéy dáֽʻaţ׃"],[8,10,"קְחֽוּ־מוּסָרִ֥⁠י וְ⁠אַל־כָּ֑סֶף וְ֝⁠דַ֗עַת מֵ⁠חָר֥וּץ נִבְחָֽר׃","qĕẖֽẇ-mẇsári֥⁠y wĕ⁠ʼal-ká֑̇sep wĕ֝⁠da֗ʻaţ mé⁠ẖár֥ẇẕ nibĕẖáֽr׃"],[8,11,"כִּֽי־טוֹבָ֣ה חָ֭כְמָה מִ⁠פְּנִינִ֑ים וְ⁠כָל־חֲ֝פָצִ֗ים לֹ֣א יִֽשְׁווּ־בָֽ⁠הּ׃","kiֽ̇y-twòbá֣h ẖá֭kĕmáh mi⁠pĕ̇niyni֑ym wĕ⁠kál-ẖà֝páẕi֗ym lò֣ʼ yiֽşĕ̌wẇ-báֽ⁠ḣ׃"],[8,12,"אֲֽנִי־חָ֭כְמָה שָׁכַ֣נְתִּי עָרְמָ֑ה וְ⁠דַ֖עַת מְזִמּ֣וֹת אֶמְצָֽא׃","ʼàֽniy-ẖá֭kĕmáh şá̌ka֣nĕţi̇y ʻárĕmá֑h wĕ⁠da֖ʻaţ mĕziṁ֣wòţ ʼemĕẕáֽʼ׃"],[8,13,"יִֽרְאַ֣ת יְהוָה֮ שְֽׂנֹ֫את רָ֥ע גֵּ֘אָ֤ה וְ⁠גָא֨וֹן ׀ וְ⁠דֶ֣רֶךְ רָ֭ע וּ⁠פִ֨י תַהְפֻּכ֬וֹת שָׂנֵֽאתִי׃","yiֽrĕʼa֣ţ yĕhwáh֮ şĕֽ̂nò֫ʼţ rá֥ʻ gé̇֘ʼá֤h wĕ⁠gáʼ֨wòn ׀ wĕ⁠de֣rekĕ rá֭ʻ ẇ⁠pi֨y ţahĕpu̇k֬wòţ şá̂néֽʼţiy׃"],[8,14,"לִֽ⁠י־עֵ֭צָה וְ⁠תוּשִׁיָּ֑ה אֲנִ֥י בִ֝ינָ֗ה לִ֣⁠י גְבוּרָֽה׃","liֽ⁠y-ʻé֭ẕáh wĕ⁠ţẇşǐyá֑̇h ʼàni֥y bi֝yná֗h li֣⁠y gĕbẇráֽh׃"],[8,15,"בִּ֭⁠י מְלָכִ֣ים יִמְלֹ֑כוּ וְ֝⁠רוֹזְנִ֗ים יְחֹ֣קְקוּ צֶֽדֶק׃","bi֭̇⁠y mĕláki֣ym yimĕlò֑kẇ wĕ֝⁠rwòzĕni֗ym yĕẖò֣qĕqẇ ẕeֽdeq׃"],[8,16,"בִּ֭⁠י שָׂרִ֣ים יָשֹׂ֑רוּ וּ֝⁠נְדִיבִ֗ים כָּל־שֹׁ֥פְטֵי צֶֽדֶק׃","bi֭̇⁠y şá̂ri֣ym yáşò֑̂rẇ ẇ֝⁠nĕdiybi֗ym ká̇l-şò֥̌pĕtéy ẕeֽdeq׃"],[8,17,"אֲ֭נִי אהבי⁠ה אֵהָ֑ב וּ֝⁠מְשַׁחֲרַ֗⁠י יִמְצָאֻֽ⁠נְנִי׃","ʼà֭niy ʼhby⁠h ʼéhá֑b ẇ֝⁠mĕşǎẖàra֗⁠y yimĕẕáʼuֽ⁠nĕniy׃"],[8,18,"עֹֽשֶׁר־וְ⁠כָב֥וֹד אִתִּ֑⁠י ה֥וֹן עָ֝תֵ֗ק וּ⁠צְדָקָֽה׃","ʻòֽşěr-wĕ⁠káb֥wòd ʼiţi֑̇⁠y h֥wòn ʻá֝ţé֗q ẇ⁠ẕĕdáqáֽh׃"],[8,19,"ט֣וֹב פִּ֭רְיִ⁠י מֵ⁠חָר֣וּץ וּ⁠מִ⁠פָּ֑ז וּ֝⁠תְבוּאָתִ֗⁠י מִ⁠כֶּ֥סֶף נִבְחָֽר׃","t֣wòb pi֭̇rĕyi⁠y mé⁠ẖár֣ẇẕ ẇ⁠mi⁠pá֑̇z ẇ֝⁠ţĕbẇʼáţi֗⁠y mi⁠kė֥sep nibĕẖáֽr׃"],[8,20,"בְּ⁠אֹֽרַח־צְדָקָ֥ה אֲהַלֵּ֑ך בְּ֝⁠ת֗וֹךְ נְתִיב֥וֹת מִשְׁפָּֽט׃","bĕ̇⁠ʼòֽraẖ-ẕĕdáqá֥h ʼàhalé֑̇k bĕ̇֝⁠ţ֗wòkĕ nĕţiyb֥wòţ mişĕ̌páֽ̇t׃"],[8,21,"לְ⁠הַנְחִ֖יל אֹהֲבַ֥⁠י ׀ יֵ֑שׁ וְ⁠אֹצְרֹ֖תֵי⁠הֶ֣ם אֲמַלֵּֽא׃פ","lĕ⁠hanĕẖi֖yl ʼòhàba֥⁠y ׀ yé֑ş̌ wĕ⁠ʼòẕĕrò֖ţéy⁠he֣m ʼàmaléֽ̇ʼ׃p"],[8,22,"יְֽהוָ֗ה קָ֭נָ⁠נִי רֵאשִׁ֣ית דַּרְכּ֑⁠וֹ קֶ֖דֶם מִפְעָלָ֣י⁠ו מֵ⁠אָֽז׃","yĕֽhwá֗h qá֭ná⁠niy réʼşǐ֣yţ dȧrĕk֑̇⁠wò qe֖dem mipĕʻálá֣y⁠w mé⁠ʼáֽz׃"],[8,23,"מֵ֭⁠עוֹלָם נִסַּ֥כְתִּי מֵ⁠רֹ֗אשׁ מִ⁠קַּדְמֵי־אָֽרֶץ׃","mé֭⁠ʻwòlám nisȧ֥kĕţi̇y mé⁠rò֗ʼş̌ mi⁠qȧdĕméy-ʼáֽreẕ׃"],[8,24,"בְּ⁠אֵין־תְּהֹמ֥וֹת חוֹלָ֑לְתִּי בְּ⁠אֵ֥ין מַ֝עְיָנ֗וֹת נִכְבַּדֵּי־מָֽיִם׃","bĕ̇⁠ʼéyn-ţĕ̇hòm֥wòţ ẖwòlá֑lĕţi̇y bĕ̇⁠ʼé֥yn ma֝ʻĕyán֗wòţ nikĕbȧdé̇y-máֽyim׃"],[8,25,"בְּ⁠טֶ֣רֶם הָרִ֣ים הָטְבָּ֑עוּ לִ⁠פְנֵ֖י גְבָע֣וֹת חוֹלָֽלְתִּי׃","bĕ̇⁠te֣rem hári֣ym hátĕbá֑̇ʻẇ li⁠pĕné֖y gĕbáʻ֣wòţ ẖwòláֽlĕţi̇y׃"],[8,26,"עַד־לֹ֣א עָ֭שָׂה אֶ֣רֶץ וְ⁠חוּצ֑וֹת וְ֝⁠רֹ֗אשׁ עָפְר֥וֹת תֵּבֵֽל׃","ʻad-lò֣ʼ ʻá֭şá̂h ʼe֣reẕ wĕ⁠ẖẇẕ֑wòţ wĕ֝⁠rò֗ʼş̌ ʻápĕr֥wòţ ţé̇béֽl׃"],[8,27,"בַּ⁠הֲכִינ֣⁠וֹ שָׁ֭מַיִם שָׁ֣ם אָ֑נִי בְּ⁠ח֥וּק⁠וֹ ח֝֗וּג עַל־פְּנֵ֥י תְהֽוֹם׃","bȧ⁠hàkiyn֣⁠wò şá֭̌mayim şá֣̌m ʼá֑niy bĕ̇⁠ẖ֥ẇq⁠wò ẖ֝֗ẇg ʻal-pĕ̇né֥y ţĕhֽwòm׃"],[8,28,"בְּ⁠אַמְּצ֣⁠וֹ שְׁחָקִ֣ים מִ⁠מָּ֑עַל בַּ֝⁠עֲז֗וֹז עִינ֥וֹת תְּהוֹם׃","bĕ̇⁠ʼamĕ̇ẕ֣⁠wò şĕ̌ẖáqi֣ym mi⁠má֑̇ʻal bȧ֝⁠ʻàz֗wòz ʻiyn֥wòţ ţĕ̇hwòm׃"],[8,29,"בְּ⁠שׂ֘וּמ֤⁠וֹ לַ⁠יָּ֨ם ׀ חֻקּ֗⁠וֹ וּ֭⁠מַיִם לֹ֣א יַֽעַבְרוּ־פִ֑י⁠ו בְּ֝⁠חוּק֗⁠וֹ מ֣וֹסְדֵי אָֽרֶץ׃","bĕ̇⁠ş̂֘ẇm֤⁠wò la⁠yá̇֨m ׀ ẖuq̇֗⁠wò ẇ֭⁠mayim lò֣ʼ yaֽʻabĕrẇ-pi֑y⁠w bĕ̇֝⁠ẖẇq֗⁠wò m֣wòsĕdéy ʼáֽreẕ׃"],[8,30,"וָֽ⁠אֶהְיֶ֥ה אֶצְל֗⁠וֹ אָ֫מ֥וֹן וָֽ⁠אֶהְיֶ֣ה שַׁ֭עֲשֻׁעִים י֤וֹם ׀ י֑וֹם מְשַׂחֶ֖קֶת לְ⁠פָנָ֣י⁠ו בְּ⁠כָל־עֵֽת׃","wáֽ⁠ʼehĕye֥h ʼeẕĕl֗⁠wò ʼá֫m֥wòn wáֽ⁠ʼehĕye֣h şǎ֭ʻàşǔʻiym y֤wòm ׀ y֑wòm mĕşâẖe֖qeţ lĕ⁠páná֣y⁠w bĕ̇⁠kál-ʻéֽţ׃"],[8,31,"מְ֭שַׂחֶקֶת בְּ⁠תֵבֵ֣ל אַרְצ֑⁠וֹ וְ֝⁠שַׁעֲשֻׁעַ֗⁠י אֶת־בְּנֵ֥י אָדָֽם׃פ","mĕ֭şâẖeqeţ bĕ̇⁠ţébé֣l ʼarĕẕ֑⁠wò wĕ֝⁠şǎʻàşǔʻa֗⁠y ʼeţ-bĕ̇né֥y ʼádáֽm׃p"],[8,32,"וְ⁠עַתָּ֣ה בָ֭נִים שִׁמְעוּ־לִ֑⁠י וְ֝⁠אַשְׁרֵ֗י דְּרָכַ֥⁠י יִשְׁמֹֽרוּ׃","wĕ⁠ʻaţá֣̇h bá֭niym şǐmĕʻẇ-li֑⁠y wĕ֝⁠ʼaşĕ̌ré֗y dĕ̇ráka֥⁠y yişĕ̌mòֽrẇ׃"],[8,33,"שִׁמְע֖וּ מוּסָ֥ר וַ⁠חֲכָ֗מוּ וְ⁠אַל־תִּפְרָֽעוּ׃","şǐmĕʻ֖ẇ mẇsá֥r wa⁠ẖàká֗mẇ wĕ⁠ʼal-ţi̇pĕráֽʻẇ׃"],[8,34,"אַ֥שְֽׁרֵי אָדָם֮ שֹׁמֵ֪עַֽ֫ לִ֥⁠י לִ⁠שְׁקֹ֣ד עַל־דַּ֭לְתֹתַ⁠י י֤וֹם ׀ י֑וֹם לִ֝⁠שְׁמֹ֗ר מְזוּזֹ֥ת פְּתָחָֽ⁠י׃","ʼa֥şĕֽ̌réy ʼádám֮ şò̌mé֪ʻaֽ֫ li֥⁠y li⁠şĕ̌qò֣d ʻal-dȧ֭lĕţòţa⁠y y֤wòm ׀ y֑wòm li֝⁠şĕ̌mò֗r mĕzẇzò֥ţ pĕ̇ţáẖáֽ⁠y׃"],[8,35,"כִּ֣י מֹ֭צְאִ⁠י מצאי חַיִּ֑ים וַ⁠יָּ֥פֶק רָ֝צ֗וֹן מֵ⁠יְהוָֽה׃","ki֣̇y mò֭ẕĕʼi⁠y mẕʼy ẖayi֑̇ym wa⁠yá֥̇peq rá֝ẕ֗wòn mé⁠yĕhwáֽh׃"],[8,36,"וְֽ֭⁠חֹטְאִ⁠י חֹמֵ֣ס נַפְשׁ֑⁠וֹ כָּל־מְ֝שַׂנְאַ֗⁠י אָ֣הֲבוּ מָֽוֶת׃פ","wĕֽ֭⁠ẖòtĕʼi⁠y ẖòmé֣s napĕş֑̌⁠wò ká̇l-mĕ֝şânĕʼa֗⁠y ʼá֣hàbẇ máֽweţ׃p"],[9,1,"חָ֭כְמוֹת בָּנְתָ֣ה בֵיתָ֑⁠הּ חָצְבָ֖ה עַמּוּדֶ֣י⁠הָ שִׁבְעָֽה׃","ẖá֭kĕmwòţ bá̇nĕţá֣h béyţá֑⁠ḣ ẖáẕĕbá֖h ʻaṁẇde֣y⁠há şǐbĕʻáֽh׃"],[9,2,"טָבְחָ֣ה טִ֭בְחָ⁠הּ מָסְכָ֣ה יֵינָ֑⁠הּ אַ֝֗ף עָֽרְכָ֥ה שֻׁלְחָנָֽ⁠הּ׃","tábĕẖá֣h ti֭bĕẖá⁠ḣ másĕká֣h yéyná֑⁠ḣ ʼa֝֗p ʻáֽrĕká֥h şǔlĕẖánáֽ⁠ḣ׃"],[9,3,"שָֽׁלְחָ֣ה נַעֲרֹתֶ֣י⁠הָ תִקְרָ֑א עַל־גַּ֝פֵּ֗י מְרֹ֣מֵי קָֽרֶת׃","şáֽ̌lĕẖá֣h naʻàròţe֣y⁠há ţiqĕrá֑ʼ ʻal-gȧ֝pé̇֗y mĕrò֣méy qáֽreţ׃"],[9,4,"מִי־פֶ֭תִי יָסֻ֣ר הֵ֑נָּה חֲסַר־לֵ֝֗ב אָ֣מְרָה לּֽ⁠וֹ׃","miy-pe֭ţiy yásu֣r hé֑ná̇h ẖàsar-lé֝֗b ʼá֣mĕráh lֽ̇⁠wò׃"],[9,5,"לְ֭כוּ לַחֲמ֣וּ בְֽ⁠לַחֲמִ֑⁠י וּ֝⁠שְׁת֗וּ בְּ⁠יַ֣יִן מָסָֽכְתִּי׃","lĕ֭kẇ laẖàm֣ẇ bĕֽ⁠laẖàmi֑⁠y ẇ֝⁠şĕ̌ţ֗ẇ bĕ̇⁠ya֣yin másáֽkĕţi̇y׃"],[9,6,"עִזְב֣וּ פְתָאיִ֣ם וִֽ⁠חְי֑וּ וְ֝⁠אִשְׁר֗וּ בְּ⁠דֶ֣רֶךְ בִּינָֽה׃","ʻizĕb֣ẇ pĕţáʼyi֣m wiֽ⁠ẖĕy֑ẇ wĕ֝⁠ʼişĕ̌r֗ẇ bĕ̇⁠de֣rekĕ bi̇ynáֽh׃"],[9,7,"יֹ֤סֵ֨ר ׀ לֵ֗ץ לֹקֵ֣חַֽ ל֣⁠וֹ קָל֑וֹן וּ⁠מוֹכִ֖יחַ לְ⁠רָשָׁ֣ע מוּמֽ⁠וֹ׃","yò֤sé֨r ׀ lé֗ẕ lòqé֣ẖaֽ l֣⁠wò qál֑wòn ẇ⁠mwòki֖yẖa lĕ⁠ráşá֣̌ʻ mẇmֽ⁠wò׃"],[9,8,"אַל־תּ֣וֹכַח לֵ֭ץ פֶּן־יִשְׂנָאֶ֑⁠ךָּ הוֹכַ֥ח לְ֝⁠חָכָ֗ם וְ⁠יֶאֱהָבֶֽ⁠ךָּ׃","ʼal-ţ֣̇wòkaẖ lé֭ẕ pėn-yişĕ̂náʼe֑⁠ká̇ hwòka֥ẖ lĕ֝⁠ẖáká֗m wĕ⁠yeʼèhábeֽ⁠ká̇׃"],[9,9,"תֵּ֣ן לְ֭⁠חָכָם וְ⁠יֶחְכַּם־ע֑וֹד הוֹדַ֥ע לְ֝⁠צַדִּ֗יק וְ⁠י֣וֹסֶף לֶֽקַח׃פ","ţé֣̇n lĕ֭⁠ẖákám wĕ⁠yeẖĕkȧm-ʻ֑wòd hwòda֥ʻ lĕ֝⁠ẕadi̇֗yq wĕ⁠y֣wòsep leֽqaẖ׃p"],[9,10,"תְּחִלַּ֣ת חָ֭כְמָה יִרְאַ֣ת יְהוָ֑ה וְ⁠דַ֖עַת קְדֹשִׁ֣ים בִּינָֽה׃","ţĕ̇ẖilȧ֣ţ ẖá֭kĕmáh yirĕʼa֣ţ yĕhwá֑h wĕ⁠da֖ʻaţ qĕdòşǐ֣ym bi̇ynáֽh׃"],[9,11,"כִּי־בִ֭⁠י יִרְבּ֣וּ יָמֶ֑י⁠ךָ וְ⁠יוֹסִ֥יפוּ לְּ֝⁠ךָ֗ שְׁנ֣וֹת חַיִּֽים׃","ki̇y-bi֭⁠y yirĕḃ֣ẇ yáme֑y⁠ká wĕ⁠ywòsi֥ypẇ lĕ̇֝⁠ká֗ şĕ̌n֣wòţ ẖayiֽ̇ym׃"],[9,12,"אִם־חָ֭כַמְתָּ חָכַ֣מְתָּ לָּ֑⁠ךְ וְ֝⁠לַ֗צְתָּ לְֽ⁠בַדְּ⁠ךָ֥ תִשָּֽׂא׃","ʼim-ẖá֭kamĕţá̇ ẖáka֣mĕţá̇ lá֑̇⁠kĕ wĕ֝⁠la֗ẕĕţá̇ lĕֽ⁠badĕ̇⁠ká֥ ţişáֽ̇̂ʼ׃"],[9,13,"אֵ֣שֶׁת כְּ֭סִילוּת הֹֽמִיָּ֑ה פְּ֝תַיּ֗וּת וּ⁠בַל־יָ֥דְעָה מָּֽה׃","ʼé֣şěţ kĕ֭̇siylẇţ hòֽmiyá֑̇h pĕ̇֝ţaẏ֗ẇţ ẇ⁠bal-yá֥dĕʻáh máֽ̇h׃"],[9,14,"וְֽ֭⁠יָשְׁבָה לְ⁠פֶ֣תַח בֵּיתָ֑⁠הּ עַל־כִּ֝סֵּ֗א מְרֹ֣מֵי קָֽרֶת׃","wĕֽ֭⁠yáşĕ̌báh lĕ⁠pe֣ţaẖ bé̇yţá֑⁠ḣ ʻal-ki̇֝sé̇֗ʼ mĕrò֣méy qáֽreţ׃"],[9,15,"לִ⁠קְרֹ֥א לְ⁠עֹֽבְרֵי־דָ֑רֶךְ הַֽ֝⁠מְיַשְּׁרִ֗ים אֹֽרְחוֹתָֽ⁠ם׃","li⁠qĕrò֥ʼ lĕ⁠ʻòֽbĕréy-dá֑rekĕ haֽ֝⁠mĕyaşĕ̇̌ri֗ym ʼòֽrĕẖwòţáֽ⁠m׃"],[9,16,"מִי־פֶ֭תִי יָסֻ֣ר הֵ֑נָּה וַ⁠חֲסַר־לֵ֝֗ב וְ⁠אָ֣מְרָה לּֽ⁠וֹ׃","miy-pe֭ţiy yásu֣r hé֑ná̇h wa⁠ẖàsar-lé֝֗b wĕ⁠ʼá֣mĕráh lֽ̇⁠wò׃"],[9,17,"מַֽיִם־גְּנוּבִ֥ים יִמְתָּ֑קוּ וְ⁠לֶ֖חֶם סְתָרִ֣ים יִנְעָֽם׃","maֽyim-gĕ̇nẇbi֥ym yimĕţá֑̇qẇ wĕ⁠le֖ẖem sĕţári֣ym yinĕʻáֽm׃"],[9,18,"וְֽ⁠לֹא־יָ֭דַע כִּֽי־רְפָאִ֣ים שָׁ֑ם בְּ⁠עִמְקֵ֖י שְׁא֣וֹל קְרֻאֶֽי⁠הָ׃פ","wĕֽ⁠lòʼ-yá֭daʻ kiֽ̇y-rĕpáʼi֣ym şá֑̌m bĕ̇⁠ʻimĕqé֖y şĕ̌ʼ֣wòl qĕruʼeֽy⁠há׃p"],[10,1,"מִשְׁלֵ֗י שְׁלֹ֫מֹ֥ה פ בֵּ֣ן חָ֭כָם יְשַׂמַּח־אָ֑ב וּ⁠בֵ֥ן כְּ֝סִ֗יל תּוּגַ֥ת אִמּֽ⁠וֹ׃","mişĕ̌lé֗y şĕ̌lò֫mò֥h p bé֣̇n ẖá֭kám yĕşâmȧẖ-ʼá֑b ẇ⁠bé֥n kĕ̇֝si֗yl ţ̇ẇga֥ţ ʼiṁֽ⁠wò׃"],[10,2,"לֹא־י֭וֹעִילוּ אוֹצְר֣וֹת רֶ֑שַׁע וּ֝⁠צְדָקָ֗ה תַּצִּ֥יל מִ⁠מָּֽוֶת׃","lòʼ-y֭wòʻiylẇ ʼwòẕĕr֣wòţ re֑şǎʻ ẇ֝⁠ẕĕdáqá֗h ţȧẕi֥̇yl mi⁠máֽ̇weţ׃"],[10,3,"לֹֽא־יַרְעִ֣יב יְ֭הוָה נֶ֣פֶשׁ צַדִּ֑יק וְ⁠הַוַּ֖ת רְשָׁעִ֣ים יֶהְדֹּֽף׃","lòֽʼ-yarĕʻi֣yb yĕ֭hwáh ne֣peş̌ ẕadi֑̇yq wĕ⁠hawȧ֖ţ rĕşá̌ʻi֣ym yehĕdòֽ̇p׃"],[10,4,"רָ֗אשׁ עֹשֶׂ֥ה כַף־רְמִיָּ֑ה וְ⁠יַ֖ד חָרוּצִ֣ים תַּעֲשִֽׁיר׃","rá֗ʼş̌ ʻòşê֥h kap-rĕmiyá֑̇h wĕ⁠ya֖d ẖárẇẕi֣ym ţȧʻàşǐֽyr׃"],[10,5,"אֹגֵ֣ר בַּ֭⁠קַּיִץ בֵּ֣ן מַשְׂכִּ֑יל נִרְדָּ֥ם בַּ֝⁠קָּצִ֗יר בֵּ֣ן מֵבִֽישׁ׃","ʼògé֣r bȧ֭⁠qȧyiẕ bé֣̇n maşĕ̂ki֑̇yl nirĕdá֥̇m bȧ֝⁠qá̇ẕi֗yr bé֣̇n mébiֽyş̌׃"],[10,6,"בְּ֭רָכוֹת לְ⁠רֹ֣אשׁ צַדִּ֑יק וּ⁠פִ֥י רְ֝שָׁעִ֗ים יְכַסֶּ֥ה חָמָֽס׃","bĕ֭̇rákwòţ lĕ⁠rò֣ʼş̌ ẕadi֑̇yq ẇ⁠pi֥y rĕ֝şá̌ʻi֗ym yĕkasė֥h ẖámáֽs׃"],[10,7,"זֵ֣כֶר צַ֭דִּיק לִ⁠בְרָכָ֑ה וְ⁠שֵׁ֖ם רְשָׁעִ֣ים יִרְקָֽב׃","zé֣ker ẕa֭di̇yq li⁠bĕráká֑h wĕ⁠şé֖̌m rĕşá̌ʻi֣ym yirĕqáֽb׃"],[10,8,"חֲכַם־לֵ֭ב יִקַּ֣ח מִצְוֺ֑ת וֶ⁠אֱוִ֥יל שְׂ֝פָתַ֗יִם יִלָּבֵֽט׃","ẖàkam-lé֭b yiqȧ֣ẖ miẕĕwֺ֑ţ we⁠ʼèwi֥yl şĕ̂֝páţa֗yim yilá̇béֽt׃"],[10,9,"הוֹלֵ֣ךְ בַּ֭⁠תֹּם יֵ֣לֶךְ בֶּ֑טַח וּ⁠מְעַקֵּ֥שׁ דְּ֝רָכָ֗י⁠ו יִוָּדֵֽעַ׃","hwòlé֣kĕ bȧ֭⁠ţò̇m yé֣lekĕ bė֑taẖ ẇ⁠mĕʻaqé֥̇ş̌ dĕ̇֝ráká֗y⁠w yiwá̇déֽʻa׃"],[10,10,"קֹ֣רֵֽץ עַ֭יִן יִתֵּ֣ן עַצָּ֑בֶת וֶ⁠אֱוִ֥יל שְׂ֝פָתַ֗יִם יִלָּבֵֽט׃","qò֣réֽẕ ʻa֭yin yiţé֣̇n ʻaẕá֑̇beţ we⁠ʼèwi֥yl şĕ̂֝páţa֗yim yilá̇béֽt׃"],[10,11,"מְק֣וֹר חַ֭יִּים פִּ֣י צַדִּ֑יק וּ⁠פִ֥י רְ֝שָׁעִ֗ים יְכַסֶּ֥ה חָמָֽס׃","mĕq֣wòr ẖa֭yi̇ym pi֣̇y ẕadi֑̇yq ẇ⁠pi֥y rĕ֝şá̌ʻi֗ym yĕkasė֥h ẖámáֽs׃"],[10,12,"שִׂ֭נְאָה תְּעוֹרֵ֣ר מְדָנִ֑ים וְ⁠עַ֥ל כָּל־פְּ֝שָׁעִ֗ים תְּכַסֶּ֥ה אַהֲבָֽה׃","şî֭nĕʼáh ţĕ̇ʻwòré֣r mĕdáni֑ym wĕ⁠ʻa֥l ká̇l-pĕ̇֝şá̌ʻi֗ym ţĕ̇kasė֥h ʼahàbáֽh׃"],[10,13,"בְּ⁠שִׂפְתֵ֣י נָ֭בוֹן תִּמָּצֵ֣א חָכְמָ֑ה וְ֝⁠שֵׁ֗בֶט לְ⁠גֵ֣ו חֲסַר־לֵֽב׃","bĕ̇⁠şîpĕţé֣y ná֭bwòn ţi̇má̇ẕé֣ʼ ẖákĕmá֑h wĕ֝⁠şé̌֗bet lĕ⁠gé֣w ẖàsar-léֽb׃"],[10,14,"חֲכָמִ֥ים יִצְפְּנוּ־דָ֑עַת וּ⁠פִֽי־אֱ֝וִיל מְחִתָּ֥ה קְרֹבָֽה׃","ẖàkámi֥ym yiẕĕpĕ̇nẇ-dá֑ʻaţ ẇ⁠piֽy-ʼè֝wiyl mĕẖiţá֥̇h qĕròbáֽh׃"],[10,15,"ה֣וֹן עָ֭שִׁיר קִרְיַ֣ת עֻזּ֑⁠וֹ מְחִתַּ֖ת דַּלִּ֣ים רֵישָֽׁ⁠ם׃","h֣wòn ʻá֭şǐyr qirĕya֣ţ ʻuż֑⁠wò mĕẖiţȧ֖ţ dȧli֣̇ym réyşáֽ̌⁠m׃"],[10,16,"פְּעֻלַּ֣ת צַדִּ֣יק לְ⁠חַיִּ֑ים תְּבוּאַ֖ת רָשָׁ֣ע לְ⁠חַטָּֽאת׃","pĕ̇ʻulȧ֣ţ ẕadi֣̇yq lĕ⁠ẖayi֑̇ym ţĕ̇bẇʼa֖ţ ráşá֣̌ʻ lĕ⁠ẖatáֽ̇ʼţ׃"],[10,17,"אֹ֣רַח לְ֭⁠חַיִּים שׁוֹמֵ֣ר מוּסָ֑ר וְ⁠עוֹזֵ֖ב תּוֹכַ֣חַת מַתְעֶֽה׃","ʼò֣raẖ lĕ֭⁠ẖayi̇ym ş̌wòmé֣r mẇsá֑r wĕ⁠ʻwòzé֖b ţ̇wòka֣ẖaţ maţĕʻeֽh׃"],[10,18,"מְכַסֶּ֣ה שִׂ֭נְאָה שִׂפְתֵי־שָׁ֑קֶר וּ⁠מוֹצִ֥א דִ֝בָּ֗ה ה֣וּא כְסִֽיל׃","mĕkasė֣h şî֭nĕʼáh şîpĕţéy-şá֑̌qer ẇ⁠mwòẕi֥ʼ di֝bá̇֗h h֣ẇʼ kĕsiֽyl׃"],[10,19,"בְּ⁠רֹ֣ב דְּ֭בָרִים לֹ֣א יֶחְדַּל־פָּ֑שַׁע וְ⁠חֹשֵׂ֖ךְ שְׂפָתָ֣י⁠ו מַשְׂכִּֽיל׃","bĕ̇⁠rò֣b dĕ֭̇báriym lò֣ʼ yeẖĕdȧl-pá֑̇şǎʻ wĕ⁠ẖòşé֖̂kĕ şĕ̂páţá֣y⁠w maşĕ̂kiֽ̇yl׃"],[10,20,"כֶּ֣סֶף נִ֭בְחָר לְשׁ֣וֹן צַדִּ֑יק לֵ֖ב רְשָׁעִ֣ים כִּ⁠מְעָֽט׃","kė֣sep ni֭bĕẖár lĕş֣̌wòn ẕadi֑̇yq lé֖b rĕşá̌ʻi֣ym ki̇⁠mĕʻáֽt׃"],[10,21,"שִׂפְתֵ֣י צַ֭דִּיק יִרְע֣וּ רַבִּ֑ים וֶֽ֝⁠אֱוִילִ֗ים בַּ⁠חֲסַר־לֵ֥ב יָמֽוּתוּ׃","şîpĕţé֣y ẕa֭di̇yq yirĕʻ֣ẇ rabi֑̇ym weֽ֝⁠ʼèwiyli֗ym bȧ⁠ẖàsar-lé֥b yámֽẇţẇ׃"],[10,22,"בִּרְכַּ֣ת יְ֭הוָה הִ֣יא תַעֲשִׁ֑יר וְ⁠לֹֽא־יוֹסִ֖ף עֶ֣צֶב עִמָּֽ⁠הּ׃","bi̇rĕkȧ֣ţ yĕ֭hwáh hi֣yʼ ţaʻàşǐ֑yr wĕ⁠lòֽʼ-ywòsi֖p ʻe֣ẕeb ʻimáֽ̇⁠ḣ׃"],[10,23,"כִּ⁠שְׂח֣וֹק לִ֭⁠כְסִיל עֲשׂ֣וֹת זִמָּ֑ה וְ֝⁠חָכְמָ֗ה לְ⁠אִ֣ישׁ תְּבוּנָֽה׃","ki̇⁠şĕ̂ẖ֣wòq li֭⁠kĕsiyl ʻàş֣̂wòţ zimá֑̇h wĕ֝⁠ẖákĕmá֗h lĕ⁠ʼi֣yş̌ ţĕ̇bẇnáֽh׃"],[10,24,"מְגוֹרַ֣ת רָ֭שָׁע הִ֣יא תְבוֹאֶ֑⁠נּוּ וְ⁠תַאֲוַ֖ת צַדִּיקִ֣ים יִתֵּֽן׃","mĕgwòra֣ţ rá֭şá̌ʻ hi֣yʼ ţĕbwòʼe֑⁠ṅẇ wĕ⁠ţaʼàwa֖ţ ẕadi̇yqi֣ym yiţéֽ̇n׃"],[10,25,"כַּ⁠עֲב֣וֹר ס֭וּפָה וְ⁠אֵ֣ין רָשָׁ֑ע וְ֝⁠צַדִּ֗יק יְס֣וֹד עוֹלָֽם׃","kȧ⁠ʻàb֣wòr s֭ẇpáh wĕ⁠ʼé֣yn ráşá֑̌ʻ wĕ֝⁠ẕadi̇֗yq yĕs֣wòd ʻwòláֽm׃"],[10,26,"כַּ⁠חֹ֤מֶץ ׀ לַ⁠שִּׁנַּ֗יִם וְ⁠כֶ⁠עָשָׁ֥ן לָ⁠עֵינָ֑יִם כֵּ֥ן הֶ֝⁠עָצֵ֗ל לְ⁠שֹׁלְחָֽי⁠ו׃","kȧ⁠ẖò֤meẕ ׀ la⁠şi̇̌nȧ֗yim wĕ⁠ke⁠ʻáşá֥̌n lá⁠ʻéyná֑yim ké֥̇n he֝⁠ʻáẕé֗l lĕ⁠şò̌lĕẖáֽy⁠w׃"],[10,27,"יִרְאַ֣ת יְ֭הוָה תּוֹסִ֣יף יָמִ֑ים וּ⁠שְׁנ֖וֹת רְשָׁעִ֣ים תִּקְצֹֽרְנָה׃","yirĕʼa֣ţ yĕ֭hwáh ţ̇wòsi֣yp yámi֑ym ẇ⁠şĕ̌n֖wòţ rĕşá̌ʻi֣ym ţi̇qĕẕòֽrĕnáh׃"],[10,28,"תּוֹחֶ֣לֶת צַדִּיקִ֣ים שִׂמְחָ֑ה וְ⁠תִקְוַ֖ת רְשָׁעִ֣ים תֹּאבֵֽד׃","ţ̇wòẖe֣leţ ẕadi̇yqi֣ym şîmĕẖá֑h wĕ⁠ţiqĕwa֖ţ rĕşá̌ʻi֣ym ţò̇ʼbéֽd׃"],[10,29,"מָע֣וֹז לַ֭⁠תֹּם דֶּ֣רֶךְ יְהוָ֑ה וּ֝⁠מְחִתָּ֗ה לְ⁠פֹ֣עֲלֵי אָֽוֶן׃","máʻ֣wòz la֭⁠ţò̇m dė֣rekĕ yĕhwá֑h ẇ֝⁠mĕẖiţá̇֗h lĕ⁠pò֣ʻàléy ʼáֽwen׃"],[10,30,"צַדִּ֣יק לְ⁠עוֹלָ֣ם בַּל־יִמּ֑וֹט וּ֝⁠רְשָׁעִ֗ים לֹ֣א יִשְׁכְּנוּ־אָֽרֶץ׃","ẕadi֣̇yq lĕ⁠ʻwòlá֣m bȧl-yiṁ֑wòt ẇ֝⁠rĕşá̌ʻi֗ym lò֣ʼ yişĕ̌kĕ̇nẇ-ʼáֽreẕ׃"],[10,31,"פִּֽי־צַ֭דִּיק יָנ֣וּב חָכְמָ֑ה וּ⁠לְשׁ֥וֹן תַּ֝הְפֻּכ֗וֹת תִּכָּרֵֽת׃","piֽ̇y-ẕa֭di̇yq yán֣ẇb ẖákĕmá֑h ẇ⁠lĕş֥̌wòn ţȧ֝hĕpu̇k֗wòţ ţi̇ká̇réֽţ׃"],[10,32,"שִׂפְתֵ֣י צַ֭דִּיק יֵדְע֣וּ⁠ן רָצ֑וֹן וּ⁠פִ֥י רְ֝שָׁעִ֗ים תַּהְפֻּכֽוֹת׃","şîpĕţé֣y ẕa֭di̇yq yédĕʻ֣ẇ⁠n ráẕ֑wòn ẇ⁠pi֥y rĕ֝şá̌ʻi֗ym ţȧhĕpu̇kֽwòţ׃"],[11,1,"מֹאזְנֵ֣י מִ֭רְמָה תּוֹעֲבַ֣ת יְהוָ֑ה וְ⁠אֶ֖בֶן שְׁלֵמָ֣ה רְצוֹנֽ⁠וֹ׃","mòʼzĕné֣y mi֭rĕmáh ţ̇wòʻàba֣ţ yĕhwá֑h wĕ⁠ʼe֖ben şĕ̌lémá֣h rĕẕwònֽ⁠wò׃"],[11,2,"בָּֽא־זָ֭דוֹן וַ⁠יָּבֹ֣א קָל֑וֹן וְֽ⁠אֶת־צְנוּעִ֥ים חָכְמָֽה׃","báֽ̇ʼ-zá֭dwòn wa⁠yá̇bò֣ʼ qál֑wòn wĕֽ⁠ʼeţ-ẕĕnẇʻi֥ym ẖákĕmáֽh׃"],[11,3,"תֻּמַּ֣ת יְשָׁרִ֣ים תַּנְחֵ֑⁠ם וְ⁠סֶ֖לֶף בּוֹגְדִ֣ים ו⁠שד⁠ם׃","ţu̇mȧ֣ţ yĕşá̌ri֣ym ţȧnĕẖé֑⁠m wĕ⁠se֖lep ḃwògĕdi֣ym w⁠şd⁠m׃"],[11,4,"לֹא־יוֹעִ֣יל ה֭וֹן בְּ⁠י֣וֹם עֶבְרָ֑ה וּ֝⁠צְדָקָ֗ה תַּצִּ֥יל מִ⁠מָּֽוֶת׃","lòʼ-ywòʻi֣yl h֭wòn bĕ̇⁠y֣wòm ʻebĕrá֑h ẇ֝⁠ẕĕdáqá֗h ţȧẕi֥̇yl mi⁠máֽ̇weţ׃"],[11,5,"צִדְקַ֣ת תָּ֭מִים תְּיַשֵּׁ֣ר דַּרְכּ֑⁠וֹ וּ֝⁠בְ⁠רִשְׁעָת֗⁠וֹ יִפֹּ֥ל רָשָֽׁע׃","ẕidĕqa֣ţ ţá֭̇miym ţĕ̇yaşé֣̇̌r dȧrĕk֑̇⁠wò ẇ֝⁠bĕ⁠rişĕ̌ʻáţ֗⁠wò yipò֥̇l ráşáֽ̌ʻ׃"],[11,6,"צִדְקַ֣ת יְ֭שָׁרִים תַּצִּילֵ֑⁠ם וּ֝⁠בְ⁠הַוַּ֗ת בֹּגְדִ֥ים יִלָּכֵֽדוּ׃","ẕidĕqa֣ţ yĕ֭şá̌riym ţȧẕi̇ylé֑⁠m ẇ֝⁠bĕ⁠hawȧ֗ţ bò̇gĕdi֥ym yilá̇kéֽdẇ׃"],[11,7,"בְּ⁠מ֤וֹת אָדָ֣ם רָ֭שָׁע תֹּאבַ֣ד תִּקְוָ֑ה וְ⁠תוֹחֶ֖לֶת אוֹנִ֣ים אָבָֽדָה׃","bĕ̇⁠m֤wòţ ʼádá֣m rá֭şá̌ʻ ţò̇ʼba֣d ţi̇qĕwá֑h wĕ⁠ţwòẖe֖leţ ʼwòni֣ym ʼábáֽdáh׃"],[11,8,"צַ֭דִּיק מִ⁠צָּרָ֣ה נֶחֱלָ֑ץ וַ⁠יָּבֹ֖א רָשָׁ֣ע תַּחְתָּֽי⁠ו׃","ẕa֭di̇yq mi⁠ẕá̇rá֣h neẖèlá֑ẕ wa⁠yá̇bò֖ʼ ráşá֣̌ʻ ţȧẖĕţáֽ̇y⁠w׃"],[11,9,"בְּ⁠פֶ֗ה חָ֭נֵף יַשְׁחִ֣ת רֵעֵ֑⁠הוּ וּ֝⁠בְ⁠דַ֗עַת צַדִּיקִ֥ים יֵחָלֵֽצוּ׃","bĕ̇⁠pe֗h ẖá֭nép yaşĕ̌ẖi֣ţ réʻé֑⁠hẇ ẇ֝⁠bĕ⁠da֗ʻaţ ẕadi̇yqi֥ym yéẖáléֽẕẇ׃"],[11,10,"בְּ⁠ט֣וּב צַ֭דִּיקִים תַּעֲלֹ֣ץ קִרְיָ֑ה וּ⁠בַ⁠אֲבֹ֖ד רְשָׁעִ֣ים רִנָּֽה׃","bĕ̇⁠t֣ẇb ẕa֭di̇yqiym ţȧʻàlò֣ẕ qirĕyá֑h ẇ⁠ba⁠ʼàbò֖d rĕşá̌ʻi֣ym rináֽ̇h׃"],[11,11,"בְּ⁠בִרְכַּ֣ת יְ֭שָׁרִים תָּר֣וּם קָ֑רֶת וּ⁠בְ⁠פִ֥י רְ֝שָׁעִ֗ים תֵּהָרֵֽס׃","bĕ̇⁠birĕkȧ֣ţ yĕ֭şá̌riym ţá̇r֣ẇm qá֑reţ ẇ⁠bĕ⁠pi֥y rĕ֝şá̌ʻi֗ym ţé̇háréֽs׃"],[11,12,"בָּז־לְ⁠רֵעֵ֥⁠הוּ חֲסַר־לֵ֑ב וְ⁠אִ֖ישׁ תְּבוּנ֣וֹת יַחֲרִֽישׁ׃","bá̇z-lĕ⁠réʻé֥⁠hẇ ẖàsar-lé֑b wĕ⁠ʼi֖yş̌ ţĕ̇bẇn֣wòţ yaẖàriֽyş̌׃"],[11,13,"הוֹלֵ֣ךְ רָ֭כִיל מְגַלֶּה־סּ֑וֹד וְ⁠נֶאֱמַן־ר֝֗וּחַ מְכַסֶּ֥ה דָבָֽר׃","hwòlé֣kĕ rá֭kiyl mĕgalėh-ṡ֑wòd wĕ⁠neʼèman-r֝֗ẇẖa mĕkasė֥h dábáֽr׃"],[11,14,"בְּ⁠אֵ֣ין תַּ֭חְבֻּלוֹת יִפָּל־עָ֑ם וּ֝⁠תְשׁוּעָ֗ה בְּ⁠רֹ֣ב יוֹעֵֽץ׃","bĕ̇⁠ʼé֣yn ţȧ֭ẖĕbu̇lwòţ yipá̇l-ʻá֑m ẇ֝⁠ţĕş̌ẇʻá֗h bĕ̇⁠rò֣b ywòʻéֽẕ׃"],[11,15,"רַע־יֵ֭רוֹעַ כִּי־עָ֣רַב זָ֑ר וְ⁠שֹׂנֵ֖א תֹקְעִ֣ים בּוֹטֵֽחַ׃","raʻ-yé֭rwòʻa ki̇y-ʻá֣rab zá֑r wĕ⁠şò̂né֖ʼ ţòqĕʻi֣ym ḃwòtéֽẖa׃"],[11,16,"אֵֽשֶׁת־חֵ֭ן תִּתְמֹ֣ךְ כָּב֑וֹד וְ֝⁠עָרִיצִ֗ים יִתְמְכוּ־עֹֽשֶׁר׃","ʼéֽşěţ-ẖé֭n ţi̇ţĕmò֣kĕ ká̇b֑wòd wĕ֝⁠ʻáriyẕi֗ym yiţĕmĕkẇ-ʻòֽşěr׃"],[11,17,"גֹּמֵ֣ל נַ֭פְשׁ⁠וֹ אִ֣ישׁ חָ֑סֶד וְ⁠עֹכֵ֥ר שְׁ֝אֵר֗⁠וֹ אַכְזָרִֽי׃","gò̇mé֣l na֭pĕş̌⁠wò ʼi֣yş̌ ẖá֑sed wĕ⁠ʻòké֥r şĕ̌֝ʼér֗⁠wò ʼakĕzáriֽy׃"],[11,18,"רָשָׁ֗ע עֹשֶׂ֥ה פְעֻלַּת־שָׁ֑קֶר וְ⁠זֹרֵ֥עַ צְ֝דָקָ֗ה שֶׂ֣כֶר אֱמֶֽת׃","ráşá̌֗ʻ ʻòşê֥h pĕʻulȧţ-şá֑̌qer wĕ⁠zòré֥ʻa ẕĕ֝dáqá֗h şê֣ker ʼèmeֽţ׃"],[11,19,"כֵּן־צְדָקָ֥ה לְ⁠חַיִּ֑ים וּ⁠מְרַדֵּ֖ף רָעָ֣ה לְ⁠מוֹתֽ⁠וֹ׃","ké̇n-ẕĕdáqá֥h lĕ⁠ẖayi֑̇ym ẇ⁠mĕradé֖̇p ráʻá֣h lĕ⁠mwòţֽ⁠wò׃"],[11,20,"תּוֹעֲבַ֣ת יְ֭הוָה עִקְּשֵׁי־לֵ֑ב וּ֝⁠רְצוֹנ֗⁠וֹ תְּמִ֣ימֵי דָֽרֶךְ׃","ţ̇wòʻàba֣ţ yĕ֭hwáh ʻiqĕ̇şé̌y-lé֑b ẇ֝⁠rĕẕwòn֗⁠wò ţĕ̇mi֣yméy dáֽrekĕ׃"],[11,21,"יָ֣ד לְ֭⁠יָד לֹא־יִנָּ֣קֶה רָּ֑ע וְ⁠זֶ֖רַע צַדִּיקִ֣ים נִמְלָֽט׃","yá֣d lĕ֭⁠yád lòʼ-yiná֣̇qeh rá֑̇ʻ wĕ⁠ze֖raʻ ẕadi̇yqi֣ym nimĕláֽt׃"],[11,22,"נֶ֣זֶם זָ֭הָב בְּ⁠אַ֣ף חֲזִ֑יר אִשָּׁ֥ה יָ֝פָ֗ה וְ⁠סָ֣רַת טָֽעַם׃","ne֣zem zá֭háb bĕ̇⁠ʼa֣p ẖàzi֑yr ʼişá֥̇̌h yá֝pá֗h wĕ⁠sá֣raţ táֽʻam׃"],[11,23,"תַּאֲוַ֣ת צַדִּיקִ֣ים אַךְ־ט֑וֹב תִּקְוַ֖ת רְשָׁעִ֣ים עֶבְרָֽה׃","ţȧʼàwa֣ţ ẕadi̇yqi֣ym ʼakĕ-t֑wòb ţi̇qĕwa֖ţ rĕşá̌ʻi֣ym ʻebĕráֽh׃"],[11,24,"יֵ֣שׁ מְ֭פַזֵּר וְ⁠נוֹסָ֥ף ע֑וֹד וְ⁠חוֹשֵׂ֥ךְ מִ֝⁠יֹּ֗שֶׁר אַךְ־לְ⁠מַחְסֽוֹר׃","yé֣ş̌ mĕ֭pazé̇r wĕ⁠nwòsá֥p ʻ֑wòd wĕ⁠ẖwòşé֥̂kĕ mi֝⁠yò̇֗şěr ʼakĕ-lĕ⁠maẖĕsֽwòr׃"],[11,25,"נֶֽפֶשׁ־בְּרָכָ֥ה תְדֻשָּׁ֑ן וּ֝⁠מַרְוֶ֗ה גַּם־ה֥וּא יוֹרֶֽא׃","neֽpeş̌-bĕ̇ráká֥h ţĕduşá֑̇̌n ẇ֝⁠marĕwe֗h gȧm-h֥ẇʼ ywòreֽʼ׃"],[11,26,"מֹ֣נֵֽעַ בָּ֭ר יִקְּבֻ֣⁠הוּ לְא֑וֹם וּ֝⁠בְרָכָ֗ה לְ⁠רֹ֣אשׁ מַשְׁבִּֽיר׃","mò֣néֽʻa bá֭̇r yiqĕ̇bu֣⁠hẇ lĕʼ֑wòm ẇ֝⁠bĕráká֗h lĕ⁠rò֣ʼş̌ maşĕ̌biֽ̇yr׃"],[11,27,"שֹׁ֣חֵֽר ט֭וֹב יְבַקֵּ֣שׁ רָצ֑וֹן וְ⁠דֹרֵ֖שׁ רָעָ֣ה תְבוֹאֶֽ⁠נּוּ׃","şò֣̌ẖéֽr t֭wòb yĕbaqé֣̇ş̌ ráẕ֑wòn wĕ⁠dòré֖ş̌ ráʻá֣h ţĕbwòʼeֽ⁠ṅẇ׃"],[11,28,"בּוֹטֵ֣חַ בְּ֭⁠עָשְׁר⁠וֹ ה֣וּא יִפֹּ֑ל וְ֝⁠כֶ⁠עָלֶ֗ה צַדִּיקִ֥ים יִפְרָֽחוּ׃","ḃwòté֣ẖa bĕ֭̇⁠ʻáşĕ̌r⁠wò h֣ẇʼ yipò֑̇l wĕ֝⁠ke⁠ʻále֗h ẕadi̇yqi֥ym yipĕráֽẖẇ׃"],[11,29,"עוֹכֵ֣ר בֵּ֭ית⁠וֹ יִנְחַל־ר֑וּחַ וְ⁠עֶ֥בֶד אֱ֝וִ֗יל לַ⁠חֲכַם־לֵֽב׃","ʻwòké֣r bé֭̇yţ⁠wò yinĕẖal-r֑ẇẖa wĕ⁠ʻe֥bed ʼè֝wi֗yl la⁠ẖàkam-léֽb׃"],[11,30,"פְּֽרִי־צַ֭דִּיק עֵ֣ץ חַיִּ֑ים וְ⁠לֹקֵ֖חַ נְפָשׂ֣וֹת חָכָֽם׃","pĕֽ̇riy-ẕa֭di̇yq ʻé֣ẕ ẖayi֑̇ym wĕ⁠lòqé֖ẖa nĕpáş֣̂wòţ ẖákáֽm׃"],[11,31,"הֵ֣ן צַ֭דִּיק בָּ⁠אָ֣רֶץ יְשֻׁלָּ֑ם אַ֝֗ף כִּֽי־רָשָׁ֥ע וְ⁠חוֹטֵֽא׃","hé֣n ẕa֭di̇yq bá̇⁠ʼá֣reẕ yĕşǔlá֑̇m ʼa֝֗p kiֽ̇y-ráşá֥̌ʻ wĕ⁠ẖwòtéֽʼ׃"],[12,1,"אֹהֵ֣ב מ֭וּסָר אֹ֣הֵֽב דָּ֑עַת וְ⁠שֹׂנֵ֖א תוֹכַ֣חַת בָּֽעַר׃","ʼòhé֣b m֭ẇsár ʼò֣héֽb dá֑̇ʻaţ wĕ⁠şò̂né֖ʼ ţwòka֣ẖaţ báֽ̇ʻar׃"],[12,2,"ט֗וֹב יָפִ֣יק רָ֭צוֹן מֵ⁠יְהוָ֑ה וְ⁠אִ֖ישׁ מְזִמּ֣וֹת יַרְשִֽׁיעַ׃","t֗wòb yápi֣yq rá֭ẕwòn mé⁠yĕhwá֑h wĕ⁠ʼi֖yş̌ mĕziṁ֣wòţ yarĕşǐֽyʻa׃"],[12,3,"לֹא־יִכּ֣וֹן אָדָ֣ם בְּ⁠רֶ֑שַׁע וְ⁠שֹׁ֥רֶשׁ צַ֝דִּיקִ֗ים בַּל־יִמּֽוֹט׃","lòʼ-yik֣̇wòn ʼádá֣m bĕ̇⁠re֑şǎʻ wĕ⁠şò֥̌reş̌ ẕa֝di̇yqi֗ym bȧl-yiṁֽwòt׃"],[12,4,"אֵֽשֶׁת־חַ֭יִל עֲטֶ֣רֶת בַּעְלָ֑⁠הּ וּ⁠כְ⁠רָקָ֖ב בְּ⁠עַצְמוֹתָ֣י⁠ו מְבִישָֽׁה׃","ʼéֽşěţ-ẖa֭yil ʻàte֣reţ bȧʻĕlá֑⁠ḣ ẇ⁠kĕ⁠ráqá֖b bĕ̇⁠ʻaẕĕmwòţá֣y⁠w mĕbiyşáֽ̌h׃"],[12,5,"מַחְשְׁב֣וֹת צַדִּיקִ֣ים מִשְׁפָּ֑ט תַּחְבֻּל֖וֹת רְשָׁעִ֣ים מִרְמָֽה׃","maẖĕşĕ̌b֣wòţ ẕadi̇yqi֣ym mişĕ̌pá֑̇t ţȧẖĕbu̇l֖wòţ rĕşá̌ʻi֣ym mirĕmáֽh׃"],[12,6,"דִּבְרֵ֣י רְשָׁעִ֣ים אֱרָב־דָּ֑ם וּ⁠פִ֥י יְ֝שָׁרִ֗ים יַצִּילֵֽ⁠ם׃","di̇bĕré֣y rĕşá̌ʻi֣ym ʼèráb-dá֑̇m ẇ⁠pi֥y yĕ֝şá̌ri֗ym yaẕi̇yléֽ⁠m׃"],[12,7,"הָפ֣וֹךְ רְשָׁעִ֣ים וְ⁠אֵינָ֑⁠ם וּ⁠בֵ֖ית צַדִּיקִ֣ים יַעֲמֹֽד׃","háp֣wòkĕ rĕşá̌ʻi֣ym wĕ⁠ʼéyná֑⁠m ẇ⁠bé֖yţ ẕadi̇yqi֣ym yaʻàmòֽd׃"],[12,8,"לְֽ⁠פִי־שִׂ֭כְל⁠וֹ יְהֻלַּל־אִ֑ישׁ וְ⁠נַעֲוֵה־לֵ֝֗ב יִהְיֶ֥ה לָ⁠בֽוּז׃","lĕֽ⁠piy-şî֭kĕl⁠wò yĕhulȧl-ʼi֑yş̌ wĕ⁠naʻàwéh-lé֝֗b yihĕye֥h lá⁠bֽẇz׃"],[12,9,"ט֣וֹב נִ֭קְלֶה וְ⁠עֶ֣בֶד ל֑⁠וֹ מִ֝⁠מְּתַכַּבֵּ֗ד וַ⁠חֲסַר־לָֽחֶם׃","t֣wòb ni֭qĕleh wĕ⁠ʻe֣bed l֑⁠wò mi֝⁠mĕ̇ţakȧbé̇֗d wa⁠ẖàsar-láֽẖem׃"],[12,10,"יוֹדֵ֣עַ צַ֭דִּיק נֶ֣פֶשׁ בְּהֶמְתּ֑⁠וֹ וְֽ⁠רַחֲמֵ֥י רְ֝שָׁעִ֗ים אַכְזָרִֽי׃","ywòdé֣ʻa ẕa֭di̇yq ne֣peş̌ bĕ̇hemĕţ֑̇⁠wò wĕֽ⁠raẖàmé֥y rĕ֝şá̌ʻi֗ym ʼakĕzáriֽy׃"],[12,11,"עֹבֵ֣ד אַ֭דְמָת⁠וֹ יִֽשְׂבַּֽע־לָ֑חֶם וּ⁠מְרַדֵּ֖ף רֵיקִ֣ים חֲסַר־לֵֽב׃","ʻòbé֣d ʼa֭dĕmáţ⁠wò yiֽşĕ̂bȧֽʻ-lá֑ẖem ẇ⁠mĕradé֖̇p réyqi֣ym ẖàsar-léֽb׃"],[12,12,"חָמַ֣ד רָ֭שָׁע מְצ֣וֹד רָעִ֑ים וְ⁠שֹׁ֖רֶשׁ צַדִּיקִ֣ים יִתֵּֽן׃","ẖáma֣d rá֭şá̌ʻ mĕẕ֣wòd ráʻi֑ym wĕ⁠şò֖̌reş̌ ẕadi̇yqi֣ym yiţéֽ̇n׃"],[12,13,"בְּ⁠פֶ֣שַׁע שְׂ֭פָתַיִם מוֹקֵ֣שׁ רָ֑ע וַ⁠יֵּצֵ֖א מִ⁠צָּרָ֣ה צַדִּֽיק׃","bĕ̇⁠pe֣şǎʻ şĕ֭̂páţayim mwòqé֣ş̌ rá֑ʻ wa⁠yé̇ẕé֖ʼ mi⁠ẕá̇rá֣h ẕadiֽ̇yq׃"],[12,14,"מִ⁠פְּרִ֣י פִי־אִ֭ישׁ יִשְׂבַּע־ט֑וֹב וּ⁠גְמ֥וּל יְדֵי־אָ֝דָ֗ם ישוב לֽ⁠וֹ׃","mi⁠pĕ̇ri֣y piy-ʼi֭yş̌ yişĕ̂bȧʻ-t֑wòb ẇ⁠gĕm֥ẇl yĕdéy-ʼá֝dá֗m yşwb lֽ⁠wò׃"],[12,15,"דֶּ֣רֶךְ אֱ֭וִיל יָשָׁ֣ר בְּ⁠עֵינָ֑י⁠ו וְ⁠שֹׁמֵ֖עַ לְ⁠עֵצָ֣ה חָכָֽם׃","dė֣rekĕ ʼè֭wiyl yáşá֣̌r bĕ̇⁠ʻéyná֑y⁠w wĕ⁠şò̌mé֖ʻa lĕ⁠ʻéẕá֣h ẖákáֽm׃"],[12,16,"אֱוִ֗יל בַּ֭⁠יּוֹם יִוָּדַ֣ע כַּעְס֑⁠וֹ וְ⁠כֹסֶ֖ה קָל֣וֹן עָרֽוּם׃","ʼèwi֗yl bȧ֭⁠ẏwòm yiwá̇da֣ʻ kȧʻĕs֑⁠wò wĕ⁠kòse֖h qál֣wòn ʻárֽẇm׃"],[12,17,"יָפִ֣יחַ אֱ֭מוּנָה יַגִּ֣יד צֶ֑דֶק וְ⁠עֵ֖ד שְׁקָרִ֣ים מִרְמָֽה׃","yápi֣yẖa ʼè֭mẇnáh yagi֣̇yd ẕe֑deq wĕ⁠ʻé֖d şĕ̌qári֣ym mirĕmáֽh׃"],[12,18,"יֵ֣שׁ בּ֭וֹטֶה כְּ⁠מַדְקְר֣וֹת חָ֑רֶב וּ⁠לְשׁ֖וֹן חֲכָמִ֣ים מַרְפֵּֽא׃","yé֣ş̌ ḃ֭wòteh kĕ̇⁠madĕqĕr֣wòţ ẖá֑reb ẇ⁠lĕş֖̌wòn ẖàkámi֣ym marĕpéֽ̇ʼ׃"],[12,19,"שְֽׂפַת־אֱ֭מֶת תִּכּ֣וֹן לָ⁠עַ֑ד וְ⁠עַד־אַ֝רְגִּ֗יעָה לְשׁ֣וֹן שָֽׁקֶר׃","şĕֽ̂paţ-ʼè֭meţ ţi̇k֣̇wòn lá⁠ʻa֑d wĕ⁠ʻad-ʼa֝rĕgi̇֗yʻáh lĕş֣̌wòn şáֽ̌qer׃"],[12,20,"מִ֭רְמָה בְּ⁠לֶב־חֹ֣רְשֵׁי רָ֑ע וּֽ⁠לְ⁠יֹעֲצֵ֖י שָׁל֣וֹם שִׂמְחָֽה׃","mi֭rĕmáh bĕ̇⁠leb-ẖò֣rĕşé̌y rá֑ʻ ẇֽ⁠lĕ⁠yòʻàẕé֖y şá̌l֣wòm şîmĕẖáֽh׃"],[12,21,"לֹא־יְאֻנֶּ֣ה לַ⁠צַּדִּ֣יק כָּל־אָ֑וֶן וּ֝⁠רְשָׁעִ֗ים מָ֣לְאוּ רָֽע׃","lòʼ-yĕʼunė֣h la⁠ẕȧdi֣̇yq ká̇l-ʼá֑wen ẇ֝⁠rĕşá̌ʻi֗ym má֣lĕʼẇ ráֽʻ׃"],[12,22,"תּוֹעֲבַ֣ת יְ֭הוָה שִׂפְתֵי־שָׁ֑קֶר וְ⁠עֹשֵׂ֖י אֱמוּנָ֣ה רְצוֹנֽ⁠וֹ׃","ţ̇wòʻàba֣ţ yĕ֭hwáh şîpĕţéy-şá֑̌qer wĕ⁠ʻòşé֖̂y ʼèmẇná֣h rĕẕwònֽ⁠wò׃"],[12,23,"אָדָ֣ם עָ֭רוּם כֹּ֣סֶה דָּ֑עַת וְ⁠לֵ֥ב כְּ֝סִילִ֗ים יִקְרָ֥א אִוֶּֽלֶת׃","ʼádá֣m ʻá֭rẇm kò֣̇seh dá֑̇ʻaţ wĕ⁠lé֥b kĕ̇֝siyli֗ym yiqĕrá֥ʼ ʼiwėֽleţ׃"],[12,24,"יַד־חָרוּצִ֥ים תִּמְשׁ֑וֹל ו֝⁠רְמִיָּ֗ה תִּהְיֶ֥ה לָ⁠מַֽס׃","yad-ẖárẇẕi֥ym ţi̇mĕş֑̌wòl w֝⁠rĕmiyá̇֗h ţi̇hĕye֥h lá⁠maֽs׃"],[12,25,"דְּאָגָ֣ה בְ⁠לֶב־אִ֣ישׁ יַשְׁחֶ֑⁠נָּה וְ⁠דָבָ֖ר ט֣וֹב יְשַׂמְּחֶֽ⁠נָּה׃","dĕ̇ʼágá֣h bĕ⁠leb-ʼi֣yş̌ yaşĕ̌ẖe֑⁠ná̇h wĕ⁠dábá֖r t֣wòb yĕşâmĕ̇ẖeֽ⁠ná̇h׃"],[12,26,"יָתֵ֣ר מֵ⁠רֵעֵ֣⁠הוּ צַדִּ֑יק וְ⁠דֶ֖רֶךְ רְשָׁעִ֣ים תַּתְעֵֽ⁠ם׃","yáţé֣r mé⁠réʻé֣⁠hẇ ẕadi֑̇yq wĕ⁠de֖rekĕ rĕşá̌ʻi֣ym ţȧţĕʻéֽ⁠m׃"],[12,27,"לֹא־יַחֲרֹ֣ךְ רְמִיָּ֣ה צֵיד֑⁠וֹ וְ⁠הוֹן־אָדָ֖ם יָקָ֣ר חָרֽוּץ׃","lòʼ-yaẖàrò֣kĕ rĕmiyá֣̇h ẕéyd֑⁠wò wĕ⁠hwòn-ʼádá֖m yáqá֣r ẖárֽẇẕ׃"],[12,28,"בְּ⁠אֹֽרַח־צְדָקָ֥ה חַיִּ֑ים וְ⁠דֶ֖רֶךְ נְתִיבָ֣ה אַל־מָֽוֶת׃","bĕ̇⁠ʼòֽraẖ-ẕĕdáqá֥h ẖayi֑̇ym wĕ⁠de֖rekĕ nĕţiybá֣h ʼal-máֽweţ׃"],[13,1,"בֵּ֣ן חָ֭כָם מ֣וּסַר אָ֑ב וְ֝⁠לֵ֗ץ לֹא־שָׁמַ֥ע גְּעָרָֽה׃","bé֣̇n ẖá֭kám m֣ẇsar ʼá֑b wĕ֝⁠lé֗ẕ lòʼ-şá̌ma֥ʻ gĕ̇ʻáráֽh׃"],[13,2,"מִ⁠פְּרִ֣י פִי־אִ֭ישׁ יֹ֣אכַל ט֑וֹב וְ⁠נֶ֖פֶשׁ בֹּגְדִ֣ים חָמָֽס׃","mi⁠pĕ̇ri֣y piy-ʼi֭yş̌ yò֣ʼkal t֑wòb wĕ⁠ne֖peş̌ bò̇gĕdi֣ym ẖámáֽs׃"],[13,3,"נֹצֵ֣ר פִּ֭י⁠ו שֹׁמֵ֣ר נַפְשׁ֑⁠וֹ פֹּשֵׂ֥ק שְׂ֝פָתָ֗י⁠ו מְחִתָּה־לֽ⁠וֹ׃","nòẕé֣r pi֭̇y⁠w şò̌mé֣r napĕş֑̌⁠wò pò̇şé֥̂q şĕ̂֝páţá֗y⁠w mĕẖiţá̇h-lֽ⁠wò׃"],[13,4,"מִתְאַוָּ֣ה וָ֭⁠אַיִן נַפְשׁ֣⁠וֹ עָצֵ֑ל וְ⁠נֶ֖פֶשׁ חָרֻצִ֣ים תְּדֻשָּֽׁן׃","miţĕʼawá֣̇h wá֭⁠ʼayin napĕş֣̌⁠wò ʻáẕé֑l wĕ⁠ne֖peş̌ ẖáruẕi֣ym ţĕ̇duşáֽ̇̌n׃"],[13,5,"דְּבַר־שֶׁ֭קֶר יִשְׂנָ֣א צַדִּ֑יק וְ֝⁠רָשָׁ֗ע יַבְאִ֥ישׁ וְ⁠יַחְפִּֽיר׃","dĕ̇bar-şě֭qer yişĕ̂ná֣ʼ ẕadi֑̇yq wĕ֝⁠ráşá̌֗ʻ yabĕʼi֥yş̌ wĕ⁠yaẖĕpiֽ̇yr׃"],[13,6,"צְ֭דָקָה תִּצֹּ֣ר תָּם־דָּ֑רֶךְ וְ֝⁠רִשְׁעָ֗ה תְּסַלֵּ֥ף חַטָּֽאת׃","ẕĕ֭dáqáh ţi̇ẕò֣̇r ţá̇m-dá֑̇rekĕ wĕ֝⁠rişĕ̌ʻá֗h ţĕ̇salé֥̇p ẖatáֽ̇ʼţ׃"],[13,7,"יֵ֣שׁ מִ֭תְעַשֵּׁר וְ⁠אֵ֣ין כֹּ֑ל מִ֝תְרוֹשֵׁ֗שׁ וְ⁠ה֣וֹן רָֽב׃","yé֣ş̌ mi֭ţĕʻaşé̇̌r wĕ⁠ʼé֣yn kò֑̇l mi֝ţĕrwòşé̌֗ş̌ wĕ⁠h֣wòn ráֽb׃"],[13,8,"כֹּ֣פֶר נֶֽפֶשׁ־אִ֣ישׁ עָשְׁר֑⁠וֹ וְ֝⁠רָ֗שׁ לֹא־שָׁמַ֥ע גְּעָרָֽה׃","kò֣̇per neֽpeş̌-ʼi֣yş̌ ʻáşĕ̌r֑⁠wò wĕ֝⁠rá֗ş̌ lòʼ-şá̌ma֥ʻ gĕ̇ʻáráֽh׃"],[13,9,"אוֹר־צַדִּיקִ֥ים יִשְׂמָ֑ח וְ⁠נֵ֖ר רְשָׁעִ֣ים יִדְעָֽךְ׃","ʼwòr-ẕadi̇yqi֥ym yişĕ̂má֑ẖ wĕ⁠né֖r rĕşá̌ʻi֣ym yidĕʻáֽkĕ׃"],[13,10,"רַק־בְּ֭⁠זָדוֹן יִתֵּ֣ן מַצָּ֑ה וְ⁠אֶת־נ֖וֹעָצִ֣ים חָכְמָֽה׃","raq-bĕ֭̇⁠zádwòn yiţé֣̇n maẕá֑̇h wĕ⁠ʼeţ-n֖wòʻáẕi֣ym ẖákĕmáֽh׃"],[13,11,"ה֭וֹן מֵ⁠הֶ֣בֶל יִמְעָ֑ט וְ⁠קֹבֵ֖ץ עַל־יָ֣ד יַרְבֶּֽה׃","h֭wòn mé⁠he֣bel yimĕʻá֑t wĕ⁠qòbé֖ẕ ʻal-yá֣d yarĕbėֽh׃"],[13,12,"תּוֹחֶ֣לֶת מְ֭מֻשָּׁכָה מַחֲלָה־לֵ֑ב וְ⁠עֵ֥ץ חַ֝יִּ֗ים תַּאֲוָ֥ה בָאָֽה׃","ţ̇wòẖe֣leţ mĕ֭muşá̇̌káh maẖàláh-lé֑b wĕ⁠ʻé֥ẕ ẖa֝yi̇֗ym ţȧʼàwá֥h báʼáֽh׃"],[13,13,"בָּ֣ז לְ֭⁠דָבָר יֵחָ֣בֶל ל֑⁠וֹ וִ⁠ירֵ֥א מִ֝צְוָ֗ה ה֣וּא יְשֻׁלָּֽם׃","bá֣̇z lĕ֭⁠dábár yéẖá֣bel l֑⁠wò wi⁠yré֥ʼ mi֝ẕĕwá֗h h֣ẇʼ yĕşǔláֽ̇m׃"],[13,14,"תּוֹרַ֣ת חָ֭כָם מְק֣וֹר חַיִּ֑ים לָ֝⁠ס֗וּר מִ⁠מֹּ֥קְשֵׁי מָֽוֶת׃","ţ̇wòra֣ţ ẖá֭kám mĕq֣wòr ẖayi֑̇ym lá֝⁠s֗ẇr mi⁠mò֥̇qĕşé̌y máֽweţ׃"],[13,15,"שֵֽׂכֶל־ט֭וֹב יִתֶּן־חֵ֑ן וְ⁠דֶ֖רֶךְ בֹּגְדִ֣ים אֵיתָֽן׃","şéֽ̂kel-t֭wòb yiţėn-ẖé֑n wĕ⁠de֖rekĕ bò̇gĕdi֣ym ʼéyţáֽn׃"],[13,16,"כָּל־עָ֭רוּם יַעֲשֶׂ֣ה בְ⁠דָ֑עַת וּ֝⁠כְסִ֗יל יִפְרֹ֥שׂ אִוֶּֽלֶת׃","ká̇l-ʻá֭rẇm yaʻàşê֣h bĕ⁠dá֑ʻaţ ẇ֝⁠kĕsi֗yl yipĕrò֥ş̂ ʼiwėֽleţ׃"],[13,17,"מַלְאָ֣ךְ רָ֭שָׁע יִפֹּ֣ל בְּ⁠רָ֑ע וְ⁠צִ֖יר אֱמוּנִ֣ים מַרְפֵּֽא׃","malĕʼá֣kĕ rá֭şá̌ʻ yipò֣̇l bĕ̇⁠rá֑ʻ wĕ⁠ẕi֖yr ʼèmẇni֣ym marĕpéֽ̇ʼ׃"],[13,18,"רֵ֣ישׁ וְ֭⁠קָלוֹן פּוֹרֵ֣עַ מוּסָ֑ר וְ⁠שׁוֹמֵ֖ר תּוֹכַ֣חַת יְכֻבָּֽד׃","ré֣yş̌ wĕ֭⁠qálwòn ṗwòré֣ʻa mẇsá֑r wĕ⁠ş̌wòmé֖r ţ̇wòka֣ẖaţ yĕkubáֽ̇d׃"],[13,19,"תַּאֲוָ֣ה נִ֭הְיָה תֶּעֱרַ֣ב לְ⁠נָ֑פֶשׁ וְ⁠תוֹעֲבַ֥ת כְּ֝סִילִ֗ים ס֣וּר מֵ⁠רָֽע׃","ţȧʼàwá֣h ni֭hĕyáh ţėʻèra֣b lĕ⁠ná֑peş̌ wĕ⁠ţwòʻàba֥ţ kĕ̇֝siyli֗ym s֣ẇr mé⁠ráֽʻ׃"],[13,20,"הלוך אֶת־חֲכָמִ֣ים ו⁠חכם וְ⁠רֹעֶ֖ה כְסִילִ֣ים יֵרֽוֹעַ׃","hlwk ʼeţ-ẖàkámi֣ym w⁠ẖkm wĕ⁠ròʻe֖h kĕsiyli֣ym yérֽwòʻa׃"],[13,21,"חַ֭טָּאִים תְּרַדֵּ֣ף רָעָ֑ה וְ⁠אֶת־צַ֝דִּיקִ֗ים יְשַׁלֶּם־טֽוֹב׃","ẖa֭tá̇ʼiym ţĕ̇radé֣̇p ráʻá֑h wĕ⁠ʼeţ-ẕa֝di̇yqi֗ym yĕşǎlėm-tֽwòb׃"],[13,22,"ט֗וֹב יַנְחִ֥יל בְּנֵֽי־בָנִ֑ים וְ⁠צָפ֥וּן לַ֝⁠צַּדִּ֗יק חֵ֣יל חוֹטֵֽא׃","t֗wòb yanĕẖi֥yl bĕ̇néֽy-báni֑ym wĕ⁠ẕáp֥ẇn la֝⁠ẕȧdi̇֗yq ẖé֣yl ẖwòtéֽʼ׃"],[13,23,"רָב־אֹ֭כֶל נִ֣יר רָאשִׁ֑ים וְ⁠יֵ֥שׁ נִ֝סְפֶּ֗ה בְּ⁠לֹ֣א מִשְׁפָּֽט׃","ráb-ʼò֭kel ni֣yr ráʼşǐ֑ym wĕ⁠yé֥ş̌ ni֝sĕpė֗h bĕ̇⁠lò֣ʼ mişĕ̌páֽ̇t׃"],[13,24,"חוֹשֵׂ֣ךְ שִׁ֭בְט⁠וֹ שׂוֹנֵ֣א בְנ֑⁠וֹ וְ֝⁠אֹהֲב֗⁠וֹ שִֽׁחֲר֥⁠וֹ מוּסָֽר׃","ẖwòşé֣̂kĕ şǐ֭bĕt⁠wò ş̂wòné֣ʼ bĕn֑⁠wò wĕ֝⁠ʼòhàb֗⁠wò şǐֽẖàr֥⁠wò mẇsáֽr׃"],[13,25,"צַדִּ֗יק אֹ֭כֵל לְ⁠שֹׂ֣בַע נַפְשׁ֑⁠וֹ וּ⁠בֶ֖טֶן רְשָׁעִ֣ים תֶּחְסָֽר׃פ","ẕadi̇֗yq ʼò֭kél lĕ⁠şò֣̂baʻ napĕş֑̌⁠wò ẇ⁠be֖ten rĕşá̌ʻi֣ym ţėẖĕsáֽr׃p"],[14,1,"חַכְמ֣וֹת נָ֭שִׁים בָּנְתָ֣ה בֵיתָ֑⁠הּ וְ֝⁠אִוֶּ֗לֶת בְּ⁠יָדֶ֥י⁠הָ תֶהֶרְסֶֽ⁠נּוּ׃","ẖakĕm֣wòţ ná֭şǐym bá̇nĕţá֣h béyţá֑⁠ḣ wĕ֝⁠ʼiwė֗leţ bĕ̇⁠yáde֥y⁠há ţeherĕseֽ⁠ṅẇ׃"],[14,2,"הוֹלֵ֣ךְ בְּ֭⁠יָשְׁר⁠וֹ יְרֵ֣א יְהוָ֑ה וּ⁠נְל֖וֹז דְּרָכָ֣י⁠ו בּוֹזֵֽ⁠הוּ׃","hwòlé֣kĕ bĕ֭̇⁠yáşĕ̌r⁠wò yĕré֣ʼ yĕhwá֑h ẇ⁠nĕl֖wòz dĕ̇ráká֣y⁠w ḃwòzéֽ⁠hẇ׃"],[14,3,"בְּֽ⁠פִי־אֱ֭וִיל חֹ֣טֶר גַּאֲוָ֑ה וְ⁠שִׂפְתֵ֥י חֲ֝כָמִ֗ים תִּשְׁמוּרֵֽ⁠ם׃","bĕֽ̇⁠piy-ʼè֭wiyl ẖò֣ter gȧʼàwá֑h wĕ⁠şîpĕţé֥y ẖà֝kámi֗ym ţi̇şĕ̌mẇréֽ⁠m׃"],[14,4,"בְּ⁠אֵ֣ין אֲ֭לָפִים אֵב֣וּס בָּ֑ר וְ⁠רָב־תְּ֝בוּא֗וֹת בְּ⁠כֹ֣חַ שֽׁוֹר׃","bĕ̇⁠ʼé֣yn ʼà֭lápiym ʼéb֣ẇs bá֑̇r wĕ⁠ráb-ţĕ̇֝bẇʼ֗wòţ bĕ̇⁠kò֣ẖa şֽ̌wòr׃"],[14,5,"עֵ֣ד אֱ֭מוּנִים לֹ֣א יְכַזֵּ֑ב וְ⁠יָפִ֥יחַ כְּ֝זָבִ֗ים עֵ֣ד שָֽׁקֶר׃","ʻé֣d ʼè֭mẇniym lò֣ʼ yĕkazé֑̇b wĕ⁠yápi֥yẖa kĕ̇֝zábi֗ym ʻé֣d şáֽ̌qer׃"],[14,6,"בִּקֶּשׁ־לֵ֣ץ חָכְמָ֣ה וָ⁠אָ֑יִן וְ⁠דַ֖עַת לְ⁠נָב֣וֹן נָקָֽל׃","bi̇qėş̌-lé֣ẕ ẖákĕmá֣h wá⁠ʼá֑yin wĕ⁠da֖ʻaţ lĕ⁠náb֣wòn náqáֽl׃"],[14,7,"לֵ֣ךְ מִ֭⁠נֶּגֶד לְ⁠אִ֣ישׁ כְּסִ֑יל וּ⁠בַל־יָ֝דַ֗עְתָּ שִׂפְתֵי־דָֽעַת׃","lé֣kĕ mi֭⁠nėged lĕ⁠ʼi֣yş̌ kĕ̇si֑yl ẇ⁠bal-yá֝da֗ʻĕţá̇ şîpĕţéy-dáֽʻaţ׃"],[14,8,"חָכְמַ֣ת עָ֭רוּם הָבִ֣ין דַּרְכּ֑⁠וֹ וְ⁠אִוֶּ֖לֶת כְּסִילִ֣ים מִרְמָֽה׃","ẖákĕma֣ţ ʻá֭rẇm hábi֣yn dȧrĕk֑̇⁠wò wĕ⁠ʼiwė֖leţ kĕ̇siyli֣ym mirĕmáֽh׃"],[14,9,"אֱ֭וִלִים יָלִ֣יץ אָשָׁ֑ם וּ⁠בֵ֖ין יְשָׁרִ֣ים רָצֽוֹן׃","ʼè֭wiliym yáli֣yẕ ʼáşá֑̌m ẇ⁠bé֖yn yĕşá̌ri֣ym ráẕֽwòn׃"],[14,10,"לֵ֗ב י֭וֹדֵעַ מָרַּ֣ת נַפְשׁ֑⁠וֹ וּ֝⁠בְ⁠שִׂמְחָת֗⁠וֹ לֹא־יִתְעָ֥רַב זָֽר׃","lé֗b y֭wòdéʻa márȧ֣ţ napĕş֑̌⁠wò ẇ֝⁠bĕ⁠şîmĕẖáţ֗⁠wò lòʼ-yiţĕʻá֥rab záֽr׃"],[14,11,"בֵּ֣ית רְ֭שָׁעִים יִשָּׁמֵ֑ד וְ⁠אֹ֖הֶל יְשָׁרִ֣ים יַפְרִֽיחַ׃","bé֣̇yţ rĕ֭şá̌ʻiym yişá̇̌mé֑d wĕ⁠ʼò֖hel yĕşá̌ri֣ym yapĕriֽyẖa׃"],[14,12,"יֵ֤שׁ דֶּ֣רֶךְ יָ֭שָׁר לִ⁠פְנֵי־אִ֑ישׁ וְ֝⁠אַחֲרִיתָ֗⁠הּ דַּרְכֵי־מָֽוֶת׃","yé֤ş̌ dė֣rekĕ yá֭şá̌r li⁠pĕnéy-ʼi֑yş̌ wĕ֝⁠ʼaẖàriyţá֗⁠ḣ dȧrĕkéy-máֽweţ׃"],[14,13,"גַּם־בִּ⁠שְׂח֥וֹק יִכְאַב־לֵ֑ב וְ⁠אַחֲרִיתָ֖⁠הּ שִׂמְחָ֣ה תוּגָֽה׃","gȧm-bi̇⁠şĕ̂ẖ֥wòq yikĕʼab-lé֑b wĕ⁠ʼaẖàriyţá֖⁠ḣ şîmĕẖá֣h ţẇgáֽh׃"],[14,14,"מִ⁠דְּרָכָ֣י⁠ו יִ֭שְׂבַּע ס֣וּג לֵ֑ב וּ֝⁠מֵ⁠עָלָ֗י⁠ו אִ֣ישׁ טֽוֹב׃","mi⁠dĕ̇ráká֣y⁠w yi֭şĕ̂bȧʻ s֣ẇg lé֑b ẇ֝⁠mé⁠ʻálá֗y⁠w ʼi֣yş̌ tֽwòb׃"],[14,15,"פֶּ֭תִי יַאֲמִ֣ין לְ⁠כָל־דָּבָ֑ר וְ֝⁠עָר֗וּם יָבִ֥ין לַ⁠אֲשֻׁרֽ⁠וֹ׃","pė֭ţiy yaʼàmi֣yn lĕ⁠kál-dá̇bá֑r wĕ֝⁠ʻár֗ẇm yábi֥yn la⁠ʼàşǔrֽ⁠wò׃"],[14,16,"חָכָ֣ם יָ֭רֵא וְ⁠סָ֣ר מֵ⁠רָ֑ע וּ֝⁠כְסִ֗יל מִתְעַבֵּ֥ר וּ⁠בוֹטֵֽחַ׃","ẖáká֣m yá֭réʼ wĕ⁠sá֣r mé⁠rá֑ʻ ẇ֝⁠kĕsi֗yl miţĕʻabé֥̇r ẇ⁠bwòtéֽẖa׃"],[14,17,"קְֽצַר־אַ֭פַּיִם יַעֲשֶׂ֣ה אִוֶּ֑לֶת וְ⁠אִ֥ישׁ מְ֝זִמּ֗וֹת יִשָּׂנֵֽא׃","qĕֽẕar-ʼa֭pȧyim yaʻàşê֣h ʼiwė֑leţ wĕ⁠ʼi֥yş̌ mĕ֝ziṁ֗wòţ yişá̇̂néֽʼ׃"],[14,18,"נָחֲל֣וּ פְתָאיִ֣ם אִוֶּ֑לֶת וַֽ֝⁠עֲרוּמִ֗ים יַכְתִּ֥רוּ דָֽעַת׃","náẖàl֣ẇ pĕţáʼyi֣m ʼiwė֑leţ waֽ֝⁠ʻàrẇmi֗ym yakĕţi֥̇rẇ dáֽʻaţ׃"],[14,19,"שַׁח֣וּ רָ֭עִים לִ⁠פְנֵ֣י טוֹבִ֑ים וּ֝⁠רְשָׁעִ֗ים עַֽל־שַׁעֲרֵ֥י צַדִּֽיק׃","şǎẖ֣ẇ rá֭ʻiym li⁠pĕné֣y twòbi֑ym ẇ֝⁠rĕşá̌ʻi֗ym ʻaֽl-şǎʻàré֥y ẕadiֽ̇yq׃"],[14,20,"גַּם־לְ֭⁠רֵעֵ⁠הוּ יִשָּׂ֣נֵא רָ֑שׁ וְ⁠אֹהֲבֵ֖י עָשִׁ֣יר רַבִּֽים׃","gȧm-lĕ֭⁠réʻé⁠hẇ yişá֣̇̂néʼ rá֑ş̌ wĕ⁠ʼòhàbé֖y ʻáşǐ֣yr rabiֽ̇ym׃"],[14,21,"בָּז־לְ⁠רֵעֵ֥⁠הוּ חוֹטֵ֑א וּ⁠מְחוֹנֵ֖ן עניים אַשְׁרָֽי⁠ו׃","bá̇z-lĕ⁠réʻé֥⁠hẇ ẖwòté֑ʼ ẇ⁠mĕẖwòné֖n ʻnyym ʼaşĕ̌ráֽy⁠w׃"],[14,22,"הֲֽ⁠לוֹא־יִ֭תְעוּ חֹ֣רְשֵׁי רָ֑ע וְ⁠חֶ֥סֶד וֶ֝⁠אֱמֶ֗ת חֹ֣רְשֵׁי טֽוֹב׃","hàֽ⁠lwòʼ-yi֭ţĕʻẇ ẖò֣rĕşé̌y rá֑ʻ wĕ⁠ẖe֥sed we֝⁠ʼème֗ţ ẖò֣rĕşé̌y tֽwòb׃"],[14,23,"בְּ⁠כָל־עֶ֭צֶב יִהְיֶ֣ה מוֹתָ֑ר וּ⁠דְבַר־שְׂ֝פָתַ֗יִם אַךְ־לְ⁠מַחְסֽוֹר׃","bĕ̇⁠kál-ʻe֭ẕeb yihĕye֣h mwòţá֑r ẇ⁠dĕbar-şĕ̂֝páţa֗yim ʼakĕ-lĕ⁠maẖĕsֽwòr׃"],[14,24,"עֲטֶ֣רֶת חֲכָמִ֣ים עָשְׁרָ֑⁠ם אִוֶּ֖לֶת כְּסִילִ֣ים אִוֶּֽלֶת׃","ʻàte֣reţ ẖàkámi֣ym ʻáşĕ̌rá֑⁠m ʼiwė֖leţ kĕ̇siyli֣ym ʼiwėֽleţ׃"],[14,25,"מַצִּ֣יל נְ֭פָשׁוֹת עֵ֣ד אֱמֶ֑ת וְ⁠יָפִ֖חַ כְּזָבִ֣ים מִרְמָֽה׃","maẕi֣̇yl nĕ֭páş̌wòţ ʻé֣d ʼème֑ţ wĕ⁠yápi֖ẖa kĕ̇zábi֣ym mirĕmáֽh׃"],[14,26,"בְּ⁠יִרְאַ֣ת יְ֭הוָה מִבְטַח־עֹ֑ז וּ֝⁠לְ⁠בָנָ֗י⁠ו יִהְיֶ֥ה מַחְסֶֽה׃","bĕ̇⁠yirĕʼa֣ţ yĕ֭hwáh mibĕtaẖ-ʻò֑z ẇ֝⁠lĕ⁠báná֗y⁠w yihĕye֥h maẖĕseֽh׃"],[14,27,"יִרְאַ֣ת יְ֭הוָה מְק֣וֹר חַיִּ֑ים לָ֝⁠ס֗וּר מִ⁠מֹּ֥קְשֵׁי מָֽוֶת׃","yirĕʼa֣ţ yĕ֭hwáh mĕq֣wòr ẖayi֑̇ym lá֝⁠s֗ẇr mi⁠mò֥̇qĕşé̌y máֽweţ׃"],[14,28,"בְּ⁠רָב־עָ֥ם הַדְרַת־מֶ֑לֶךְ וּ⁠בְ⁠אֶ֥פֶס לְ֝אֹ֗ם מְחִתַּ֥ת רָזֽוֹן׃","bĕ̇⁠ráb-ʻá֥m hadĕraţ-me֑lekĕ ẇ⁠bĕ⁠ʼe֥pes lĕ֝ʼò֗m mĕẖiţȧ֥ţ rázֽwòn׃"],[14,29,"אֶ֣רֶךְ אַ֭פַּיִם רַב־תְּבוּנָ֑ה וּ⁠קְצַר־ר֝֗וּחַ מֵרִ֥ים אִוֶּֽלֶת׃","ʼe֣rekĕ ʼa֭pȧyim rab-ţĕ̇bẇná֑h ẇ⁠qĕẕar-r֝֗ẇẖa méri֥ym ʼiwėֽleţ׃"],[14,30,"חַיֵּ֣י בְ֭שָׂרִים לֵ֣ב מַרְפֵּ֑א וּ⁠רְקַ֖ב עֲצָמ֣וֹת קִנְאָֽה׃","ẖayé֣̇y bĕ֭şá̂riym lé֣b marĕpé֑̇ʼ ẇ⁠rĕqa֖b ʻàẕám֣wòţ qinĕʼáֽh׃"],[14,31,"עֹ֣שֵֽׁק דָּ֭ל חֵרֵ֣ף עֹשֵׂ֑⁠הוּ וּ֝⁠מְכַבְּד֗⁠וֹ חֹנֵ֥ן אֶבְיֽוֹן׃","ʻò֣şéֽ̌q dá֭̇l ẖéré֣p ʻòşé֑̂⁠hẇ ẇ֝⁠mĕkabĕ̇d֗⁠wò ẖòné֥n ʼebĕyֽwòn׃"],[14,32,"בְּֽ֭⁠רָעָת⁠וֹ יִדָּחֶ֣ה רָשָׁ֑ע וְ⁠חֹסֶ֖ה בְ⁠מוֹת֣⁠וֹ צַדִּֽיק׃","bĕֽ֭̇⁠ráʻáţ⁠wò yidá̇ẖe֣h ráşá֑̌ʻ wĕ⁠ẖòse֖h bĕ⁠mwòţ֣⁠wò ẕadiֽ̇yq׃"],[14,33,"בְּ⁠לֵ֣ב נָ֭בוֹן תָּנ֣וּחַ חָכְמָ֑ה וּ⁠בְ⁠קֶ֥רֶב כְּ֝סִילִ֗ים תִּוָּדֵֽעַ׃","bĕ̇⁠lé֣b ná֭bwòn ţá̇n֣ẇẖa ẖákĕmá֑h ẇ⁠bĕ⁠qe֥reb kĕ̇֝siyli֗ym ţi̇wá̇déֽʻa׃"],[14,34,"צְדָקָ֥ה תְרֽוֹמֵֽם־גּ֑וֹי וְ⁠חֶ֖סֶד לְאֻמִּ֣ים חַטָּֽאת׃","ẕĕdáqá֥h ţĕrֽwòméֽm-ġ֑wòy wĕ⁠ẖe֖sed lĕʼumi֣̇ym ẖatáֽ̇ʼţ׃"],[14,35,"רְֽצוֹן־מֶ֭לֶךְ לְ⁠עֶ֣בֶד מַשְׂכִּ֑יל וְ֝⁠עֶבְרָת֗⁠וֹ תִּהְיֶ֥ה מֵבִֽישׁ׃","rĕֽẕwòn-me֭lekĕ lĕ⁠ʻe֣bed maşĕ̂ki֑̇yl wĕ֝⁠ʻebĕráţ֗⁠wò ţi̇hĕye֥h mébiֽyş̌׃"],[15,1,"מַֽעֲנֶה־רַּ֭ךְ יָשִׁ֣יב חֵמָ֑ה וּ⁠דְבַר־עֶ֝֗צֶב יַעֲלֶה־אָֽף׃","maֽʻàneh-rȧ֭kĕ yáşǐ֣yb ẖémá֑h ẇ⁠dĕbar-ʻe֝֗ẕeb yaʻàleh-ʼáֽp׃"],[15,2,"לְשׁ֣וֹן חֲ֭כָמִים תֵּיטִ֣יב דָּ֑עַת וּ⁠פִ֥י כְ֝סִילִ֗ים יַבִּ֥יעַ אִוֶּֽלֶת׃","lĕş֣̌wòn ẖà֭kámiym ţé̇yti֣yb dá֑̇ʻaţ ẇ⁠pi֥y kĕ֝siyli֗ym yabi֥̇yʻa ʼiwėֽleţ׃"],[15,3,"בְּֽ⁠כָל־מָ֭קוֹם עֵינֵ֣י יְהוָ֑ה צֹ֝פ֗וֹת רָעִ֥ים ו⁠טוֹבִֽים׃","bĕֽ̇⁠kál-má֭qwòm ʻéyné֣y yĕhwá֑h ẕò֝p֗wòţ ráʻi֥ym w⁠twòbiֽym׃"],[15,4,"מַרְפֵּ֣א לָ֭שׁוֹן עֵ֣ץ חַיִּ֑ים וְ⁠סֶ֥לֶף בָּ֝֗⁠הּ שֶׁ֣בֶר בְּ⁠רֽוּחַ׃","marĕpé֣̇ʼ lá֭ş̌wòn ʻé֣ẕ ẖayi֑̇ym wĕ⁠se֥lep bá̇֝֗⁠ḣ şě֣ber bĕ̇⁠rֽẇẖa׃"],[15,5,"אֱוִ֗יל יִ֭נְאַץ מוּסַ֣ר אָבִ֑י⁠ו וְ⁠שֹׁמֵ֖ר תּוֹכַ֣חַת יַעְרִֽם׃","ʼèwi֗yl yi֭nĕʼaẕ mẇsa֣r ʼábi֑y⁠w wĕ⁠şò̌mé֖r ţ̇wòka֣ẖaţ yaʻĕriֽm׃"],[15,6,"בֵּ֣ית צַ֭דִּיק חֹ֣סֶן רָ֑ב וּ⁠בִ⁠תְבוּאַ֖ת רָשָׁ֣ע נֶעְכָּֽרֶת׃","bé֣̇yţ ẕa֭di̇yq ẖò֣sen rá֑b ẇ⁠bi⁠ţĕbẇʼa֖ţ ráşá֣̌ʻ neʻĕkáֽ̇reţ׃"],[15,7,"שִׂפְתֵ֣י חֲ֭כָמִים יְזָ֣רוּ דָ֑עַת וְ⁠לֵ֖ב כְּסִילִ֣ים לֹא־כֵֽן׃","şîpĕţé֣y ẖà֭kámiym yĕzá֣rẇ dá֑ʻaţ wĕ⁠lé֖b kĕ̇siyli֣ym lòʼ-kéֽn׃"],[15,8,"זֶ֣בַח רְ֭שָׁעִים תּוֹעֲבַ֣ת יְהוָ֑ה וּ⁠תְפִלַּ֖ת יְשָׁרִ֣ים רְצוֹנֽ⁠וֹ׃","ze֣baẖ rĕ֭şá̌ʻiym ţ̇wòʻàba֣ţ yĕhwá֑h ẇ⁠ţĕpilȧ֖ţ yĕşá̌ri֣ym rĕẕwònֽ⁠wò׃"],[15,9,"תּוֹעֲבַ֣ת יְ֭הוָה דֶּ֣רֶךְ רָשָׁ֑ע וּ⁠מְרַדֵּ֖ף צְדָקָ֣ה יֶאֱהָֽב׃","ţ̇wòʻàba֣ţ yĕ֭hwáh dė֣rekĕ ráşá֑̌ʻ ẇ⁠mĕradé֖̇p ẕĕdáqá֣h yeʼèháֽb׃"],[15,10,"מוּסָ֣ר רָ֭ע לְ⁠עֹזֵ֣ב אֹ֑רַח שׂוֹנֵ֖א תוֹכַ֣חַת יָמֽוּת׃","mẇsá֣r rá֭ʻ lĕ⁠ʻòzé֣b ʼò֑raẖ ş̂wòné֖ʼ ţwòka֣ẖaţ yámֽẇţ׃"],[15,11,"שְׁא֣וֹל וַ֭⁠אֲבַדּוֹן נֶ֣גֶד יְהוָ֑ה אַ֝֗ף כִּֽי־לִבּ֥וֹת בְּֽנֵי־אָדָֽם׃","şĕ̌ʼ֣wòl wa֭⁠ʼàbaḋwòn ne֣ged yĕhwá֑h ʼa֝֗p kiֽ̇y-liḃ֥wòţ bĕֽ̇néy-ʼádáֽm׃"],[15,12,"לֹ֣א יֶאֱהַב־לֵ֭ץ הוֹכֵ֣חַֽ ל֑⁠וֹ אֶל־חֲ֝כָמִ֗ים לֹ֣א יֵלֵֽךְ׃","lò֣ʼ yeʼèhab-lé֭ẕ hwòké֣ẖaֽ l֑⁠wò ʼel-ẖà֝kámi֗ym lò֣ʼ yéléֽkĕ׃"],[15,13,"לֵ֣ב שָׂ֭מֵחַ יֵיטִ֣ב פָּנִ֑ים וּ⁠בְ⁠עַצְּבַת־לֵ֝ב ר֣וּחַ נְכֵאָֽה׃","lé֣b şá֭̂méẖa yéyti֣b pá̇ni֑ym ẇ⁠bĕ⁠ʻaẕĕ̇baţ-lé֝b r֣ẇẖa nĕkéʼáֽh׃"],[15,14,"לֵ֣ב נָ֭בוֹן יְבַקֶּשׁ־דָּ֑עַת ו⁠פני כְ֝סִילִ֗ים יִרְעֶ֥ה אִוֶּֽלֶת׃","lé֣b ná֭bwòn yĕbaqėş̌-dá֑̇ʻaţ w⁠pny kĕ֝siyli֗ym yirĕʻe֥h ʼiwėֽleţ׃"],[15,15,"כָּל־יְמֵ֣י עָנִ֣י רָעִ֑ים וְ⁠טֽוֹב־לֵ֝֗ב מִשְׁתֶּ֥ה תָמִֽיד׃","ká̇l-yĕmé֣y ʻáni֣y ráʻi֑ym wĕ⁠tֽwòb-lé֝֗b mişĕ̌ţė֥h ţámiֽyd׃"],[15,16,"טוֹב־מְ֭עַט בְּ⁠יִרְאַ֣ת יְהוָ֑ה מֵ⁠אוֹצָ֥ר רָ֝֗ב וּ⁠מְה֥וּמָה בֽ⁠וֹ׃","twòb-mĕ֭ʻat bĕ̇⁠yirĕʼa֣ţ yĕhwá֑h mé⁠ʼwòẕá֥r rá֝֗b ẇ⁠mĕh֥ẇmáh bֽ⁠wò׃"],[15,17,"ט֤וֹב אֲרֻחַ֣ת יָ֭רָק וְ⁠אַהֲבָה־שָׁ֑ם מִ⁠שּׁ֥וֹר אָ֝ב֗וּס וְ⁠שִׂנְאָה־בֽ⁠וֹ׃","t֤wòb ʼàruẖa֣ţ yá֭ráq wĕ⁠ʼahàbáh-şá֑̌m mi⁠ş֥̇̌wòr ʼá֝b֗ẇs wĕ⁠şînĕʼáh-bֽ⁠wò׃"],[15,18,"אִ֣ישׁ חֵ֭מָה יְגָרֶ֣ה מָד֑וֹן וְ⁠אֶ֥רֶך אַ֝פַּ֗יִם יַשְׁקִ֥יט רִֽיב׃","ʼi֣yş̌ ẖé֭máh yĕgáre֣h mád֑wòn wĕ⁠ʼe֥rek ʼa֝pȧ֗yim yaşĕ̌qi֥yt riֽyb׃"],[15,19,"דֶּ֣רֶךְ עָ֭צֵל כִּ⁠מְשֻׂ֣כַת חָ֑דֶק וְ⁠אֹ֖רַח יְשָׁרִ֣ים סְלֻלָֽה׃","dė֣rekĕ ʻá֭ẕél ki̇⁠mĕşû֣kaţ ẖá֑deq wĕ⁠ʼò֖raẖ yĕşá̌ri֣ym sĕluláֽh׃"],[15,20,"בֵּ֣ן חָ֭כָם יְשַׂמַּח־אָ֑ב וּ⁠כְסִ֥יל אָ֝דָ֗ם בּוֹזֶ֥ה אִמּֽ⁠וֹ׃","bé֣̇n ẖá֭kám yĕşâmȧẖ-ʼá֑b ẇ⁠kĕsi֥yl ʼá֝dá֗m ḃwòze֥h ʼiṁֽ⁠wò׃"],[15,21,"אִ֭וֶּלֶת שִׂמְחָ֣ה לַ⁠חֲסַר־לֵ֑ב וְ⁠אִ֥ישׁ תְּ֝בוּנָ֗ה יְיַשֶׁר־לָֽכֶת׃","ʼi֭wėleţ şîmĕẖá֣h la⁠ẖàsar-lé֑b wĕ⁠ʼi֥yş̌ ţĕ̇֝bẇná֗h yĕyaşěr-láֽkeţ׃"],[15,22,"הָפֵ֣ר מַ֭חֲשָׁבוֹת בְּ⁠אֵ֣ין ס֑וֹד וּ⁠בְ⁠רֹ֖ב יוֹעֲצִ֣ים תָּקֽוּם׃","hápé֣r ma֭ẖàşá̌bwòţ bĕ̇⁠ʼé֣yn s֑wòd ẇ⁠bĕ⁠rò֖b ywòʻàẕi֣ym ţá̇qֽẇm׃"],[15,23,"שִׂמְחָ֣ה לָ֭⁠אִישׁ בְּ⁠מַעֲנֵה־פִ֑י⁠ו וְ⁠דָבָ֖ר בְּ⁠עִתּ֣⁠וֹ מַה־טּֽוֹב׃","şîmĕẖá֣h lá֭⁠ʼiyş̌ bĕ̇⁠maʻànéh-pi֑y⁠w wĕ⁠dábá֖r bĕ̇⁠ʻiţ֣̇⁠wò mah-ṫֽwòb׃"],[15,24,"אֹ֣רַח חַ֭יִּים לְ⁠מַ֣עְלָ⁠ה לְ⁠מַשְׂכִּ֑יל לְמַ֥עַן ס֝֗וּר מִ⁠שְּׁא֥וֹל מָֽטָּה׃","ʼò֣raẖ ẖa֭yi̇ym lĕ⁠ma֣ʻĕlá⁠h lĕ⁠maşĕ̂ki֑̇yl lĕma֥ʻan s֝֗ẇr mi⁠şĕ̇̌ʼ֥wòl máֽtá̇h׃"],[15,25,"בֵּ֣ית גֵּ֭אִים יִסַּ֥ח ׀ יְהוָ֑ה וְ֝⁠יַצֵּ֗ב גְּב֣וּל אַלְמָנָֽה׃","bé֣̇yţ gé֭̇ʼiym yisȧ֥ẖ ׀ yĕhwá֑h wĕ֝⁠yaẕé̇֗b gĕ̇b֣ẇl ʼalĕmánáֽh׃"],[15,26,"תּוֹעֲבַ֣ת יְ֭הוָה מַחְשְׁב֣וֹת רָ֑ע וּ֝⁠טְהֹרִ֗ים אִמְרֵי־נֹֽעַם׃","ţ̇wòʻàba֣ţ yĕ֭hwáh maẖĕşĕ̌b֣wòţ rá֑ʻ ẇ֝⁠tĕhòri֗ym ʼimĕréy-nòֽʻam׃"],[15,27,"עֹכֵ֣ר בֵּ֭ית⁠וֹ בּוֹצֵ֣עַ בָּ֑צַע וְ⁠שׂוֹנֵ֖א מַתָּנֹ֣ת יִחְיֶֽה׃","ʻòké֣r bé֭̇yţ⁠wò ḃwòẕé֣ʻa bá֑̇ẕaʻ wĕ⁠ş̂wòné֖ʼ maţá̇nò֣ţ yiẖĕyeֽh׃"],[15,28,"לֵ֣ב צַ֭דִּיק יֶהְגֶּ֣ה לַ⁠עֲנ֑וֹת וּ⁠פִ֥י רְ֝שָׁעִ֗ים יַבִּ֥יעַ רָעֽוֹת׃","lé֣b ẕa֭di̇yq yehĕgė֣h la⁠ʻàn֑wòţ ẇ⁠pi֥y rĕ֝şá̌ʻi֗ym yabi֥̇yʻa ráʻֽwòţ׃"],[15,29,"רָח֣וֹק יְ֭הוָה מֵ⁠רְשָׁעִ֑ים וּ⁠תְפִלַּ֖ת צַדִּיקִ֣ים יִשְׁמָֽע׃","ráẖ֣wòq yĕ֭hwáh mé⁠rĕşá̌ʻi֑ym ẇ⁠ţĕpilȧ֖ţ ẕadi̇yqi֣ym yişĕ̌máֽʻ׃"],[15,30,"מְֽאוֹר־עֵ֭ינַיִם יְשַׂמַּֽח־לֵ֑ב שְׁמוּעָ֥ה ט֝וֹבָ֗ה תְּדַשֶּׁן־עָֽצֶם׃","mĕֽʼwòr-ʻé֭ynayim yĕşâmȧֽẖ-lé֑b şĕ̌mẇʻá֥h t֝wòbá֗h ţĕ̇daşė̌n-ʻáֽẕem׃"],[15,31,"אֹ֗זֶן שֹׁ֭מַעַת תּוֹכַ֣חַת חַיִּ֑ים בְּ⁠קֶ֖רֶב חֲכָמִ֣ים תָּלִֽין׃","ʼò֗zen şò֭̌maʻaţ ţ̇wòka֣ẖaţ ẖayi֑̇ym bĕ̇⁠qe֖reb ẖàkámi֣ym ţá̇liֽyn׃"],[15,32,"פּוֹרֵ֣עַ מ֭וּסָר מוֹאֵ֣ס נַפְשׁ֑⁠וֹ וְ⁠שׁוֹמֵ֥עַ תּ֝וֹכַ֗חַת ק֣וֹנֶה לֵּֽב׃","ṗwòré֣ʻa m֭ẇsár mwòʼé֣s napĕş֑̌⁠wò wĕ⁠ş̌wòmé֥ʻa ţ̇֝wòka֗ẖaţ q֣wòneh léֽ̇b׃"],[15,33,"יִרְאַ֣ת יְ֭הוָה מוּסַ֣ר חָכְמָ֑ה וְ⁠לִ⁠פְנֵ֖י כָב֣וֹד עֲנָוָֽה׃","yirĕʼa֣ţ yĕ֭hwáh mẇsa֣r ẖákĕmá֑h wĕ⁠li⁠pĕné֖y káb֣wòd ʻànáwáֽh׃"],[16,1,"לְ⁠אָדָ֥ם מַֽעַרְכֵי־לֵ֑ב וּ֝⁠מֵ⁠יְהוָ֗ה מַעֲנֵ֥ה לָשֽׁוֹן׃","lĕ⁠ʼádá֥m maֽʻarĕkéy-lé֑b ẇ֝⁠mé⁠yĕhwá֗h maʻàné֥h láşֽ̌wòn׃"],[16,2,"כָּֽל־דַּרְכֵי־אִ֭ישׁ זַ֣ךְ בְּ⁠עֵינָ֑י⁠ו וְ⁠תֹכֵ֖ן רוּח֣וֹת יְהוָֽה׃","káֽ̇l-dȧrĕkéy-ʼi֭yş̌ za֣kĕ bĕ̇⁠ʻéyná֑y⁠w wĕ⁠ţòké֖n rẇẖ֣wòţ yĕhwáֽh׃"],[16,3,"גֹּ֣ל אֶל־יְהוָ֣ה מַעֲשֶׂ֑י⁠ךָ וְ֝⁠יִכֹּ֗נוּ מַחְשְׁבֹתֶֽי⁠ךָ׃","gò֣̇l ʼel-yĕhwá֣h maʻàşê֑y⁠ká wĕ֝⁠yikò̇֗nẇ maẖĕşĕ̌bòţeֽy⁠ká׃"],[16,4,"כֹּ֤ל פָּעַ֣ל יְ֭הוָה לַֽ⁠מַּעֲנֵ֑⁠הוּ וְ⁠גַם־רָ֝שָׁ֗ע לְ⁠י֣וֹם רָעָֽה׃","kò֤̇l pá̇ʻa֣l yĕ֭hwáh laֽ⁠mȧʻàné֑⁠hẇ wĕ⁠gam-rá֝şá̌֗ʻ lĕ⁠y֣wòm ráʻáֽh׃"],[16,5,"תּוֹעֲבַ֣ת יְ֭הוָה כָּל־גְּבַהּ־לֵ֑ב יָ֥ד לְ֝⁠יָ֗ד לֹ֣א יִנָּקֶֽה׃","ţ̇wòʻàba֣ţ yĕ֭hwáh ká̇l-gĕ̇baḣ-lé֑b yá֥d lĕ֝⁠yá֗d lò֣ʼ yiná̇qeֽh׃"],[16,6,"בְּ⁠חֶ֣סֶד וֶ֭⁠אֱמֶת יְכֻפַּ֣ר עָוֺ֑ן וּ⁠בְ⁠יִרְאַ֥ת יְ֝הוָ֗ה ס֣וּר מֵ⁠רָֽע׃","bĕ̇⁠ẖe֣sed we֭⁠ʼèmeţ yĕkupȧ֣r ʻáwֺ֑n ẇ⁠bĕ⁠yirĕʼa֥ţ yĕ֝hwá֗h s֣ẇr mé⁠ráֽʻ׃"],[16,7,"בִּ⁠רְצ֣וֹת יְ֭הוָה דַּרְכֵי־אִ֑ישׁ גַּם־א֝וֹיְבָ֗י⁠ו יַשְׁלִ֥ם אִתּֽ⁠וֹ׃","bi̇⁠rĕẕ֣wòţ yĕ֭hwáh dȧrĕkéy-ʼi֑yş̌ gȧm-ʼ֝wòyĕbá֗y⁠w yaşĕ̌li֥m ʼiţֽ̇⁠wò׃"],[16,8,"טוֹב־מְ֭עַט בִּ⁠צְדָקָ֑ה מֵ⁠רֹ֥ב תְּ֝בוּא֗וֹת בְּ⁠לֹ֣א מִשְׁפָּֽט׃","twòb-mĕ֭ʻat bi̇⁠ẕĕdáqá֑h mé⁠rò֥b ţĕ̇֝bẇʼ֗wòţ bĕ̇⁠lò֣ʼ mişĕ̌páֽ̇t׃"],[16,9,"לֵ֣ב אָ֭דָם יְחַשֵּׁ֣ב דַּרְכּ֑⁠וֹ וַֽ֝⁠יהוָ֗ה יָכִ֥ין צַעֲדֽ⁠וֹ׃","lé֣b ʼá֭dám yĕẖaşé֣̇̌b dȧrĕk֑̇⁠wò waֽ֝⁠yhwá֗h yáki֥yn ẕaʻàdֽ⁠wò׃"],[16,10,"קֶ֤סֶם ׀ עַֽל־שִׂפְתֵי־מֶ֑לֶךְ בְּ֝⁠מִשְׁפָּ֗ט לֹ֣א יִמְעַל־פִּֽי⁠ו׃","qe֤sem ׀ ʻaֽl-şîpĕţéy-me֑lekĕ bĕ̇֝⁠mişĕ̌pá̇֗t lò֣ʼ yimĕʻal-piֽ̇y⁠w׃"],[16,11,"פֶּ֤לֶס ׀ וּ⁠מֹאזְנֵ֣י מִ֭שְׁפָּט לַֽ⁠יהוָ֑ה מַ֝עֲשֵׂ֗⁠הוּ כָּל־אַבְנֵי־כִֽיס׃","pė֤les ׀ ẇ⁠mòʼzĕné֣y mi֭şĕ̌pá̇t laֽ⁠yhwá֑h ma֝ʻàşé̂֗⁠hẇ ká̇l-ʼabĕnéy-kiֽys׃"],[16,12,"תּוֹעֲבַ֣ת מְ֭לָכִים עֲשׂ֣וֹת רֶ֑שַׁע כִּ֥י בִ֝⁠צְדָקָ֗ה יִכּ֥וֹן כִּסֵּֽא׃","ţ̇wòʻàba֣ţ mĕ֭lákiym ʻàş֣̂wòţ re֑şǎʻ ki֥̇y bi֝⁠ẕĕdáqá֗h yik֥̇wòn ki̇séֽ̇ʼ׃"],[16,13,"רְצ֣וֹן מְ֭לָכִים שִׂפְתֵי־צֶ֑דֶק וְ⁠דֹבֵ֖ר יְשָׁרִ֣ים יֶאֱהָֽב׃","rĕẕ֣wòn mĕ֭lákiym şîpĕţéy-ẕe֑deq wĕ⁠dòbé֖r yĕşá̌ri֣ym yeʼèháֽb׃"],[16,14,"חֲמַת־מֶ֥לֶךְ מַלְאֲכֵי־מָ֑וֶת וְ⁠אִ֖ישׁ חָכָ֣ם יְכַפְּרֶֽ⁠נָּה׃","ẖàmaţ-me֥lekĕ malĕʼàkéy-má֑weţ wĕ⁠ʼi֖yş̌ ẖáká֣m yĕkapĕ̇reֽ⁠ná̇h׃"],[16,15,"בְּ⁠אוֹר־פְּנֵי־מֶ֥לֶךְ חַיִּ֑ים וּ֝⁠רְצוֹנ֗⁠וֹ כְּ⁠עָ֣ב מַלְקֽוֹשׁ׃","bĕ̇⁠ʼwòr-pĕ̇néy-me֥lekĕ ẖayi֑̇ym ẇ֝⁠rĕẕwòn֗⁠wò kĕ̇⁠ʻá֣b malĕqֽwòş̌׃"],[16,16,"קְֽנֹה־חָכְמָ֗ה מַה־טּ֥וֹב מֵ⁠חָר֑וּץ וּ⁠קְנ֥וֹת בִּ֝ינָ֗ה נִבְחָ֥ר מִ⁠כָּֽסֶף׃","qĕֽnòh-ẖákĕmá֗h mah-ṫ֥wòb mé⁠ẖár֑ẇẕ ẇ⁠qĕn֥wòţ bi̇֝yná֗h nibĕẖá֥r mi⁠káֽ̇sep׃"],[16,17,"מְסִלַּ֣ת יְ֭שָׁרִים ס֣וּר מֵ⁠רָ֑ע שֹׁמֵ֥ר נַ֝פְשׁ֗⁠וֹ נֹצֵ֥ר דַּרְכּֽ⁠וֹ׃","mĕsilȧ֣ţ yĕ֭şá̌riym s֣ẇr mé⁠rá֑ʻ şò̌mé֥r na֝pĕş̌֗⁠wò nòẕé֥r dȧrĕkֽ̇⁠wò׃"],[16,18,"לִ⁠פְנֵי־שֶׁ֥בֶר גָּא֑וֹן וְ⁠לִ⁠פְנֵ֥י כִ֝שָּׁל֗וֹן גֹּ֣בַהּ רֽוּחַ׃","li⁠pĕnéy-şě֥ber gá̇ʼ֑wòn wĕ⁠li⁠pĕné֥y ki֝şá̇̌l֗wòn gò֣̇baḣ rֽẇẖa׃"],[16,19,"ט֣וֹב שְׁפַל־ר֭וּחַ אֶת־עניים מֵֽ⁠חַלֵּ֥ק שָׁ֝לָ֗ל אֶת־גֵּאִֽים׃","t֣wòb şĕ̌pal-r֭ẇẖa ʼeţ-ʻnyym méֽ⁠ẖalé֥̇q şá̌֝lá֗l ʼeţ-gé̇ʼiֽym׃"],[16,20,"מַשְׂכִּ֣יל עַל־דָּ֭בָר יִמְצָא־ט֑וֹב וּ⁠בוֹטֵ֖חַ בַּ⁠יהוָ֣ה אַשְׁרָֽי⁠ו׃","maşĕ̂ki֣̇yl ʻal-dá֭̇bár yimĕẕáʼ-t֑wòb ẇ⁠bwòté֖ẖa bȧ⁠yhwá֣h ʼaşĕ̌ráֽy⁠w׃"],[16,21,"לַ⁠חֲכַם־לֵ֭ב יִקָּרֵ֣א נָב֑וֹן וּ⁠מֶ֥תֶק שְׂ֝פָתַ֗יִם יֹסִ֥יף לֶֽקַח׃","la⁠ẖàkam-lé֭b yiqá̇ré֣ʼ náb֑wòn ẇ⁠me֥ţeq şĕ̂֝páţa֗yim yòsi֥yp leֽqaẖ׃"],[16,22,"מְק֣וֹר חַ֭יִּים שֵׂ֣כֶל בְּעָלָ֑י⁠ו וּ⁠מוּסַ֖ר אֱוִלִ֣ים אִוֶּֽלֶת׃","mĕq֣wòr ẖa֭yi̇ym şé֣̂kel bĕ̇ʻálá֑y⁠w ẇ⁠mẇsa֖r ʼèwili֣ym ʼiwėֽleţ׃"],[16,23,"לֵ֣ב חָ֭כָם יַשְׂכִּ֣יל פִּ֑י⁠הוּ וְ⁠עַל־שְׂ֝פָתָ֗י⁠ו יֹסִ֥יף לֶֽקַח׃","lé֣b ẖá֭kám yaşĕ̂ki֣̇yl pi֑̇y⁠hẇ wĕ⁠ʻal-şĕ̂֝páţá֗y⁠w yòsi֥yp leֽqaẖ׃"],[16,24,"צוּף־דְּ֭בַשׁ אִמְרֵי־נֹ֑עַם מָת֥וֹק לַ֝⁠נֶּפֶשׁ וּ⁠מַרְפֵּ֥א לָ⁠עָֽצֶם׃","ẕẇp-dĕ֭̇baş̌ ʼimĕréy-nò֑ʻam máţ֥wòq la֝⁠nėpeş̌ ẇ⁠marĕpé֥̇ʼ lá⁠ʻáֽẕem׃"],[16,25,"יֵ֤שׁ דֶּ֣רֶךְ יָ֭שָׁר לִ⁠פְנֵי־אִ֑ישׁ וְ֝⁠אַחֲרִיתָ֗⁠הּ דַּרְכֵי־מָֽוֶת׃","yé֤ş̌ dė֣rekĕ yá֭şá̌r li⁠pĕnéy-ʼi֑yş̌ wĕ֝⁠ʼaẖàriyţá֗⁠ḣ dȧrĕkéy-máֽweţ׃"],[16,26,"נֶ֣פֶשׁ עָ֭מֵל עָ֣מְלָה לּ֑⁠וֹ כִּֽי־אָכַ֖ף עָלָ֣י⁠ו פִּֽי⁠הוּ׃","ne֣peş̌ ʻá֭mél ʻá֣mĕláh l֑̇⁠wò kiֽ̇y-ʼáka֖p ʻálá֣y⁠w piֽ̇y⁠hẇ׃"],[16,27,"אִ֣ישׁ בְּ֭לִיַּעַל כֹּרֶ֣ה רָעָ֑ה וְ⁠עַל־שפתי⁠ו כְּ⁠אֵ֣שׁ צָרָֽבֶת׃","ʼi֣yş̌ bĕ֭̇liyȧʻal kò̇re֣h ráʻá֑h wĕ⁠ʻal-şpţy⁠w kĕ̇⁠ʼé֣ş̌ ẕáráֽbeţ׃"],[16,28,"אִ֣ישׁ תַּ֭הְפֻּכוֹת יְשַׁלַּ֣ח מָד֑וֹן וְ֝נִרְגָּ֗ן מַפְרִ֥יד אַלּֽוּף׃","ʼi֣yş̌ ţȧ֭hĕpu̇kwòţ yĕşǎlȧ֣ẖ mád֑wòn wĕ֝nirĕgá̇֗n mapĕri֥yd ʼalֽ̇ẇp׃"],[16,29,"אִ֣ישׁ חָ֭מָס יְפַתֶּ֣ה רֵעֵ֑⁠הוּ וְ֝⁠הוֹלִיכ֗⁠וֹ בְּ⁠דֶ֣רֶךְ לֹא־טֽוֹב׃","ʼi֣yş̌ ẖá֭más yĕpaţė֣h réʻé֑⁠hẇ wĕ֝⁠hwòliyk֗⁠wò bĕ̇⁠de֣rekĕ lòʼ-tֽwòb׃"],[16,30,"עֹצֶ֣ה עֵ֭ינָי⁠ו לַ⁠חְשֹׁ֣ב תַּהְפֻּכ֑וֹת קֹרֵ֥ץ שְׂ֝פָתָ֗י⁠ו כִּלָּ֥ה רָעָֽה׃","ʻòẕe֣h ʻé֭ynáy⁠w la⁠ẖĕşò֣̌b ţȧhĕpu̇k֑wòţ qòré֥ẕ şĕ̂֝páţá֗y⁠w ki̇lá֥̇h ráʻáֽh׃"],[16,31,"עֲטֶ֣רֶת תִּפְאֶ֣רֶת שֵׂיבָ֑ה בְּ⁠דֶ֥רֶךְ צְ֝דָקָ֗ה תִּמָּצֵֽא׃","ʻàte֣reţ ţi̇pĕʼe֣reţ şé̂ybá֑h bĕ̇⁠de֥rekĕ ẕĕ֝dáqá֗h ţi̇má̇ẕéֽʼ׃"],[16,32,"ט֤וֹב אֶ֣רֶךְ אַ֭פַּיִם מִ⁠גִּבּ֑וֹר וּ⁠מֹשֵׁ֥ל בְּ֝⁠רוּח֗⁠וֹ מִ⁠לֹּכֵ֥ד עִֽיר׃","t֤wòb ʼe֣rekĕ ʼa֭pȧyim mi⁠gi̇ḃ֑wòr ẇ⁠mòşé֥̌l bĕ̇֝⁠rẇẖ֗⁠wò mi⁠lò̇ké֥d ʻiֽyr׃"],[16,33,"בַּ֭⁠חֵיק יוּטַ֣ל אֶת־הַ⁠גּוֹרָ֑ל וּ֝⁠מֵ⁠יְהוָ֗ה כָּל־מִשְׁפָּטֽ⁠וֹ׃","bȧ֭⁠ẖéyq yẇta֣l ʼeţ-ha⁠ġwòrá֑l ẇ֝⁠mé⁠yĕhwá֗h ká̇l-mişĕ̌pá̇tֽ⁠wò׃"],[17,1,"ט֤וֹב פַּ֣ת חֲ֭רֵבָה וְ⁠שַׁלְוָה־בָ֑⁠הּ מִ֝⁠בַּ֗יִת מָלֵ֥א זִבְחֵי־רִֽיב׃","t֤wòb pȧ֣ţ ẖà֭rébáh wĕ⁠şǎlĕwáh-bá֑⁠ḣ mi֝⁠bȧ֗yiţ málé֥ʼ zibĕẖéy-riֽyb׃"],[17,2,"עֶֽבֶד־מַשְׂכִּ֗יל יִ֭מְשֹׁל בְּ⁠בֵ֣ן מֵבִ֑ישׁ וּ⁠בְ⁠ת֥וֹךְ אַ֝חִ֗ים יַחֲלֹ֥ק נַחֲלָֽה׃","ʻeֽbed-maşĕ̂ki̇֗yl yi֭mĕşò̌l bĕ̇⁠bé֣n mébi֑yş̌ ẇ⁠bĕ⁠ţ֥wòkĕ ʼa֝ẖi֗ym yaẖàlò֥q naẖàláֽh׃"],[17,3,"מַצְרֵ֣ף לַ֭⁠כֶּסֶף וְ⁠כ֣וּר לַ⁠זָּהָ֑ב וּ⁠בֹחֵ֖ן לִבּ֣וֹת יְהוָֽה׃","maẕĕré֣p la֭⁠kėsep wĕ⁠k֣ẇr la⁠zá̇há֑b ẇ⁠bòẖé֖n liḃ֣wòţ yĕhwáֽh׃"],[17,4,"מֵ֭רַע מַקְשִׁ֣יב עַל־שְׂפַת־אָ֑וֶן שֶׁ֥קֶר מֵ֝זִין עַל־לְשׁ֥וֹן הַוֺּֽת׃","mé֭raʻ maqĕşǐ֣yb ʻal-şĕ̂paţ-ʼá֑wen şě֥qer mé֝ziyn ʻal-lĕş֥̌wòn haẇֺֽţ׃"],[17,5,"לֹעֵ֣ג לָ֭⁠רָשׁ חֵרֵ֣ף עֹשֵׂ֑⁠הוּ שָׂמֵ֥חַ לְ֝⁠אֵ֗יד לֹ֣א יִנָּקֶֽה׃","lòʻé֣g lá֭⁠ráş̌ ẖéré֣p ʻòşé֑̂⁠hẇ şá̂mé֥ẖa lĕ֝⁠ʼé֗yd lò֣ʼ yiná̇qeֽh׃"],[17,6,"עֲטֶ֣רֶת זְ֭קֵנִים בְּנֵ֣י בָנִ֑ים וְ⁠תִפְאֶ֖רֶת בָּנִ֣ים אֲבוֹתָֽ⁠ם׃","ʻàte֣reţ zĕ֭qéniym bĕ̇né֣y báni֑ym wĕ⁠ţipĕʼe֖reţ bá̇ni֣ym ʼàbwòţáֽ⁠m׃"],[17,7,"לֹא־נָאוָ֣ה לְ⁠נָבָ֣ל שְׂפַת־יֶ֑תֶר אַ֝֗ף כִּֽי־לְ⁠נָדִ֥יב שְׂפַת־שָֽׁקֶר׃","lòʼ-náʼwá֣h lĕ⁠nábá֣l şĕ̂paţ-ye֑ţer ʼa֝֗p kiֽ̇y-lĕ⁠nádi֥yb şĕ̂paţ-şáֽ̌qer׃"],[17,8,"אֶֽבֶן־חֵ֣ן הַ֭⁠שֹּׁחַד בְּ⁠עֵינֵ֣י בְעָלָ֑י⁠ו אֶֽל־כָּל־אֲשֶׁ֖ר יִפְנֶ֣ה יַשְׂכִּֽיל׃","ʼeֽben-ẖé֣n ha֭⁠şò̇̌ẖad bĕ̇⁠ʻéyné֣y bĕʻálá֑y⁠w ʼeֽl-ká̇l-ʼàşě֖r yipĕne֣h yaşĕ̂kiֽ̇yl׃"],[17,9,"מְֽכַסֶּה־פֶּ֭שַׁע מְבַקֵּ֣שׁ אַהֲבָ֑ה וְ⁠שֹׁנֶ֥ה בְ֝⁠דָבָ֗ר מַפְרִ֥יד אַלּֽוּף׃","mĕֽkasėh-pė֭şǎʻ mĕbaqé֣̇ş̌ ʼahàbá֑h wĕ⁠şò̌ne֥h bĕ֝⁠dábá֗r mapĕri֥yd ʼalֽ̇ẇp׃"],[17,10,"תֵּ֣חַת גְּעָרָ֣ה בְ⁠מֵבִ֑ין מֵ⁠הַכּ֖וֹת כְּסִ֣יל מֵאָֽה׃","ţé֣̇ẖaţ gĕ̇ʻárá֣h bĕ⁠mébi֑yn mé⁠hak֖̇wòţ kĕ̇si֣yl méʼáֽh׃"],[17,11,"אַךְ־מְרִ֥י יְבַקֶּשׁ־רָ֑ע וּ⁠מַלְאָ֥ךְ אַ֝כְזָרִ֗י יְשֻׁלַּח־בּֽ⁠וֹ׃","ʼakĕ-mĕri֥y yĕbaqėş̌-rá֑ʻ ẇ⁠malĕʼá֥kĕ ʼa֝kĕzári֗y yĕşǔlȧẖ-ḃֽ⁠wò׃"],[17,12,"פָּג֬וֹשׁ דֹּ֣ב שַׁכּ֣וּל בְּ⁠אִ֑ישׁ וְ⁠אַל־כְּ֝סִ֗יל בְּ⁠אִוַּלְתּֽ⁠וֹ׃","pá̇g֬wòş̌ dò֣̇b şǎk֣̇ẇl bĕ̇⁠ʼi֑yş̌ wĕ⁠ʼal-kĕ̇֝si֗yl bĕ̇⁠ʼiwȧlĕţֽ̇⁠wò׃"],[17,13,"מֵשִׁ֣יב רָ֭עָה תַּ֣חַת טוֹבָ֑ה לֹא־תמיש רָ֝עָ֗ה מִ⁠בֵּיתֽ⁠וֹ׃","méşǐ֣yb rá֭ʻáh ţȧ֣ẖaţ twòbá֑h lòʼ-ţmyş rá֝ʻá֗h mi⁠bé̇yţֽ⁠wò׃"],[17,14,"פּ֣וֹטֵֽר מַ֭יִם רֵאשִׁ֣ית מָד֑וֹן וְ⁠לִ⁠פְנֵ֥י הִ֝תְגַּלַּ֗ע הָ⁠רִ֥יב נְטֽוֹשׁ׃","ṗ֣wòtéֽr ma֭yim réʼşǐ֣yţ mád֑wòn wĕ⁠li⁠pĕné֥y hi֝ţĕgȧlȧ֗ʻ há⁠ri֥yb nĕtֽwòş̌׃"],[17,15,"מַצְדִּ֣יק רָ֭שָׁע וּ⁠מַרְשִׁ֣יעַ צַדִּ֑יק תּוֹעֲבַ֥ת יְ֝הוָ֗ה גַּם־שְׁנֵי⁠הֶֽם׃","maẕĕdi֣̇yq rá֭şá̌ʻ ẇ⁠marĕşǐ֣yʻa ẕadi֑̇yq ţ̇wòʻàba֥ţ yĕ֝hwá֗h gȧm-şĕ̌néy⁠heֽm׃"],[17,16,"לָ⁠מָּה־זֶּ֣ה מְחִ֣יר בְּ⁠יַד־כְּסִ֑יל לִ⁠קְנ֖וֹת חָכְמָ֣ה וְ⁠לֶב־אָֽיִן׃","lá⁠má̇h-zė֣h mĕẖi֣yr bĕ̇⁠yad-kĕ̇si֑yl li⁠qĕn֖wòţ ẖákĕmá֣h wĕ⁠leb-ʼáֽyin׃"],[17,17,"בְּ⁠כָל־עֵ֭ת אֹהֵ֣ב הָ⁠רֵ֑עַ וְ⁠אָ֥ח לְ֝⁠צָרָ֗ה יִוָּלֵֽד׃","bĕ̇⁠kál-ʻé֭ţ ʼòhé֣b há⁠ré֑ʻa wĕ⁠ʼá֥ẖ lĕ֝⁠ẕárá֗h yiwá̇léֽd׃"],[17,18,"אָדָ֣ם חֲסַר־לֵ֭ב תּוֹקֵ֣עַ כָּ֑ף עֹרֵ֥ב עֲ֝רֻבָּ֗ה לִ⁠פְנֵ֥י רֵעֵֽ⁠הוּ׃","ʼádá֣m ẖàsar-lé֭b ţ̇wòqé֣ʻa ká֑̇p ʻòré֥b ʻà֝rubá̇֗h li⁠pĕné֥y réʻéֽ⁠hẇ׃"],[17,19,"אֹ֣הֵֽב פֶּ֭שַׁע אֹהֵ֣ב מַצָּ֑ה מַגְבִּ֥יהַּ פִּ֝תְח֗⁠וֹ מְבַקֶּשׁ־שָֽׁבֶר׃","ʼò֣héֽb pė֭şǎʻ ʼòhé֣b maẕá֑̇h magĕbi֥̇yhȧ pi̇֝ţĕẖ֗⁠wò mĕbaqėş̌-şáֽ̌ber׃"],[17,20,"עִקֶּשׁ־לֵ֭ב לֹ֣א יִמְצָא־ט֑וֹב וְ⁠נֶהְפָּ֥ךְ בִּ֝⁠לְשׁוֹנ֗⁠וֹ יִפּ֥וֹל בְּ⁠רָעָֽה׃","ʻiqėş̌-lé֭b lò֣ʼ yimĕẕáʼ-t֑wòb wĕ⁠nehĕpá֥̇kĕ bi̇֝⁠lĕş̌wòn֗⁠wò yiṗ֥wòl bĕ̇⁠ráʻáֽh׃"],[17,21,"יֹלֵ֣ד כְּ֭סִיל לְ⁠ת֣וּגָה ל֑⁠וֹ וְ⁠לֹֽא־יִ֝שְׂמַ֗ח אֲבִ֣י נָבָֽל׃","yòlé֣d kĕ֭̇siyl lĕ⁠ţ֣ẇgáh l֑⁠wò wĕ⁠lòֽʼ-yi֝şĕ̂ma֗ẖ ʼàbi֣y nábáֽl׃"],[17,22,"לֵ֣ב שָׂ֭מֵחַ יֵיטִ֣ב גֵּהָ֑ה וְ⁠ר֥וּחַ נְ֝כֵאָ֗ה תְּיַבֶּשׁ־גָּֽרֶם׃","lé֣b şá֭̂méẖa yéyti֣b gé̇há֑h wĕ⁠r֥ẇẖa nĕ֝kéʼá֗h ţĕ̇yabėş̌-gáֽ̇rem׃"],[17,23,"שֹׁ֣חַד מֵ֭⁠חֵיק רָשָׁ֣ע יִקָּ֑ח לְ֝⁠הַטּ֗וֹת אָרְח֥וֹת מִשְׁפָּֽט׃","şò֣̌ẖad mé֭⁠ẖéyq ráşá֣̌ʻ yiqá֑̇ẖ lĕ֝⁠haṫ֗wòţ ʼárĕẖ֥wòţ mişĕ̌páֽ̇t׃"],[17,24,"אֶת־פְּנֵ֣י מֵבִ֣ין חָכְמָ֑ה וְ⁠עֵינֵ֥י כְ֝סִ֗יל בִּ⁠קְצֵה־אָֽרֶץ׃","ʼeţ-pĕ̇né֣y mébi֣yn ẖákĕmá֑h wĕ⁠ʻéyné֥y kĕ֝si֗yl bi̇⁠qĕẕéh-ʼáֽreẕ׃"],[17,25,"כַּ֣עַס לְ֭⁠אָבִי⁠ו בֵּ֣ן כְּסִ֑יל וּ֝⁠מֶ֗מֶר לְ⁠יוֹלַדְתּֽ⁠וֹ׃","kȧ֣ʻas lĕ֭⁠ʼábiy⁠w bé֣̇n kĕ̇si֑yl ẇ֝⁠me֗mer lĕ⁠ywòladĕţֽ̇⁠wò׃"],[17,26,"גַּ֤ם עֲנ֣וֹשׁ לַ⁠צַּדִּ֣יק לֹא־ט֑וֹב לְ⁠הַכּ֖וֹת נְדִיבִ֣ים עַל־יֹֽשֶׁר׃","gȧ֤m ʻàn֣wòş̌ la⁠ẕȧdi֣̇yq lòʼ-t֑wòb lĕ⁠hak֖̇wòţ nĕdiybi֣ym ʻal-yòֽşěr׃"],[17,27,"חוֹשֵׂ֣ךְ אֲ֭מָרָי⁠ו יוֹדֵ֣עַ דָּ֑עַת ו⁠קר־ר֝֗וּחַ אִ֣ישׁ תְּבוּנָֽה׃","ẖwòşé֣̂kĕ ʼà֭máráy⁠w ywòdé֣ʻa dá֑̇ʻaţ w⁠qr-r֝֗ẇẖa ʼi֣yş̌ ţĕ̇bẇnáֽh׃"],[17,28,"גַּ֤ם אֱוִ֣יל מַ֭חֲרִישׁ חָכָ֣ם יֵחָשֵׁ֑ב אֹטֵ֖ם שְׂפָתָ֣י⁠ו נָבֽוֹן׃","gȧ֤m ʼèwi֣yl ma֭ẖàriyş̌ ẖáká֣m yéẖáşé֑̌b ʼòté֖m şĕ̂páţá֣y⁠w nábֽwòn׃"],[18,1,"לְֽ֭⁠תַאֲוָה יְבַקֵּ֣שׁ נִפְרָ֑ד בְּ⁠כָל־תּ֝וּשִׁיָּ֗ה יִתְגַּלָּֽע׃","lĕֽ֭⁠ţaʼàwáh yĕbaqé֣̇ş̌ nipĕrá֑d bĕ̇⁠kál-ţ̇֝ẇşǐyá̇֗h yiţĕgȧláֽ̇ʻ׃"],[18,2,"לֹֽא־יַחְפֹּ֣ץ כְּ֭סִיל בִּ⁠תְבוּנָ֑ה כִּ֝֗י אִֽם־בְּ⁠הִתְגַּלּ֥וֹת לִבּֽ⁠וֹ׃","lòֽʼ-yaẖĕpò֣̇ẕ kĕ֭̇siyl bi̇⁠ţĕbẇná֑h ki̇֝֗y ʼiֽm-bĕ̇⁠hiţĕgȧl֥̇wòţ liḃֽ⁠wò׃"],[18,3,"בְּֽ⁠בוֹא־רָ֭שָׁע בָּ֣א גַם־בּ֑וּז וְֽ⁠עִם־קָל֥וֹן חֶרְפָּֽה׃","bĕֽ̇⁠bwòʼ-rá֭şá̌ʻ bá֣̇ʼ gam-ḃ֑ẇz wĕֽ⁠ʻim-qál֥wòn ẖerĕpáֽ̇h׃"],[18,4,"מַ֣יִם עֲ֭מֻקִּים דִּבְרֵ֣י פִי־אִ֑ישׁ נַ֥חַל נֹ֝בֵ֗עַ מְק֣וֹר חָכְמָֽה׃","ma֣yim ʻà֭muqi̇ym di̇bĕré֣y piy-ʼi֑yş̌ na֥ẖal nò֝bé֗ʻa mĕq֣wòr ẖákĕmáֽh׃"],[18,5,"שְׂאֵ֣ת פְּנֵי־רָשָׁ֣ע לֹא־ט֑וֹב לְ⁠הַטּ֥וֹת צַ֝דִּ֗יק בַּ⁠מִּשְׁפָּֽט׃","şĕ̂ʼé֣ţ pĕ̇néy-ráşá֣̌ʻ lòʼ-t֑wòb lĕ⁠haṫ֥wòţ ẕa֝di̇֗yq bȧ⁠mi̇şĕ̌páֽ̇t׃"],[18,6,"שִׂפְתֵ֣י כְ֭סִיל יָבֹ֣אֽוּ בְ⁠רִ֑יב וּ֝⁠פִ֗י⁠ו לְֽ⁠מַהֲלֻמ֥וֹת יִקְרָֽא׃","şîpĕţé֣y kĕ֭siyl yábò֣ʼֽẇ bĕ⁠ri֑yb ẇ֝⁠pi֗y⁠w lĕֽ⁠mahàlum֥wòţ yiqĕráֽʼ׃"],[18,7,"פִּֽי־כְ֭סִיל מְחִתָּה־ל֑⁠וֹ וּ֝⁠שְׂפָתָ֗י⁠ו מוֹקֵ֥שׁ נַפְשֽׁ⁠וֹ׃","piֽ̇y-kĕ֭siyl mĕẖiţá̇h-l֑⁠wò ẇ֝⁠şĕ̂páţá֗y⁠w mwòqé֥ş̌ napĕşֽ̌⁠wò׃"],[18,8,"דִּבְרֵ֣י נִ֭רְגָּן כְּ⁠מִֽתְלַהֲמִ֑ים וְ֝⁠הֵ֗ם יָרְד֥וּ חַדְרֵי־בָֽטֶן׃","di̇bĕré֣y ni֭rĕgá̇n kĕ̇⁠miֽţĕlahàmi֑ym wĕ֝⁠hé֗m yárĕd֥ẇ ẖadĕréy-báֽten׃"],[18,9,"גַּ֭ם מִתְרַפֶּ֣ה בִ⁠מְלַאכְתּ֑⁠וֹ אָ֥ח ה֝֗וּא לְ⁠בַ֣עַל מַשְׁחִֽית׃","gȧ֭m miţĕrapė֣h bi⁠mĕlaʼkĕţ֑̇⁠wò ʼá֥ẖ h֝֗ẇʼ lĕ⁠ba֣ʻal maşĕ̌ẖiֽyţ׃"],[18,10,"מִגְדַּל־עֹ֭ז שֵׁ֣ם יְהוָ֑ה בּֽ⁠וֹ־יָר֖וּץ צַדִּ֣יק וְ⁠נִשְׂגָּֽב׃","migĕdȧl-ʻò֭z şé֣̌m yĕhwá֑h ḃֽ⁠wò-yár֖ẇẕ ẕadi֣̇yq wĕ⁠nişĕ̂gáֽ̇b׃"],[18,11,"ה֣וֹן עָ֭שִׁיר קִרְיַ֣ת עֻזּ֑⁠וֹ וּ⁠כְ⁠חוֹמָ֥ה נִ֝שְׂגָּבָ֗ה בְּ⁠מַשְׂכִּיתֽ⁠וֹ׃","h֣wòn ʻá֭şǐyr qirĕya֣ţ ʻuż֑⁠wò ẇ⁠kĕ⁠ẖwòmá֥h ni֝şĕ̂gá̇bá֗h bĕ̇⁠maşĕ̂ki̇yţֽ⁠wò׃"],[18,12,"לִ⁠פְנֵי־שֶׁ֭בֶר יִגְבַּ֣הּ לֵב־אִ֑ישׁ וְ⁠לִ⁠פְנֵ֖י כָב֣וֹד עֲנָוָֽה׃","li⁠pĕnéy-şě֭ber yigĕbȧ֣ḣ léb-ʼi֑yş̌ wĕ⁠li⁠pĕné֖y káb֣wòd ʻànáwáֽh׃"],[18,13,"מֵשִׁ֣יב דָּ֭בָר בְּ⁠טֶ֣רֶם יִשְׁמָ֑ע אִוֶּ֥לֶת הִיא־ל֝֗⁠וֹ וּ⁠כְלִמָּֽה׃","méşǐ֣yb dá֭̇bár bĕ̇⁠te֣rem yişĕ̌má֑ʻ ʼiwė֥leţ hiyʼ-l֝֗⁠wò ẇ⁠kĕlimáֽ̇h׃"],[18,14,"רֽוּחַ־אִ֭ישׁ יְכַלְכֵּ֣ל מַחֲלֵ֑⁠הוּ וְ⁠ר֥וּחַ נְ֝כֵאָ֗ה מִ֣י יִשָּׂאֶֽ⁠נָּה׃","rֽẇẖa-ʼi֭yş̌ yĕkalĕké֣̇l maẖàlé֑⁠hẇ wĕ⁠r֥ẇẖa nĕ֝kéʼá֗h mi֣y yişá̇̂ʼeֽ⁠ná̇h׃"],[18,15,"לֵ֣ב נָ֭בוֹן יִקְנֶה־דָּ֑עַת וְ⁠אֹ֥זֶן חֲ֝כָמִ֗ים תְּבַקֶּשׁ־דָּֽעַת׃","lé֣b ná֭bwòn yiqĕneh-dá֑̇ʻaţ wĕ⁠ʼò֥zen ẖà֝kámi֗ym ţĕ̇baqėş̌-dáֽ̇ʻaţ׃"],[18,16,"מַתָּ֣ן אָ֭דָם יַרְחִ֣יב ל֑⁠וֹ וְ⁠לִ⁠פְנֵ֖י גְדֹלִ֣ים יַנְחֶֽ⁠נּוּ׃","maţá֣̇n ʼá֭dám yarĕẖi֣yb l֑⁠wò wĕ⁠li⁠pĕné֖y gĕdòli֣ym yanĕẖeֽ⁠ṅẇ׃"],[18,17,"צַדִּ֣יק הָ⁠רִאשׁ֣וֹן בְּ⁠רִיב֑⁠וֹ יבא־רֵ֝עֵ֗⁠הוּ וַ⁠חֲקָרֽ⁠וֹ׃","ẕadi֣̇yq há⁠riʼş֣̌wòn bĕ̇⁠riyb֑⁠wò ybʼ-ré֝ʻé֗⁠hẇ wa⁠ẖàqárֽ⁠wò׃"],[18,18,"מִ֭דְיָנִים יַשְׁבִּ֣ית הַ⁠גּוֹרָ֑ל וּ⁠בֵ֖ין עֲצוּמִ֣ים יַפְרִֽיד׃","mi֭dĕyániym yaşĕ̌bi֣̇yţ ha⁠ġwòrá֑l ẇ⁠bé֖yn ʻàẕẇmi֣ym yapĕriֽyd׃"],[18,19,"אָ֗ח נִפְשָׁ֥ע מִ⁠קִּרְיַת־עֹ֑ז ו⁠מדונים כִּ⁠בְרִ֥יחַ אַרְמֽוֹן׃","ʼá֗ẖ nipĕşá֥̌ʻ mi⁠qi̇rĕyaţ-ʻò֑z w⁠mdwnym ki̇⁠bĕri֥yẖa ʼarĕmֽwòn׃"],[18,20,"מִ⁠פְּרִ֣י פִי־אִ֭ישׁ תִּשְׂבַּ֣ע בִּטְנ֑⁠וֹ תְּבוּאַ֖ת שְׂפָתָ֣י⁠ו יִשְׂבָּֽע׃","mi⁠pĕ̇ri֣y piy-ʼi֭yş̌ ţi̇şĕ̂bȧ֣ʻ bi̇tĕn֑⁠wò ţĕ̇bẇʼa֖ţ şĕ̂páţá֣y⁠w yişĕ̂báֽ̇ʻ׃"],[18,21,"מָ֣וֶת וְ֭⁠חַיִּים בְּ⁠יַד־לָשׁ֑וֹן וְ֝⁠אֹהֲבֶ֗י⁠הָ יֹאכַ֥ל פִּרְיָֽ⁠הּ׃","má֣weţ wĕ֭⁠ẖayi̇ym bĕ̇⁠yad-láş֑̌wòn wĕ֝⁠ʼòhàbe֗y⁠há yòʼka֥l pi̇rĕyáֽ⁠ḣ׃"],[18,22,"מָצָ֣א אִ֭שָּׁה מָ֣צָא ט֑וֹב וַ⁠יָּ֥פֶק רָ֝צ֗וֹן מֵ⁠יְהוָֽה׃","máẕá֣ʼ ʼi֭şá̇̌h má֣ẕáʼ t֑wòb wa⁠yá֥̇peq rá֝ẕ֗wòn mé⁠yĕhwáֽh׃"],[18,23,"תַּחֲנוּנִ֥ים יְדַבֶּר־רָ֑שׁ וְ֝⁠עָשִׁ֗יר יַעֲנֶ֥ה עַזּֽוֹת׃","ţȧẖànẇni֥ym yĕdabėr-rá֑ş̌ wĕ֝⁠ʻáşǐ֗yr yaʻàne֥h ʻażֽwòţ׃"],[18,24,"אִ֣ישׁ רֵ֭עִים לְ⁠הִתְרֹעֵ֑עַ וְ⁠יֵ֥שׁ אֹ֝הֵ֗ב דָּבֵ֥ק מֵ⁠אָֽח׃","ʼi֣yş̌ ré֭ʻiym lĕ⁠hiţĕròʻé֑ʻa wĕ⁠yé֥ş̌ ʼò֝hé֗b dá̇bé֥q mé⁠ʼáֽẖ׃"],[19,1,"טֽוֹב־רָ֭שׁ הוֹלֵ֣ךְ בְּ⁠תֻמּ֑⁠וֹ מֵ⁠עִקֵּ֥שׁ שְׂ֝פָתָ֗י⁠ו וְ⁠ה֣וּא כְסִֽיל׃","tֽwòb-rá֭ş̌ hwòlé֣kĕ bĕ̇⁠ţuṁ֑⁠wò mé⁠ʻiqé֥̇ş̌ şĕ̂֝páţá֗y⁠w wĕ⁠h֣ẇʼ kĕsiֽyl׃"],[19,2,"גַּ֤ם בְּ⁠לֹא־דַ֣עַת נֶ֣פֶשׁ לֹא־ט֑וֹב וְ⁠אָ֖ץ בְּ⁠רַגְלַ֣יִם חוֹטֵֽא׃","gȧ֤m bĕ̇⁠lòʼ-da֣ʻaţ ne֣peş̌ lòʼ-t֑wòb wĕ⁠ʼá֖ẕ bĕ̇⁠ragĕla֣yim ẖwòtéֽʼ׃"],[19,3,"אִוֶּ֣לֶת אָ֭דָם תְּסַלֵּ֣ף דַּרְכּ֑⁠וֹ וְ⁠עַל־יְ֝הוָ֗ה יִזְעַ֥ף לִבּֽ⁠וֹ׃","ʼiwė֣leţ ʼá֭dám ţĕ̇salé֣̇p dȧrĕk֑̇⁠wò wĕ⁠ʻal-yĕ֝hwá֗h yizĕʻa֥p liḃֽ⁠wò׃"],[19,4,"ה֗וֹן יֹ֭סִיף רֵעִ֣ים רַבִּ֑ים וְ֝⁠דָ֗ל מֵרֵ֥ע⁠הוּ יִפָּרֵֽד׃","h֗wòn yò֭siyp réʻi֣ym rabi֑̇ym wĕ֝⁠dá֗l méré֥ʻ⁠hẇ yipá̇réֽd׃"],[19,5,"עֵ֣ד שְׁ֭קָרִים לֹ֣א יִנָּקֶ֑ה וְ⁠יָפִ֥יחַ כְּ֝זָבִ֗ים לֹ֣א יִמָּלֵֽט׃","ʻé֣d şĕ֭̌qáriym lò֣ʼ yiná̇qe֑h wĕ⁠yápi֥yẖa kĕ̇֝zábi֗ym lò֣ʼ yimá̇léֽt׃"],[19,6,"רַ֭בִּים יְחַלּ֣וּ פְנֵֽי־נָדִ֑יב וְ⁠כָל־הָ֝⁠רֵ֗עַ לְ⁠אִ֣ישׁ מַתָּֽן׃","ra֭bi̇ym yĕẖal֣̇ẇ pĕnéֽy-nádi֑yb wĕ⁠kál-há֝⁠ré֗ʻa lĕ⁠ʼi֣yş̌ maţáֽ̇n׃"],[19,7,"כָּ֥ל אֲחֵי־רָ֨שׁ ׀ שְֽׂנֵאֻ֗⁠הוּ אַ֤ף כִּ֣י מְ֭רֵעֵ⁠הוּ רָחֲק֣וּ מִמֶּ֑⁠נּוּ מְרַדֵּ֖ף אֲמָרִ֣ים לא־הֵֽמָּה׃","ká֥̇l ʼàẖéy-rá֨ş̌ ׀ şĕֽ̂néʼu֗⁠hẇ ʼa֤p ki֣̇y mĕ֭réʻé⁠hẇ ráẖàq֣ẇ mimė֑⁠ṅẇ mĕradé֖̇p ʼàmári֣ym lʼ-héֽmá̇h׃"],[19,8,"קֹֽנֶה־לֵּ֭ב אֹהֵ֣ב נַפְשׁ֑⁠וֹ שֹׁמֵ֥ר תְּ֝בוּנָ֗ה לִ⁠מְצֹא־טֽוֹב׃","qòֽneh-lé֭̇b ʼòhé֣b napĕş֑̌⁠wò şò̌mé֥r ţĕ̇֝bẇná֗h li⁠mĕẕòʼ-tֽwòb׃"],[19,9,"עֵ֣ד שְׁ֭קָרִים לֹ֣א יִנָּקֶ֑ה וְ⁠יָפִ֖יחַ כְּזָבִ֣ים יֹאבֵֽד׃פ","ʻé֣d şĕ֭̌qáriym lò֣ʼ yiná̇qe֑h wĕ⁠yápi֖yẖa kĕ̇zábi֣ym yòʼbéֽd׃p"],[19,10,"לֹֽא־נָאוֶ֣ה לִ⁠כְסִ֣יל תַּעֲנ֑וּג אַ֝֗ף כִּֽי־לְ⁠עֶ֤בֶד ׀ מְשֹׁ֬ל בְּ⁠שָׂרִֽים׃","lòֽʼ-náʼwe֣h li⁠kĕsi֣yl ţȧʻàn֑ẇg ʼa֝֗p kiֽ̇y-lĕ⁠ʻe֤bed ׀ mĕşò̌֬l bĕ̇⁠şá̂riֽym׃"],[19,11,"שֵׂ֣כֶל אָ֭דָם הֶאֱרִ֣יךְ אַפּ֑⁠וֹ וְ֝⁠תִפאַרְתּ֗⁠וֹ עֲבֹ֣ר עַל־פָּֽשַׁע׃","şé֣̂kel ʼá֭dám heʼèri֣ykĕ ʼaṗ֑⁠wò wĕ֝⁠ţipʼarĕţ̇֗⁠wò ʻàbò֣r ʻal-páֽ̇şǎʻ׃"],[19,12,"נַ֣הַם כַּ֭⁠כְּפִיר זַ֣עַף מֶ֑לֶךְ וּ⁠כְ⁠טַ֖ל עַל־עֵ֣שֶׂב רְצוֹנֽ⁠וֹ׃","na֣ham kȧ֭⁠kĕ̇piyr za֣ʻap me֑lekĕ ẇ⁠kĕ⁠ta֖l ʻal-ʻé֣şêb rĕẕwònֽ⁠wò׃"],[19,13,"הַוֺּ֣ת לְ֭⁠אָבִי⁠ו בֵּ֣ן כְּסִ֑יל וְ⁠דֶ֥לֶף טֹ֝רֵ֗ד מִדְיְנֵ֥י אִשָּֽׁה׃","haẇֺ֣ţ lĕ֭⁠ʼábiy⁠w bé֣̇n kĕ̇si֑yl wĕ⁠de֥lep tò֝ré֗d midĕyĕné֥y ʼişáֽ̇̌h׃"],[19,14,"בַּ֣יִת וָ֭⁠הוֹן נַחֲלַ֣ת אָב֑וֹת וּ֝⁠מֵ⁠יְהוָ֗ה אִשָּׁ֥ה מַשְׂכָּֽלֶת׃","bȧ֣yiţ wá֭⁠hwòn naẖàla֣ţ ʼáb֑wòţ ẇ֝⁠mé⁠yĕhwá֗h ʼişá֥̇̌h maşĕ̂káֽ̇leţ׃"],[19,15,"עַ֭צְלָה תַּפִּ֣יל תַּרְדֵּמָ֑ה וְ⁠נֶ֖פֶשׁ רְמִיָּ֣ה תִרְעָֽב׃","ʻa֭ẕĕláh ţȧpi֣̇yl ţȧrĕdé̇má֑h wĕ⁠ne֖peş̌ rĕmiyá֣̇h ţirĕʻáֽb׃"],[19,16,"שֹׁמֵ֣ר מִ֭צְוָה שֹׁמֵ֣ר נַפְשׁ֑⁠וֹ בּוֹזֵ֖ה דְרָכָ֣י⁠ו יומת׃","şò̌mé֣r mi֭ẕĕwáh şò̌mé֣r napĕş֑̌⁠wò ḃwòzé֖h dĕráká֣y⁠w ywmţ׃"],[19,17,"מַלְוֵ֣ה יְ֭הוָה ח֣וֹנֵֽן דָּ֑ל וּ֝⁠גְמֻל֗⁠וֹ יְשַׁלֶּם־לֽ⁠וֹ׃","malĕwé֣h yĕ֭hwáh ẖ֣wònéֽn dá֑̇l ẇ֝⁠gĕmul֗⁠wò yĕşǎlėm-lֽ⁠wò׃"],[19,18,"יַסֵּ֣ר בִּ֭נְ⁠ךָ כִּי־יֵ֣שׁ תִּקְוָ֑ה וְ⁠אֶל־הֲ֝מִית֗⁠וֹ אַל־תִּשָּׂ֥א נַפְשֶֽׁ⁠ךָ׃","yasé֣̇r bi֭̇nĕ⁠ká ki̇y-yé֣ş̌ ţi̇qĕwá֑h wĕ⁠ʼel-hà֝miyţ֗⁠wò ʼal-ţi̇şá֥̇̂ʼ napĕşěֽ⁠ká׃"],[19,19,"גרל־חֵ֭מָה נֹ֣שֵׂא עֹ֑נֶשׁ כִּ֥י אִם־תַּ֝צִּ֗יל וְ⁠ע֣וֹד תּוֹסִֽף׃","grl-ẖé֭máh nò֣şé̂ʼ ʻò֑neş̌ ki֥̇y ʼim-ţȧ֝ẕi̇֗yl wĕ⁠ʻ֣wòd ţ̇wòsiֽp׃"],[19,20,"שְׁמַ֣ע עֵ֭צָה וְ⁠קַבֵּ֣ל מוּסָ֑ר לְ֝מַ֗עַן תֶּחְכַּ֥ם בְּ⁠אַחֲרִיתֶֽ⁠ךָ׃","şĕ̌ma֣ʻ ʻé֭ẕáh wĕ⁠qabé֣̇l mẇsá֑r lĕ֝ma֗ʻan ţėẖĕkȧ֥m bĕ̇⁠ʼaẖàriyţeֽ⁠ká׃"],[19,21,"רַבּ֣וֹת מַחֲשָׁב֣וֹת בְּ⁠לֶב־אִ֑ישׁ וַ⁠עֲצַ֥ת יְ֝הוָ֗ה הִ֣יא תָקֽוּם׃","raḃ֣wòţ maẖàşá̌b֣wòţ bĕ̇⁠leb-ʼi֑yş̌ wa⁠ʻàẕa֥ţ yĕ֝hwá֗h hi֣yʼ ţáqֽẇm׃"],[19,22,"תַּאֲוַ֣ת אָדָ֣ם חַסְדּ֑⁠וֹ וְ⁠טֽוֹב־רָ֝שׁ מֵ⁠אִ֥ישׁ כָּזָֽב׃","ţȧʼàwa֣ţ ʼádá֣m ẖasĕḋ֑⁠wò wĕ⁠tֽwòb-rá֝ş̌ mé⁠ʼi֥yş̌ ká̇záֽb׃"],[19,23,"יִרְאַ֣ת יְהוָ֣ה לְ⁠חַיִּ֑ים וְ⁠שָׂבֵ֥עַ יָ֝לִ֗ין בַּל־יִפָּ֥קֶד רָֽע׃","yirĕʼa֣ţ yĕhwá֣h lĕ⁠ẖayi֑̇ym wĕ⁠şá̂bé֥ʻa yá֝li֗yn bȧl-yipá֥̇qed ráֽʻ׃"],[19,24,"טָ֘מַ֤ן עָצֵ֣ל יָ֭ד⁠וֹ בַּ⁠צַּלָּ֑חַת גַּם־אֶל־פִּ֝֗י⁠הוּ לֹ֣א יְשִׁיבֶֽ⁠נָּה׃","tá֘ma֤n ʻáẕé֣l yá֭d⁠wò bȧ⁠ẕȧlá֑̇ẖaţ gȧm-ʼel-pi̇֝֗y⁠hẇ lò֣ʼ yĕşǐybeֽ⁠ná̇h׃"],[19,25,"לֵ֣ץ תַּ֭כֶּה וּ⁠פֶ֣תִי יַעְרִ֑ם וְ⁠הוֹכִ֥יחַ לְ֝⁠נָב֗וֹן יָבִ֥ין דָּֽעַת׃","lé֣ẕ ţȧ֭kėh ẇ⁠pe֣ţiy yaʻĕri֑m wĕ⁠hwòki֥yẖa lĕ֝⁠náb֗wòn yábi֥yn dáֽ̇ʻaţ׃"],[19,26,"מְֽשַׁדֶּד־אָ֭ב יַבְרִ֣יחַ אֵ֑ם בֵּ֝֗ן מֵבִ֥ישׁ וּ⁠מַחְפִּֽיר׃","mĕֽşǎdėd-ʼá֭b yabĕri֣yẖa ʼé֑m bé̇֝֗n mébi֥yş̌ ẇ⁠maẖĕpiֽ̇yr׃"],[19,27,"חַֽדַל־בְּ֭נִ⁠י לִ⁠שְׁמֹ֣עַ מוּסָ֑ר לִ֝⁠שְׁג֗וֹת מֵֽ⁠אִמְרֵי־דָֽעַת׃","ẖaֽdal-bĕ֭̇ni⁠y li⁠şĕ̌mò֣ʻa mẇsá֑r li֝⁠şĕ̌g֗wòţ méֽ⁠ʼimĕréy-dáֽʻaţ׃"],[19,28,"עֵ֣ד בְּ֭לִיַּעַל יָלִ֣יץ מִשְׁפָּ֑ט וּ⁠פִ֥י רְ֝שָׁעִ֗ים יְבַלַּע־אָֽוֶן׃","ʻé֣d bĕ֭̇liyȧʻal yáli֣yẕ mişĕ̌pá֑̇t ẇ⁠pi֥y rĕ֝şá̌ʻi֗ym yĕbalȧʻ-ʼáֽwen׃"],[19,29,"נָכ֣וֹנוּ לַ⁠לֵּצִ֣ים שְׁפָטִ֑ים וּ֝⁠מַהֲלֻמ֗וֹת לְ⁠גֵ֣ו כְּסִילִֽים׃","nák֣wònẇ la⁠lé̇ẕi֣ym şĕ̌páti֑ym ẇ֝⁠mahàlum֗wòţ lĕ⁠gé֣w kĕ̇siyliֽym׃"],[20,1,"לֵ֣ץ הַ֭⁠יַּין הֹמֶ֣ה שֵׁכָ֑ר וְ⁠כָל־שֹׁ֥גֶה בּ֝֗⁠וֹ לֹ֣א יֶחְכָּֽם׃","lé֣ẕ ha֭⁠yȧyn hòme֣h şé̌ká֑r wĕ⁠kál-şò֥̌geh ḃ֝֗⁠wò lò֣ʼ yeẖĕkáֽ̇m׃"],[20,2,"נַ֣הַם כַּ֭⁠כְּפִיר אֵ֣ימַת מֶ֑לֶךְ מִ֝תְעַבְּר֗⁠וֹ חוֹטֵ֥א נַפְשֽׁ⁠וֹ׃","na֣ham kȧ֭⁠kĕ̇piyr ʼé֣ymaţ me֑lekĕ mi֝ţĕʻabĕ̇r֗⁠wò ẖwòté֥ʼ napĕşֽ̌⁠wò׃"],[20,3,"כָּב֣וֹד לָ֭⁠אִישׁ שֶׁ֣בֶת מֵ⁠רִ֑יב וְ⁠כָל־אֱ֝וִ֗יל יִתְגַּלָּֽע׃","ká̇b֣wòd lá֭⁠ʼiyş̌ şě֣beţ mé⁠ri֑yb wĕ⁠kál-ʼè֝wi֗yl yiţĕgȧláֽ̇ʻ׃"],[20,4,"מֵ֭⁠חֹרֶף עָצֵ֣ל לֹא־יַחֲרֹ֑שׁ ישאל בַּ⁠קָּצִ֣יר וָ⁠אָֽיִן׃","mé֭⁠ẖòrep ʻáẕé֣l lòʼ-yaẖàrò֑ş̌ yşʼl bȧ⁠qá̇ẕi֣yr wá⁠ʼáֽyin׃"],[20,5,"מַ֣יִם עֲ֭מֻקִּים עֵצָ֣ה בְ⁠לֶב־אִ֑ישׁ וְ⁠אִ֖ישׁ תְּבוּנָ֣ה יִדְלֶֽ⁠נָּה׃","ma֣yim ʻà֭muqi̇ym ʻéẕá֣h bĕ⁠leb-ʼi֑yş̌ wĕ⁠ʼi֖yş̌ ţĕ̇bẇná֣h yidĕleֽ⁠ná̇h׃"],[20,6,"רָב־אָדָ֗ם יִ֭קְרָא אִ֣ישׁ חַסְדּ֑⁠וֹ וְ⁠אִ֥ישׁ אֱ֝מוּנִ֗ים מִ֣י יִמְצָֽא׃","ráb-ʼádá֗m yi֭qĕráʼ ʼi֣yş̌ ẖasĕḋ֑⁠wò wĕ⁠ʼi֥yş̌ ʼè֝mẇni֗ym mi֣y yimĕẕáֽʼ׃"],[20,7,"מִתְהַלֵּ֣ךְ בְּ⁠תֻמּ֣⁠וֹ צַדִּ֑יק אַשְׁרֵ֖י בָנָ֣י⁠ו אַחֲרָֽי⁠ו׃","miţĕhalé֣̇kĕ bĕ̇⁠ţuṁ֣⁠wò ẕadi֑̇yq ʼaşĕ̌ré֖y báná֣y⁠w ʼaẖàráֽy⁠w׃"],[20,8,"מֶ֗לֶךְ יוֹשֵׁ֥ב עַל־כִּסֵּא־דִ֑ין מְזָרֶ֖ה בְ⁠עֵינָ֣י⁠ו כָּל־רָֽע׃","me֗lekĕ ywòşé֥̌b ʻal-ki̇sé̇ʼ-di֑yn mĕzáre֖h bĕ⁠ʻéyná֣y⁠w ká̇l-ráֽʻ׃"],[20,9,"מִֽי־יֹ֭אמַר זִכִּ֣יתִי לִבִּ֑⁠י טָ֝הַ֗רְתִּי מֵ⁠חַטָּאתִֽ⁠י׃","miֽy-yò֭ʼmar ziki֣̇yţiy libi֑̇⁠y tá֝ha֗rĕţi̇y mé⁠ẖatá̇ʼţiֽ⁠y׃"],[20,10,"אֶ֣בֶן וָ֭⁠אֶבֶן אֵיפָ֣ה וְ⁠אֵיפָ֑ה תּוֹעֲבַ֥ת יְ֝הוָ֗ה גַּם־שְׁנֵי⁠הֶֽם׃","ʼe֣ben wá֭⁠ʼeben ʼéypá֣h wĕ⁠ʼéypá֑h ţ̇wòʻàba֥ţ yĕ֝hwá֗h gȧm-şĕ̌néy⁠heֽm׃"],[20,11,"גַּ֣ם בְּ֭⁠מַעֲלָלָי⁠ו יִתְנַכֶּר־נָ֑עַר אִם־זַ֖ךְ וְ⁠אִם־יָשָׁ֣ר פָּעֳלֽ⁠וֹ׃","gȧ֣m bĕ֭̇⁠maʻàláláy⁠w yiţĕnakėr-ná֑ʻar ʼim-za֖kĕ wĕ⁠ʼim-yáşá֣̌r pá̇ʻolֽ⁠wò׃"],[20,12,"אֹ֣זֶן שֹׁ֭מַעַת וְ⁠עַ֣יִן רֹאָ֑ה יְ֝הוָ֗ה עָשָׂ֥ה גַם־שְׁנֵי⁠הֶֽם׃","ʼò֣zen şò֭̌maʻaţ wĕ⁠ʻa֣yin ròʼá֑h yĕ֝hwá֗h ʻáşá֥̂h gam-şĕ̌néy⁠heֽm׃"],[20,13,"אַל־תֶּֽאֱהַ֣ב שֵׁ֭נָה פֶּן־תִּוָּרֵ֑שׁ פְּקַ֖ח עֵינֶ֣י⁠ךָ שְֽׂבַֽע־לָֽחֶם׃","ʼal-ţėֽʼèha֣b şé֭̌náh pėn-ţi̇wá̇ré֑ş̌ pĕ̇qa֖ẖ ʻéyne֣y⁠ká şĕֽ̂baֽʻ-láֽẖem׃"],[20,14,"רַ֣ע רַ֭ע יֹאמַ֣ר הַ⁠קּוֹנֶ֑ה וְ⁠אֹזֵ֥ל ל֝֗⁠וֹ אָ֣ז יִתְהַלָּֽל׃","ra֣ʻ ra֭ʻ yòʼma֣r ha⁠q̇wòne֑h wĕ⁠ʼòzé֥l l֝֗⁠wò ʼá֣z yiţĕhaláֽ̇l׃"],[20,15,"יֵ֣שׁ זָ֭הָב וְ⁠רָב־פְּנִינִ֑ים וּ⁠כְלִ֥י יְ֝קָ֗ר שִׂפְתֵי־דָֽעַת׃","yé֣ş̌ zá֭háb wĕ⁠ráb-pĕ̇niyni֑ym ẇ⁠kĕli֥y yĕ֝qá֗r şîpĕţéy-dáֽʻaţ׃"],[20,16,"לְֽקַח־בִּ֭גְד⁠וֹ כִּי־עָ֣רַב זָ֑ר וּ⁠בְעַ֖ד נכרים חַבְלֵֽ⁠הוּ׃","lĕֽqaẖ-bi֭̇gĕd⁠wò ki̇y-ʻá֣rab zá֑r ẇ⁠bĕʻa֖d nkrym ẖabĕléֽ⁠hẇ׃"],[20,17,"עָרֵ֣ב לָ֭⁠אִישׁ לֶ֣חֶם שָׁ֑קֶר וְ֝⁠אַחַ֗ר יִמָּֽלֵא־פִ֥י⁠הוּ חָצָֽץ׃","ʻáré֣b lá֭⁠ʼiyş̌ le֣ẖem şá֑̌qer wĕ֝⁠ʼaẖa֗r yimáֽ̇léʼ-pi֥y⁠hẇ ẖáẕáֽẕ׃"],[20,18,"מַ֭חֲשָׁבוֹת בְּ⁠עֵצָ֣ה תִכּ֑וֹן וּ֝⁠בְ⁠תַחְבֻּל֗וֹת עֲשֵׂ֣ה מִלְחָמָֽה׃","ma֭ẖàşá̌bwòţ bĕ̇⁠ʻéẕá֣h ţik֑̇wòn ẇ֝⁠bĕ⁠ţaẖĕbu̇l֗wòţ ʻàşé֣̂h milĕẖámáֽh׃"],[20,19,"גּֽוֹלֶה־סּ֭וֹד הוֹלֵ֣ךְ רָכִ֑יל וּ⁠לְ⁠פֹתֶ֥ה שְׂ֝פָתָ֗י⁠ו לֹ֣א תִתְעָרָֽב׃","ġֽwòleh-ṡ֭wòd hwòlé֣kĕ ráki֑yl ẇ⁠lĕ⁠pòţe֥h şĕ̂֝páţá֗y⁠w lò֣ʼ ţiţĕʻáráֽb׃"],[20,20,"מְ֭קַלֵּל אָבִ֣י⁠ו וְ⁠אִמּ֑⁠וֹ יִֽדְעַ֥ךְ נֵ֝ר֗⁠וֹ ב⁠אישון חֹֽשֶׁךְ׃","mĕ֭qalé̇l ʼábi֣y⁠w wĕ⁠ʼiṁ֑⁠wò yiֽdĕʻa֥kĕ né֝r֗⁠wò b⁠ʼyşwn ẖòֽşěkĕ׃"],[20,21,"נַ֭חֲלָה מבחלת בָּ⁠רִאשֹׁנָ֑ה וְ֝⁠אַחֲרִיתָ֗⁠הּ לֹ֣א תְבֹרָֽךְ׃","na֭ẖàláh mbẖlţ bá̇⁠riʼşò̌ná֑h wĕ֝⁠ʼaẖàriyţá֗⁠ḣ lò֣ʼ ţĕbòráֽkĕ׃"],[20,22,"אַל־תֹּאמַ֥ר אֲשַׁלְּמָה־רָ֑ע קַוֵּ֥ה לַֽ֝⁠יהוָ֗ה וְ⁠יֹ֣שַֽׁע לָֽ⁠ךְ׃","ʼal-ţò̇ʼma֥r ʼàşǎlĕ̇máh-rá֑ʻ qawé֥̇h laֽ֝⁠yhwá֗h wĕ⁠yò֣şǎֽʻ láֽ⁠kĕ׃"],[20,23,"תּוֹעֲבַ֣ת יְ֭הוָה אֶ֣בֶן וָ⁠אָ֑בֶן וּ⁠מֹאזְנֵ֖י מִרְמָ֣ה לֹא־טֽוֹב׃","ţ̇wòʻàba֣ţ yĕ֭hwáh ʼe֣ben wá⁠ʼá֑ben ẇ⁠mòʼzĕné֖y mirĕmá֣h lòʼ-tֽwòb׃"],[20,24,"מֵ⁠יהוָ֥ה מִצְעֲדֵי־גָ֑בֶר וְ֝⁠אָדָ֗ם מַה־יָּבִ֥ין דַּרְכּֽ⁠וֹ׃","mé⁠yhwá֥h miẕĕʻàdéy-gá֑ber wĕ֝⁠ʼádá֗m mah-yá̇bi֥yn dȧrĕkֽ̇⁠wò׃"],[20,25,"מוֹקֵ֣שׁ אָ֭דָם יָ֣לַע קֹ֑דֶשׁ וְ⁠אַחַ֖ר נְדָרִ֣ים לְ⁠בַקֵּֽר׃","mwòqé֣ş̌ ʼá֭dám yá֣laʻ qò֑deş̌ wĕ⁠ʼaẖa֖r nĕdári֣ym lĕ⁠baqéֽ̇r׃"],[20,26,"מְזָרֶ֣ה רְ֭שָׁעִים מֶ֣לֶךְ חָכָ֑ם וַ⁠יָּ֖שֶׁב עֲלֵי⁠הֶ֣ם אוֹפָֽן׃","mĕzáre֣h rĕ֭şá̌ʻiym me֣lekĕ ẖáká֑m wa⁠yá֖̇şěb ʻàléy⁠he֣m ʼwòpáֽn׃"],[20,27,"נֵ֣ר יְ֭הוָה נִשְׁמַ֣ת אָדָ֑ם חֹ֝פֵ֗שׂ כָּל־חַדְרֵי־בָֽטֶן׃","né֣r yĕ֭hwáh nişĕ̌ma֣ţ ʼádá֑m ẖò֝pé֗ş̂ ká̇l-ẖadĕréy-báֽten׃"],[20,28,"חֶ֣סֶד וֶ֭⁠אֱמֶת יִצְּרוּ־מֶ֑לֶךְ וְ⁠סָעַ֖ד בַּ⁠חֶ֣סֶד כִּסְאֽ⁠וֹ׃","ẖe֣sed we֭⁠ʼèmeţ yiẕĕ̇rẇ-me֑lekĕ wĕ⁠sáʻa֖d bȧ⁠ẖe֣sed ki̇sĕʼֽ⁠wò׃"],[20,29,"תִּפְאֶ֣רֶת בַּחוּרִ֣ים כֹּחָ֑⁠ם וַ⁠הֲדַ֖ר זְקֵנִ֣ים שֵׂיבָֽה׃","ţi̇pĕʼe֣reţ bȧẖẇri֣ym kò̇ẖá֑⁠m wa⁠hàda֖r zĕqéni֣ym şé̂ybáֽh׃"],[20,30,"חַבֻּר֣וֹת פֶּ֭צַע תמריק בְּ⁠רָ֑ע וּ֝⁠מַכּ֗וֹת חַדְרֵי־בָֽטֶן׃","ẖabu̇r֣wòţ pė֭ẕaʻ ţmryq bĕ̇⁠rá֑ʻ ẇ֝⁠mak̇֗wòţ ẖadĕréy-báֽten׃"],[21,1,"פַּלְגֵי־מַ֣יִם לֶב־מֶ֭לֶךְ בְּ⁠יַד־יְהוָ֑ה עַֽל־כָּל־אֲשֶׁ֖ר יַחְפֹּ֣ץ יַטֶּֽ⁠נּוּ׃","pȧlĕgéy-ma֣yim leb-me֭lekĕ bĕ̇⁠yad-yĕhwá֑h ʻaֽl-ká̇l-ʼàşě֖r yaẖĕpò֣̇ẕ yatėֽ⁠ṅẇ׃"],[21,2,"כָּֽל־דֶּרֶךְ־אִ֭ישׁ יָשָׁ֣ר בְּ⁠עֵינָ֑י⁠ו וְ⁠תֹכֵ֖ן לִבּ֣וֹת יְהוָֽה׃","káֽ̇l-dėrekĕ-ʼi֭yş̌ yáşá֣̌r bĕ̇⁠ʻéyná֑y⁠w wĕ⁠ţòké֖n liḃ֣wòţ yĕhwáֽh׃"],[21,3,"עֲ֭שֹׂה צְדָקָ֣ה וּ⁠מִשְׁפָּ֑ט נִבְחָ֖ר לַ⁠יהוָ֣ה מִ⁠זָּֽבַח׃","ʻà֭şò̂h ẕĕdáqá֣h ẇ⁠mişĕ̌pá֑̇t nibĕẖá֖r la⁠yhwá֣h mi⁠záֽ̇baẖ׃"],[21,4,"רוּם־עֵ֭ינַיִם וּ⁠רְחַב־לֵ֑ב נִ֖ר רְשָׁעִ֣ים חַטָּֽאת׃","rẇm-ʻé֭ynayim ẇ⁠rĕẖab-lé֑b ni֖r rĕşá̌ʻi֣ym ẖatáֽ̇ʼţ׃"],[21,5,"מַחְשְׁב֣וֹת חָ֭רוּץ אַךְ־לְ⁠מוֹתָ֑ר וְ⁠כָל־אָ֝֗ץ אַךְ־לְ⁠מַחְסֽוֹר׃","maẖĕşĕ̌b֣wòţ ẖá֭rẇẕ ʼakĕ-lĕ⁠mwòţá֑r wĕ⁠kál-ʼá֝֗ẕ ʼakĕ-lĕ⁠maẖĕsֽwòr׃"],[21,6,"פֹּ֣עַל א֭וֹצָרוֹת בִּ⁠לְשׁ֣וֹן שָׁ֑קֶר הֶ֥בֶל נִ֝דָּ֗ף מְבַקְשֵׁי־מָֽוֶת׃","pò֣̇ʻal ʼ֭wòẕárwòţ bi̇⁠lĕş֣̌wòn şá֑̌qer he֥bel ni֝dá̇֗p mĕbaqĕşé̌y-máֽweţ׃"],[21,7,"שֹׁד־רְשָׁעִ֥ים יְגוֹרֵ֑⁠ם כִּ֥י מֵ֝אֲנ֗וּ לַ⁠עֲשׂ֥וֹת מִשְׁפָּֽט׃","şò̌d-rĕşá̌ʻi֥ym yĕgwòré֑⁠m ki֥̇y mé֝ʼàn֗ẇ la⁠ʻàş֥̂wòţ mişĕ̌páֽ̇t׃"],[21,8,"הֲפַכְפַּ֬ךְ דֶּ֣רֶךְ אִ֣ישׁ וָזָ֑ר וְ֝⁠זַ֗ךְ יָשָׁ֥ר פָּעֳלֽ⁠וֹ׃","hàpakĕpȧ֬kĕ dė֣rekĕ ʼi֣yş̌ wázá֑r wĕ֝⁠za֗kĕ yáşá֥̌r pá̇ʻolֽ⁠wò׃"],[21,9,"ט֗וֹב לָ⁠שֶׁ֥בֶת עַל־פִּנַּת־גָּ֑ג מֵ⁠אֵ֥שֶׁת מִ֝דְיָנִ֗ים וּ⁠בֵ֥ית חָֽבֶר׃","t֗wòb lá⁠şě֥beţ ʻal-pi̇nȧţ-gá֑̇g mé⁠ʼé֥şěţ mi֝dĕyáni֗ym ẇ⁠bé֥yţ ẖáֽber׃"],[21,10,"נֶ֣פֶשׁ רָ֭שָׁע אִוְּתָה־רָ֑ע לֹא־יֻחַ֖ן בְּ⁠עֵינָ֣י⁠ו רֵעֵֽ⁠הוּ׃","ne֣peş̌ rá֭şá̌ʻ ʼiwĕ̇ţáh-rá֑ʻ lòʼ-yuẖa֖n bĕ̇⁠ʻéyná֣y⁠w réʻéֽ⁠hẇ׃"],[21,11,"בַּ⁠עְנָשׁ־לֵ֭ץ יֶחְכַּם־פֶּ֑תִי וּ⁠בְ⁠הַשְׂכִּ֥יל לְ֝⁠חָכָ֗ם יִקַּח־דָּֽעַת׃","bȧ⁠ʻĕnáş̌-lé֭ẕ yeẖĕkȧm-pė֑ţiy ẇ⁠bĕ⁠haşĕ̂ki֥̇yl lĕ֝⁠ẖáká֗m yiqȧẖ-dáֽ̇ʻaţ׃"],[21,12,"מַשְׂכִּ֣יל צַ֭דִּיק לְ⁠בֵ֣ית רָשָׁ֑ע מְסַלֵּ֖ף רְשָׁעִ֣ים לָ⁠רָֽע׃","maşĕ̂ki֣̇yl ẕa֭di̇yq lĕ⁠bé֣yţ ráşá֑̌ʻ mĕsalé֖̇p rĕşá̌ʻi֣ym lá⁠ráֽʻ׃"],[21,13,"אֹטֵ֣ם אָ֭זְנ⁠וֹ מִ⁠זַּעֲקַת־דָּ֑ל גַּֽם־ה֥וּא יִ֝קְרָ֗א וְ⁠לֹ֣א יֵעָנֶֽה׃","ʼòté֣m ʼá֭zĕn⁠wò mi⁠zȧʻàqaţ-dá֑̇l gȧֽm-h֥ẇʼ yi֝qĕrá֗ʼ wĕ⁠lò֣ʼ yéʻáneֽh׃"],[21,14,"מַתָּ֣ן בַּ֭⁠סֵּתֶר יִכְפֶּה־אָ֑ף וְ⁠שֹׁ֥חַד בַּ֝⁠חֵ֗ק חֵמָ֥ה עַזָּֽה׃","maţá֣̇n bȧ֭⁠sé̇ţer yikĕpėh-ʼá֑p wĕ⁠şò֥̌ẖad bȧ֝⁠ẖé֗q ẖémá֥h ʻazáֽ̇h׃"],[21,15,"שִׂמְחָ֣ה לַ֭⁠צַּדִּיק עֲשׂ֣וֹת מִשְׁפָּ֑ט וּ֝⁠מְחִתָּ֗ה לְ⁠פֹ֣עֲלֵי אָֽוֶן׃","şîmĕẖá֣h la֭⁠ẕȧdi̇yq ʻàş֣̂wòţ mişĕ̌pá֑̇t ẇ֝⁠mĕẖiţá̇֗h lĕ⁠pò֣ʻàléy ʼáֽwen׃"],[21,16,"אָדָ֗ם תּ֭וֹעֶה מִ⁠דֶּ֣רֶךְ הַשְׂכֵּ֑ל בִּ⁠קְהַ֖ל רְפָאִ֣ים יָנֽוּחַ׃","ʼádá֗m ţ֭̇wòʻeh mi⁠dė֣rekĕ haşĕ̂ké֑̇l bi̇⁠qĕha֖l rĕpáʼi֣ym yánֽẇẖa׃"],[21,17,"אִ֣ישׁ מַ֭חְסוֹר אֹהֵ֣ב שִׂמְחָ֑ה אֹהֵ֥ב יַֽיִן־וָ֝⁠שֶׁ֗מֶן לֹ֣א יַעֲשִֽׁיר׃","ʼi֣yş̌ ma֭ẖĕswòr ʼòhé֣b şîmĕẖá֑h ʼòhé֥b yaֽyin-wá֝⁠şě֗men lò֣ʼ yaʻàşǐֽyr׃"],[21,18,"כֹּ֣פֶר לַ⁠צַּדִּ֣יק רָשָׁ֑ע וְ⁠תַ֖חַת יְשָׁרִ֣ים בּוֹגֵֽד׃","kò֣̇per la⁠ẕȧdi֣̇yq ráşá֑̌ʻ wĕ⁠ţa֖ẖaţ yĕşá̌ri֣ym ḃwògéֽd׃"],[21,19,"ט֗וֹב שֶׁ֥בֶת בְּ⁠אֶֽרֶץ־מִדְבָּ֑ר מֵ⁠אֵ֖שֶׁת מדונים וָ⁠כָֽעַס׃","t֗wòb şě֥beţ bĕ̇⁠ʼeֽreẕ-midĕbá֑̇r mé⁠ʼé֖şěţ mdwnym wá⁠káֽʻas׃"],[21,20,"אוֹצָ֤ר ׀ נֶחְמָ֣ד וָ֭⁠שֶׁמֶן בִּ⁠נְוֵ֣ה חָכָ֑ם וּ⁠כְסִ֖יל אָדָ֣ם יְבַלְּעֶֽ⁠נּוּ׃","ʼwòẕá֤r ׀ neẖĕmá֣d wá֭⁠şěmen bi̇⁠nĕwé֣h ẖáká֑m ẇ⁠kĕsi֖yl ʼádá֣m yĕbalĕ̇ʻeֽ⁠ṅẇ׃"],[21,21,"רֹ֭דֵף צְדָקָ֣ה וָ⁠חָ֑סֶד יִמְצָ֥א חַ֝יִּ֗ים צְדָקָ֥ה וְ⁠כָבֽוֹד׃","rò֭dép ẕĕdáqá֣h wá⁠ẖá֑sed yimĕẕá֥ʼ ẖa֝yi̇֗ym ẕĕdáqá֥h wĕ⁠kábֽwòd׃"],[21,22,"עִ֣יר גִּ֭בֹּרִים עָלָ֣ה חָכָ֑ם וַ֝⁠יֹּ֗רֶד עֹ֣ז מִבְטֶחָֽ⁠ה׃","ʻi֣yr gi֭̇bò̇riym ʻálá֣h ẖáká֑m wa֝⁠yò̇֗red ʻò֣z mibĕteẖáֽ⁠h׃"],[21,23,"שֹׁמֵ֣ר פִּ֭י⁠ו וּ⁠לְשׁוֹנ֑⁠וֹ שֹׁמֵ֖ר מִ⁠צָּר֣וֹת נַפְשֽׁ⁠וֹ׃","şò̌mé֣r pi֭̇y⁠w ẇ⁠lĕş̌wòn֑⁠wò şò̌mé֖r mi⁠ẕá̇r֣wòţ napĕşֽ̌⁠wò׃"],[21,24,"זֵ֣ד יָ֭הִיר לֵ֣ץ שְׁמ֑⁠וֹ ע֝וֹשֶׂ֗ה בְּ⁠עֶבְרַ֥ת זָדֽוֹן׃","zé֣d yá֭hiyr lé֣ẕ şĕ̌m֑⁠wò ʻ֝wòşê֗h bĕ̇⁠ʻebĕra֥ţ zádֽwòn׃"],[21,25,"תַּאֲוַ֣ת עָצֵ֣ל תְּמִיתֶ֑⁠נּוּ כִּֽי־מֵאֲנ֖וּ יָדָ֣י⁠ו לַ⁠עֲשֽׂוֹת׃","ţȧʼàwa֣ţ ʻáẕé֣l ţĕ̇miyţe֑⁠ṅẇ kiֽ̇y-méʼàn֖ẇ yádá֣y⁠w la⁠ʻàşֽ̂wòţ׃"],[21,26,"כָּל־הַ֭⁠יּוֹם הִתְאַוָּ֣ה תַאֲוָ֑ה וְ⁠צַדִּ֥יק יִ֝תֵּ֗ן וְ⁠לֹ֣א יַחְשֹֽׂךְ׃","ká̇l-ha֭⁠ẏwòm hiţĕʼawá֣̇h ţaʼàwá֑h wĕ⁠ẕadi֥̇yq yi֝ţé̇֗n wĕ⁠lò֣ʼ yaẖĕşòֽ̂kĕ׃"],[21,27,"זֶ֣בַח רְ֭שָׁעִים תּוֹעֵבָ֑ה אַ֝֗ף כִּֽי־בְ⁠זִמָּ֥ה יְבִיאֶֽ⁠נּוּ׃","ze֣baẖ rĕ֭şá̌ʻiym ţ̇wòʻébá֑h ʼa֝֗p kiֽ̇y-bĕ⁠zimá֥̇h yĕbiyʼeֽ⁠ṅẇ׃"],[21,28,"עֵד־כְּזָבִ֥ים יֹאבֵ֑ד וְ⁠אִ֥ישׁ שׁ֝וֹמֵ֗עַ לָ⁠נֶ֥צַח יְדַבֵּֽר׃","ʻéd-kĕ̇zábi֥ym yòʼbé֑d wĕ⁠ʼi֥yş̌ ş̌֝wòmé֗ʻa lá⁠ne֥ẕaẖ yĕdabéֽ̇r׃"],[21,29,"הֵעֵ֬ז אִ֣ישׁ רָשָׁ֣ע בְּ⁠פָנָ֑י⁠ו וְ֝⁠יָשָׁ֗ר ה֤וּא ׀ יכין דרכי⁠ו׃","héʻé֬z ʼi֣yş̌ ráşá֣̌ʻ bĕ̇⁠páná֑y⁠w wĕ֝⁠yáşá̌֗r h֤ẇʼ ׀ ykyn drky⁠w׃"],[21,30,"אֵ֣ין חָ֭כְמָה וְ⁠אֵ֣ין תְּבוּנָ֑ה וְ⁠אֵ֥ין עֵ֝צָ֗ה לְ⁠נֶ֣גֶד יְהוָֽה׃פ","ʼé֣yn ẖá֭kĕmáh wĕ⁠ʼé֣yn ţĕ̇bẇná֑h wĕ⁠ʼé֥yn ʻé֝ẕá֗h lĕ⁠ne֣ged yĕhwáֽh׃p"],[21,31,"ס֗וּס מ֭וּכָן לְ⁠י֣וֹם מִלְחָמָ֑ה וְ֝⁠לַֽ⁠יהוָ֗ה הַ⁠תְּשׁוּעָֽה׃","s֗ẇs m֭ẇkán lĕ⁠y֣wòm milĕẖámá֑h wĕ֝⁠laֽ⁠yhwá֗h ha⁠ţĕ̇ş̌ẇʻáֽh׃"],[22,1,"נִבְחָ֣ר שֵׁ֭ם מֵ⁠עֹ֣שֶׁר רָ֑ב מִ⁠כֶּ֥סֶף וּ֝⁠מִ⁠זָּהָ֗ב חֵ֣ן טֽוֹב׃","nibĕẖá֣r şé֭̌m mé⁠ʻò֣şěr rá֑b mi⁠kė֥sep ẇ֝⁠mi⁠zá̇há֗b ẖé֣n tֽwòb׃"],[22,2,"עָשִׁ֣יר וָ⁠רָ֣שׁ נִפְגָּ֑שׁוּ עֹשֵׂ֖ה כֻלָּ֣⁠ם יְהוָֽה׃","ʻáşǐ֣yr wá⁠rá֣ş̌ nipĕgá֑̇ş̌ẇ ʻòşé֖̂h kulá֣̇⁠m yĕhwáֽh׃"],[22,3,"עָר֤וּם ׀ רָאָ֣ה רָעָ֣ה ו⁠יסתר וּ֝⁠פְתָיִ֗ים עָבְר֥וּ וְֽ⁠נֶעֱנָֽשׁוּ׃","ʻár֤ẇm ׀ ráʼá֣h ráʻá֣h w⁠ysţr ẇ֝⁠pĕţáyi֗ym ʻábĕr֥ẇ wĕֽ⁠neʻènáֽş̌ẇ׃"],[22,4,"עֵ֣קֶב עֲ֭נָוָה יִרְאַ֣ת יְהוָ֑ה עֹ֖שֶׁר וְ⁠כָב֣וֹד וְ⁠חַיִּֽים׃","ʻé֣qeb ʻà֭náwáh yirĕʼa֣ţ yĕhwá֑h ʻò֖şěr wĕ⁠káb֣wòd wĕ⁠ẖayiֽ̇ym׃"],[22,5,"צִנִּ֣ים פַּ֭חִים בְּ⁠דֶ֣רֶךְ עִקֵּ֑שׁ שׁוֹמֵ֥ר נַ֝פְשׁ֗⁠וֹ יִרְחַ֥ק מֵ⁠הֶֽם׃","ẕini֣̇ym pȧ֭ẖiym bĕ̇⁠de֣rekĕ ʻiqé֑̇ş̌ ş̌wòmé֥r na֝pĕş̌֗⁠wò yirĕẖa֥q mé⁠heֽm׃"],[22,6,"חֲנֹ֣ךְ לַ֭⁠נַּעַר עַל־פִּ֣י דַרְכּ֑⁠וֹ גַּ֥ם כִּֽי־יַ֝זְקִ֗ין לֹֽא־יָס֥וּר מִמֶּֽ⁠נָּה׃","ẖànò֣kĕ la֭⁠nȧʻar ʻal-pi֣̇y darĕk֑̇⁠wò gȧ֥m kiֽ̇y-ya֝zĕqi֗yn lòֽʼ-yás֥ẇr mimėֽ⁠ná̇h׃"],[22,7,"עָ֭שִׁיר בְּ⁠רָשִׁ֣ים יִמְשׁ֑וֹל וְ⁠עֶ֥בֶד לֹ֝וֶ֗ה לְ⁠אִ֣ישׁ מַלְוֶֽה׃","ʻá֭şǐyr bĕ̇⁠ráşǐ֣ym yimĕş֑̌wòl wĕ⁠ʻe֥bed lò֝we֗h lĕ⁠ʼi֣yş̌ malĕweֽh׃"],[22,8,"זוֹרֵ֣עַ עַ֭וְלָה יקצור־אָ֑וֶן וְ⁠שֵׁ֖בֶט עֶבְרָת֣⁠וֹ יִכְלֶֽה׃","zwòré֣ʻa ʻa֭wĕláh yqẕwr-ʼá֑wen wĕ⁠şé֖̌bet ʻebĕráţ֣⁠wò yikĕleֽh׃"],[22,9,"טֽוֹב־עַ֭יִן ה֣וּא יְבֹרָ֑ךְ כִּֽי־נָתַ֖ן מִ⁠לַּחְמ֣⁠וֹ לַ⁠דָּֽל׃","tֽwòb-ʻa֭yin h֣ẇʼ yĕbòrá֑kĕ kiֽ̇y-náţa֖n mi⁠lȧẖĕm֣⁠wò la⁠dáֽ̇l׃"],[22,10,"גָּ֣רֵֽשׁ לֵ֭ץ וְ⁠יֵצֵ֣א מָד֑וֹן וְ֝⁠יִשְׁבֹּ֗ת דִּ֣ין וְ⁠קָלֽוֹן׃","gá֣̇réֽş̌ lé֭ẕ wĕ⁠yéẕé֣ʼ mád֑wòn wĕ֝⁠yişĕ̌bò̇֗ţ di֣̇yn wĕ⁠qálֽwòn׃"],[22,11,"אֹהֵ֥ב טהור־לֵ֑ב חֵ֥ן שְׂ֝פָתָ֗י⁠ו רֵעֵ֥⁠הוּ מֶֽלֶךְ׃","ʼòhé֥b thwr-lé֑b ẖé֥n şĕ̂֝páţá֗y⁠w réʻé֥⁠hẇ meֽlekĕ׃"],[22,12,"עֵינֵ֣י יְ֭הוָה נָ֣צְרוּ דָ֑עַת וַ֝⁠יְסַלֵּ֗ף דִּבְרֵ֥י בֹגֵֽד׃","ʻéyné֣y yĕ֭hwáh ná֣ẕĕrẇ dá֑ʻaţ wa֝⁠yĕsalé̇֗p di̇bĕré֥y bògéֽd׃"],[22,13,"אָמַ֣ר עָ֭צֵל אֲרִ֣י בַ⁠ח֑וּץ בְּ⁠ת֥וֹךְ רְ֝חֹב֗וֹת אֵֽרָצֵֽחַ׃","ʼáma֣r ʻá֭ẕél ʼàri֣y ba⁠ẖ֑ẇẕ bĕ̇⁠ţ֥wòkĕ rĕ֝ẖòb֗wòţ ʼéֽráẕéֽẖa׃"],[22,14,"שׁוּחָ֣ה עֲ֭מֻקָּה פִּ֣י זָר֑וֹת זְע֥וּם יְ֝הוָ֗ה יפול־שָֽׁם׃","ş̌ẇẖá֣h ʻà֭muqá̇h pi֣̇y zár֑wòţ zĕʻ֥ẇm yĕ֝hwá֗h ypwl-şáֽ̌m׃"],[22,15,"אִ֭וֶּלֶת קְשׁוּרָ֣ה בְ⁠לֶב־נָ֑עַר שֵׁ֥בֶט מ֝וּסָ֗ר יַרְחִיקֶ֥⁠נָּה מִמֶּֽ⁠נּוּ׃","ʼi֭wėleţ qĕş̌ẇrá֣h bĕ⁠leb-ná֑ʻar şé֥̌bet m֝ẇsá֗r yarĕẖiyqe֥⁠ná̇h mimėֽ⁠ṅẇ׃"],[22,16,"עֹ֣שֵֽׁק דָּ֭ל לְ⁠הַרְבּ֣וֹת ל֑⁠וֹ נֹתֵ֥ן לְ֝⁠עָשִׁ֗יר אַךְ־לְ⁠מַחְסֽוֹר׃","ʻò֣şéֽ̌q dá֭̇l lĕ⁠harĕḃ֣wòţ l֑⁠wò nòţé֥n lĕ֝⁠ʻáşǐ֗yr ʼakĕ-lĕ⁠maẖĕsֽwòr׃"],[22,17,"הַ֥ט אָזְנְ⁠ךָ֗ וּ֭⁠שְׁמַע דִּבְרֵ֣י חֲכָמִ֑ים וְ֝⁠לִבְּ⁠ךָ֗ תָּשִׁ֥ית לְ⁠דַעְתִּֽ⁠י׃","ha֥t ʼázĕnĕ⁠ká֗ ẇ֭⁠şĕ̌maʻ di̇bĕré֣y ẖàkámi֑ym wĕ֝⁠libĕ̇⁠ká֗ ţá̇şǐ֥yţ lĕ⁠daʻĕţiֽ̇⁠y׃"],[22,18,"כִּֽי־נָ֭עִים כִּֽי־תִשְׁמְרֵ֣⁠ם בְּ⁠בִטְנֶ֑⁠ךָ יִכֹּ֥נוּ יַ֝חְדָּ֗ו עַל־שְׂפָתֶֽי⁠ךָ׃","kiֽ̇y-ná֭ʻiym kiֽ̇y-ţişĕ̌mĕré֣⁠m bĕ̇⁠bitĕne֑⁠ká yikò֥̇nẇ ya֝ẖĕdá̇֗w ʻal-şĕ̂páţeֽy⁠ká׃"],[22,19,"לִ⁠הְי֣וֹת בַּ֭⁠יהוָה מִבְטַחֶ֑⁠ךָ הוֹדַעְתִּ֖י⁠ךָ הַ⁠יּ֣וֹם אַף־אָֽתָּה׃","li⁠hĕy֣wòţ bȧ֭⁠yhwáh mibĕtaẖe֑⁠ká hwòdaʻĕţi֖̇y⁠ká ha⁠ẏ֣wòm ʼap-ʼáֽţá̇h׃"],[22,20,"הֲ⁠לֹ֤א כָתַ֣בְתִּי לְ֭⁠ךָ שלשום בְּ⁠מ֖וֹעֵצֹ֣ת וָ⁠דָֽעַת׃","hà⁠lò֤ʼ káţa֣bĕţi̇y lĕ֭⁠ká şlşwm bĕ̇⁠m֖wòʻéẕò֣ţ wá⁠dáֽʻaţ׃"],[22,21,"לְ⁠הוֹדִֽיעֲ⁠ךָ֗ קֹ֭שְׁטְ אִמְרֵ֣י אֱמֶ֑ת לְ⁠הָשִׁ֥יב אֲמָרִ֥ים אֱ֝מֶ֗ת לְ⁠שֹׁלְחֶֽי⁠ךָ׃פ","lĕ⁠hwòdiֽyʻà⁠ká֗ qò֭şĕ̌tĕ ʼimĕré֣y ʼème֑ţ lĕ⁠háşǐ֥yb ʼàmári֥ym ʼè֝me֗ţ lĕ⁠şò̌lĕẖeֽy⁠ká׃p"],[22,22,"אַֽל־תִּגְזָל־דָּ֭ל כִּ֣י דַל־ה֑וּא וְ⁠אַל־תְּדַכֵּ֖א עָנִ֣י בַ⁠שָּֽׁעַר׃","ʼaֽl-ţi̇gĕzál-dá֭̇l ki֣̇y dal-h֑ẇʼ wĕ⁠ʼal-ţĕ̇daké֖̇ʼ ʻáni֣y ba⁠şáֽ̇̌ʻar׃"],[22,23,"כִּֽי־יְ֭הוָה יָרִ֣יב רִיבָ֑⁠ם וְ⁠קָבַ֖ע אֶת־קֹבְעֵי⁠הֶ֣ם נָֽפֶשׁ׃","kiֽ̇y-yĕ֭hwáh yári֣yb riybá֑⁠m wĕ⁠qába֖ʻ ʼeţ-qòbĕʻéy⁠he֣m náֽpeş̌׃"],[22,24,"אַל־תִּ֭תְרַע אֶת־בַּ֣עַל אָ֑ף וְ⁠אֶת־אִ֥ישׁ חֵ֝מוֹת לֹ֣א תָבֽוֹא׃","ʼal-ţi֭̇ţĕraʻ ʼeţ-bȧ֣ʻal ʼá֑p wĕ⁠ʼeţ-ʼi֥yş̌ ẖé֝mwòţ lò֣ʼ ţábֽwòʼ׃"],[22,25,"פֶּן־תֶּאֱלַ֥ף ארחת⁠ו וְ⁠לָקַחְתָּ֖ מוֹקֵ֣שׁ לְ⁠נַפְשֶֽׁ⁠ךָ׃","pėn-ţėʼèla֥p ʼrẖţ⁠w wĕ⁠láqaẖĕţá֖̇ mwòqé֣ş̌ lĕ⁠napĕşěֽ⁠ká׃"],[22,26,"אַל־תְּהִ֥י בְ⁠תֹֽקְעֵי־כָ֑ף בַּ֝⁠עֹרְבִ֗ים מַשָּׁאֽוֹת׃","ʼal-ţĕ̇hi֥y bĕ⁠ţòֽqĕʻéy-ká֑p bȧ֝⁠ʻòrĕbi֗ym maşá̇̌ʼֽwòţ׃"],[22,27,"אִם־אֵֽין־לְ⁠ךָ֥ לְ⁠שַׁלֵּ֑ם לָ֥⁠מָּה יִקַּ֥ח מִ֝שְׁכָּבְ⁠ךָ֗ מִ⁠תַּחְתֶּֽי⁠ךָ׃","ʼim-ʼéֽyn-lĕ⁠ká֥ lĕ⁠şǎlé֑̇m lá֥⁠má̇h yiqȧ֥ẖ mi֝şĕ̌ká̇bĕ⁠ká֗ mi⁠ţȧẖĕţėֽy⁠ká׃"],[22,28,"אַל־תַּ֭סֵּג גְּב֣וּל עוֹלָ֑ם אֲשֶׁ֖ר עָשׂ֣וּ אֲבוֹתֶֽי⁠ךָ׃","ʼal-ţȧ֭sé̇g gĕ̇b֣ẇl ʻwòlá֑m ʼàşě֖r ʻáş֣̂ẇ ʼàbwòţeֽy⁠ká׃"],[22,29,"חָזִ֡יתָ אִ֤ישׁ ׀ מָ֘הִ֤יר בִּ⁠מְלַאכְתּ֗⁠וֹ לִֽ⁠פְנֵֽי־מְלָכִ֥ים יִתְיַצָּ֑ב בַּל־יִ֝תְיַצֵּב לִ⁠פְנֵ֥י חֲשֻׁכִּֽים׃פ","ẖázi֡yţá ʼi֤yş̌ ׀ má֘hi֤yr bi̇⁠mĕlaʼkĕţ̇֗⁠wò liֽ⁠pĕnéֽy-mĕláki֥ym yiţĕyaẕá֑̇b bȧl-yi֝ţĕyaẕé̇b li⁠pĕné֥y ẖàşǔkiֽ̇ym׃p"],[23,1,"כִּֽי־תֵ֭שֵׁב לִ⁠לְח֣וֹם אֶת־מוֹשֵׁ֑ל בִּ֥ין תָּ֝בִ֗ין אֶת־אֲשֶׁ֥ר לְ⁠פָנֶֽי⁠ךָ׃","kiֽ̇y-ţé֭şé̌b li⁠lĕẖ֣wòm ʼeţ-mwòşé֑̌l bi֥̇yn ţá̇֝bi֗yn ʼeţ-ʼàşě֥r lĕ⁠páneֽy⁠ká׃"],[23,2,"וְ⁠שַׂמְתָּ֣ שַׂכִּ֣ין בְּ⁠לֹעֶ֑⁠ךָ אִם־בַּ֖עַל נֶ֣פֶשׁ אָֽתָּה׃","wĕ⁠şâmĕţá֣̇ şâki֣̇yn bĕ̇⁠lòʻe֑⁠ká ʼim-bȧ֖ʻal ne֣peş̌ ʼáֽţá̇h׃"],[23,3,"אַל־תתאו לְ⁠מַטְעַמּוֹתָ֑י⁠ו וְ֝⁠ה֗וּא לֶ֣חֶם כְּזָבִֽים׃","ʼal-ţţʼw lĕ⁠matĕʻaṁwòţá֑y⁠w wĕ֝⁠h֗ẇʼ le֣ẖem kĕ̇zábiֽym׃"],[23,4,"אַל־תִּיגַ֥ע לְֽ⁠הַעֲשִׁ֑יר מִֽ⁠בִּינָתְ⁠ךָ֥ חֲדָֽל׃","ʼal-ţi̇yga֥ʻ lĕֽ⁠haʻàşǐ֑yr miֽ⁠bi̇ynáţĕ⁠ká֥ ẖàdáֽl׃"],[23,5,"ה⁠תעוף עֵינֶ֥י⁠ךָ בּ֗⁠וֹ וְֽ⁠אֵ֫ינֶ֥⁠נּוּ כִּ֤י עָשֹׂ֣ה יַעֲשֶׂה־לּ֣⁠וֹ כְנָפַ֑יִם כְּ֝⁠נֶ֗שֶׁר ו⁠עיף הַ⁠שָּׁמָֽיִם׃פ","h⁠ţʻwp ʻéyne֥y⁠ká ḃ֗⁠wò wĕֽ⁠ʼé֫yne֥⁠ṅẇ ki֤̇y ʻáşò֣̂h yaʻàşêh-l֣̇⁠wò kĕnápa֑yim kĕ̇֝⁠ne֗şěr w⁠ʻyp ha⁠şá̇̌máֽyim׃p"],[23,6,"אַל־תִּלְחַ֗ם אֶת־לֶ֭חֶם רַ֣ע עָ֑יִן וְ⁠אַל־תתאו לְ⁠מַטְעַמֹּתָֽי⁠ו׃","ʼal-ţi̇lĕẖa֗m ʼeţ-le֭ẖem ra֣ʻ ʻá֑yin wĕ⁠ʼal-ţţʼw lĕ⁠matĕʻamò̇ţáֽy⁠w׃"],[23,7,"כִּ֤י ׀ כְּמוֹ־שָׁעַ֥ר בְּ⁠נַפְשׁ֗⁠וֹ כֶּ֫ן־ה֥וּא אֱכֹ֣ל וּ֭⁠שְׁתֵה יֹ֣אמַר לָ֑⁠ךְ וְ֝⁠לִבּ֗⁠וֹ בַּל־עִמָּֽ⁠ךְ׃","ki֤̇y ׀ kĕ̇mwò-şá̌ʻa֥r bĕ̇⁠napĕş̌֗⁠wò kė֫n-h֥ẇʼ ʼèkò֣l ẇ֭⁠şĕ̌ţéh yò֣ʼmar lá֑⁠kĕ wĕ֝⁠liḃ֗⁠wò bȧl-ʻimáֽ̇⁠kĕ׃"],[23,8,"פִּֽתְּ⁠ךָ־אָכַ֥לְתָּ תְקִיאֶ֑⁠נָּה וְ֝⁠שִׁחַ֗תָּ דְּבָרֶ֥י⁠ךָ הַ⁠נְּעִימִֽים׃","piֽ̇ţĕ̇⁠ká-ʼáka֥lĕţá̇ ţĕqiyʼe֑⁠ná̇h wĕ֝⁠şǐẖa֗ţá̇ dĕ̇báre֥y⁠ká ha⁠nĕ̇ʻiymiֽym׃"],[23,9,"בְּ⁠אָזְנֵ֣י כְ֭סִיל אַל־תְּדַבֵּ֑ר כִּֽי־יָ֝ב֗וּז לְ⁠שֵׂ֣כֶל מִלֶּֽי⁠ךָ׃","bĕ̇⁠ʼázĕné֣y kĕ֭siyl ʼal-ţĕ̇dabé֑̇r kiֽ̇y-yá֝b֗ẇz lĕ⁠şé֣̂kel milėֽy⁠ká׃"],[23,10,"אַל־תַּ֭סֵּג גְּב֣וּל עוֹלָ֑ם וּ⁠בִ⁠שְׂדֵ֥י יְ֝תוֹמִ֗ים אַל־תָּבֹֽא׃","ʼal-ţȧ֭sé̇g gĕ̇b֣ẇl ʻwòlá֑m ẇ⁠bi⁠şĕ̂dé֥y yĕ֝ţwòmi֗ym ʼal-ţá̇bòֽʼ׃"],[23,11,"כִּֽי־גֹאֲלָ֥⁠ם חָזָ֑ק הֽוּא־יָרִ֖יב אֶת־רִיבָ֣⁠ם אִתָּֽ⁠ךְ׃","kiֽ̇y-gòʼàlá֥⁠m ẖázá֑q hֽẇʼ-yári֖yb ʼeţ-riybá֣⁠m ʼiţáֽ̇⁠kĕ׃"],[23,12,"הָבִ֣יאָ⁠ה לַ⁠מּוּסָ֣ר לִבֶּ֑⁠ךָ וְ֝⁠אָזְנֶ֗⁠ךָ לְ⁠אִמְרֵי־דָֽעַת׃","hábi֣yʼá⁠h la⁠ṁẇsá֣r libė֑⁠ká wĕ֝⁠ʼázĕne֗⁠ká lĕ⁠ʼimĕréy-dáֽʻaţ׃"],[23,13,"אַל־תִּמְנַ֣ע מִ⁠נַּ֣עַר מוּסָ֑ר כִּֽי־תַכֶּ֥⁠נּוּ בַ֝⁠שֵּׁ֗בֶט לֹ֣א יָמֽוּת׃","ʼal-ţi̇mĕna֣ʻ mi⁠nȧ֣ʻar mẇsá֑r kiֽ̇y-ţakė֥⁠ṅẇ ba֝⁠şé̇̌֗bet lò֣ʼ yámֽẇţ׃"],[23,14,"אַ֭תָּה בַּ⁠שֵּׁ֣בֶט תַּכֶּ֑⁠נּוּ וְ֝⁠נַפְשׁ֗⁠וֹ מִ⁠שְּׁא֥וֹל תַּצִּֽיל׃","ʼa֭ţá̇h bȧ⁠şé֣̇̌bet ţȧkė֑⁠ṅẇ wĕ֝⁠napĕş̌֗⁠wò mi⁠şĕ̇̌ʼ֥wòl ţȧẕiֽ̇yl׃"],[23,15,"בְּ֭נִ⁠י אִם־חָכַ֣ם לִבֶּ֑⁠ךָ יִשְׂמַ֖ח לִבִּ֣⁠י גַם־אָֽנִי׃","bĕ֭̇ni⁠y ʼim-ẖáka֣m libė֑⁠ká yişĕ̂ma֖ẖ libi֣̇⁠y gam-ʼáֽniy׃"],[23,16,"וְ⁠תַעְלֹ֥זְנָה כִלְיוֹתָ֑⁠י בְּ⁠דַבֵּ֥ר שְׂ֝פָתֶ֗י⁠ךָ מֵישָׁרִֽים׃","wĕ⁠ţaʻĕlò֥zĕnáh kilĕywòţá֑⁠y bĕ̇⁠dabé֥̇r şĕ̂֝páţe֗y⁠ká méyşá̌riֽym׃"],[23,17,"אַל־יְקַנֵּ֣א לִ֭בְּ⁠ךָ בַּֽ⁠חַטָּאִ֑ים כִּ֥י אִם־בְּ⁠יִרְאַת־יְ֝הוָ֗ה כָּל־הַ⁠יּֽוֹם׃","ʼal-yĕqané֣̇ʼ li֭bĕ̇⁠ká bȧֽ⁠ẖatá̇ʼi֑ym ki֥̇y ʼim-bĕ̇⁠yirĕʼaţ-yĕ֝hwá֗h ká̇l-ha⁠ẏֽwòm׃"],[23,18,"כִּ֭י אִם־יֵ֣שׁ אַחֲרִ֑ית וְ֝⁠תִקְוָתְ⁠ךָ֗ לֹ֣א תִכָּרֵֽת׃","ki֭̇y ʼim-yé֣ş̌ ʼaẖàri֑yţ wĕ֝⁠ţiqĕwáţĕ⁠ká֗ lò֣ʼ ţiká̇réֽţ׃"],[23,19,"שְׁמַע־אַתָּ֣ה בְנִ֣⁠י וַ⁠חֲכָ֑ם וְ⁠אַשֵּׁ֖ר בַּ⁠דֶּ֣רֶךְ לִבֶּֽ⁠ךָ׃","şĕ̌maʻ-ʼaţá֣̇h bĕni֣⁠y wa⁠ẖàká֑m wĕ⁠ʼaşé֖̇̌r bȧ⁠dė֣rekĕ libėֽ⁠ká׃"],[23,20,"אַל־תְּהִ֥י בְ⁠סֹֽבְאֵי־יָ֑יִן בְּ⁠זֹלֲלֵ֖י בָשָׂ֣ר לָֽ⁠מוֹ׃","ʼal-ţĕ̇hi֥y bĕ⁠sòֽbĕʼéy-yá֑yin bĕ̇⁠zòlàlé֖y báşá֣̂r láֽ⁠mwò׃"],[23,21,"כִּי־סֹבֵ֣א וְ֭⁠זוֹלֵל יִוָּרֵ֑שׁ וּ֝⁠קְרָעִ֗ים תַּלְבִּ֥ישׁ נוּמָֽה׃","ki̇y-sòbé֣ʼ wĕ֭⁠zwòlél yiwá̇ré֑ş̌ ẇ֝⁠qĕráʻi֗ym ţȧlĕbi֥̇yş̌ nẇmáֽh׃"],[23,22,"שְׁמַ֣ע לְ֭⁠אָבִי⁠ךָ זֶ֣ה יְלָדֶ֑⁠ךָ וְ⁠אַל־תָּ֝ב֗וּז כִּֽי־זָקְנָ֥ה אִמֶּֽ⁠ךָ׃","şĕ̌ma֣ʻ lĕ֭⁠ʼábiy⁠ká ze֣h yĕláde֑⁠ká wĕ⁠ʼal-ţá̇֝b֗ẇz kiֽ̇y-záqĕná֥h ʼimėֽ⁠ká׃"],[23,23,"אֱמֶ֣ת קְ֭נֵה וְ⁠אַל־תִּמְכֹּ֑ר חָכְמָ֖ה וּ⁠מוּסָ֣ר וּ⁠בִינָֽה׃","ʼème֣ţ qĕ֭néh wĕ⁠ʼal-ţi̇mĕkò֑̇r ẖákĕmá֖h ẇ⁠mẇsá֣r ẇ⁠biynáֽh׃"],[23,24,"גול יגול אֲבִ֣י צַדִּ֑יק יולד חָ֝כָ֗ם ו⁠ישמח־בּֽ⁠וֹ׃","gwl ygwl ʼàbi֣y ẕadi֑̇yq ywld ẖá֝ká֗m w⁠yşmẖ-ḃֽ⁠wò׃"],[23,25,"יִֽשְׂמַח־אָבִ֥י⁠ךָ וְ⁠אִמֶּ֑⁠ךָ וְ֝⁠תָגֵ֗ל יֽוֹלַדְתֶּֽ⁠ךָ׃","yiֽşĕ̂maẖ-ʼábi֥y⁠ká wĕ⁠ʼimė֑⁠ká wĕ֝⁠ţágé֗l yֽwòladĕţėֽ⁠ká׃"],[23,26,"תְּנָֽ⁠ה־בְנִ֣⁠י לִבְּ⁠ךָ֣ לִ֑⁠י וְ֝⁠עֵינֶ֗י⁠ךָ דְּרָכַ֥⁠י תרצנה׃","ţĕ̇náֽ⁠h-bĕni֣⁠y libĕ̇⁠ká֣ li֑⁠y wĕ֝⁠ʻéyne֗y⁠ká dĕ̇ráka֥⁠y ţrẕnh׃"],[23,27,"כִּֽי־שׁוּחָ֣ה עֲמֻקָּ֣ה זוֹנָ֑ה וּ⁠בְאֵ֥ר צָ֝רָ֗ה נָכְרִיָּֽה׃","kiֽ̇y-ş̌ẇẖá֣h ʻàmuqá֣̇h zwòná֑h ẇ⁠bĕʼé֥r ẕá֝rá֗h nákĕriyáֽ̇h׃"],[23,28,"אַף־הִ֭יא כְּ⁠חֶ֣תֶף תֶּֽאֱרֹ֑ב וּ֝⁠בוֹגְדִ֗ים בְּ⁠אָדָ֥ם תּוֹסִֽף׃","ʼap-hi֭yʼ kĕ̇⁠ẖe֣ţep ţėֽʼèrò֑b ẇ֝⁠bwògĕdi֗ym bĕ̇⁠ʼádá֥m ţ̇wòsiֽp׃"],[23,29,"לְ⁠מִ֨י א֥וֹי לְ⁠מִ֪י אֲב֡וֹי לְ⁠מִ֤י מדונים ׀ לְ⁠מִ֥י שִׂ֗יחַ לְ֭⁠מִי פְּצָעִ֣ים חִנָּ֑ם לְ֝⁠מִ֗י חַכְלִל֥וּת עֵינָֽיִם׃","lĕ⁠mi֨y ʼ֥wòy lĕ⁠mi֪y ʼàb֡wòy lĕ⁠mi֤y mdwnym ׀ lĕ⁠mi֥y şî֗yẖa lĕ֭⁠miy pĕ̇ẕáʻi֣ym ẖiná֑̇m lĕ֝⁠mi֗y ẖakĕlil֥ẇţ ʻéynáֽyim׃"],[23,30,"לַֽ⁠מְאַחֲרִ֥ים עַל־הַ⁠יָּ֑יִן לַ֝⁠בָּאִ֗ים לַ⁠חְקֹ֥ר מִמְסָֽךְ׃","laֽ⁠mĕʼaẖàri֥ym ʻal-ha⁠yá֑̇yin la֝⁠bá̇ʼi֗ym la⁠ẖĕqò֥r mimĕsáֽkĕ׃"],[23,31,"אַל־תֵּ֥רֶא יַיִן֮ כִּ֪י יִתְאַ֫דָּ֥ם כִּֽי־יִתֵּ֣ן ב⁠כיס עֵינ֑⁠וֹ יִ֝תְהַלֵּ֗ךְ בְּ⁠מֵישָׁרִֽים׃","ʼal-ţé֥̇reʼ yayin֮ ki֪̇y yiţĕʼa֫dá֥̇m kiֽ̇y-yiţé֣̇n b⁠kys ʻéyn֑⁠wò yi֝ţĕhalé̇֗kĕ bĕ̇⁠méyşá̌riֽym׃"],[23,32,"אַ֭חֲרִית⁠וֹ כְּ⁠נָחָ֣שׁ יִשָּׁ֑ךְ וּֽ⁠כְ⁠צִפְעֹנִ֥י יַפְרִֽשׁ׃","ʼa֭ẖàriyţ⁠wò kĕ̇⁠náẖá֣ş̌ yişá֑̇̌kĕ ẇֽ⁠kĕ⁠ẕipĕʻòni֥y yapĕriֽş̌׃"],[23,33,"עֵ֭ינֶי⁠ךָ יִרְא֣וּ זָר֑וֹת וְ֝⁠לִבְּ⁠ךָ֗ יְדַבֵּ֥ר תַּהְפֻּכֽוֹת׃","ʻé֭yney⁠ká yirĕʼ֣ẇ zár֑wòţ wĕ֝⁠libĕ̇⁠ká֗ yĕdabé֥̇r ţȧhĕpu̇kֽwòţ׃"],[23,34,"וְ֭⁠הָיִיתָ כְּ⁠שֹׁכֵ֣ב בְּ⁠לֶב־יָ֑ם וּ֝⁠כְ⁠שֹׁכֵ֗ב בְּ⁠רֹ֣אשׁ חִבֵּֽל׃","wĕ֭⁠háyiyţá kĕ̇⁠şò̌ké֣b bĕ̇⁠leb-yá֑m ẇ֝⁠kĕ⁠şò̌ké֗b bĕ̇⁠rò֣ʼş̌ ẖibéֽ̇l׃"],[23,35,"הִכּ֥וּ⁠נִי בַל־חָלִיתִי֮ הֲלָמ֗וּ⁠נִי בַּל־יָ֫דָ֥עְתִּי מָתַ֥י אָקִ֑יץ א֝וֹסִ֗יף אֲבַקְשֶׁ֥⁠נּוּ עֽוֹד׃","hik֥̇ẇ⁠niy bal-ẖáliyţiy֮ hàlám֗ẇ⁠niy bȧl-yá֫dá֥ʻĕţi̇y máţa֥y ʼáqi֑yẕ ʼ֝wòsi֗yp ʼàbaqĕşě֥⁠ṅẇ ʻֽwòd׃"],[24,1,"אַל־תְּ֭קַנֵּא בְּ⁠אַנְשֵׁ֣י רָעָ֑ה וְ⁠אַל־תתאו לִ⁠הְי֥וֹת אִתָּֽ⁠ם׃","ʼal-ţĕ֭̇qané̇ʼ bĕ̇⁠ʼanĕşé֣̌y ráʻá֑h wĕ⁠ʼal-ţţʼw li⁠hĕy֥wòţ ʼiţáֽ̇⁠m׃"],[24,2,"כִּי־שֹׁ֭ד יֶהְגֶּ֣ה לִבָּ֑⁠ם וְ֝⁠עָמָ֗ל שִׂפְתֵי⁠הֶ֥ם תְּדַבֵּֽרְנָה׃","ki̇y-şò֭̌d yehĕgė֣h libá֑̇⁠m wĕ֝⁠ʻámá֗l şîpĕţéy⁠he֥m ţĕ̇dabéֽ̇rĕnáh׃"],[24,3,"בְּ֭⁠חָכְמָה יִבָּ֣נֶה בָּ֑יִת וּ֝⁠בִ⁠תְבוּנָ֗ה יִתְכּוֹנָֽן׃","bĕ֭̇⁠ẖákĕmáh yibá֣̇neh bá֑̇yiţ ẇ֝⁠bi⁠ţĕbẇná֗h yiţĕk̇wònáֽn׃"],[24,4,"וּ֭⁠בְ⁠דַעַת חֲדָרִ֣ים יִמָּלְא֑וּ כָּל־ה֖וֹן יָקָ֣ר וְ⁠נָעִֽים׃","ẇ֭⁠bĕ⁠daʻaţ ẖàdári֣ym yimá̇lĕʼ֑ẇ ká̇l-h֖wòn yáqá֣r wĕ⁠náʻiֽym׃"],[24,5,"גֶּֽבֶר־חָכָ֥ם בַּ⁠ע֑וֹז וְ⁠אִֽישׁ־דַּ֝֗עַת מְאַמֶּץ־כֹּֽחַ׃","gėֽber-ẖáká֥m bȧ⁠ʻ֑wòz wĕ⁠ʼiֽyş̌-dȧ֝֗ʻaţ mĕʼamėẕ-kòֽ̇ẖa׃"],[24,6,"כִּ֣י בְ֭⁠תַחְבֻּלוֹת תַּעֲשֶׂה־לְּ⁠ךָ֣ מִלְחָמָ֑ה וּ֝⁠תְשׁוּעָ֗ה בְּ⁠רֹ֣ב יוֹעֵֽץ׃","ki֣̇y bĕ֭⁠ţaẖĕbu̇lwòţ ţȧʻàşêh-lĕ̇⁠ká֣ milĕẖámá֑h ẇ֝⁠ţĕş̌ẇʻá֗h bĕ̇⁠rò֣b ywòʻéֽẕ׃"],[24,7,"רָאמ֣וֹת לֶֽ⁠אֱוִ֣יל חָכְמ֑וֹת בַּ֝⁠שַּׁ֗עַר לֹ֣א יִפְתַּח־פִּֽי⁠הוּ׃","ráʼm֣wòţ leֽ⁠ʼèwi֣yl ẖákĕm֑wòţ bȧ֝⁠şȧ̌֗ʻar lò֣ʼ yipĕţȧẖ-piֽ̇y⁠hẇ׃"],[24,8,"מְחַשֵּׁ֥ב לְ⁠הָרֵ֑עַ ל֝֗⁠וֹ בַּֽעַל־מְזִמּ֥וֹת יִקְרָֽאוּ׃","mĕẖaşé֥̇̌b lĕ⁠háré֑ʻa l֝֗⁠wò bȧֽʻal-mĕziṁ֥wòţ yiqĕráֽʼẇ׃"],[24,9,"זִמַּ֣ת אִוֶּ֣לֶת חַטָּ֑את וְ⁠תוֹעֲבַ֖ת לְ⁠אָדָ֣ם לֵֽץ׃","zimȧ֣ţ ʼiwė֣leţ ẖatá֑̇ʼţ wĕ⁠ţwòʻàba֖ţ lĕ⁠ʼádá֣m léֽẕ׃"],[24,10,"הִ֭תְרַפִּיתָ בְּ⁠י֥וֹם צָרָ֗ה צַ֣ר כֹּחֶֽ⁠כָה׃","hi֭ţĕrapi̇yţá bĕ̇⁠y֥wòm ẕárá֗h ẕa֣r kò̇ẖeֽ⁠káh׃"],[24,11,"הַ֭צֵּל לְקֻחִ֣ים לַ⁠מָּ֑וֶת וּ⁠מָטִ֥ים לַ֝⁠הֶ֗רֶג אִם־תַּחְשֽׂוֹךְ׃","ha֭ẕé̇l lĕquẖi֣ym la⁠má֑̇weţ ẇ⁠máti֥ym la֝⁠he֗reg ʼim-ţȧẖĕşֽ̂wòkĕ׃"],[24,12,"כִּֽי־תֹאמַ֗ר הֵן֮ לֹא־יָדַ֪עְנ֫וּ זֶ֥ה הֲֽ⁠לֹא־תֹ֘כֵ֤ן לִבּ֨וֹת ׀ הֽוּא־יָבִ֗ין וְ⁠נֹצֵ֣ר נַ֭פְשְׁ⁠ךָ ה֣וּא יֵדָ֑ע וְ⁠הֵשִׁ֖יב לְ⁠אָדָ֣ם כְּ⁠פָעֳלֽ⁠וֹ׃","kiֽ̇y-ţòʼma֗r hén֮ lòʼ-yáda֪ʻĕn֫ẇ ze֥h hàֽ⁠lòʼ-ţò֘ké֤n liḃ֨wòţ ׀ hֽẇʼ-yábi֗yn wĕ⁠nòẕé֣r na֭pĕşĕ̌⁠ká h֣ẇʼ yédá֑ʻ wĕ⁠héşǐ֖yb lĕ⁠ʼádá֣m kĕ̇⁠páʻolֽ⁠wò׃"],[24,13,"אֱכָל־בְּנִ֣⁠י דְבַ֣שׁ כִּי־ט֑וֹב וְ⁠נֹ֥פֶת מָ֝ת֗וֹק עַל־חִכֶּֽ⁠ךָ׃","ʼèkál-bĕ̇ni֣⁠y dĕba֣ş̌ ki̇y-t֑wòb wĕ⁠nò֥peţ má֝ţ֗wòq ʻal-ẖikėֽ⁠ká׃"],[24,14,"כֵּ֤ן ׀ דְּעֶ֥⁠ה חָכְמָ֗ה לְ⁠נַ֫פְשֶׁ֥⁠ךָ אִם־מָ֭צָאתָ וְ⁠יֵ֣שׁ אַחֲרִ֑ית וְ֝⁠תִקְוָתְ⁠ךָ֗ לֹ֣א תִכָּרֵֽת׃פ","ké֤̇n ׀ dĕ̇ʻe֥⁠h ẖákĕmá֗h lĕ⁠na֫pĕşě֥⁠ká ʼim-má֭ẕáʼţá wĕ⁠yé֣ş̌ ʼaẖàri֑yţ wĕ֝⁠ţiqĕwáţĕ⁠ká֗ lò֣ʼ ţiká̇réֽţ׃p"],[24,15,"אַל־תֶּאֱרֹ֣ב רָ֭שָׁע לִ⁠נְוֵ֣ה צַדִּ֑יק אַֽל־תְּשַׁדֵּ֥ד רִבְצ⁠וֹ׃","ʼal-ţėʼèrò֣b rá֭şá̌ʻ li⁠nĕwé֣h ẕadi֑̇yq ʼaֽl-ţĕ̇şǎdé֥̇d ribĕẕ⁠wò׃"],[24,16,"כִּ֤י שֶׁ֨בַע ׀ יִפּ֣וֹל צַדִּ֣יק וָ⁠קָ֑ם וּ֝⁠רְשָׁעִ֗ים יִכָּשְׁל֥וּ בְ⁠רָעָֽה׃","ki֤̇y şě֨baʻ ׀ yiṗ֣wòl ẕadi֣̇yq wá⁠qá֑m ẇ֝⁠rĕşá̌ʻi֗ym yiká̇şĕ̌l֥ẇ bĕ⁠ráʻáֽh׃"],[24,17,"בִּ⁠נְפֹ֣ל אויבי⁠ך אַל־תִּשְׂמָ֑ח וּ֝⁠בִ⁠כָּשְׁל֗⁠וֹ אַל־יָגֵ֥ל לִבֶּֽ⁠ךָ׃","bi̇⁠nĕpò֣l ʼwyby⁠k ʼal-ţi̇şĕ̂má֑ẖ ẇ֝⁠bi⁠ká̇şĕ̌l֗⁠wò ʼal-yágé֥l libėֽ⁠ká׃"],[24,18,"פֶּן־יִרְאֶ֣ה יְ֭הוָה וְ⁠רַ֣ע בְּ⁠עֵינָ֑י⁠ו וְ⁠הֵשִׁ֖יב מֵ⁠עָלָ֣י⁠ו אַפּֽ⁠וֹ׃","pėn-yirĕʼe֣h yĕ֭hwáh wĕ⁠ra֣ʻ bĕ̇⁠ʻéyná֑y⁠w wĕ⁠héşǐ֖yb mé⁠ʻálá֣y⁠w ʼaṗֽ⁠wò׃"],[24,19,"אַל־תִּתְחַ֥ר בַּ⁠מְּרֵעִ֑ים אַל־תְּ֝קַנֵּ֗א בָּ⁠רְשָׁעִֽים׃","ʼal-ţi̇ţĕẖa֥r bȧ⁠mĕ̇réʻi֑ym ʼal-ţĕ̇֝qané̇֗ʼ bá̇⁠rĕşá̌ʻiֽym׃"],[24,20,"כִּ֤י ׀ לֹֽא־תִהְיֶ֣ה אַחֲרִ֣ית לָ⁠רָ֑ע נֵ֖ר רְשָׁעִ֣ים יִדְעָֽךְ׃","ki֤̇y ׀ lòֽʼ-ţihĕye֣h ʼaẖàri֣yţ lá⁠rá֑ʻ né֖r rĕşá̌ʻi֣ym yidĕʻáֽkĕ׃"],[24,21,"יְרָֽא־אֶת־יְהוָ֣ה בְּנִ֣⁠י וָ⁠מֶ֑לֶךְ עִם־שׁ֝וֹנִ֗ים אַל־תִּתְעָרָֽב׃","yĕráֽʼ-ʼeţ-yĕhwá֣h bĕ̇ni֣⁠y wá⁠me֑lekĕ ʻim-ş̌֝wòni֗ym ʼal-ţi̇ţĕʻáráֽb׃"],[24,22,"כִּֽי־פִ֭תְאֹם יָק֣וּם אֵידָ֑⁠ם וּ⁠פִ֥יד שְׁ֝נֵי⁠הֶ֗ם מִ֣י יוֹדֵֽעַ׃ס","kiֽ̇y-pi֭ţĕʼòm yáq֣ẇm ʼéydá֑⁠m ẇ⁠pi֥yd şĕ̌֝néy⁠he֗m mi֣y ywòdéֽʻa׃s"],[24,23,"גַּם־אֵ֥לֶּה לַֽ⁠חֲכָמִ֑ים הַֽכֵּר־פָּנִ֖ים בְּ⁠מִשְׁפָּ֣ט בַּל־טֽוֹב׃","gȧm-ʼé֥lėh laֽ⁠ẖàkámi֑ym haֽké̇r-pá̇ni֖ym bĕ̇⁠mişĕ̌pá֣̇t bȧl-tֽwòb׃"],[24,24,"אֹ֤מֵ֨ר ׀ לְ⁠רָשָׁע֮ צַדִּ֪יק אָ֥תָּה יִקְּבֻ֥⁠הוּ עַמִּ֑ים יִזְעָמ֥וּ⁠הוּ לְאֻמִּֽים׃","ʼò֤mé֨r ׀ lĕ⁠ráşá̌ʻ֮ ẕadi֪̇yq ʼá֥ţá̇h yiqĕ̇bu֥⁠hẇ ʻami֑̇ym yizĕʻám֥ẇ⁠hẇ lĕʼumiֽ̇ym׃"],[24,25,"וְ⁠לַ⁠מּוֹכִיחִ֥ים יִנְעָ֑ם וַֽ֝⁠עֲלֵי⁠הֶ֗ם תָּב֥וֹא בִרְכַּת־טֽוֹב׃","wĕ⁠la⁠ṁwòkiyẖi֥ym yinĕʻá֑m waֽ֝⁠ʻàléy⁠he֗m ţá̇b֥wòʼ birĕkȧţ-tֽwòb׃"],[24,26,"שְׂפָתַ֥יִם יִשָּׁ֑ק מֵ֝שִׁ֗יב דְּבָרִ֥ים נְכֹחִֽים׃","şĕ̂páţa֥yim yişá֑̇̌q mé֝şǐ֗yb dĕ̇bári֥ym nĕkòẖiֽym׃"],[24,27,"הָ֘כֵ֤ן בַּ⁠ח֨וּץ ׀ מְלַאכְתֶּ֗⁠ךָ וְ⁠עַתְּדָ֣⁠הּ בַּ⁠שָּׂדֶ֣ה לָ֑⁠ךְ אַ֝חַ֗ר וּ⁠בָנִ֥יתָ בֵיתֶֽ⁠ךָ׃פ","há֘ké֤n bȧ⁠ẖ֨ẇẕ ׀ mĕlaʼkĕţė֗⁠ká wĕ⁠ʻaţĕ̇dá֣⁠ḣ bȧ⁠şá̇̂de֣h lá֑⁠kĕ ʼa֝ẖa֗r ẇ⁠báni֥yţá béyţeֽ⁠ká׃p"],[24,28,"אַל־תְּהִ֣י עֵד־חִנָּ֣ם בְּ⁠רֵעֶ֑⁠ךָ וַ֝⁠הֲ⁠פִתִּ֗יתָ בִּ⁠שְׂפָתֶֽי⁠ךָ׃","ʼal-ţĕ̇hi֣y ʻéd-ẖiná֣̇m bĕ̇⁠réʻe֑⁠ká wa֝⁠hà⁠piţi̇֗yţá bi̇⁠şĕ̂páţeֽy⁠ká׃"],[24,29,"אַל־תֹּאמַ֗ר כַּ⁠אֲשֶׁ֣ר עָֽשָׂה־לִ֭⁠י כֵּ֤ן אֶֽעֱשֶׂה־לּ֑⁠וֹ אָשִׁ֖יב לָ⁠אִ֣ישׁ כְּ⁠פָעֳלֽ⁠וֹ׃","ʼal-ţò̇ʼma֗r kȧ⁠ʼàşě֣r ʻáֽşá̂h-li֭⁠y ké֤̇n ʼeֽʻèşêh-l֑̇⁠wò ʼáşǐ֖yb lá⁠ʼi֣yş̌ kĕ̇⁠páʻolֽ⁠wò׃"],[24,30,"עַל־שְׂדֵ֣ה אִישׁ־עָצֵ֣ל עָבַ֑רְתִּי וְ⁠עַל־כֶּ֝֗רֶם אָדָ֥ם חֲסַר־לֵֽב׃","ʻal-şĕ̂dé֣h ʼiyş̌-ʻáẕé֣l ʻába֑rĕţi̇y wĕ⁠ʻal-kė֝֗rem ʼádá֥m ẖàsar-léֽb׃"],[24,31,"וְ⁠הִנֵּ֨ה עָ֘לָ֤ה כֻלּ֨⁠וֹ ׀ קִמְּשֹׂנִ֗ים כָּסּ֣וּ פָנָ֣י⁠ו חֲרֻלִּ֑ים וְ⁠גֶ֖דֶר אֲבָנָ֣י⁠ו נֶהֱרָֽסָה׃","wĕ⁠hiné̇֨h ʻá֘lá֤h kul̇֨⁠wò ׀ qimĕ̇şò̂ni֗ym ká̇ṡ֣ẇ páná֣y⁠w ẖàruli֑̇ym wĕ⁠ge֖der ʼàbáná֣y⁠w nehèráֽsáh׃"],[24,32,"וָֽ⁠אֶחֱזֶ֣ה אָ֭נֹכִֽי אָשִׁ֣ית לִבִּ֑⁠י רָ֝אִ֗יתִי לָקַ֥חְתִּי מוּסָֽר׃","wáֽ⁠ʼeẖèze֣h ʼá֭nòkiֽy ʼáşǐ֣yţ libi֑̇⁠y rá֝ʼi֗yţiy láqa֥ẖĕţi̇y mẇsáֽr׃"],[24,33,"מְעַ֣ט שֵׁ֭נוֹת מְעַ֣ט תְּנוּמ֑וֹת מְעַ֓ט ׀ חִבֻּ֖ק יָדַ֣יִם לִ⁠שְׁכָּֽב׃","mĕʻa֣t şé֭̌nwòţ mĕʻa֣t ţĕ̇nẇm֑wòţ mĕʻa֓t ׀ ẖibu֖̇q yáda֣yim li⁠şĕ̌káֽ̇b׃"],[24,34,"וּ⁠בָֽא־מִתְהַלֵּ֥ךְ רֵישֶׁ֑⁠ךָ וּ֝⁠מַחְסֹרֶ֗י⁠ךָ כְּ⁠אִ֣ישׁ מָגֵֽן׃פ","ẇ⁠báֽʼ-miţĕhalé֥̇kĕ réyşě֑⁠ká ẇ֝⁠maẖĕsòre֗y⁠ká kĕ̇⁠ʼi֣yş̌ mágéֽn׃p"],[25,1,"גַּם־אֵ֭לֶּה מִשְׁלֵ֣י שְׁלֹמֹ֑ה אֲשֶׁ֥ר הֶ֝עְתִּ֗יקוּ אַנְשֵׁ֤י ׀ חִזְקִיָּ֬ה מֶֽלֶךְ־יְהוּדָֽה׃","gȧm-ʼé֭lėh mişĕ̌lé֣y şĕ̌lòmò֑h ʼàşě֥r he֝ʻĕţi̇֗yqẇ ʼanĕşé֤̌y ׀ ẖizĕqiyá̇֬h meֽlekĕ-yĕhẇdáֽh׃"],[25,2,"כְּבֹ֣ד אֱ֭לֹהִים הַסְתֵּ֣ר דָּבָ֑ר וּ⁠כְבֹ֥ד מְ֝לָכִ֗ים חֲקֹ֣ר דָּבָֽר׃","kĕ̇bò֣d ʼè֭lòhiym hasĕţé֣̇r dá̇bá֑r ẇ⁠kĕbò֥d mĕ֝láki֗ym ẖàqò֣r dá̇báֽr׃"],[25,3,"שָׁמַ֣יִם לָ֭⁠רוּם וָ⁠אָ֣רֶץ לָ⁠עֹ֑מֶק וְ⁠לֵ֥ב מְ֝לָכִ֗ים אֵ֣ין חֵֽקֶר׃","şá̌ma֣yim lá֭⁠rẇm wá⁠ʼá֣reẕ lá⁠ʻò֑meq wĕ⁠lé֥b mĕ֝láki֗ym ʼé֣yn ẖéֽqer׃"],[25,4,"הָג֣וֹ סִיגִ֣ים מִ⁠כָּ֑סֶף וַ⁠יֵּצֵ֖א לַ⁠צֹּרֵ֣ף כֶּֽלִי׃","hág֣wò siygi֣ym mi⁠ká֑̇sep wa⁠yé̇ẕé֖ʼ la⁠ẕò̇ré֣p kėֽliy׃"],[25,5,"הָג֣וֹ רָ֭שָׁע לִ⁠פְנֵי־מֶ֑לֶךְ וְ⁠יִכּ֖וֹן בַּ⁠צֶּ֣דֶק כִּסְאֽ⁠וֹ׃","hág֣wò rá֭şá̌ʻ li⁠pĕnéy-me֑lekĕ wĕ⁠yik֖̇wòn bȧ⁠ẕė֣deq ki̇sĕʼֽ⁠wò׃"],[25,6,"אַל־תִּתְהַדַּ֥ר לִ⁠פְנֵי־מֶ֑לֶךְ וּ⁠בִ⁠מְק֥וֹם גְּ֝דֹלִ֗ים אַֽל־תַּעֲמֹֽד׃","ʼal-ţi̇ţĕhadȧ֥r li⁠pĕnéy-me֑lekĕ ẇ⁠bi⁠mĕq֥wòm gĕ̇֝dòli֗ym ʼaֽl-ţȧʻàmòֽd׃"],[25,7,"כִּ֤י ט֥וֹב אֲמָר־לְ⁠ךָ֗ עֲֽלֵ֫ה הֵ֥נָּה מֵֽ֭⁠הַשְׁפִּ֣ילְ⁠ךָ לִ⁠פְנֵ֣י נָדִ֑יב אֲשֶׁ֖ר רָא֣וּ עֵינֶֽי⁠ךָ׃","ki֤̇y t֥wòb ʼàmár-lĕ⁠ká֗ ʻàֽlé֫h hé֥ná̇h méֽ֭⁠haşĕ̌pi֣̇ylĕ⁠ká li⁠pĕné֣y nádi֑yb ʼàşě֖r ráʼ֣ẇ ʻéyneֽy⁠ká׃"],[25,8,"אַל־תֵּצֵ֥א לָ⁠רִ֗ב מַ֫הֵ֥ר פֶּ֣ן מַה־תַּ֭עֲשֶׂה בְּ⁠אַחֲרִיתָ֑⁠הּ בְּ⁠הַכְלִ֖ים אֹתְ⁠ךָ֣ רֵעֶֽ⁠ךָ׃","ʼal-ţé̇ẕé֥ʼ lá⁠ri֗b ma֫hé֥r pė֣n mah-ţȧ֭ʻàşêh bĕ̇⁠ʼaẖàriyţá֑⁠ḣ bĕ̇⁠hakĕli֖ym ʼòţĕ⁠ká֣ réʻeֽ⁠ká׃"],[25,9,"רִֽ֭יבְ⁠ךָ רִ֣יב אֶת־רֵעֶ֑⁠ךָ וְ⁠ס֖וֹד אַחֵ֣ר אַל־תְּגָֽל׃","riֽ֭ybĕ⁠ká ri֣yb ʼeţ-réʻe֑⁠ká wĕ⁠s֖wòd ʼaẖé֣r ʼal-ţĕ̇gáֽl׃"],[25,10,"פֶּֽן־יְחַסֶּדְ⁠ךָ֥ שֹׁמֵ֑עַ וְ֝⁠דִבָּתְ⁠ךָ֗ לֹ֣א תָשֽׁוּב׃","pėֽn-yĕẖasėdĕ⁠ká֥ şò̌mé֑ʻa wĕ֝⁠dibá̇ţĕ⁠ká֗ lò֣ʼ ţáşֽ̌ẇb׃"],[25,11,"תַּפּוּחֵ֣י זָ֭הָב בְּ⁠מַשְׂכִּיּ֥וֹת כָּ֑סֶף דָּ֝בָ֗ר דָּבֻ֥ר עַל־אָפְנָֽי⁠ו׃","ţȧṗẇẖé֣y zá֭háb bĕ̇⁠maşĕ̂ki̇ẏ֥wòţ ká֑̇sep dá̇֝bá֗r dá̇bu֥r ʻal-ʼápĕnáֽy⁠w׃"],[25,12,"נֶ֣זֶם זָ֭הָב וַ⁠חֲלִי־כָ֑תֶם מוֹכִ֥יחַ חָ֝כָ֗ם עַל־אֹ֥זֶן שֹׁמָֽעַת׃","ne֣zem zá֭háb wa⁠ẖàliy-ká֑ţem mwòki֥yẖa ẖá֝ká֗m ʻal-ʼò֥zen şò̌máֽʻaţ׃"],[25,13,"כְּ⁠צִנַּת־שֶׁ֨לֶג ׀ בְּ⁠י֬וֹם קָצִ֗יר צִ֣יר נֶ֭אֱמָן לְ⁠שֹׁלְחָ֑י⁠ו וְ⁠נֶ֖פֶשׁ אֲדֹנָ֣י⁠ו יָשִֽׁיב׃פ","kĕ̇⁠ẕinȧţ-şě֨leg ׀ bĕ̇⁠y֬wòm qáẕi֗yr ẕi֣yr ne֭ʼèmán lĕ⁠şò̌lĕẖá֑y⁠w wĕ⁠ne֖peş̌ ʼàdòná֣y⁠w yáşǐֽyb׃p"],[25,14,"נְשִׂיאִ֣ים וְ֭⁠רוּחַ וְ⁠גֶ֣שֶׁם אָ֑יִן אִ֥ישׁ מִ֝תְהַלֵּ֗ל בְּ⁠מַתַּת־שָֽׁקֶר׃","nĕşîyʼi֣ym wĕ֭⁠rẇẖa wĕ⁠ge֣şěm ʼá֑yin ʼi֥yş̌ mi֝ţĕhalé̇֗l bĕ̇⁠maţȧţ-şáֽ̌qer׃"],[25,15,"בְּ⁠אֹ֣רֶךְ אַ֭פַּיִם יְפֻתֶּ֣ה קָצִ֑ין וְ⁠לָשׁ֥וֹן רַ֝כָּ֗ה תִּשְׁבָּר־גָּֽרֶם׃","bĕ̇⁠ʼò֣rekĕ ʼa֭pȧyim yĕpuţė֣h qáẕi֑yn wĕ⁠láş֥̌wòn ra֝ká̇֗h ţi̇şĕ̌bá̇r-gáֽ̇rem׃"],[25,16,"דְּבַ֣שׁ מָ֭צָאתָ אֱכֹ֣ל דַּיֶּ֑⁠ךָּ פֶּן־תִּ֝שְׂבָּעֶ֗⁠נּוּ וַ⁠הֲקֵֽאתֽ⁠וֹ׃","dĕ̇ba֣ş̌ má֭ẕáʼţá ʼèkò֣l dȧyė֑⁠ká̇ pėn-ţi̇֝şĕ̂bá̇ʻe֗⁠ṅẇ wa⁠hàqéֽʼţֽ⁠wò׃"],[25,17,"הֹקַ֣ר רַ֭גְלְ⁠ךָ מִ⁠בֵּ֣ית רֵעֶ֑⁠ךָ פֶּן־יִ֝שְׂבָּעֲ⁠ךָ֗ וּ⁠שְׂנֵאֶֽ⁠ךָ׃","hòqa֣r ra֭gĕlĕ⁠ká mi⁠bé֣̇yţ réʻe֑⁠ká pėn-yi֝şĕ̂bá̇ʻà⁠ká֗ ẇ⁠şĕ̂néʼeֽ⁠ká׃"],[25,18,"מֵפִ֣יץ וְ֭⁠חֶרֶב וְ⁠חֵ֣ץ שָׁנ֑וּן אִ֥ישׁ עֹנֶ֥ה בְ֝⁠רֵעֵ֗⁠הוּ עֵ֣ד שָֽׁקֶר׃","mépi֣yẕ wĕ֭⁠ẖereb wĕ⁠ẖé֣ẕ şá̌n֑ẇn ʼi֥yş̌ ʻòne֥h bĕ֝⁠réʻé֗⁠hẇ ʻé֣d şáֽ̌qer׃"],[25,19,"שֵׁ֣ן רֹ֭עָה וְ⁠רֶ֣גֶל מוּעָ֑דֶת מִבְטָ֥ח בּ֝וֹגֵ֗ד בְּ⁠י֣וֹם צָרָֽה׃","şé֣̌n rò֭ʻáh wĕ⁠re֣gel mẇʻá֑deţ mibĕtá֥ẖ ḃ֝wògé֗d bĕ̇⁠y֣wòm ẕáráֽh׃"],[25,20,"מַ֥עֲדֶה בֶּ֨גֶד ׀ בְּ⁠י֣וֹם קָ֭רָה חֹ֣מֶץ עַל־נָ֑תֶר וְ⁠שָׁ֥ר בַּ֝⁠שִּׁרִ֗ים עַ֣ל לֶב־רָֽע׃פ","ma֥ʻàdeh bė֨ged ׀ bĕ̇⁠y֣wòm qá֭ráh ẖò֣meẕ ʻal-ná֑ţer wĕ⁠şá֥̌r bȧ֝⁠şi̇̌ri֗ym ʻa֣l leb-ráֽʻ׃p"],[25,21,"אִם־רָעֵ֣ב שֹׂ֭נַאֲ⁠ךָ הַאֲכִלֵ֣⁠הוּ לָ֑חֶם וְ⁠אִם־צָ֝מֵ֗א הַשְׁקֵ֥⁠הוּ מָֽיִם׃","ʼim-ráʻé֣b şò֭̂naʼà⁠ká haʼàkilé֣⁠hẇ lá֑ẖem wĕ⁠ʼim-ẕá֝mé֗ʼ haşĕ̌qé֥⁠hẇ máֽyim׃"],[25,22,"כִּ֤י גֶֽחָלִ֗ים אַ֭תָּה חֹתֶ֣ה עַל־רֹאשׁ֑⁠וֹ וַֽ֝⁠יהוָ֗ה יְשַׁלֶּם־לָֽ⁠ךְ׃","ki֤̇y geֽẖáli֗ym ʼa֭ţá̇h ẖòţe֣h ʻal-ròʼş֑̌⁠wò waֽ֝⁠yhwá֗h yĕşǎlėm-láֽ⁠kĕ׃"],[25,23,"ר֣וּחַ צָ֭פוֹן תְּח֣וֹלֵֽל גָּ֑שֶׁם וּ⁠פָנִ֥ים נִ֝זְעָמִ֗ים לְשׁ֣וֹן סָֽתֶר׃","r֣ẇẖa ẕá֭pwòn ţĕ̇ẖ֣wòléֽl gá֑̇şěm ẇ⁠páni֥ym ni֝zĕʻámi֗ym lĕş֣̌wòn sáֽţer׃"],[25,24,"ט֗וֹב שֶׁ֥בֶת עַל־פִּנַּת־גָּ֑ג מֵ⁠אֵ֥שֶׁת מדונים וּ⁠בֵ֥ית חָֽבֶר׃","t֗wòb şě֥beţ ʻal-pi̇nȧţ-gá֑̇g mé⁠ʼé֥şěţ mdwnym ẇ⁠bé֥yţ ẖáֽber׃"],[25,25,"מַ֣יִם קָ֭רִים עַל־נֶ֣פֶשׁ עֲיֵפָ֑ה וּ⁠שְׁמוּעָ֥ה ט֝וֹבָ֗ה מֵ⁠אֶ֥רֶץ מֶרְחָֽק׃","ma֣yim qá֭riym ʻal-ne֣peş̌ ʻàyépá֑h ẇ⁠şĕ̌mẇʻá֥h t֝wòbá֗h mé⁠ʼe֥reẕ merĕẖáֽq׃"],[25,26,"מַעְיָ֣ן נִ֭רְפָּשׂ וּ⁠מָק֣וֹר מָשְׁחָ֑ת צַ֝דִּ֗יק מָ֣ט לִ⁠פְנֵֽי־רָשָֽׁע׃","maʻĕyá֣n ni֭rĕpá̇ş̂ ẇ⁠máq֣wòr máşĕ̌ẖá֑ţ ẕa֝di̇֗yq má֣t li⁠pĕnéֽy-ráşáֽ̌ʻ׃"],[25,27,"אָ֘כֹ֤ל דְּבַ֣שׁ הַרְבּ֣וֹת לֹא־ט֑וֹב וְ⁠חֵ֖קֶר כְּבֹדָ֣⁠ם כָּבֽוֹד׃","ʼá֘kò֤l dĕ̇ba֣ş̌ harĕḃ֣wòţ lòʼ-t֑wòb wĕ⁠ẖé֖qer kĕ̇bòdá֣⁠m ká̇bֽwòd׃"],[25,28,"עִ֣יר פְּ֭רוּצָה אֵ֣ין חוֹמָ֑ה אִ֝֗ישׁ אֲשֶׁ֤ר אֵ֖ין מַעְצָ֣ר לְ⁠רוּחֽ⁠וֹ׃","ʻi֣yr pĕ֭̇rẇẕáh ʼé֣yn ẖwòmá֑h ʼi֝֗yş̌ ʼàşě֤r ʼé֖yn maʻĕẕá֣r lĕ⁠rẇẖֽ⁠wò׃"],[26,1,"כַּ⁠שֶּׁ֤לֶג ׀ בַּ⁠קַּ֗יִץ וְ⁠כַ⁠מָּטָ֥ר בַּ⁠קָּצִ֑יר כֵּ֤ן לֹא־נָאוֶ֖ה לִ⁠כְסִ֣יל כָּבֽוֹד׃","kȧ⁠şė֤̌leg ׀ bȧ⁠qȧ֗yiẕ wĕ⁠ka⁠má̇tá֥r bȧ⁠qá̇ẕi֑yr ké֤̇n lòʼ-náʼwe֖h li⁠kĕsi֣yl ká̇bֽwòd׃"],[26,2,"כַּ⁠צִּפּ֣וֹר לָ֭⁠נוּד כַּ⁠דְּר֣וֹר לָ⁠ע֑וּף כֵּ֥ן קִֽלְלַ֥ת חִ֝נָּ֗ם לא תָבֹֽא׃","kȧ⁠ẕi̇ṗ֣wòr lá֭⁠nẇd kȧ⁠dĕ̇r֣wòr lá⁠ʻ֑ẇp ké֥̇n qiֽlĕla֥ţ ẖi֝ná̇֗m lʼ ţábòֽʼ׃"],[26,3,"שׁ֣וֹט לַ֭⁠סּוּס מֶ֣תֶג לַ⁠חֲמ֑וֹר וְ֝⁠שֵׁ֗בֶט לְ⁠גֵ֣ו כְּסִילִֽים׃","ş֣̌wòt la֭⁠ṡẇs me֣ţeg la⁠ẖàm֑wòr wĕ֝⁠şé̌֗bet lĕ⁠gé֣w kĕ̇siyliֽym׃"],[26,4,"אַל־תַּ֣עַן כְּ֭סִיל כְּ⁠אִוַּלְתּ֑⁠וֹ פֶּֽן־תִּשְׁוֶה־לּ֥⁠וֹ גַם־אָֽתָּה׃","ʼal-ţȧ֣ʻan kĕ֭̇siyl kĕ̇⁠ʼiwȧlĕţ֑̇⁠wò pėֽn-ţi̇şĕ̌weh-l֥̇⁠wò gam-ʼáֽţá̇h׃"],[26,5,"עֲנֵ֣ה כְ֭סִיל כְּ⁠אִוַּלְתּ֑⁠וֹ פֶּן־יִהְיֶ֖ה חָכָ֣ם בְּ⁠עֵינָֽי⁠ו׃","ʻàné֣h kĕ֭siyl kĕ̇⁠ʼiwȧlĕţ֑̇⁠wò pėn-yihĕye֖h ẖáká֣m bĕ̇⁠ʻéynáֽy⁠w׃"],[26,6,"מְקַצֶּ֣ה רַ֭גְלַיִם חָמָ֣ס שֹׁתֶ֑ה שֹׁלֵ֖חַ דְּבָרִ֣ים בְּ⁠יַד־כְּסִֽיל׃","mĕqaẕė֣h ra֭gĕlayim ẖámá֣s şò̌ţe֑h şò̌lé֖ẖa dĕ̇bári֣ym bĕ̇⁠yad-kĕ̇siֽyl׃"],[26,7,"דַּלְי֣וּ שֹׁ֭קַיִם מִ⁠פִּסֵּ֑חַ וּ֝⁠מָשָׁ֗ל בְּ⁠פִ֣י כְסִילִֽים׃","dȧlĕy֣ẇ şò֭̌qayim mi⁠pi̇sé֑̇ẖa ẇ֝⁠máşá̌֗l bĕ̇⁠pi֣y kĕsiyliֽym׃"],[26,8,"כִּ⁠צְר֣וֹר אֶ֭בֶן בְּ⁠מַרְגֵּמָ֑ה כֵּן־נוֹתֵ֖ן לִ⁠כְסִ֣יל כָּבֽוֹד׃","ki̇⁠ẕĕr֣wòr ʼe֭ben bĕ̇⁠marĕgé̇má֑h ké̇n-nwòţé֖n li⁠kĕsi֣yl ká̇bֽwòd׃"],[26,9,"ח֭וֹחַ עָלָ֣ה בְ⁠יַד־שִׁכּ֑וֹר וּ֝⁠מָשָׁ֗ל בְּ⁠פִ֣י כְסִילִֽים׃","ẖ֭wòẖa ʻálá֣h bĕ⁠yad-şǐk֑̇wòr ẇ֝⁠máşá̌֗l bĕ̇⁠pi֣y kĕsiyliֽym׃"],[26,10,"רַ֥ב מְחֽוֹלֵֽל־כֹּ֑ל וְ⁠שֹׂכֵ֥ר כְּ֝סִ֗יל וְ⁠שֹׂכֵ֥ר עֹבְרִֽים׃","ra֥b mĕẖֽwòléֽl-kò֑̇l wĕ⁠şò̂ké֥r kĕ̇֝si֗yl wĕ⁠şò̂ké֥r ʻòbĕriֽym׃"],[26,11,"כְּ֭⁠כֶלֶב שָׁ֣ב עַל־קֵא֑⁠וֹ כְּ֝סִ֗יל שׁוֹנֶ֥ה בְ⁠אִוַּלְתּֽ⁠וֹ׃","kĕ֭̇⁠keleb şá֣̌b ʻal-qéʼ֑⁠wò kĕ̇֝si֗yl ş̌wòne֥h bĕ⁠ʼiwȧlĕţֽ̇⁠wò׃"],[26,12,"רָאִ֗יתָ אִ֭ישׁ חָכָ֣ם בְּ⁠עֵינָ֑י⁠ו תִּקְוָ֖ה לִ⁠כְסִ֣יל מִמֶּֽ⁠נּוּ׃","ráʼi֗yţá ʼi֭yş̌ ẖáká֣m bĕ̇⁠ʻéyná֑y⁠w ţi̇qĕwá֖h li⁠kĕsi֣yl mimėֽ⁠ṅẇ׃"],[26,13,"אָמַ֣ר עָ֭צֵל שַׁ֣חַל בַּ⁠דָּ֑רֶךְ אֲ֝רִ֗י בֵּ֣ין הָ⁠רְחֹבֽוֹת׃","ʼáma֣r ʻá֭ẕél şǎ֣ẖal bȧ⁠dá֑̇rekĕ ʼà֝ri֗y bé֣̇yn há⁠rĕẖòbֽwòţ׃"],[26,14,"הַ֭⁠דֶּלֶת תִּסּ֣וֹב עַל־צִירָ֑⁠הּ וְ֝⁠עָצֵ֗ל עַל־מִטָּתֽ⁠וֹ׃","ha֭⁠dėleţ ţi̇ṡ֣wòb ʻal-ẕiyrá֑⁠ḣ wĕ֝⁠ʻáẕé֗l ʻal-mitá̇ţֽ⁠wò׃"],[26,15,"טָ֘מַ֤ן עָצֵ֣ל יָ֭ד⁠וֹ בַּ⁠צַּלָּ֑חַת נִ֝לְאָ֗ה לַֽ⁠הֲשִׁיבָ֥⁠הּ אֶל־פִּֽי⁠ו׃","tá֘ma֤n ʻáẕé֣l yá֭d⁠wò bȧ⁠ẕȧlá֑̇ẖaţ ni֝lĕʼá֗h laֽ⁠hàşǐybá֥⁠ḣ ʼel-piֽ̇y⁠w׃"],[26,16,"חָכָ֣ם עָצֵ֣ל בְּ⁠עֵינָ֑י⁠ו מִ֝⁠שִּׁבְעָ֗ה מְשִׁ֣יבֵי טָֽעַם׃","ẖáká֣m ʻáẕé֣l bĕ̇⁠ʻéyná֑y⁠w mi֝⁠şi̇̌bĕʻá֗h mĕşǐ֣ybéy táֽʻam׃"],[26,17,"מַחֲזִ֥יק בְּ⁠אָזְנֵי־כָ֑לֶב עֹבֵ֥ר מִ֝תְעַבֵּ֗ר עַל־רִ֥יב לֹּֽא־לֽ⁠וֹ׃","maẖàzi֥yq bĕ̇⁠ʼázĕnéy-ká֑leb ʻòbé֥r mi֝ţĕʻabé̇֗r ʻal-ri֥yb lòֽ̇ʼ-lֽ⁠wò׃"],[26,18,"כְּֽ֭⁠מִתְלַהְלֵהַּ הַ⁠יֹּרֶ֥ה זִקִּ֗ים חִצִּ֥ים וָ⁠מָֽוֶת׃","kĕֽ֭̇⁠miţĕlahĕléhȧ ha⁠yò̇re֥h ziqi̇֗ym ẖiẕi֥̇ym wá⁠máֽweţ׃"],[26,19,"כֵּֽן־אִ֭ישׁ רִמָּ֣ה אֶת־רֵעֵ֑⁠הוּ וְ֝⁠אָמַ֗ר הֲֽ⁠לֹא־מְשַׂחֵ֥ק אָֽנִי׃","kéֽ̇n-ʼi֭yş̌ rimá֣̇h ʼeţ-réʻé֑⁠hẇ wĕ֝⁠ʼáma֗r hàֽ⁠lòʼ-mĕşâẖé֥q ʼáֽniy׃"],[26,20,"בְּ⁠אֶ֣פֶס עֵ֭צִים תִּכְבֶּה־אֵ֑שׁ וּ⁠בְ⁠אֵ֥ין נִ֝רְגָּ֗ן יִשְׁתֹּ֥ק מָדֽוֹן׃","bĕ̇⁠ʼe֣pes ʻé֭ẕiym ţi̇kĕbėh-ʼé֑ş̌ ẇ⁠bĕ⁠ʼé֥yn ni֝rĕgá̇֗n yişĕ̌ţò֥̇q mádֽwòn׃"],[26,21,"פֶּחָ֣ם לְ֭⁠גֶחָלִים וְ⁠עֵצִ֣ים לְ⁠אֵ֑שׁ וְ⁠אִ֥ישׁ מדונים לְ⁠חַרְחַר־רִֽיב׃פ","pėẖá֣m lĕ֭⁠geẖáliym wĕ⁠ʻéẕi֣ym lĕ⁠ʼé֑ş̌ wĕ⁠ʼi֥yş̌ mdwnym lĕ⁠ẖarĕẖar-riֽyb׃p"],[26,22,"דִּבְרֵ֣י נִ֭רְגָּן כְּ⁠מִֽתְלַהֲמִ֑ים וְ֝⁠הֵ֗ם יָרְד֥וּ חַדְרֵי־בָֽטֶן׃","di̇bĕré֣y ni֭rĕgá̇n kĕ̇⁠miֽţĕlahàmi֑ym wĕ֝⁠hé֗m yárĕd֥ẇ ẖadĕréy-báֽten׃"],[26,23,"כֶּ֣סֶף סִ֭יגִים מְצֻפֶּ֣ה עַל־חָ֑רֶשׂ שְׂפָתַ֖יִם דֹּלְקִ֣ים וְ⁠לֶב־רָֽע׃","kė֣sep si֭ygiym mĕẕupė֣h ʻal-ẖá֑reş̂ şĕ̂páţa֖yim dò̇lĕqi֣ym wĕ⁠leb-ráֽʻ׃"],[26,24,"ב⁠שפת⁠ו יִנָּכֵ֣ר שׂוֹנֵ֑א וּ֝⁠בְ⁠קִרְבּ֗⁠וֹ יָשִׁ֥ית מִרְמָֽה׃","b⁠şpţ⁠w yiná̇ké֣r ş̂wòné֑ʼ ẇ֝⁠bĕ⁠qirĕḃ֗⁠wò yáşǐ֥yţ mirĕmáֽh׃"],[26,25,"כִּֽי־יְחַנֵּ֣ן ק֭וֹל⁠וֹ אַל־תַּֽאֲמֶן־בּ֑⁠וֹ כִּ֤י שֶׁ֖בַע תּוֹעֵב֣וֹת בְּ⁠לִבּֽ⁠וֹ׃","kiֽ̇y-yĕẖané֣̇n q֭wòl⁠wò ʼal-ţȧֽʼàmen-ḃ֑⁠wò ki֤̇y şě֖baʻ ţ̇wòʻéb֣wòţ bĕ̇⁠liḃֽ⁠wò׃"],[26,26,"תִּכַּסֶּ֣ה שִׂ֭נְאָה בְּ⁠מַשָּׁא֑וֹן תִּגָּלֶ֖ה רָעָת֣⁠וֹ בְ⁠קָהָֽל׃","ţi̇kȧsė֣h şî֭nĕʼáh bĕ̇⁠maşá̇̌ʼ֑wòn ţi̇gá̇le֖h ráʻáţ֣⁠wò bĕ⁠qáháֽl׃"],[26,27,"כֹּֽרֶה־שַּׁ֭חַת בָּ֣⁠הּ יִפֹּ֑ל וְ⁠גֹ֥לֵ֥ל אֶ֝בֶן אֵלָ֥י⁠ו תָּשֽׁוּב׃","kòֽ̇reh-şȧ֭̌ẖaţ bá֣̇⁠ḣ yipò֑̇l wĕ⁠gò֥lé֥l ʼe֝ben ʼélá֥y⁠w ţá̇şֽ̌ẇb׃"],[26,28,"לְֽשׁוֹן־שֶׁ֭קֶר יִשְׂנָ֣א דַכָּ֑י⁠ו וּ⁠פֶ֥ה חָ֝לָ֗ק יַעֲשֶׂ֥ה מִדְחֶֽה׃","lĕֽş̌wòn-şě֭qer yişĕ̂ná֣ʼ daká֑̇y⁠w ẇ⁠pe֥h ẖá֝lá֗q yaʻàşê֥h midĕẖeֽh׃"],[27,1,"אַֽל־תִּ֭תְהַלֵּל בְּ⁠י֣וֹם מָחָ֑ר כִּ֤י לֹא־תֵ֝דַ֗ע מַה־יֵּ֥לֶד יֽוֹם׃","ʼaֽl-ţi֭̇ţĕhalé̇l bĕ̇⁠y֣wòm máẖá֑r ki֤̇y lòʼ-ţé֝da֗ʻ mah-yé֥̇led yֽwòm׃"],[27,2,"יְהַלֶּלְ⁠ךָ֣ זָ֣ר וְ⁠לֹא־פִ֑י⁠ךָ נָ֝כְרִ֗י וְ⁠אַל־שְׂפָתֶֽי⁠ךָ׃","yĕhalėlĕ⁠ká֣ zá֣r wĕ⁠lòʼ-pi֑y⁠ká ná֝kĕri֗y wĕ⁠ʼal-şĕ̂páţeֽy⁠ká׃"],[27,3,"כֹּֽבֶד־אֶ֭בֶן וְ⁠נֵ֣טֶל הַ⁠ח֑וֹל וְ⁠כַ֥עַס אֱ֝וִ֗יל כָּבֵ֥ד מִ⁠שְּׁנֵי⁠הֶֽם׃","kòֽ̇bed-ʼe֭ben wĕ⁠né֣tel ha⁠ẖ֑wòl wĕ⁠ka֥ʻas ʼè֝wi֗yl ká̇bé֥d mi⁠şĕ̇̌néy⁠heֽm׃"],[27,4,"אַכְזְרִיּ֣וּת חֵ֭מָה וְ⁠שֶׁ֣טֶף אָ֑ף וּ⁠מִ֥י יַ֝עֲמֹד לִ⁠פְנֵ֥י קִנְאָֽה׃","ʼakĕzĕriẏ֣ẇţ ẖé֭máh wĕ⁠şě֣tep ʼá֑p ẇ⁠mi֥y ya֝ʻàmòd li⁠pĕné֥y qinĕʼáֽh׃"],[27,5,"ט֭וֹבָה תּוֹכַ֣חַת מְגֻלָּ֑ה מֵֽ⁠אַהֲבָ֥ה מְסֻתָּֽרֶת׃","t֭wòbáh ţ̇wòka֣ẖaţ mĕgulá֑̇h méֽ⁠ʼahàbá֥h mĕsuţáֽ̇reţ׃"],[27,6,"נֶ֭אֱמָנִים פִּצְעֵ֣י אוֹהֵ֑ב וְ֝⁠נַעְתָּר֗וֹת נְשִׁיק֥וֹת שׂוֹנֵֽא׃","ne֭ʼèmániym pi̇ẕĕʻé֣y ʼwòhé֑b wĕ֝⁠naʻĕţá̇r֗wòţ nĕşǐyq֥wòţ ş̂wònéֽʼ׃"],[27,7,"נֶ֣פֶשׁ שְׂ֭בֵעָה תָּב֣וּס נֹ֑פֶת וְ⁠נֶ֥פֶשׁ רְ֝עֵבָ֗ה כָּל־מַ֥ר מָתֽוֹק׃","ne֣peş̌ şĕ֭̂béʻáh ţá̇b֣ẇs nò֑peţ wĕ⁠ne֥peş̌ rĕ֝ʻébá֗h ká̇l-ma֥r máţֽwòq׃"],[27,8,"כְּ֭⁠צִפּוֹר נוֹדֶ֣דֶת מִן־קִנָּ֑⁠הּ כֵּֽן־אִ֝֗ישׁ נוֹדֵ֥ד מִ⁠מְּקוֹמֽ⁠וֹ׃","kĕ֭̇⁠ẕiṗwòr nwòde֣deţ min-qiná֑̇⁠ḣ kéֽ̇n-ʼi֝֗yş̌ nwòdé֥d mi⁠mĕ̇qwòmֽ⁠wò׃"],[27,9,"שֶׁ֣מֶן וּ֭⁠קְטֹרֶת יְשַׂמַּֽח־לֵ֑ב וּ⁠מֶ֥תֶק רֵ֝עֵ֗⁠הוּ מֵֽ⁠עֲצַת־נָֽפֶשׁ׃","şě֣men ẇ֭⁠qĕtòreţ yĕşâmȧֽẖ-lé֑b ẇ⁠me֥ţeq ré֝ʻé֗⁠hẇ méֽ⁠ʻàẕaţ-náֽpeş̌׃"],[27,10,"רֵֽעֲ⁠ךָ֨ ו⁠רעה אָבִ֡י⁠ךָ אַֽל־תַּעֲזֹ֗ב וּ⁠בֵ֥ית אָחִ֗י⁠ךָ אַל־תָּ֭בוֹא בְּ⁠י֣וֹם אֵידֶ֑⁠ךָ ט֥וֹב שָׁכֵ֥ן קָ֝ר֗וֹב מֵ⁠אָ֥ח רָחֽוֹק׃","réֽʻà⁠ká֨ w⁠rʻh ʼábi֡y⁠ká ʼaֽl-ţȧʻàzò֗b ẇ⁠bé֥yţ ʼáẖi֗y⁠ká ʼal-ţá֭̇bwòʼ bĕ̇⁠y֣wòm ʼéyde֑⁠ká t֥wòb şá̌ké֥n qá֝r֗wòb mé⁠ʼá֥ẖ ráẖֽwòq׃"],[27,11,"חֲכַ֣ם בְּ֭נִ⁠י וְ⁠שַׂמַּ֣ח לִבִּ֑⁠י וְ⁠אָשִׁ֖יבָה חֹרְפִ֣⁠י דָבָֽר׃","ẖàka֣m bĕ֭̇ni⁠y wĕ⁠şâmȧ֣ẖ libi֑̇⁠y wĕ⁠ʼáşǐ֖ybáh ẖòrĕpi֣⁠y dábáֽr׃"],[27,12,"עָר֤וּם רָאָ֣ה רָעָ֣ה נִסְתָּ֑ר פְּ֝תָאיִ֗ם עָבְר֥וּ נֶעֱנָֽשׁוּ׃","ʻár֤ẇm ráʼá֣h ráʻá֣h nisĕţá֑̇r pĕ̇֝ţáʼyi֗m ʻábĕr֥ẇ neʻènáֽş̌ẇ׃"],[27,13,"קַח־בִּ֭גְד⁠וֹ כִּי־עָ֣רַב זָ֑ר וּ⁠בְעַ֖ד נָכְרִיָּ֣ה חַבְלֵֽ⁠הוּ׃","qaẖ-bi֭̇gĕd⁠wò ki̇y-ʻá֣rab zá֑r ẇ⁠bĕʻa֖d nákĕriyá֣̇h ẖabĕléֽ⁠hẇ׃"],[27,14,"מְבָ֘רֵ֤ךְ רֵעֵ֨⁠הוּ ׀ בְּ⁠ק֣וֹל גָּ֭דוֹל בַּ⁠בֹּ֣קֶר הַשְׁכֵּ֑ים קְ֝לָלָ֗ה תֵּחָ֥שֶׁב לֽ⁠וֹ׃","mĕbá֘ré֤kĕ réʻé֨⁠hẇ ׀ bĕ̇⁠q֣wòl gá֭̇dwòl bȧ⁠bò֣̇qer haşĕ̌ké֑̇ym qĕ֝lálá֗h ţé̇ẖá֥şěb lֽ⁠wò׃"],[27,15,"דֶּ֣לֶף ט֭וֹרֵד בְּ⁠י֣וֹם סַגְרִ֑יר וְ⁠אֵ֥שֶׁת מדונים נִשְׁתָּוָֽה׃","dė֣lep t֭wòréd bĕ̇⁠y֣wòm sagĕri֑yr wĕ⁠ʼé֥şěţ mdwnym nişĕ̌ţá̇wáֽh׃"],[27,16,"צֹפְנֶ֥י⁠הָ צָֽפַן־ר֑וּחַ וְ⁠שֶׁ֖מֶן יְמִינ֣⁠וֹ יִקְרָֽא׃","ẕòpĕne֥y⁠há ẕáֽpan-r֑ẇẖa wĕ⁠şě֖men yĕmiyn֣⁠wò yiqĕráֽʼ׃"],[27,17,"בַּרְזֶ֣ל בְּ⁠בַרְזֶ֣ל יָ֑חַד וְ֝⁠אִ֗ישׁ יַ֣חַד פְּנֵֽי־רֵעֵֽ⁠הוּ׃","bȧrĕze֣l bĕ̇⁠barĕze֣l yá֑ẖad wĕ֝⁠ʼi֗yş̌ ya֣ẖad pĕ̇néֽy-réʻéֽ⁠hẇ׃"],[27,18,"נֹצֵ֣ר תְּ֭אֵנָה יֹאכַ֣ל פִּרְיָ֑⁠הּ וְ⁠שֹׁמֵ֖ר אֲדֹנָ֣י⁠ו יְכֻבָּֽד׃","nòẕé֣r ţĕ֭̇ʼénáh yòʼka֣l pi̇rĕyá֑⁠ḣ wĕ⁠şò̌mé֖r ʼàdòná֣y⁠w yĕkubáֽ̇d׃"],[27,19,"כַּ֭⁠מַּיִם הַ⁠פָּנִ֣ים לַ⁠פָּנִ֑ים כֵּ֤ן לֵֽב־הָ֝⁠אָדָ֗ם לָ⁠אָדָֽם׃","kȧ֭⁠mȧyim ha⁠pá̇ni֣ym la⁠pá̇ni֑ym ké֤̇n léֽb-há֝⁠ʼádá֗m lá⁠ʼádáֽm׃"],[27,20,"שְׁא֣וֹל ו⁠אבדה לֹ֣א תִשְׂבַּ֑עְנָה וְ⁠עֵינֵ֥י הָ֝⁠אָדָ֗ם לֹ֣א תִשְׂבַּֽעְנָה׃","şĕ̌ʼ֣wòl w⁠ʼbdh lò֣ʼ ţişĕ̂bȧ֑ʻĕnáh wĕ⁠ʻéyné֥y há֝⁠ʼádá֗m lò֣ʼ ţişĕ̂bȧֽʻĕnáh׃"],[27,21,"מַצְרֵ֣ף לַ֭⁠כֶּסֶף וְ⁠כ֣וּר לַ⁠זָּהָ֑ב וְ֝⁠אִ֗ישׁ לְ⁠פִ֣י מַהֲלָלֽ⁠וֹ׃","maẕĕré֣p la֭⁠kėsep wĕ⁠k֣ẇr la⁠zá̇há֑b wĕ֝⁠ʼi֗yş̌ lĕ⁠pi֣y mahàlálֽ⁠wò׃"],[27,22,"אִ֥ם תִּכְתּֽוֹשׁ־אֶת־הָ⁠אֱוִ֨יל ׀ בַּֽ⁠מַּכְתֵּ֡שׁ בְּ⁠ת֣וֹךְ הָ֭⁠רִיפוֹת בַּֽ⁠עֱלִ֑י לֹא־תָס֥וּר מֵ֝⁠עָלָ֗י⁠ו אִוַּלְתּֽ⁠וֹ׃פ","ʼi֥m ţi̇kĕţֽ̇wòş̌-ʼeţ-há⁠ʼèwi֨yl ׀ bȧֽ⁠mȧkĕţé̇֡ş̌ bĕ̇⁠ţ֣wòkĕ há֭⁠riypwòţ bȧֽ⁠ʻèli֑y lòʼ-ţás֥ẇr mé֝⁠ʻálá֗y⁠w ʼiwȧlĕţֽ̇⁠wò׃p"],[27,23,"יָדֹ֣עַ תֵּ֭דַע פְּנֵ֣י צֹאנֶ֑⁠ךָ שִׁ֥ית לִ֝בְּ⁠ךָ֗ לַ⁠עֲדָרִֽים׃","yádò֣ʻa ţé֭̇daʻ pĕ̇né֣y ẕòʼne֑⁠ká şǐ֥yţ li֝bĕ̇⁠ká֗ la⁠ʻàdáriֽym׃"],[27,24,"כִּ֤י לֹ֣א לְ⁠עוֹלָ֣ם חֹ֑סֶן וְ⁠אִם־נֵ֝֗זֶר לְ⁠ד֣וֹר דור׃","ki֤̇y lò֣ʼ lĕ⁠ʻwòlá֣m ẖò֑sen wĕ⁠ʼim-né֝֗zer lĕ⁠d֣wòr dwr׃"],[27,25,"גָּלָ֣ה חָ֭צִיר וְ⁠נִרְאָה־דֶ֑שֶׁא וְ֝⁠נֶאֶסְפ֗וּ עִשְּׂב֥וֹת הָרִֽים׃","gá̇lá֣h ẖá֭ẕiyr wĕ⁠nirĕʼáh-de֑şěʼ wĕ֝⁠neʼesĕp֗ẇ ʻişĕ̇̂b֥wòţ háriֽym׃"],[27,26,"כְּבָשִׂ֥ים לִ⁠לְבוּשֶׁ֑⁠ךָ וּ⁠מְחִ֥יר שָׂ֝דֶ֗ה עַתּוּדִֽים׃","kĕ̇báşî֥ym li⁠lĕbẇşě֑⁠ká ẇ⁠mĕẖi֥yr şá̂֝de֗h ʻaţ̇ẇdiֽym׃"],[27,27,"וְ⁠דֵ֤י ׀ חֲלֵ֬ב עִזִּ֗ים לְֽ֭⁠לַחְמְ⁠ךָ לְ⁠לֶ֣חֶם בֵּיתֶ֑⁠ךָ וְ֝⁠חַיִּ֗ים לְ⁠נַעֲרוֹתֶֽי⁠ךָ׃","wĕ⁠dé֤y ׀ ẖàlé֬b ʻizi̇֗ym lĕֽ֭⁠laẖĕmĕ⁠ká lĕ⁠le֣ẖem bé̇yţe֑⁠ká wĕ֝⁠ẖayi̇֗ym lĕ⁠naʻàrwòţeֽy⁠ká׃"],[28,1,"נָ֣סוּ וְ⁠אֵין־רֹדֵ֣ף רָשָׁ֑ע וְ֝⁠צַדִּיקִ֗ים כִּ⁠כְפִ֥יר יִבְטָֽח׃","ná֣sẇ wĕ⁠ʼéyn-ròdé֣p ráşá֑̌ʻ wĕ֝⁠ẕadi̇yqi֗ym ki̇⁠kĕpi֥yr yibĕtáֽẖ׃"],[28,2,"בְּ⁠פֶ֣שַֽׁע אֶ֭רֶץ רַבִּ֣ים שָׂרֶ֑י⁠הָ וּ⁠בְ⁠אָדָ֥ם מֵבִ֥ין יֹ֝דֵ֗עַ כֵּ֣ן יַאֲרִֽיךְ׃","bĕ̇⁠pe֣şǎֽʻ ʼe֭reẕ rabi֣̇ym şá̂re֑y⁠há ẇ⁠bĕ⁠ʼádá֥m mébi֥yn yò֝dé֗ʻa ké֣̇n yaʼàriֽykĕ׃"],[28,3,"גֶּ֣בֶר רָ֭שׁ וְ⁠עֹשֵׁ֣ק דַּלִּ֑ים מָטָ֥ר סֹ֝חֵ֗ף וְ⁠אֵ֣ין לָֽחֶם׃","gė֣ber rá֭ş̌ wĕ⁠ʻòşé֣̌q dȧli֑̇ym mátá֥r sò֝ẖé֗p wĕ⁠ʼé֣yn láֽẖem׃"],[28,4,"עֹזְבֵ֣י ת֭וֹרָה יְהַֽלְל֣וּ רָשָׁ֑ע וְ⁠שֹׁמְרֵ֥י ת֝וֹרָ֗ה יִתְגָּ֥רוּ בָֽ⁠ם׃פ","ʻòzĕbé֣y ţ֭wòráh yĕhaֽlĕl֣ẇ ráşá֑̌ʻ wĕ⁠şò̌mĕré֥y ţ֝wòrá֗h yiţĕgá֥̇rẇ báֽ⁠m׃p"],[28,5,"אַנְשֵׁי־רָ֭ע לֹא־יָבִ֣ינוּ מִשְׁפָּ֑ט וּ⁠מְבַקְשֵׁ֥י יְ֝הוָ֗ה יָבִ֥ינוּ כֹֽל׃","ʼanĕşé̌y-rá֭ʻ lòʼ-yábi֣ynẇ mişĕ̌pá֑̇t ẇ⁠mĕbaqĕşé֥̌y yĕ֝hwá֗h yábi֥ynẇ kòֽl׃"],[28,6,"טֽוֹב־רָ֭שׁ הוֹלֵ֣ךְ בְּ⁠תֻמּ֑⁠וֹ מֵ⁠עִקֵּ֥שׁ דְּ֝רָכַ֗יִם וְ⁠ה֣וּא עָשִֽׁיר׃","tֽwòb-rá֭ş̌ hwòlé֣kĕ bĕ̇⁠ţuṁ֑⁠wò mé⁠ʻiqé֥̇ş̌ dĕ̇֝ráka֗yim wĕ⁠h֣ẇʼ ʻáşǐֽyr׃"],[28,7,"נוֹצֵ֣ר תּ֭וֹרָה בֵּ֣ן מֵבִ֑ין וְ⁠רֹעֶה זֽ֝וֹלְלִ֗ים יַכְלִ֥ים אָבִֽי⁠ו׃","nwòẕé֣r ţ֭̇wòráh bé֣̇n mébi֑yn wĕ⁠ròʻeh zֽ֝wòlĕli֗ym yakĕli֥ym ʼábiֽy⁠w׃"],[28,8,"מַרְבֶּ֣ה ה֭וֹנ⁠וֹ בְּ⁠נֶ֣שֶׁךְ ו⁠ב⁠תרבית לְ⁠חוֹנֵ֖ן דַּלִּ֣ים יִקְבְּצֶֽ⁠נּוּ׃","marĕbė֣h h֭wòn⁠wò bĕ̇⁠ne֣şěkĕ w⁠b⁠ţrbyţ lĕ⁠ẖwòné֖n dȧli֣̇ym yiqĕbĕ̇ẕeֽ⁠ṅẇ׃"],[28,9,"מֵסִ֣יר אָ֭זְנ⁠וֹ מִ⁠שְּׁמֹ֣עַ תּוֹרָ֑ה גַּֽם־תְּ֝פִלָּת֗⁠וֹ תּוֹעֵבָֽה׃","mési֣yr ʼá֭zĕn⁠wò mi⁠şĕ̇̌mò֣ʻa ţ̇wòrá֑h gȧֽm-ţĕ̇֝pilá̇ţ֗⁠wò ţ̇wòʻébáֽh׃"],[28,10,"מַשְׁגֶּ֤ה יְשָׁרִ֨ים ׀ בְּ⁠דֶ֥רֶךְ רָ֗ע בִּ⁠שְׁחוּת֥⁠וֹ הֽוּא־יִפּ֑וֹל וּ֝⁠תְמִימִ֗ים יִנְחֲלוּ־טֽוֹב׃","maşĕ̌gė֤h yĕşá̌ri֨ym ׀ bĕ̇⁠de֥rekĕ rá֗ʻ bi̇⁠şĕ̌ẖẇţ֥⁠wò hֽẇʼ-yiṗ֑wòl ẇ֝⁠ţĕmiymi֗ym yinĕẖàlẇ-tֽwòb׃"],[28,11,"חָכָ֣ם בְּ֭⁠עֵינָי⁠ו אִ֣ישׁ עָשִׁ֑יר וְ⁠דַ֖ל מֵבִ֣ין יַחְקְרֶֽ⁠נּוּ׃","ẖáká֣m bĕ֭̇⁠ʻéynáy⁠w ʼi֣yş̌ ʻáşǐ֑yr wĕ⁠da֖l mébi֣yn yaẖĕqĕreֽ⁠ṅẇ׃"],[28,12,"בַּ⁠עֲלֹ֣ץ צַ֭דִּיקִים רַבָּ֣ה תִפְאָ֑רֶת וּ⁠בְ⁠ק֥וּם רְ֝שָׁעִ֗ים יְחֻפַּ֥שׂ אָדָֽם׃","bȧ⁠ʻàlò֣ẕ ẕa֭di̇yqiym rabá֣̇h ţipĕʼá֑reţ ẇ⁠bĕ⁠q֥ẇm rĕ֝şá̌ʻi֗ym yĕẖupȧ֥ş̂ ʼádáֽm׃"],[28,13,"מְכַסֶּ֣ה פְ֭שָׁעָי⁠ו לֹ֣א יַצְלִ֑יחַ וּ⁠מוֹדֶ֖ה וְ⁠עֹזֵ֣ב יְרֻחָֽם׃","mĕkasė֣h pĕ֭şá̌ʻáy⁠w lò֣ʼ yaẕĕli֑yẖa ẇ⁠mwòde֖h wĕ⁠ʻòzé֣b yĕruẖáֽm׃"],[28,14,"אַשְׁרֵ֣י אָ֭דָם מְפַחֵ֣ד תָּמִ֑יד וּ⁠מַקְשֶׁ֥ה לִ֝בּ֗⁠וֹ יִפּ֥וֹל בְּ⁠רָעָֽה׃","ʼaşĕ̌ré֣y ʼá֭dám mĕpaẖé֣d ţá̇mi֑yd ẇ⁠maqĕşě֥h li֝ḃ֗⁠wò yiṗ֥wòl bĕ̇⁠ráʻáֽh׃"],[28,15,"אֲרִי־נֹ֭הֵם וְ⁠דֹ֣ב שׁוֹקֵ֑ק מֹשֵׁ֥ל רָ֝שָׁ֗ע עַ֣ל עַם־דָּֽל׃","ʼàriy-nò֭hém wĕ⁠dò֣b ş̌wòqé֑q mòşé֥̌l rá֝şá̌֗ʻ ʻa֣l ʻam-dáֽ̇l׃"],[28,16,"נָגִ֗יד חֲסַ֣ר תְּ֭בוּנוֹת וְ⁠רַ֥ב מַעֲשַׁקּ֑וֹת שנאי בֶ֝֗צַע יַאֲרִ֥יךְ יָמִֽים׃פ","nági֗yd ẖàsa֣r ţĕ֭̇bẇnwòţ wĕ⁠ra֥b maʻàşǎq֑̇wòţ şnʼy be֝֗ẕaʻ yaʼàri֥ykĕ yámiֽym׃p"],[28,17,"אָ֭דָם עָשֻׁ֣ק בְּ⁠דַם־נָפֶשׁ עַד־בּ֥וֹר יָ֝נ֗וּס אַל־יִתְמְכוּ־בֽ⁠וֹ׃","ʼá֭dám ʻáşǔ֣q bĕ̇⁠dam-nápeş̌ ʻad-ḃ֥wòr yá֝n֗ẇs ʼal-yiţĕmĕkẇ-bֽ⁠wò׃"],[28,18,"הוֹלֵ֣ךְ תָּ֭מִים יִוָּשֵׁ֑עַ וְ⁠נֶעְקַ֥שׁ דְּ֝רָכַ֗יִם יִפּ֥וֹל בְּ⁠אֶחָֽת׃","hwòlé֣kĕ ţá֭̇miym yiwá̇şé֑̌ʻa wĕ⁠neʻĕqa֥ş̌ dĕ̇֝ráka֗yim yiṗ֥wòl bĕ̇⁠ʼeẖáֽţ׃"],[28,19,"עֹבֵ֣ד אַ֭דְמָת⁠וֹ יִֽשְׂבַּֽע־לָ֑חֶם וּ⁠מְרַדֵּ֥ף רֵ֝קִ֗ים יִֽשְׂבַּֽע־רִֽישׁ׃","ʻòbé֣d ʼa֭dĕmáţ⁠wò yiֽşĕ̂bȧֽʻ-lá֑ẖem ẇ⁠mĕradé֥̇p ré֝qi֗ym yiֽşĕ̂bȧֽʻ-riֽyş̌׃"],[28,20,"אִ֣ישׁ אֱ֭מוּנוֹת רַב־בְּרָכ֑וֹת וְ⁠אָ֥ץ לְ֝⁠הַעֲשִׁ֗יר לֹ֣א יִנָּקֶֽה׃","ʼi֣yş̌ ʼè֭mẇnwòţ rab-bĕ̇rák֑wòţ wĕ⁠ʼá֥ẕ lĕ֝⁠haʻàşǐ֗yr lò֣ʼ yiná̇qeֽh׃"],[28,21,"הַֽכֵּר־פָּנִ֥ים לֹא־ט֑וֹב וְ⁠עַל־פַּת־לֶ֝֗חֶם יִפְשַׁע־גָּֽבֶר׃","haֽké̇r-pá̇ni֥ym lòʼ-t֑wòb wĕ⁠ʻal-pȧţ-le֝֗ẖem yipĕşǎʻ-gáֽ̇ber׃"],[28,22,"נִֽבֳהָ֥ל לַ⁠ה֗וֹן אִ֭ישׁ רַ֣ע עָ֑יִן וְ⁠לֹֽא־יֵ֝דַע כִּי־חֶ֥סֶר יְבֹאֶֽ⁠נּוּ׃","niֽbohá֥l la⁠h֗wòn ʼi֭yş̌ ra֣ʻ ʻá֑yin wĕ⁠lòֽʼ-yé֝daʻ ki̇y-ẖe֥ser yĕbòʼeֽ⁠ṅẇ׃"],[28,23,"מ֘וֹכִ֤יחַ אָדָ֣ם אַ֭חֲרַי חֵ֣ן יִמְצָ֑א מִֽ⁠מַּחֲלִ֥יק לָשֽׁוֹן׃","m֘wòki֤yẖa ʼádá֣m ʼa֭ẖàray ẖé֣n yimĕẕá֑ʼ miֽ⁠mȧẖàli֥yq láşֽ̌wòn׃"],[28,24,"גּוֹזֵ֤ל ׀ אָ֘בִ֤י⁠ו וְ⁠אִמּ֗⁠וֹ וְ⁠אֹמֵ֥ר אֵֽין־פָּ֑שַׁע חָבֵ֥ר ה֝֗וּא לְ⁠אִ֣ישׁ מַשְׁחִֽית׃","ġwòzé֤l ׀ ʼá֘bi֤y⁠w wĕ⁠ʼiṁ֗⁠wò wĕ⁠ʼòmé֥r ʼéֽyn-pá֑̇şǎʻ ẖábé֥r h֝֗ẇʼ lĕ⁠ʼi֣yş̌ maşĕ̌ẖiֽyţ׃"],[28,25,"רְחַב־נֶ֭פֶשׁ יְגָרֶ֣ה מָד֑וֹן וּ⁠בוֹטֵ֖חַ עַל־יְהוָ֣ה יְדֻשָּֽׁן׃","rĕẖab-ne֭peş̌ yĕgáre֣h mád֑wòn ẇ⁠bwòté֖ẖa ʻal-yĕhwá֣h yĕduşáֽ̇̌n׃"],[28,26,"בּוֹטֵ֣חַ בְּ֭⁠לִבּ⁠וֹ ה֣וּא כְסִ֑יל וְ⁠הוֹלֵ֥ךְ בְּ֝⁠חָכְמָ֗ה ה֣וּא יִמָּלֵֽט׃","ḃwòté֣ẖa bĕ֭̇⁠liḃ⁠wò h֣ẇʼ kĕsi֑yl wĕ⁠hwòlé֥kĕ bĕ̇֝⁠ẖákĕmá֗h h֣ẇʼ yimá̇léֽt׃"],[28,27,"נוֹתֵ֣ן לָ֭⁠רָשׁ אֵ֣ין מַחְס֑וֹר וּ⁠מַעְלִ֥ים עֵ֝ינָ֗י⁠ו רַב־מְאֵרֽוֹת׃","nwòţé֣n lá֭⁠ráş̌ ʼé֣yn maẖĕs֑wòr ẇ⁠maʻĕli֥ym ʻé֝yná֗y⁠w rab-mĕʼérֽwòţ׃"],[28,28,"בְּ⁠ק֣וּם רְ֭שָׁעִים יִסָּתֵ֣ר אָדָ֑ם וּ֝⁠בְ⁠אָבְדָ֗⁠ם יִרְבּ֥וּ צַדִּיקִֽים׃","bĕ̇⁠q֣ẇm rĕ֭şá̌ʻiym yisá̇ţé֣r ʼádá֑m ẇ֝⁠bĕ⁠ʼábĕdá֗⁠m yirĕḃ֥ẇ ẕadi̇yqiֽym׃"],[29,1,"אִ֣ישׁ תּ֭וֹכָחוֹת מַקְשֶׁה־עֹ֑רֶף פֶּ֥תַע יִ֝שָּׁבֵ֗ר וְ⁠אֵ֣ין מַרְפֵּֽא׃","ʼi֣yş̌ ţ֭̇wòkáẖwòţ maqĕşěh-ʻò֑rep pė֥ţaʻ yi֝şá̇̌bé֗r wĕ⁠ʼé֣yn marĕpéֽ̇ʼ׃"],[29,2,"בִּ⁠רְב֣וֹת צַ֭דִּיקִים יִשְׂמַ֣ח הָ⁠עָ֑ם וּ⁠בִ⁠מְשֹׁ֥ל רָ֝שָׁ֗ע יֵאָ֥נַֽח עָֽם׃","bi̇⁠rĕb֣wòţ ẕa֭di̇yqiym yişĕ̂ma֣ẖ há⁠ʻá֑m ẇ⁠bi⁠mĕşò֥̌l rá֝şá̌֗ʻ yéʼá֥naֽẖ ʻáֽm׃"],[29,3,"אִֽישׁ־אֹהֵ֣ב חָ֭כְמָה יְשַׂמַּ֣ח אָבִ֑י⁠ו וְ⁠רֹעֶ֥ה ז֝וֹנ֗וֹת יְאַבֶּד־הֽוֹן׃","ʼiֽyş̌-ʼòhé֣b ẖá֭kĕmáh yĕşâmȧ֣ẖ ʼábi֑y⁠w wĕ⁠ròʻe֥h z֝wòn֗wòţ yĕʼabėd-hֽwòn׃"],[29,4,"מֶ֗לֶךְ בְּ֭⁠מִשְׁפָּט יַעֲמִ֣יד אָ֑רֶץ וְ⁠אִ֖ישׁ תְּרוּמ֣וֹת יֶֽהֶרְסֶֽ⁠נָּה׃","me֗lekĕ bĕ֭̇⁠mişĕ̌pá̇t yaʻàmi֣yd ʼá֑reẕ wĕ⁠ʼi֖yş̌ ţĕ̇rẇm֣wòţ yeֽherĕseֽ⁠ná̇h׃"],[29,5,"גֶּ֭בֶר מַחֲלִ֣יק עַל־רֵעֵ֑⁠הוּ רֶ֝֗שֶׁת פּוֹרֵ֥שׂ עַל־פְּעָמָֽי⁠ו׃","gė֭ber maẖàli֣yq ʻal-réʻé֑⁠hẇ re֝֗şěţ ṗwòré֥ş̂ ʻal-pĕ̇ʻámáֽy⁠w׃"],[29,6,"בְּ⁠פֶ֤שַֽׁע אִ֣ישׁ רָ֣ע מוֹקֵ֑שׁ וְ֝⁠צַדִּ֗יק יָר֥וּן וְ⁠שָׂמֵֽחַ׃","bĕ̇⁠pe֤şǎֽʻ ʼi֣yş̌ rá֣ʻ mwòqé֑ş̌ wĕ֝⁠ẕadi̇֗yq yár֥ẇn wĕ⁠şá̂méֽẖa׃"],[29,7,"יֹדֵ֣עַ צַ֭דִּיק דִּ֣ין דַּלִּ֑ים רָ֝שָׁ֗ע לֹא־יָבִ֥ין דָּֽעַת׃","yòdé֣ʻa ẕa֭di̇yq di֣̇yn dȧli֑̇ym rá֝şá̌֗ʻ lòʼ-yábi֥yn dáֽ̇ʻaţ׃"],[29,8,"אַנְשֵׁ֣י לָ֭צוֹן יָפִ֣יחוּ קִרְיָ֑ה וַ֝⁠חֲכָמִ֗ים יָשִׁ֥יבוּ אָֽף׃","ʼanĕşé֣̌y lá֭ẕwòn yápi֣yẖẇ qirĕyá֑h wa֝⁠ẖàkámi֗ym yáşǐ֥ybẇ ʼáֽp׃"],[29,9,"אִֽישׁ־חָכָ֗ם נִ֭שְׁפָּט אֶת־אִ֣ישׁ אֱוִ֑יל וְ⁠רָגַ֥ז וְ֝⁠שָׂחַ֗ק וְ⁠אֵ֣ין נָֽחַת׃","ʼiֽyş̌-ẖáká֗m ni֭şĕ̌pá̇t ʼeţ-ʼi֣yş̌ ʼèwi֑yl wĕ⁠rága֥z wĕ֝⁠şá̂ẖa֗q wĕ⁠ʼé֣yn náֽẖaţ׃"],[29,10,"אַנְשֵׁ֣י דָ֭מִים יִשְׂנְאוּ־תָ֑ם וִֽ֝⁠ישָׁרִ֗ים יְבַקְשׁ֥וּ נַפְשֽׁ⁠וֹ׃","ʼanĕşé֣̌y dá֭miym yişĕ̂nĕʼẇ-ţá֑m wiֽ֝⁠yşá̌ri֗ym yĕbaqĕş֥̌ẇ napĕşֽ̌⁠wò׃"],[29,11,"כָּל־ר֭וּח⁠וֹ יוֹצִ֣יא כְסִ֑יל וְ֝⁠חָכָ֗ם בְּ⁠אָח֥וֹר יְשַׁבְּחֶֽ⁠נָּה׃","ká̇l-r֭ẇẖ⁠wò ywòẕi֣yʼ kĕsi֑yl wĕ֝⁠ẖáká֗m bĕ̇⁠ʼáẖ֥wòr yĕşǎbĕ̇ẖeֽ⁠ná̇h׃"],[29,12,"מֹ֭שֵׁל מַקְשִׁ֣יב עַל־דְּבַר־שָׁ֑קֶר כָּֽל־מְשָׁרְתָ֥י⁠ו רְשָׁעִֽים׃","mò֭şé̌l maqĕşǐ֣yb ʻal-dĕ̇bar-şá֑̌qer káֽ̇l-mĕşá̌rĕţá֥y⁠w rĕşá̌ʻiֽym׃"],[29,13,"רָ֤שׁ וְ⁠אִ֣ישׁ תְּכָכִ֣ים נִפְגָּ֑שׁוּ מֵ֤אִיר־עֵינֵ֖י שְׁנֵי⁠הֶ֣ם יְהוָֽה׃","rá֤ş̌ wĕ⁠ʼi֣yş̌ ţĕ̇káki֣ym nipĕgá֑̇ş̌ẇ mé֤ʼiyr-ʻéyné֖y şĕ̌néy⁠he֣m yĕhwáֽh׃"],[29,14,"מֶ֤לֶךְ שׁוֹפֵ֣ט בֶּֽ⁠אֱמֶ֣ת דַּלִּ֑ים כִּ֝סְא֗⁠וֹ לָ⁠עַ֥ד יִכּֽוֹן׃","me֤lekĕ ş̌wòpé֣t bėֽ⁠ʼème֣ţ dȧli֑̇ym ki̇֝sĕʼ֗⁠wò lá⁠ʻa֥d yikֽ̇wòn׃"],[29,15,"שֵׁ֣בֶט וְ֭⁠תוֹכַחַת יִתֵּ֣ן חָכְמָ֑ה וְ⁠נַ֥עַר מְ֝שֻׁלָּ֗ח מֵבִ֥ישׁ אִמּֽ⁠וֹ׃","şé֣̌bet wĕ֭⁠ţwòkaẖaţ yiţé֣̇n ẖákĕmá֑h wĕ⁠na֥ʻar mĕ֝şǔlá̇֗ẖ mébi֥yş̌ ʼiṁֽ⁠wò׃"],[29,16,"בִּ⁠רְב֣וֹת רְ֭שָׁעִים יִרְבֶּה־פָּ֑שַׁע וְ֝⁠צַדִּיקִ֗ים בְּֽ⁠מַפַּלְתָּ֥⁠ם יִרְאֽוּ׃","bi̇⁠rĕb֣wòţ rĕ֭şá̌ʻiym yirĕbėh-pá֑̇şǎʻ wĕ֝⁠ẕadi̇yqi֗ym bĕֽ̇⁠mapȧlĕţá֥̇⁠m yirĕʼֽẇ׃"],[29,17,"יַסֵּ֣ר בִּ֭נְ⁠ךָ וִֽ⁠ינִיחֶ֑⁠ךָ וְ⁠יִתֵּ֖ן מַעֲדַנִּ֣ים לְ⁠נַפְשֶֽׁ⁠ךָ׃פ","yasé֣̇r bi֭̇nĕ⁠ká wiֽ⁠yniyẖe֑⁠ká wĕ⁠yiţé֖̇n maʻàdani֣̇ym lĕ⁠napĕşěֽ⁠ká׃p"],[29,18,"בְּ⁠אֵ֣ין חָ֭זוֹן יִפָּ֣רַֽע עָ֑ם וְ⁠שֹׁמֵ֖ר תּוֹרָ֣ה אַשְׁרֵֽ⁠הוּ׃","bĕ̇⁠ʼé֣yn ẖá֭zwòn yipá֣̇raֽʻ ʻá֑m wĕ⁠şò̌mé֖r ţ̇wòrá֣h ʼaşĕ̌réֽ⁠hẇ׃"],[29,19,"בִּ֭⁠דְבָרִים לֹא־יִוָּ֣סֶר עָ֑בֶד כִּֽי־יָ֝בִ֗ין וְ⁠אֵ֣ין מַעֲנֶֽה׃","bi֭̇⁠dĕbáriym lòʼ-yiwá֣̇ser ʻá֑bed kiֽ̇y-yá֝bi֗yn wĕ⁠ʼé֣yn maʻàneֽh׃"],[29,20,"חָזִ֗יתָ אִ֭ישׁ אָ֣ץ בִּ⁠דְבָרָ֑י⁠ו תִּקְוָ֖ה לִ⁠כְסִ֣יל מִמֶּֽ⁠נּוּ׃","ẖázi֗yţá ʼi֭yş̌ ʼá֣ẕ bi̇⁠dĕbárá֑y⁠w ţi̇qĕwá֖h li⁠kĕsi֣yl mimėֽ⁠ṅẇ׃"],[29,21,"מְפַנֵּ֣ק מִ⁠נֹּ֣עַר עַבְדּ֑⁠וֹ וְ֝⁠אַחֲרִית֗⁠וֹ יִהְיֶ֥ה מָנֽוֹן׃","mĕpané֣̇q mi⁠nò֣̇ʻar ʻabĕḋ֑⁠wò wĕ֝⁠ʼaẖàriyţ֗⁠wò yihĕye֥h mánֽwòn׃"],[29,22,"אִֽישׁ־אַ֭ף יְגָרֶ֣ה מָד֑וֹן וּ⁠בַ֖עַל חֵמָ֣ה רַב־פָּֽשַׁע׃","ʼiֽyş̌-ʼa֭p yĕgáre֣h mád֑wòn ẇ⁠ba֖ʻal ẖémá֣h rab-páֽ̇şǎʻ׃"],[29,23,"גַּאֲוַ֣ת אָ֭דָם תַּשְׁפִּילֶ֑⁠נּוּ וּ⁠שְׁפַל־ר֝֗וּחַ יִתְמֹ֥ךְ כָּבֽוֹד׃","gȧʼàwa֣ţ ʼá֭dám ţȧşĕ̌pi̇yle֑⁠ṅẇ ẇ⁠şĕ̌pal-r֝֗ẇẖa yiţĕmò֥kĕ ká̇bֽwòd׃"],[29,24,"חוֹלֵ֣ק עִם־גַּ֭נָּב שׂוֹנֵ֣א נַפְשׁ֑⁠וֹ אָלָ֥ה יִ֝שְׁמַ֗ע וְ⁠לֹ֣א יַגִּֽיד׃","ẖwòlé֣q ʻim-gȧ֭ná̇b ş̂wòné֣ʼ napĕş֑̌⁠wò ʼálá֥h yi֝şĕ̌ma֗ʻ wĕ⁠lò֣ʼ yagiֽ̇yd׃"],[29,25,"חֶרְדַּ֣ת אָ֭דָם יִתֵּ֣ן מוֹקֵ֑שׁ וּ⁠בוֹטֵ֖חַ בַּ⁠יהוָ֣ה יְשֻׂגָּֽב׃","ẖerĕdȧ֣ţ ʼá֭dám yiţé֣̇n mwòqé֑ş̌ ẇ⁠bwòté֖ẖa bȧ⁠yhwá֣h yĕşûgáֽ̇b׃"],[29,26,"רַ֭בִּים מְבַקְשִׁ֣ים פְּנֵי־מוֹשֵׁ֑ל וּ֝⁠מֵ⁠יְהוָ֗ה מִשְׁפַּט־אִֽישׁ׃","ra֭bi̇ym mĕbaqĕşǐ֣ym pĕ̇néy-mwòşé֑̌l ẇ֝⁠mé⁠yĕhwá֗h mişĕ̌pȧt-ʼiֽyş̌׃"],[29,27,"תּוֹעֲבַ֣ת צַ֭דִּיקִים אִ֣ישׁ עָ֑וֶל וְ⁠תוֹעֲבַ֖ת רָשָׁ֣ע יְשַׁר־דָּֽרֶךְ׃פ","ţ̇wòʻàba֣ţ ẕa֭di̇yqiym ʼi֣yş̌ ʻá֑wel wĕ⁠ţwòʻàba֖ţ ráşá֣̌ʻ yĕşǎr-dáֽ̇rekĕ׃p"],[30,1,"דִּבְרֵ֤י ׀ אָג֥וּר בִּן־יָקֶ֗ה הַ⁠מַּ֫שָּׂ֥א נְאֻ֣ם הַ֭⁠גֶּבֶר לְ⁠אִֽיתִיאֵ֑ל לְ⁠אִ֖יתִיאֵ֣ל וְ⁠אֻכָֽל׃","di̇bĕré֤y ׀ ʼág֥ẇr bi̇n-yáqe֗h ha⁠mȧ֫şá֥̇̂ʼ nĕʼu֣m ha֭⁠gėber lĕ⁠ʼiֽyţiyʼé֑l lĕ⁠ʼi֖yţiyʼé֣l wĕ⁠ʼukáֽl׃"],[30,2,"כִּ֤י בַ֣עַר אָנֹכִ֣י מֵ⁠אִ֑ישׁ וְ⁠לֹֽא־בִינַ֖ת אָדָ֣ם לִֽ⁠י׃","ki֤̇y ba֣ʻar ʼánòki֣y mé⁠ʼi֑yş̌ wĕ⁠lòֽʼ-biyna֖ţ ʼádá֣m liֽ⁠y׃"],[30,3,"וְ⁠לֹֽא־לָמַ֥דְתִּי חָכְמָ֑ה וְ⁠דַ֖עַת קְדֹשִׁ֣ים אֵדָֽע׃","wĕ⁠lòֽʼ-láma֥dĕţi̇y ẖákĕmá֑h wĕ⁠da֖ʻaţ qĕdòşǐ֣ym ʼédáֽʻ׃"],[30,4,"מִ֤י עָלָֽה־שָׁמַ֨יִם ׀ וַ⁠יֵּרַ֡ד מִ֤י אָֽסַף־ר֨וּחַ ׀ בְּ⁠חָפְנָ֡י⁠ו מִ֤י צָֽרַר־מַ֨יִם ׀ בַּ⁠שִּׂמְלָ֗ה מִ֭י הֵקִ֣ים כָּל־אַפְסֵי־אָ֑רֶץ מַה־שְּׁמ֥⁠וֹ וּ⁠מַֽה־שֶּׁם־בְּ֝נ֗⁠וֹ כִּ֣י תֵדָֽע׃","mi֤y ʻáláֽh-şá̌ma֨yim ׀ wa⁠yé̇ra֡d mi֤y ʼáֽsap-r֨ẇẖa ׀ bĕ̇⁠ẖápĕná֡y⁠w mi֤y ẕáֽrar-ma֨yim ׀ bȧ⁠şi̇̂mĕlá֗h mi֭y héqi֣ym ká̇l-ʼapĕséy-ʼá֑reẕ mah-şĕ̇̌m֥⁠wò ẇ⁠maֽh-şė̌m-bĕ̇֝n֗⁠wò ki֣̇y ţédáֽʻ׃"],[30,5,"כָּל־אִמְרַ֣ת אֱל֣וֹהַּ צְרוּפָ֑ה מָגֵ֥ן ה֝֗וּא לַֽ⁠חֹסִ֥ים בּֽ⁠וֹ׃","ká̇l-ʼimĕra֣ţ ʼèl֣wòhȧ ẕĕrẇpá֑h mágé֥n h֝֗ẇʼ laֽ⁠ẖòsi֥ym ḃֽ⁠wò׃"],[30,6,"אַל־תּ֥וֹסְףְּ עַל־דְּבָרָ֑י⁠ו פֶּן־יוֹכִ֖יחַ בְּ⁠ךָ֣ וְ⁠נִכְזָֽבְתָּ׃פ","ʼal-ţ֥̇wòsĕpĕ̇ ʻal-dĕ̇bárá֑y⁠w pėn-ywòki֖yẖa bĕ̇⁠ká֣ wĕ⁠nikĕzáֽbĕţá̇׃p"],[30,7,"שְׁ֭תַּיִם שָׁאַ֣לְתִּי מֵ⁠אִתָּ֑⁠ךְ אַל־תִּמְנַ֥ע מִ֝מֶּ֗⁠נִּי בְּ⁠טֶ֣רֶם אָמֽוּת׃","şĕ֭̌ţȧyim şá̌ʼa֣lĕţi̇y mé⁠ʼiţá֑̇⁠kĕ ʼal-ţi̇mĕna֥ʻ mi֝mė֗⁠ni̇y bĕ̇⁠te֣rem ʼámֽẇţ׃"],[30,8,"שָׁ֤וְא ׀ וּֽ⁠דְבַר־כָּזָ֡ב הַרְחֵ֬ק מִמֶּ֗⁠נִּי רֵ֣אשׁ וָ֭⁠עֹשֶׁר אַל־תִּֽתֶּן־לִ֑⁠י הַ֝טְרִיפֵ֗⁠נִי לֶ֣חֶם חֻקִּֽ⁠י׃","şá֤̌wĕʼ ׀ ẇֽ⁠dĕbar-ká̇zá֡b harĕẖé֬q mimė֗⁠ni̇y ré֣ʼş̌ wá֭⁠ʻòşěr ʼal-ţiֽ̇ţėn-li֑⁠y ha֝tĕriypé֗⁠niy le֣ẖem ẖuqiֽ̇⁠y׃"],[30,9,"פֶּ֥ן אֶשְׂבַּ֨ע ׀ וְ⁠כִחַשְׁתִּי֮ וְ⁠אָמַ֗רְתִּי מִ֥י יְה֫וָ֥ה וּ⁠פֶֽן־אִוָּרֵ֥שׁ וְ⁠גָנַ֑בְתִּי וְ֝⁠תָפַ֗שְׂתִּי שֵׁ֣ם אֱלֹהָֽ⁠י׃פ","pė֥n ʼeşĕ̂bȧ֨ʻ ׀ wĕ⁠kiẖaşĕ̌ţi̇y֮ wĕ⁠ʼáma֗rĕţi̇y mi֥y yĕh֫wá֥h ẇ⁠peֽn-ʼiwá̇ré֥ş̌ wĕ⁠gána֑bĕţi̇y wĕ֝⁠ţápa֗şĕ̂ţi̇y şé֣̌m ʼèlòháֽ⁠y׃p"],[30,10,"אַל־תַּלְשֵׁ֣ן עֶ֭בֶד אֶל־אדנ⁠ו פֶּֽן־יְקַלֶּלְ⁠ךָ֥ וְ⁠אָשָֽׁמְתָּ׃","ʼal-ţȧlĕşé֣̌n ʻe֭bed ʼel-ʼdn⁠w pėֽn-yĕqalėlĕ⁠ká֥ wĕ⁠ʼáşáֽ̌mĕţá̇׃"],[30,11,"דּ֭וֹר אָבִ֣י⁠ו יְקַלֵּ֑ל וְ⁠אֶת־אִ֝מּ֗⁠וֹ לֹ֣א יְבָרֵֽךְ׃","ḋ֭wòr ʼábi֣y⁠w yĕqalé֑̇l wĕ⁠ʼeţ-ʼi֝ṁ֗⁠wò lò֣ʼ yĕbáréֽkĕ׃"],[30,12,"דּ֭וֹר טָה֣וֹר בְּ⁠עֵינָ֑י⁠ו וּ֝⁠מִ⁠צֹּאָת֗⁠וֹ לֹ֣א רֻחָֽץ׃","ḋ֭wòr táh֣wòr bĕ̇⁠ʻéyná֑y⁠w ẇ֝⁠mi⁠ẕò̇ʼáţ֗⁠wò lò֣ʼ ruẖáֽẕ׃"],[30,13,"דּ֭וֹר מָה־רָמ֣וּ עֵינָ֑י⁠ו וְ֝⁠עַפְעַפָּ֗י⁠ו יִנָּשֵֽׂאוּ׃","ḋ֭wòr máh-rám֣ẇ ʻéyná֑y⁠w wĕ֝⁠ʻapĕʻapá̇֗y⁠w yiná̇şéֽ̂ʼẇ׃"],[30,14,"דּ֤וֹר ׀ חֲרָב֣וֹת שִׁנָּי⁠ו֮ וּֽ⁠מַאֲכָל֪וֹת מְֽתַלְּעֹ֫תָ֥י⁠ו לֶ⁠אֱכֹ֣ל עֲנִיִּ֣ים מֵ⁠אֶ֑רֶץ וְ֝⁠אֶבְיוֹנִ֗ים מֵ⁠אָדָֽם׃פ","ḋ֤wòr ׀ ẖàráb֣wòţ şǐná̇y⁠w֮ ẇֽ⁠maʼàkál֪wòţ mĕֽţalĕ̇ʻò֫ţá֥y⁠w le⁠ʼèkò֣l ʻàniyi֣̇ym mé⁠ʼe֑reẕ wĕ֝⁠ʼebĕywòni֗ym mé⁠ʼádáֽm׃p"],[30,15,"לַֽ⁠עֲלוּקָ֨ה ׀ שְׁתֵּ֥י בָנוֹת֮ הַ֤ב ׀ הַ֥ב שָׁל֣וֹשׁ הֵ֭נָּה לֹ֣א תִשְׂבַּ֑עְנָה אַ֝רְבַּ֗ע לֹא־אָ֥מְרוּ הֽוֹן׃","laֽ⁠ʻàlẇqá֨h ׀ şĕ̌ţé֥̇y bánwòţ֮ ha֤b ׀ ha֥b şá̌l֣wòş̌ hé֭ná̇h lò֣ʼ ţişĕ̂bȧ֑ʻĕnáh ʼa֝rĕbȧ֗ʻ lòʼ-ʼá֥mĕrẇ hֽwòn׃"],[30,16,"שְׁאוֹל֮ וְ⁠עֹ֪צֶ֫ר רָ֥חַם אֶ֭רֶץ לֹא־שָׂ֣בְעָה מַּ֑יִם וְ֝⁠אֵ֗שׁ לֹא־אָ֥מְרָה הֽוֹן׃","şĕ̌ʼwòl֮ wĕ⁠ʻò֪ẕe֫r rá֥ẖam ʼe֭reẕ lòʼ-şá֣̂bĕʻáh mȧ֑yim wĕ֝⁠ʼé֗ş̌ lòʼ-ʼá֥mĕráh hֽwòn׃"],[30,17,"עַ֤יִן ׀ תִּֽלְעַ֣ג לְ⁠אָב֮ וְ⁠תָב֪וּז לִֽ⁠יקֲּהַ֫ת־אֵ֥ם יִקְּר֥וּ⁠הָ עֹרְבֵי־נַ֑חַל וְֽ⁠יֹאכְל֥וּ⁠הָ בְנֵי־נָֽשֶׁר׃פ","ʻa֤yin ׀ ţiֽ̇lĕʻa֣g lĕ⁠ʼáb֮ wĕ⁠ţáb֪ẇz liֽ⁠yqà̇ha֫ţ-ʼé֥m yiqĕ̇r֥ẇ⁠há ʻòrĕbéy-na֑ẖal wĕֽ⁠yòʼkĕl֥ẇ⁠há bĕnéy-náֽşěr׃p"],[30,18,"שְׁלֹשָׁ֣ה הֵ֭מָּה נִפְלְא֣וּ מִמֶּ֑⁠נִּי ו⁠ארבע לֹ֣א יְדַעְתִּֽי⁠ם׃","şĕ̌lòşá֣̌h hé֭má̇h nipĕlĕʼ֣ẇ mimė֑⁠ni̇y w⁠ʼrbʻ lò֣ʼ yĕdaʻĕţiֽ̇y⁠m׃"],[30,19,"דֶּ֤רֶךְ הַ⁠נֶּ֨שֶׁר ׀ בַּ⁠שָּׁמַיִם֮ דֶּ֥רֶךְ נָחָ֗שׁ עֲלֵ֫י צ֥וּר דֶּֽרֶךְ־אֳנִיָּ֥ה בְ⁠לֶב־יָ֑ם וְ⁠דֶ֖רֶךְ גֶּ֣בֶר בְּ⁠עַלְמָֽה׃","dė֤rekĕ ha⁠nė֨şěr ׀ bȧ⁠şá̇̌mayim֮ dė֥rekĕ náẖá֗ş̌ ʻàlé֫y ẕ֥ẇr dėֽrekĕ-ʼoniyá֥̇h bĕ⁠leb-yá֑m wĕ⁠de֖rekĕ gė֣ber bĕ̇⁠ʻalĕmáֽh׃"],[30,20,"כֵּ֤ן ׀ דֶּ֥רֶךְ אִשָּׁ֗ה מְנָ֫אָ֥פֶת אָ֭כְלָה וּ⁠מָ֣חֲתָה פִ֑י⁠הָ וְ֝⁠אָמְרָ֗ה לֹֽא־פָעַ֥לְתִּי אָֽוֶן׃פ","ké֤̇n ׀ dė֥rekĕ ʼişá̇̌֗h mĕná֫ʼá֥peţ ʼá֭kĕláh ẇ⁠má֣ẖàţáh pi֑y⁠há wĕ֝⁠ʼámĕrá֗h lòֽʼ-páʻa֥lĕţi̇y ʼáֽwen׃p"],[30,21,"תַּ֣חַת שָׁ֭לוֹשׁ רָ֣גְזָה אֶ֑רֶץ וְ⁠תַ֥חַת אַ֝רְבַּ֗ע לֹא־תוּכַ֥ל שְׂאֵֽת׃","ţȧ֣ẖaţ şá֭̌lwòş̌ rá֣gĕzáh ʼe֑reẕ wĕ⁠ţa֥ẖaţ ʼa֝rĕbȧ֗ʻ lòʼ-ţẇka֥l şĕ̂ʼéֽţ׃"],[30,22,"תַּֽחַת־עֶ֭בֶד כִּ֣י יִמְל֑וֹךְ וְ֝⁠נָבָ֗ל כִּ֣י יִֽשְׂבַּֽע־לָֽחֶם׃","ţȧֽẖaţ-ʻe֭bed ki֣̇y yimĕl֑wòkĕ wĕ֝⁠nábá֗l ki֣̇y yiֽşĕ̂bȧֽʻ-láֽẖem׃"],[30,23,"תַּ֣חַת שְׂ֭נוּאָה כִּ֣י תִבָּעֵ֑ל וְ֝⁠שִׁפְחָ֗ה כִּֽי־תִירַ֥שׁ גְּבִרְתָּֽ⁠הּ׃פ","ţȧ֣ẖaţ şĕ֭̂nẇʼáh ki֣̇y ţibá̇ʻé֑l wĕ֝⁠şǐpĕẖá֗h kiֽ̇y-ţiyra֥ş̌ gĕ̇birĕţáֽ̇⁠ḣ׃p"],[30,24,"אַרְבָּ֣עָה הֵ֭ם קְטַנֵּי־אָ֑רֶץ וְ֝⁠הֵ֗מָּה חֲכָמִ֥ים מְחֻכָּמִֽים׃","ʼarĕbá֣̇ʻáh hé֭m qĕtané̇y-ʼá֑reẕ wĕ֝⁠hé֗má̇h ẖàkámi֥ym mĕẖuká̇miֽym׃"],[30,25,"הַ֭⁠נְּמָלִים עַ֣ם לֹא־עָ֑ז וַ⁠יָּכִ֖ינוּ בַ⁠קַּ֣יִץ לַחְמָֽ⁠ם׃","ha֭⁠nĕ̇máliym ʻa֣m lòʼ-ʻá֑z wa⁠yá̇ki֖ynẇ ba⁠qȧ֣yiẕ laẖĕmáֽ⁠m׃"],[30,26,"שְׁ֭פַנִּים עַ֣ם לֹא־עָצ֑וּם וַ⁠יָּשִׂ֖ימוּ בַ⁠סֶּ֣לַע בֵּיתָֽ⁠ם׃","şĕ֭̌pani̇ym ʻa֣m lòʼ-ʻáẕ֑ẇm wa⁠yá̇şî֖ymẇ ba⁠sė֣laʻ bé̇yţáֽ⁠m׃"],[30,27,"מֶ֭לֶךְ אֵ֣ין לָ⁠אַרְבֶּ֑ה וַ⁠יֵּצֵ֖א חֹצֵ֣ץ כֻּלּֽ⁠וֹ׃","me֭lekĕ ʼé֣yn lá⁠ʼarĕbė֑h wa⁠yé̇ẕé֖ʼ ẖòẕé֣ẕ ku̇lֽ̇⁠wò׃"],[30,28,"שְׂ֭מָמִית בְּ⁠יָדַ֣יִם תְּתַפֵּ֑שׂ וְ֝⁠הִ֗יא בְּ⁠הֵ֣יכְלֵי מֶֽלֶךְ׃פ","şĕ֭̂mámiyţ bĕ̇⁠yáda֣yim ţĕ̇ţapé֑̇ş̂ wĕ֝⁠hi֗yʼ bĕ̇⁠hé֣ykĕléy meֽlekĕ׃p"],[30,29,"שְׁלֹשָׁ֣ה הֵ֭מָּה מֵיטִ֣יבֵי צָ֑עַד וְ֝⁠אַרְבָּעָ֗ה מֵיטִ֥בֵי לָֽכֶת׃","şĕ̌lòşá֣̌h hé֭má̇h méyti֣ybéy ẕá֑ʻad wĕ֝⁠ʼarĕbá̇ʻá֗h méyti֥béy láֽkeţ׃"],[30,30,"לַ֭יִשׁ גִּבּ֣וֹר בַּ⁠בְּהֵמָ֑ה וְ⁠לֹא־יָ֝שׁ֗וּב מִ⁠פְּנֵי־כֹֽל׃","la֭yiş̌ gi̇ḃ֣wòr bȧ⁠bĕ̇hémá֑h wĕ⁠lòʼ-yá֝ş̌֗ẇb mi⁠pĕ̇néy-kòֽl׃"],[30,31,"זַרְזִ֣יר מָתְנַ֣יִם אוֹ־תָ֑יִשׁ וּ֝⁠מֶ֗לֶךְ אַלְק֥וּם עִמּֽ⁠וֹ׃","zarĕzi֣yr máţĕna֣yim ʼwò-ţá֑yiş̌ ẇ֝⁠me֗lekĕ ʼalĕq֥ẇm ʻiṁֽ⁠wò׃"],[30,32,"אִם־נָבַ֥לְתָּ בְ⁠הִתְנַשֵּׂ֑א וְ⁠אִם־זַ֝מּ֗וֹתָ יָ֣ד לְ⁠פֶֽה׃","ʼim-nába֥lĕţá̇ bĕ⁠hiţĕnaşé֑̇̂ʼ wĕ⁠ʼim-za֝ṁ֗wòţá yá֣d lĕ⁠peֽh׃"],[30,33,"כִּ֤י מִ֪יץ חָלָ֡ב י֘וֹצִ֤יא חֶמְאָ֗ה וּֽ⁠מִיץ־אַ֭ף י֣וֹצִיא דָ֑ם וּ⁠מִ֥יץ אַ֝פַּ֗יִם י֣וֹצִיא רִֽיב׃פ","ki֤̇y mi֪yẕ ẖálá֡b y֘wòẕi֤yʼ ẖemĕʼá֗h ẇֽ⁠miyẕ-ʼa֭p y֣wòẕiyʼ dá֑m ẇ⁠mi֥yẕ ʼa֝pȧ֗yim y֣wòẕiyʼ riֽyb׃p"],[31,1,"דִּ֭בְרֵי לְמוּאֵ֣ל מֶ֑לֶךְ מַ֝שָּׂ֗א אֲֽשֶׁר־יִסְּרַ֥תּ⁠וּ אִמּֽ⁠וֹ׃","di֭̇bĕréy lĕmẇʼé֣l me֑lekĕ ma֝şá̇̂֗ʼ ʼàֽşěr-yisĕ̇ra֥ţ̇⁠ẇ ʼiṁֽ⁠wò׃"],[31,2,"מַה־בְּ֭רִ⁠י וּ⁠מַֽה־בַּר־בִּטְנִ֑⁠י וּ֝⁠מֶה בַּר־נְדָרָֽ⁠י׃","mah-bĕ֭̇ri⁠y ẇ⁠maֽh-bȧr-bi̇tĕni֑⁠y ẇ֝⁠meh bȧr-nĕdáráֽ⁠y׃"],[31,3,"אַל־תִּתֵּ֣ן לַ⁠נָּשִׁ֣ים חֵילֶ֑⁠ךָ וּ֝⁠דְרָכֶ֗י⁠ךָ לַֽ⁠מְח֥וֹת מְלָכִֽין׃","ʼal-ţi̇ţé֣̇n la⁠ná̇şǐ֣ym ẖéyle֑⁠ká ẇ֝⁠dĕráke֗y⁠ká laֽ⁠mĕẖ֥wòţ mĕlákiֽyn׃"],[31,4,"אַ֤ל לַֽ⁠מְלָכִ֨ים ׀ לְֽמוֹאֵ֗ל אַ֣ל לַֽ⁠מְלָכִ֣ים שְׁתוֹ־יָ֑יִן וּ֝⁠לְ⁠רוֹזְנִ֗ים או שֵׁכָֽר׃","ʼa֤l laֽ⁠mĕláki֨ym ׀ lĕֽmwòʼé֗l ʼa֣l laֽ⁠mĕláki֣ym şĕ̌ţwò-yá֑yin ẇ֝⁠lĕ⁠rwòzĕni֗ym ʼw şé̌káֽr׃"],[31,5,"פֶּן־יִ֭שְׁתֶּה וְ⁠יִשְׁכַּ֣ח מְחֻקָּ֑ק וִֽ֝⁠ישַׁנֶּה דִּ֣ין כָּל־בְּנֵי־עֹֽנִי׃","pėn-yi֭şĕ̌ţėh wĕ⁠yişĕ̌kȧ֣ẖ mĕẖuqá֑̇q wiֽ֝⁠yşǎnėh di֣̇yn ká̇l-bĕ̇néy-ʻòֽniy׃"],[31,6,"תְּנוּ־שֵׁכָ֣ר לְ⁠אוֹבֵ֑ד וְ֝⁠יַיִן לְ⁠מָ֣רֵי נָֽפֶשׁ׃","ţĕ̇nẇ-şé̌ká֣r lĕ⁠ʼwòbé֑d wĕ֝⁠yayin lĕ⁠má֣réy náֽpeş̌׃"],[31,7,"יִ֭שְׁתֶּה וְ⁠יִשְׁכַּ֣ח רִישׁ֑⁠וֹ וַ֝⁠עֲמָל֗⁠וֹ לֹ֣א יִזְכָּר־עֽוֹד׃","yi֭şĕ̌ţėh wĕ⁠yişĕ̌kȧ֣ẖ riyş֑̌⁠wò wa֝⁠ʻàmál֗⁠wò lò֣ʼ yizĕká̇r-ʻֽwòd׃"],[31,8,"פְּתַח־פִּ֥י⁠ךָ לְ⁠אִלֵּ֑ם אֶל־דִּ֝֗ין כָּל־בְּנֵ֥י חֲלֽוֹף׃","pĕ̇ţaẖ-pi֥̇y⁠ká lĕ⁠ʼilé֑̇m ʼel-di̇֝֗yn ká̇l-bĕ̇né֥y ẖàlֽwòp׃"],[31,9,"פְּתַח־פִּ֥י⁠ךָ שְׁפָט־צֶ֑דֶק וְ֝⁠דִ֗ין עָנִ֥י וְ⁠אֶבְיֽוֹן׃פ","pĕ̇ţaẖ-pi֥̇y⁠ká şĕ̌pát-ẕe֑deq wĕ֝⁠di֗yn ʻáni֥y wĕ⁠ʼebĕyֽwòn׃p"],[31,10,"אֵֽשֶׁת־חַ֭יִל מִ֣י יִמְצָ֑א וְ⁠רָחֹ֖ק מִ⁠פְּנִינִ֣ים מִכְרָֽ⁠הּ׃","ʼéֽşěţ-ẖa֭yil mi֣y yimĕẕá֑ʼ wĕ⁠ráẖò֖q mi⁠pĕ̇niyni֣ym mikĕráֽ⁠ḣ׃"],[31,11,"בָּ֣טַח בָּ֭⁠הּ לֵ֣ב בַּעְלָ֑⁠הּ וְ֝⁠שָׁלָ֗ל לֹ֣א יֶחְסָֽר׃","bá֣̇taẖ bá֭̇⁠ḣ lé֣b bȧʻĕlá֑⁠ḣ wĕ֝⁠şá̌lá֗l lò֣ʼ yeẖĕsáֽr׃"],[31,12,"גְּמָלַ֣תְ⁠הוּ ט֣וֹב וְ⁠לֹא־רָ֑ע כֹּ֝֗ל יְמֵ֣י חַיֶּֽי⁠ה׃","gĕ̇mála֣ţĕ⁠hẇ t֣wòb wĕ⁠lòʼ-rá֑ʻ kò̇֝֗l yĕmé֣y ẖayėֽy⁠h׃"],[31,13,"דָּ֭רְשָׁה צֶ֣מֶר וּ⁠פִשְׁתִּ֑ים וַ֝⁠תַּ֗עַשׂ בְּ⁠חֵ֣פֶץ כַּפֶּֽי⁠הָ׃","dá֭̇rĕşá̌h ẕe֣mer ẇ⁠pişĕ̌ţi֑̇ym wa֝⁠ţȧ֗ʻaş̂ bĕ̇⁠ẖé֣peẕ kȧpėֽy⁠há׃"],[31,14,"הָ֭יְתָה כָּ⁠אֳנִיּ֣וֹת סוֹחֵ֑ר מִ֝⁠מֶּרְחָ֗ק תָּבִ֥יא לַחְמָֽ⁠הּ׃","há֭yĕţáh ká̇⁠ʼoniẏ֣wòţ swòẖé֑r mi֝⁠mėrĕẖá֗q ţá̇bi֥yʼ laẖĕmáֽ⁠ḣ׃"],[31,15,"וַ⁠תָּ֤קָם ׀ בְּ⁠ע֬וֹד לַ֗יְלָה וַ⁠תִּתֵּ֣ן טֶ֣רֶף לְ⁠בֵיתָ֑⁠הּ וְ֝⁠חֹ֗ק לְ⁠נַעֲרֹתֶֽי⁠הָ׃","wa⁠ţá֤̇qám ׀ bĕ̇⁠ʻ֬wòd la֗yĕláh wa⁠ţi̇ţé֣̇n te֣rep lĕ⁠béyţá֑⁠ḣ wĕ֝⁠ẖò֗q lĕ⁠naʻàròţeֽy⁠há׃"],[31,16,"זָמְמָ֣ה שָׂ֭דֶה וַ⁠תִּקָּחֵ֑⁠הוּ מִ⁠פְּרִ֥י כַ֝פֶּ֗י⁠הָ נטע כָּֽרֶם׃","zámĕmá֣h şá֭̂deh wa⁠ţi̇qá̇ẖé֑⁠hẇ mi⁠pĕ̇ri֥y ka֝pė֗y⁠há ntʻ káֽ̇rem׃"],[31,17,"חָֽגְרָ֣ה בְ⁠ע֣וֹז מָתְנֶ֑י⁠הָ וַ֝⁠תְּאַמֵּ֗ץ זְרֹעוֹתֶֽי⁠הָ׃","ẖáֽgĕrá֣h bĕ⁠ʻ֣wòz máţĕne֑y⁠há wa֝⁠ţĕ̇ʼamé̇֗ẕ zĕròʻwòţeֽy⁠há׃"],[31,18,"טָ֭עֲמָה כִּי־ט֣וֹב סַחְרָ֑⁠הּ לֹֽא־יִכְבֶּ֖ה ב⁠ליל נֵרָֽ⁠הּ׃","tá֭ʻàmáh ki̇y-t֣wòb saẖĕrá֑⁠ḣ lòֽʼ-yikĕbė֖h b⁠lyl néráֽ⁠ḣ׃"],[31,19,"יָ֭דֶי⁠הָ שִׁלְּחָ֣ה בַ⁠כִּישׁ֑וֹר וְ֝⁠כַפֶּ֗י⁠הָ תָּ֣מְכוּ פָֽלֶךְ׃","yá֭dey⁠há şǐlĕ̇ẖá֣h ba⁠ki̇yş֑̌wòr wĕ֝⁠kapė֗y⁠há ţá֣̇mĕkẇ páֽlekĕ׃"],[31,20,"כַּ֭פָּ⁠הּ פָּרְשָׂ֣ה לֶ⁠עָנִ֑י וְ֝⁠יָדֶ֗י⁠הָ שִׁלְּחָ֥ה לָֽ⁠אֶבְיֽוֹן׃","kȧ֭pá̇⁠ḣ pá̇rĕşá֣̂h le⁠ʻáni֑y wĕ֝⁠yáde֗y⁠há şǐlĕ̇ẖá֥h láֽ⁠ʼebĕyֽwòn׃"],[31,21,"לֹא־תִירָ֣א לְ⁠בֵיתָ֣⁠הּ מִ⁠שָּׁ֑לֶג כִּ֥י כָל־בֵּ֝יתָ֗⁠הּ לָבֻ֥שׁ שָׁנִֽים׃","lòʼ-ţiyrá֣ʼ lĕ⁠béyţá֣⁠ḣ mi⁠şá֑̇̌leg ki֥̇y kál-bé̇֝yţá֗⁠ḣ lábu֥ş̌ şá̌niֽym׃"],[31,22,"מַרְבַדִּ֥ים עָֽשְׂתָה־לָּ֑⁠הּ שֵׁ֖שׁ וְ⁠אַרְגָּמָ֣ן לְבוּשָֽׁ⁠הּ׃","marĕbadi֥̇ym ʻáֽşĕ̂ţáh-lá֑̇⁠ḣ şé֖̌ş̌ wĕ⁠ʼarĕgá̇má֣n lĕbẇşáֽ̌⁠ḣ׃"],[31,23,"נוֹדָ֣ע בַּ⁠שְּׁעָרִ֣ים בַּעְלָ֑⁠הּ בְּ֝⁠שִׁבְתּ֗⁠וֹ עִם־זִקְנֵי־אָֽרֶץ׃","nwòdá֣ʻ bȧ⁠şĕ̇̌ʻári֣ym bȧʻĕlá֑⁠ḣ bĕ̇֝⁠şǐbĕţ̇֗⁠wò ʻim-ziqĕnéy-ʼáֽreẕ׃"],[31,24,"סָדִ֣ין עָ֭שְׂתָה וַ⁠תִּמְכֹּ֑ר וַ֝⁠חֲג֗וֹר נָתְנָ֥ה לַֽ⁠כְּנַעֲנִֽי׃","sádi֣yn ʻá֭şĕ̂ţáh wa⁠ţi̇mĕkò֑̇r wa֝⁠ẖàg֗wòr náţĕná֥h laֽ⁠kĕ̇naʻàniֽy׃"],[31,25,"עֹז־וְ⁠הָדָ֥ר לְבוּשָׁ֑⁠הּ וַ֝⁠תִּשְׂחַ֗ק לְ⁠י֣וֹם אַחֲרֽוֹן׃","ʻòz-wĕ⁠hádá֥r lĕbẇşá֑̌⁠ḣ wa֝⁠ţi̇şĕ̂ẖa֗q lĕ⁠y֣wòm ʼaẖàrֽwòn׃"],[31,26,"פִּ֭י⁠הָ פָּתְחָ֣ה בְ⁠חָכְמָ֑ה וְ⁠תֽוֹרַת־חֶ֝֗סֶד עַל־לְשׁוֹנָֽ⁠הּ׃","pi֭̇y⁠há pá̇ţĕẖá֣h bĕ⁠ẖákĕmá֑h wĕ⁠ţֽwòraţ-ẖe֝֗sed ʻal-lĕş̌wònáֽ⁠ḣ׃"],[31,27,"צ֭וֹפִיָּה הֲלִיכ֣וֹת בֵּיתָ֑⁠הּ וְ⁠לֶ֥חֶם עַ֝צְל֗וּת לֹ֣א תֹאכֵֽל׃","ẕ֭wòpiyá̇h hàliyk֣wòţ bé̇yţá֑⁠ḣ wĕ⁠le֥ẖem ʻa֝ẕĕl֗ẇţ lò֣ʼ ţòʼkéֽl׃"],[31,28,"קָ֣מוּ בָ֭נֶי⁠הָ וַֽ⁠יְאַשְּׁר֑וּ⁠הָ בַּ֝עְלָ֗⁠הּ וַֽ⁠יְהַֽלְלָ⁠הּ׃","qá֣mẇ bá֭ney⁠há waֽ⁠yĕʼaşĕ̇̌r֑ẇ⁠há bȧ֝ʻĕlá֗⁠ḣ waֽ⁠yĕhaֽlĕlá⁠ḣ׃"],[31,29,"רַבּ֣וֹת בָּ֭נוֹת עָ֣שׂוּ חָ֑יִל וְ֝⁠אַ֗תְּ עָלִ֥ית עַל־כֻּלָּֽ⁠נָה׃","raḃ֣wòţ bá֭̇nwòţ ʻá֣ş̂ẇ ẖá֑yil wĕ֝⁠ʼa֗ţĕ̇ ʻáli֥yţ ʻal-ku̇láֽ̇⁠náh׃"],[31,30,"שֶׁ֣קֶר הַ֭⁠חֵן וְ⁠הֶ֣בֶל הַ⁠יֹּ֑פִי אִשָּׁ֥ה יִרְאַת־יְ֝הוָ֗ה הִ֣יא תִתְהַלָּֽל׃","şě֣qer ha֭⁠ẖén wĕ⁠he֣bel ha⁠yò֑̇piy ʼişá֥̇̌h yirĕʼaţ-yĕ֝hwá֗h hi֣yʼ ţiţĕhaláֽ̇l׃"],[31,31,"תְּנוּ־לָ֭⁠הּ מִ⁠פְּרִ֣י יָדֶ֑י⁠הָ וִֽ⁠יהַלְל֖וּ⁠הָ בַ⁠שְּׁעָרִ֣ים מַעֲשֶֽׂי⁠הָ׃","ţĕ̇nẇ-lá֭⁠ḣ mi⁠pĕ̇ri֣y yáde֑y⁠há wiֽ⁠yhalĕl֖ẇ⁠há ba⁠şĕ̇̌ʻári֣ym maʻàşêֽy⁠há׃"]]}};